        private static void IslandSystemTilesFollowTheIconStyle()
        {
            ThemeManager.Initialize("dark");
            string original = WidgetManager.Instance.Config.IconStyle;
            // Startup path: the constructor itself applies the persisted style.
            WidgetManager.Instance.Config.IconStyle = IconStyleIds.Classic;
            var island = new IslandWindow();
            try
            {
                AssertSystemTilesUsePresenters(island);
                string classic = SystemTileFingerprint(island);

                WidgetManager.Instance.Config.IconStyle = IconStyleIds.HandDrawn;
                island.RefreshIconStyle();
                if (IconStyleManager.Current != IconStyleIds.HandDrawn)
                    throw new InvalidOperationException("the hand-drawn style did not reach IconStyleManager");
                string drawn = SystemTileFingerprint(island);
                if (classic == drawn)
                    throw new InvalidOperationException("the system tiles did not repaint for the hand-drawn style");

                WidgetManager.Instance.Config.IconStyle = IconStyleIds.Classic;
                island.RefreshIconStyle();
                if (IconStyleManager.Current != IconStyleIds.Classic)
                    throw new InvalidOperationException("the classic style did not reach IconStyleManager");
            }
            finally
            {
                WidgetManager.Instance.Config.IconStyle = original;
                island.RefreshIconStyle();
                island.Close();
            }
        }

        private static void AssertSystemTilesUsePresenters(IslandWindow island)
        {
            RequireIcon(island, "DesktopTileIcon", IconId.Desktop);
            RequireIcon(island, "SettingsTileIcon", IconId.Settings);
            RequireIcon(island, "AddTileIcon", IconId.Plus);
        }

        private static string SystemTileFingerprint(IslandWindow island)
        {
            var parts = new List<string>();
            foreach (string name in new[] { "DesktopTileIcon", "SettingsTileIcon", "AddTileIcon" })
            {
                var icon = island.FindName(name) as IconPresenter;
                if (icon == null) throw new InvalidOperationException(name + " was not found");
                parts.Add(name + ":" + RenderPresenterFingerprint(icon));
            }
            return string.Join("|", parts);
        }

        private static string RenderPresenterFingerprint(IconPresenter icon)
        {
            const int size = 24;
            icon.Measure(new Size(size, size));
            icon.Arrange(new Rect(0, 0, size, size));
            icon.InvalidateVisual(); // the offscreen presenter has no Loaded subscription
            icon.UpdateLayout();

            var bitmap = new RenderTargetBitmap(size, size, 96, 96, PixelFormats.Pbgra32);
            bitmap.Render(icon);
            var pixels = new byte[size * size * 4];
            bitmap.CopyPixels(pixels, size * 4, 0);

            ulong hash = 1469598103934665603UL;
            foreach (byte value in pixels)
            {
                hash ^= value;
                hash *= 1099511628211UL;
            }
            return hash.ToString("x16");
        }

        private static void IslandDesktopSlashFollowsHiddenState()
        {
            ThemeManager.Initialize("dark");
            bool originalHidden = WidgetManager.Instance.Config.HideDesktopIcons;
            var island = new IslandWindow();
            try
            {
                var update = typeof(IslandWindow).GetMethod("UpdateDesktopTile",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                if (update == null)
                    throw new InvalidOperationException("UpdateDesktopTile was not found");

                WidgetManager.Instance.Config.HideDesktopIcons = true;
                update.Invoke(island, null);
                AssertSlashVisibility(island, "DesktopSlash", true, "state");

                WidgetManager.Instance.Config.HideDesktopIcons = false;
                update.Invoke(island, null);
                AssertSlashVisibility(island, "DesktopSlash", false, "state");
            }
            finally
            {
                WidgetManager.Instance.Config.HideDesktopIcons = originalHidden;
                island.Close();
            }
        }

        private static void AssertSlashVisibility(IslandWindow island, string name, bool hidden, string style)
        {
            var slash = island.FindName(name) as Shape;
            if (slash == null)
                throw new InvalidOperationException(name + " was not found");
            Visibility wanted = hidden ? Visibility.Visible : Visibility.Collapsed;
            if (slash.Visibility != wanted)
                throw new InvalidOperationException(style + ": " + name + " is " + slash.Visibility +
                    " with HideDesktopIcons=" + hidden + ", wanted " + wanted);
        }

        private static void IslandHandDrawnSystemGeometryDiffers()
        {
            foreach (var id in new[] { IconId.Desktop, IconId.Settings, IconId.Plus })
            {
                string classic = IconCatalog.GetPathData(id, false);
                string handDrawn = IconCatalog.GetPathData(id, true);
                if (string.Equals(classic, handDrawn, StringComparison.Ordinal))
                    throw new InvalidOperationException(id + " has no distinct hand-drawn geometry");
            }
            Console.WriteLine("PASS island: hand-drawn system geometry differs from classic");
        }

        private static void IslandAddMenuOpensOnMouseUp()
        {
            ThemeManager.Initialize("dark");
            var island = new IslandWindow();
            try
            {
                island.Show();
                island.ShowIsland();
                island.UpdateLayout();

                var addTile = (UIElement)typeof(IslandWindow)
                    .GetField("AddTile", BindingFlags.Instance | BindingFlags.NonPublic)
                    .GetValue(island);
                var popupField = typeof(IslandWindow)
                    .GetField("_addWidgetPopup", BindingFlags.Instance | BindingFlags.NonPublic);

                addTile.RaiseEvent(new MouseButtonEventArgs(
                    Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent
                });
                var popup = popupField.GetValue(island) as Popup;
                if (popup == null || !popup.IsOpen)
                    throw new InvalidOperationException("the add menu did not open on mouse-up");

                // Opening on mouse-down would let the popup's own capture turn
                // the same click's release into an outside click, closing it.
                typeof(IslandWindow)
                    .GetMethod("CloseAddWidgetMenu", BindingFlags.Instance | BindingFlags.NonPublic)
                    .Invoke(island, null);
                addTile.RaiseEvent(new MouseButtonEventArgs(
                    Mouse.PrimaryDevice, Environment.TickCount, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonDownEvent
                });
                if (popupField.GetValue(island) != null)
                    throw new InvalidOperationException("the add menu opened on mouse-down");
            }
            finally
            {
                island.Close();
            }
        }

        private static void IslandAddMenuUsesTheLauncherCard()
        {
            ThemeManager.Initialize("dark");
            var island = new IslandWindow();
            try
            {
                var card = island.BuildAddWidgetContent() as Border;
                if (card == null || !"IslandAddMenu".Equals(card.Tag as string))
                    throw new InvalidOperationException("the island add menu is not a tagged Border");
                if (Math.Abs(card.CornerRadius.TopLeft - UiTokens.RadiusWindow) > 0.01)
                    throw new InvalidOperationException("the island add menu radius is " + card.CornerRadius.TopLeft);

                var header = FindByTag(card, "IslandAddHeader") as TextBlock;
                if (header == null || header.Text != Localization.Get("Island_NewWidgetHeader"))
                    throw new InvalidOperationException("the island add menu has no localized header");

                int kindRows = 0;
                CountKindRows(card, ref kindRows);
                if (kindRows != WidgetKindRegistry.All.Count)
                    throw new InvalidOperationException("the island add menu has " + kindRows
                        + " kind rows, wanted " + WidgetKindRegistry.All.Count);

                var style = Application.Current.FindResource("Kobold.Style.LauncherItem") as Style;
                foreach (var id in new[] { "folder", "todo", "note", "search" })
                {
                    var row = FindByTag(card, id) as Button;
                    if (row == null) throw new InvalidOperationException("no " + id + " row");
                    if (!ReferenceEquals(row.Style, style))
                        throw new InvalidOperationException("the " + id + " row does not wear the launcher style");

                    var grid = row.Content as Grid;
                    var view = grid == null || grid.Children.Count == 0 ? null : grid.Children[0] as Viewbox;
                    if (view == null || Math.Abs(view.Width - 24) > 0.01 || Math.Abs(view.Height - 24) > 0.01)
                        throw new InvalidOperationException("the " + id + " row icon is not a 24px Viewbox");
                    var canvas = view.Child as Canvas;
                    if (canvas == null || Math.Abs(canvas.Width - 64) > 0.01 || Math.Abs(canvas.Height - 64) > 0.01)
                        throw new InvalidOperationException("the " + id + " icon canvas is not 64px");
                    if (CountNonEmptyText(grid) < 2)
                        throw new InvalidOperationException("the " + id + " row has no name + hint");
                }
            }
            finally
            {
                island.Close();
            }
        }

        private static void SharedPaletteHasNineSwatches()
        {
            ThemeManager.Initialize("dark");
            var window = ColorPaletteDialog.Build("选择颜色", UiTokens.FolderPalette, UiTokens.DefaultFolderColor,
                false, null, c => { }, () => { });
            var root = window.Content as Border;
            if (root == null) throw new InvalidOperationException("the palette has no Border content");

            int swatches = 0;
            foreach (var color in UiTokens.FolderPalette)
            {
                var swatch = FindByTag(root, color) as Border;
                if (swatch == null) throw new InvalidOperationException("no swatch for " + color);
                swatches++;
            }
            if (swatches != 9) throw new InvalidOperationException("the palette has " + swatches + " swatches");

            var current = FindByTag(root, UiTokens.DefaultFolderColor) as Border;
            if (current == null || current.BorderThickness.Left != 3 ||
                !ReferenceEquals(current.BorderBrush, ThemeManager.TextBrush))
                throw new InvalidOperationException("the current swatch has no ring");

            var currentCheck = current.Child as IconPresenter;
            if (currentCheck == null || currentCheck.Icon != IconId.Check ||
                !"PaletteCheck".Equals(currentCheck.Tag as string))
            {
                throw new InvalidOperationException("the current swatch has no Check IconPresenter");
            }

            var caption = FindByTag(root, "PaletteCaption") as TextBlock;
            if (caption == null || caption.Text != Localization.Get("Color_Clay"))
                throw new InvalidOperationException("the caption does not name the current color");

            if (FindByTag(root, "PaletteDefault") != null)
                throw new InvalidOperationException("a widget palette shows the default button");
        }

