            {
                throw new InvalidOperationException("search data did not build a SearchWidget");
            }
        }

        /// <summary>
        /// Task 8: the results list must virtualize with recycling so a 300-row
        /// result set never builds 300 containers.
        /// </summary>
        private static void SearchResultListIsVirtualized()
        {
            ThemeManager.Initialize("dark");
            var widget = new SearchWidget(new SearchData());
            var list = widget.PanelView.FindName("ResultsList") as ListBox;
            if (list == null)
            {
                throw new InvalidOperationException("the search panel has no ResultsList");
            }
            if (!VirtualizingStackPanel.GetIsVirtualizing(list))
            {
                throw new InvalidOperationException("the result list is not virtualizing");
            }
            if (VirtualizingStackPanel.GetVirtualizationMode(list) != VirtualizationMode.Recycling)
            {
                throw new InvalidOperationException(
                    "the result list virtualization mode is "
                    + VirtualizingStackPanel.GetVirtualizationMode(list));
            }
            if (!ScrollViewer.GetCanContentScroll(list))
            {
                throw new InvalidOperationException("the result list does not content-scroll");
            }

            // The virtualized row pitch is part of the contract: one 44-DIP
            // Grid is the template root.
            DataTemplate template = list.ItemTemplate;
            var rowRoot = template == null ? null : template.LoadContent() as FrameworkElement;
            if (rowRoot == null || Math.Abs(rowRoot.Height - 44) > 0.01)
            {
                throw new InvalidOperationException(
                    "the result row height is " + (rowRoot == null ? "missing" : rowRoot.Height.ToString())
                    + ", wanted 44");
            }
        }

        /// <summary>
        /// Task 8: the skeleton carries the empty, no-index and onboarding state
        /// panels plus their controls; Task 9 fills the onboarding behaviour.
        /// </summary>
        private static void SearchStatesExist()
        {
            ThemeManager.Initialize("dark");
            var widget = new SearchWidget(new SearchData());

            foreach (string name in new[]
            {
                "EmptyState", "NoIndexState", "OnboardingPanel", "StartIndexButton",
                "OnboardingStartButton", "OnboardingLaterButton", "RootsList", "ScopeHint",
                "SearchBox", "StatusText"
            })
            {
                if (widget.PanelView.FindName(name) == null)
                {
                    throw new InvalidOperationException("the search panel has no " + name);
                }
            }
        }

        /// <summary>
        /// Task 9: the Settings window carries the file-search section and every
        /// control the code-behind drives. The labels must already be localized
        /// by the constructor's UpdateLocalizedText pass.
        /// </summary>
        private static void SettingsFileSearchSectionExists()
        {
            ThemeManager.Initialize("dark");
            var window = new SettingsWindow();

            foreach (string name in new[]
            {
                "FileSearchHeader", "FileSearchStatusText", "FileSearchSizeText",
                "FileSearchLastUpdatedText", "FileSearchAllFilesCheck",
                "FileSearchExtensionlessCheck", "FileSearchFoldersCheck",
                "FileSearchTypesBox", "FileSearchExcludesBox", "FileSearchReconcileBox",
                "FileSearchRootsList", "FileSearchRebuildButton", "FileSearchPauseButton",
                "FileSearchCancelButton"
            })
            {
                if (window.FindName(name) == null)
                {
                    throw new InvalidOperationException("the settings window has no " + name);
                }
            }

            var header = window.FindName("FileSearchHeader") as TextBlock;
            if (header == null || header.Text != Localization.Get("Settings_FileSearch"))
            {
                throw new InvalidOperationException(
                    "the file-search header shows '" + (header == null ? "null" : header.Text) + "'");
            }

            var allFiles = window.FindName("FileSearchAllFilesCheck") as CheckBox;
            if (allFiles == null || allFiles.Content as string != Localization.Get("Search_SettingsAllFiles"))
            {
                throw new InvalidOperationException(
                    "the all-files check shows '" + (allFiles == null ? "null" : allFiles.Content) + "'");
            }

            var rebuild = window.FindName("FileSearchRebuildButton") as Button;
            if (rebuild == null || rebuild.Content as string != Localization.Get("Search_SettingsRebuild"))
            {
                throw new InvalidOperationException(
                    "the rebuild button shows '" + (rebuild == null ? "null" : rebuild.Content) + "'");
            }

            var pause = window.FindName("FileSearchPauseButton") as Button;
            string pauseLabel = pause == null ? null : pause.Content as string;
            if (pauseLabel != Localization.Get("Search_SettingsPause") &&
                pauseLabel != Localization.Get("Search_SettingsResume"))
            {
                throw new InvalidOperationException(
                    "the pause button shows '" + pauseLabel + "', wanted a localized Pause/Resume label");
            }

            var cancel = window.FindName("FileSearchCancelButton") as Button;
            if (cancel == null || cancel.Content as string != Localization.Get("Search_Cancel"))
            {
                throw new InvalidOperationException(
                    "the cancel button shows '" + (cancel == null ? "null" : cancel.Content) + "'");
            }
        }

        /// <summary>
        /// Task 9: a fresh install's onboarding lists one checked checkbox per
        /// fixed NTFS root (the configured-roots form when config carries any)
        /// and has Start/Later. Filling the list must never start a scan.
        /// </summary>
        private static void SearchOnboardingHasActions()
        {
            ThemeManager.Initialize("dark");
            var widget = new SearchWidget(new SearchData());
            var view = widget.PanelView;

            // RefreshOnboarding is internal: the check assembly reaches it the
            // same way the other private-method pins do.
            var refresh = typeof(SearchPanelView).GetMethod("RefreshOnboarding",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (refresh == null)
            {
                throw new InvalidOperationException("SearchPanelView.RefreshOnboarding was not found");
            }
            refresh.Invoke(view, null);

            var rootsList = view.FindName("RootsList") as ItemsControl;
            var start = view.FindName("OnboardingStartButton") as Button;
            var later = view.FindName("OnboardingLaterButton") as Button;
            if (rootsList == null || start == null || later == null)
            {
                throw new InvalidOperationException("the onboarding controls are missing");
            }

            int expected = SearchRoots.FixedNtfsRoots().Count;
            if (rootsList.Items.Count != expected)
            {
                throw new InvalidOperationException(
                    "the onboarding lists " + rootsList.Items.Count + " root(s), wanted " + expected);
            }

            foreach (object item in rootsList.Items)
            {
                var box = item as CheckBox;
                if (box == null || box.IsChecked != true || string.IsNullOrEmpty(box.Tag as string))
                {
                    throw new InvalidOperationException(
                        "a root entry is not a checked checkbox with its path tag");
                }
            }

            if (!start.IsEnabled)
            {
                throw new InvalidOperationException("the start button is disabled with every root checked");
            }

            FileSearchState state = FileSearchIndexService.Instance.Status.State;
            if (state == FileSearchState.Indexing || state == FileSearchState.Reconciling)
            {
                throw new InvalidOperationException(
                    "populating the onboarding started a scan (" + state + ")");
            }
        }

        /// <summary>
        /// Task 9 fix round 1: a Save that only changes theme/opacity must not
        /// activate file search. The save decision seam is invoked directly
        /// (SaveButton would also write the registry and close the window):
        /// untouched -> false and FileSearch stays null; one changed control ->
        /// true and a configured section is created.
        /// </summary>
        private static void SettingsFileSearchSaveStaysOptional()
        {
            ThemeManager.Initialize("dark");
            AppConfig config = WidgetManager.Instance.Config;
            FileSearchSettings saved = config.FileSearch;
            try
            {
                config.FileSearch = null;
                var window = new SettingsWindow();

                var apply = typeof(SettingsWindow).GetMethod("TryApplyFileSearchSection",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                if (apply == null)
                {
                    throw new InvalidOperationException("SettingsWindow.TryApplyFileSearchSection was not found");
                }

                bool applied = (bool)apply.Invoke(window, null);
                if (applied)
                {
                    throw new InvalidOperationException("an untouched file-search section was applied");
                }
                if (config.FileSearch != null)
                {
                    throw new InvalidOperationException("an untouched save created FileSearch");
                }

                var allFiles = window.FindName("FileSearchAllFilesCheck") as CheckBox;
                if (allFiles == null)
                {
                    throw new InvalidOperationException("the all-files check is missing");
                }
                allFiles.IsChecked = true;

                applied = (bool)apply.Invoke(window, null);
                if (!applied)
                {
                    throw new InvalidOperationException("an edited file-search section was not applied");
                }
                if (config.FileSearch == null || !config.FileSearch.Configured
                    || !config.FileSearch.Enabled || !config.FileSearch.IndexAllFiles)
                {
                    throw new InvalidOperationException(
                        "the edited section was not saved as a configured, all-files setting");
                }
            }
            finally
            {
                config.FileSearch = saved;
            }
        }

        /// <summary>
        /// Task 9 fix round 1: a configured install reaches onboarding through
        /// the no-index Start button, so Start must build/save/apply settings
        /// and request the scan instead of returning. The internal
        /// StartScanForChecks hook records the request; no real scan runs.
        /// </summary>
        private static void SearchConfiguredOnboardingStarts()
        {
            ThemeManager.Initialize("dark");
            AppConfig config = WidgetManager.Instance.Config;
            FileSearchSettings saved = config.FileSearch;

            string root = IO.Path.Combine(IO.Path.GetTempPath(),
                "kobold-onboarding-" + Guid.NewGuid().ToString("N"));
            IO.Directory.CreateDirectory(root);

            try
            {
                var settings = FileSearchSettings.CreateDefault();
                settings.Configured = true;
                settings.Enabled = true;
                settings.Roots = new[] { root };
                config.FileSearch = settings;

                var view = new SearchWidget(new SearchData()).PanelView;

                // A configured install does not auto-show onboarding; the
                // no-index Start button calls ShowOnboarding.
                var show = typeof(SearchPanelView).GetMethod("ShowOnboarding",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                if (show == null) throw new InvalidOperationException("ShowOnboarding was not found");
                show.Invoke(view, null);

                var rootsList = view.FindName("RootsList") as ItemsControl;
                if (rootsList == null || rootsList.Items.Count != 1
                    || !((rootsList.Items[0] as CheckBox)?.IsChecked == true))
                {
                    throw new InvalidOperationException(
                        "the configured roots were not seeded into the onboarding");
                }

                FileSearchSettings started = null;
                IReadOnlyList<string> startedRoots = null;
                int calls = 0;

                var hook = typeof(SearchPanelView).GetProperty("StartScanForChecks",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                if (hook == null) throw new InvalidOperationException("StartScanForChecks was not found");
                hook.SetValue(view, new Action<FileSearchSettings, IReadOnlyList<string>>(
                    (s, r) => { calls++; started = s; startedRoots = r; }));

                var click = typeof(SearchPanelView).GetMethod("OnboardingStartButton_Click",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                if (click == null) throw new InvalidOperationException("OnboardingStartButton_Click was not found");
                click.Invoke(view, new object[] { view, new RoutedEventArgs() });

                if (calls != 1)
                {
                    throw new InvalidOperationException(
                        "the configured start never reached the scan path (calls=" + calls + ")");
                }
                if (started == null || !started.Configured || !started.Enabled)
                {
                    throw new InvalidOperationException("the applied settings are not configured/enabled");
                }
                if (startedRoots == null || startedRoots.Count != 1)
                {
                    throw new InvalidOperationException(
                        "the scan got " + (startedRoots == null ? "null" : startedRoots.Count.ToString()) + " root(s)");
                }
                if (config.FileSearch == null || !config.FileSearch.Configured)
                {
                    throw new InvalidOperationException("starting the configured onboarding did not save the config");
                }
            }
            finally
            {
                config.FileSearch = saved;
                try { IO.Directory.Delete(root, true); } catch (Exception) { }
            }
        }

        /// <summary>
        /// Task 9: the search widget's menu offers rebuild and the pause toggle
        /// (localized from the service state) before the delete separator, while
        /// the other kinds keep their menus.
        /// </summary>
        private static void SearchMenuOffersRebuildAndPause()
        {
            ThemeManager.Initialize("dark");
            var widget = new SearchWidget(new SearchData());
            var menu = WidgetMenuBuilder.Build(widget, null);

            int rebuildIndex = -1;
            int pauseIndex = -1;
            int separatorIndex = -1;
            for (int i = 0; i < menu.Items.Count; i++)
            {
                if (menu.Items[i] is Separator && separatorIndex < 0)
                {
                    separatorIndex = i;
                    continue;
                }

                var item = menu.Items[i] as MenuItem;
                string header = item == null ? null : item.Header as string;
                if (header == Localization.Get("Search_Rebuild")) rebuildIndex = i;
                if (header == Localization.Get("Search_Pause")) pauseIndex = i;
            }

            if (rebuildIndex < 0)
            {
                throw new InvalidOperationException("the search menu has no rebuild entry");
            }
            if (pauseIndex < 0)
            {
                throw new InvalidOperationException("the search menu has no pause entry");
            }
            if (separatorIndex < 0 || rebuildIndex > separatorIndex || pauseIndex > separatorIndex)
            {
                throw new InvalidOperationException(
                    "the search actions must sit before the delete separator (" +
                    rebuildIndex + "/" + pauseIndex + " vs " + separatorIndex + ")");
            }
        }

        /// <summary>
        /// Fix round 5: the definitive IME fix is to draw no hint inside or over
        /// the box at all - the same plain TextBox the new-file dialog uses.
        /// Fix round 6: the style also stops overriding the template, so the
        /// native TextBox layout owns the text/IME geometry (the remaining
        /// clipping/ghost came from the custom PART_ContentHost layout).
        /// Task 3 (2026-10-26): the user no longer wants a tooltip either, so
        /// the box is a bare TextBox - no tooltip, no tag, no hint anywhere.
        /// </summary>
        private static void SearchBoxHintAndStyle()
        {
            ThemeManager.Initialize("dark");
            var view = new SearchWidget(new SearchData()).PanelView;
            var box = view.FindName("SearchBox") as TextBox;
            if (box == null)
            {
                throw new InvalidOperationException("the search panel has no SearchBox");
            }

            if (box.ToolTip != null)
            {
                throw new InvalidOperationException(
                    "the search box still carries a tooltip ('" + box.ToolTip + "')");
            }
            if (box.Tag != null)
            {
                throw new InvalidOperationException(
                    "the search box still carries a tag ('" + box.Tag + "')");
            }

            Style style = box.Style;
            if (style == null)
            {
                throw new InvalidOperationException("the search box has no style");
            }

            box.ApplyTemplate();
            ControlTemplate template = box.Template;
            if (template == null)
            {
                throw new InvalidOperationException("the search box has no template");
            }

            if (template.FindName("Watermark", box) != null)
            {
                throw new InvalidOperationException(
                    "the search box template still draws a watermark");
            }
            if (template.FindName("PART_ContentHost", box) as ScrollViewer == null)
            {
                throw new InvalidOperationException(
                    "the search box template has no PART_ContentHost scroll viewer");
            }

            // No text layer at all: the template's own tree carries no TextBlock
            // that could sit under the IME composition string.
            var root = template.LoadContent() as DependencyObject;
            if (root == null || ContainsTextBlock(root))
            {
                throw new InvalidOperationException(
                    "the search box template still layers text inside the box");
            }

            // The native focus border/selection read Kobold.Brush.Accent; the
            // view must have overridden that key with the widget accent.
            var searchAccent = view.Resources["SearchAccent"];
            var accentOverride = view.Resources["Kobold.Brush.Accent"];
            if (searchAccent == null || !ReferenceEquals(accentOverride, searchAccent))
            {
                throw new InvalidOperationException(
                    "the view did not colour Kobold.Brush.Accent with the search accent");
            }
        }

        /// <summary>
        /// Fix round 6: the search box style must not set its own Template (or
        /// caret/selection brushes): the app's native TextBox template owns the
        /// text host layout, which is what fixes the IME clipping. Only the
        /// translucent selection opacity stays local.
        /// </summary>
        private static void SearchBoxStyleHasNoCustomTemplate()
        {
            ThemeManager.Initialize("dark");
            var view = new SearchWidget(new SearchData()).PanelView;
            var box = view.FindName("SearchBox") as TextBox;
            if (box == null)
            {
                throw new InvalidOperationException("the search panel has no SearchBox");
            }

            Style style = box.Style;
            if (style == null)
            {
                throw new InvalidOperationException("the search box has no style");
            }
            if (TemplateOf(style) != null)
            {
                throw new InvalidOperationException(
                    "the search box style overrides the native TextBox template");
            }
            if (style.Setters.Count != 1
                || ((Setter)style.Setters[0]).Property != TextBoxBase.SelectionOpacityProperty)
            {
                throw new InvalidOperationException(
                    "the search box style carries setters beyond SelectionOpacity ("
                    + style.Setters.Count + ")");
            }

            var implicitStyle = Application.Current.TryFindResource(typeof(TextBox)) as Style;
            ControlTemplate nativeTemplate = implicitStyle == null ? null : TemplateOf(implicitStyle);
            if (nativeTemplate == null)
            {
                throw new InvalidOperationException("the app has no implicit TextBox template");
            }
            if (!ReferenceEquals(box.Template, nativeTemplate))
            {
                throw new InvalidOperationException(
                    "the search box does not use the app's native TextBox template");
            }

            // The selection paints the widget accent, so a light widget colour
            // must stay readable - the accent wash is translucent.
            double? selectionOpacity = null;
            foreach (Setter setter in style.Setters)
            {
                if (setter.Property == TextBoxBase.SelectionOpacityProperty
                    && setter.Value is double)
                {
                    selectionOpacity = (double)setter.Value;
                }
            }
            if (!selectionOpacity.HasValue
                || selectionOpacity.Value <= 0 || selectionOpacity.Value >= 1)
            {
                throw new InvalidOperationException(
                    "the search box selection opacity is "
                    + (selectionOpacity.HasValue ? selectionOpacity.Value.ToString() : "<unset>")
                    + ", wanted a translucent accent wash");
            }
        }

        /// <summary>
        /// Fix round 7: the box is a fixed 34 DIP high, so the content host
        /// (PART_ContentHost) only gets the height its border and padding leave
        /// over. The shared TextBox style's 6+6 vertical padding starved it to
        /// 20 DIP for a 17.5 DIP line under TextFormattingMode=Display, so the
        /// text view painted outside the host was clipped to a sliver. The box
        /// therefore drops the vertical padding (VerticalContentAlignment=Center
        /// supplies the inset): the host must have one and a half line heights.
        /// The Height == 34 footprint assertion also passes on the old code: the
        /// content-host check is the red-then-green guard, the footprint check
        /// only blocks future shrinkage.
        /// </summary>
        private static void SearchBoxLineFits()
        {
            ThemeManager.Initialize("dark");
            var view = new SearchWidget(new SearchData()).PanelView;
            var box = view.FindName("SearchBox") as TextBox;
            if (box == null)
            {
                throw new InvalidOperationException("the search panel has no SearchBox");
            }

            // The line the box has to show: the box's real typeface and size,
            // measured at the harness's 96 DPI (the pin is structural - the
            // content host's height, not a rendered bitmap, is what clips).
            var typeface = new Typeface(box.FontFamily, box.FontStyle, box.FontWeight, box.FontStretch);
            var formatted = new FormattedText("abc \u4e3b,", CultureInfo.CurrentUICulture,
                FlowDirection.LeftToRight, typeface, box.FontSize, Brushes.Black, 1.0);

            double line = formatted.Height;
            double content = box.Height - box.BorderThickness.Top - box.BorderThickness.Bottom
                             - box.Padding.Top - box.Padding.Bottom;

            if (content < line * 1.5)
            {
                throw new InvalidOperationException(
                    "the search box content host is " + content.ToString("0.##") + " DIP for a "
                    + line.ToString("0.##") + " DIP line (height " + box.Height + ", padding "
                    + box.Padding + "): the line is clipped");
            }

            if (box.Height != 34)
            {
                throw new InvalidOperationException(
                    "the search box is " + box.Height + " DIP high, wanted the plan's 34");
            }
        }

        /// <summary>
        /// The search shell fills the row; the icon and the borderless input
        /// sit inside it, so the text can never drift away from the magnifier.
        /// </summary>
        private static void SearchBoxFillsTheRow()
        {
            ThemeManager.Initialize("dark");
            var view = new SearchWidget(new SearchData()).PanelView;

            if (view.FindName("ClearButton") != null)
            {
                throw new InvalidOperationException("the search panel still has a clear button");
            }

            var box = view.FindName("SearchBox") as TextBox;
            var shell = view.FindName("SearchBoxShell") as Border;
            if (box == null || shell == null)
                throw new InvalidOperationException("the search panel has no SearchBox shell/box");

            view.Measure(new Size(422, 562));
            view.Arrange(new Rect(0, 0, 422, 562));
            view.UpdateLayout();

            var row = shell.Parent as Grid;
            if (row == null)
                throw new InvalidOperationException("the search shell's row grid was not found");
            if (row.Children.Count != 2 || !ReferenceEquals(row.Children[1], shell))
            {
                throw new InvalidOperationException(
                    "the search row is not the focus ring + shell (" + row.Children.Count + " children)");
            }

            double wanted = view.ActualWidth - row.Margin.Left - row.Margin.Right;
            if (Math.Abs(row.ActualWidth - wanted) > 0.5 || Math.Abs(shell.ActualWidth - wanted) > 0.5)
            {
                throw new InvalidOperationException(
                    "the search shell is " + shell.ActualWidth.ToString("0.##") + " DIP wide in a "
                    + row.ActualWidth.ToString("0.##") + " DIP row, wanted " + wanted.ToString("0.##"));
            }
            if (box.Padding.Left != 0 || box.BorderThickness.Left != 0)
            {
                throw new InvalidOperationException(
                    "the inner search box still owns padding/border (padding " + box.Padding
                    + ", border " + box.BorderThickness + ")");
            }
        }

        /// <summary>
        /// The user's screenshot: a magnifier far left and the text far right.
        /// The icon and the input must be laid out as neighbours (<= 8 DIP gap).
        /// </summary>
        private static void SearchIconSitsNextToTheInput()
        {
            ThemeManager.Initialize("dark");
            var view = new SearchWidget(new SearchData()).PanelView;
            var shell = view.FindName("SearchBoxShell") as Border;
            var icon = view.FindName("SearchBoxIcon") as IconPresenter;
            var box = view.FindName("SearchBox") as TextBox;
            if (shell == null || icon == null || box == null)
                throw new InvalidOperationException("the search shell/icon/box was not found");

            view.Measure(new Size(422, 562));
            view.Arrange(new Rect(0, 0, 422, 562));
            view.UpdateLayout();

            double iconRight = icon.TranslatePoint(new Point(icon.ActualWidth, 0), shell).X;
            double boxLeft = box.TranslatePoint(new Point(0, 0), shell).X;
            if (boxLeft < iconRight || boxLeft - iconRight > 8)
            {
                throw new InvalidOperationException(
                    "the input starts " + (boxLeft - iconRight).ToString("0.##")
                    + " DIP after the magnifier (icon right " + iconRight.ToString("0.##")
                    + ", box left " + boxLeft.ToString("0.##") + "), wanted <= 8");
            }
        }

        /// <summary>
        /// Task 3 (2026-10-26): the panel's outer rounded border carries a
        /// "loading meteor" while a search query is in flight - a dim base ring
        /// plus four dash layers (halo / tail / mid / head) that travel one
        /// perimeter per GlowSeconds, no blur effect anywhere. Stopping hides
        /// the layer and drops the animation clocks (nothing ticks unseen).
        /// </summary>
        private static void SearchPanelGlowsWhileQuerying()
        {
            ThemeManager.Initialize("dark");

            var widget = new SearchWidget(new SearchData());
            var chrome = widget.FindName("SearchChrome") as WidgetChrome;
            if (chrome == null) chrome = widget.Content as WidgetChrome;
            if (chrome == null) throw new InvalidOperationException("the search widget has no chrome");

            var layer = chrome.FindName("GlowLayer") as Grid;
            if (layer == null) throw new InvalidOperationException("the chrome has no GlowLayer");
            if (layer.Visibility != Visibility.Collapsed)
            {
                throw new InvalidOperationException("the glow layer is visible before any query");
            }
            if (chrome.IsGlowActive)
            {
                throw new InvalidOperationException("the glow is active before any query");
            }

            var track = GlowPath(chrome, "GlowTrack");
            var halo = GlowPath(chrome, "GlowHalo");
            var tail = GlowPath(chrome, "GlowTail");
            var mid = GlowPath(chrome, "GlowMid");
            var head = GlowPath(chrome, "GlowHead");

            // The ring is built from the chrome's own size: give it the search
            // panel's default footprint (422x562) before starting the glow.
            ArrangeChrome(chrome, 422, 562);

            // Fix round 1: non-default timing (the tokens are 1.2 s / 0.28), so
            // an implementation that ignored either property fails the pin.
            chrome.ApplyGlowColor("#F97316");
            chrome.GlowSeconds = 2.0;
            chrome.GlowTailFraction = 0.5;
            chrome.StartGlow();

            if (!chrome.IsGlowActive) throw new InvalidOperationException("StartGlow did not activate the glow");
            if (layer.Visibility != Visibility.Visible) throw new InvalidOperationException("StartGlow left the layer hidden");

            var paths = new[] { track, halo, tail, mid, head };
            foreach (var path in paths)
            {
                if (path.Stroke == null) throw new InvalidOperationException(path.Name + " has no stroke");

                var geometry = path.Data as RectangleGeometry;
                if (geometry == null) throw new InvalidOperationException(path.Name + " has no rectangle geometry");

                // The track hugs the border with half its own width; the four
                // meteor layers share the 2.5 DIP core centreline (the halo is
                // a wider band centred on it, not inset by its own width).
                double inset = ReferenceEquals(path, track)
                    ? path.StrokeThickness / 2
                    : UiTokens.GlowCoreThickness / 2;
                if (Math.Abs(geometry.RadiusX - UiTokens.GlowRadius) > 1e-6 ||
                    Math.Abs(geometry.RadiusY - UiTokens.GlowRadius) > 1e-6)
                {
                    throw new InvalidOperationException(
                        path.Name + " radius is " + geometry.RadiusX + "x" + geometry.RadiusY +
                        ", wanted " + UiTokens.GlowRadius);
                }
                if (Math.Abs(geometry.Rect.X - inset) > 1e-6 || Math.Abs(geometry.Rect.Y - inset) > 1e-6
                    || Math.Abs(geometry.Rect.Width - (422 - 2 * inset)) > 1e-6
                    || Math.Abs(geometry.Rect.Height - (562 - 2 * inset)) > 1e-6)
                {
                    throw new InvalidOperationException(
                        path.Name + " ring does not hug the border (rect " + geometry.Rect
                        + ", inset " + inset + ")");
                }
            }

            // The head rides a linear one-perimeter animation: the loop is
            // seamless only when the travel equals the ring perimeter in dash
            // units (perimeter / thickness).
            var headGeometry = (RectangleGeometry)head.Data;
            double headPerimeter = RingPerimeter(headGeometry);
            double headPeriod = headPerimeter / head.StrokeThickness;

            DoubleAnimation animation = GlowAnimation(chrome, head);
            if (animation == null) throw new InvalidOperationException("the head carries no animation");

            // WPF reports an attached clock through HasAnimatedProperties (the
            // per-property IsAnimated flag only flips on the first render tick,
            // which the headless harness never runs). StopGlow later clears
            // exactly StrokeDashOffset, so the pair proves the clock sits on
            // that property: any other animated property would keep the flag.
            if (!head.HasAnimatedProperties)
            {
                throw new InvalidOperationException("the head carries no animation clock");
            }
            if ((double)head.GetAnimationBaseValue(Shape.StrokeDashOffsetProperty) != 0)
            {
                throw new InvalidOperationException(
                    "the head dash offset carries a local value instead of the animated one");
            }
            if (Math.Abs(animation.Duration.TimeSpan.TotalSeconds - 2.0) > 1e-6)
            {
                throw new InvalidOperationException(
                    "the glow duration is " + animation.Duration + ", wanted the configured 2.0s");
            }
            if (!animation.RepeatBehavior.Equals(RepeatBehavior.Forever))
            {
                throw new InvalidOperationException(
                    "the glow does not repeat forever (" + animation.RepeatBehavior + ")");
            }
            if (!animation.To.HasValue || animation.To.Value >= 0)
            {
                throw new InvalidOperationException(
                    "the head dash offset does not travel backwards (" + animation.To + ")");
            }
            if (Math.Abs((animation.From.Value - animation.To.Value) - headPeriod) > 1e-6)
            {
                throw new InvalidOperationException(
                    "the glow advances " + (animation.From.Value - animation.To.Value)
                    + " dash units, wanted one perimeter (" + headPeriod + ")");
            }
            if (animation.EasingFunction != null)
            {
                throw new InvalidOperationException("the glow is not linear");
            }

            // Bright head, softer mid, faint tail, faintest halo; the track is
            // exempt (its colour carries the alpha).
            if (!(head.Opacity > mid.Opacity && mid.Opacity > tail.Opacity && tail.Opacity > halo.Opacity))
            {
                throw new InvalidOperationException(
                    "the glow layer opacities are out of order (head " + head.Opacity + ", mid "
                    + mid.Opacity + ", tail " + tail.Opacity + ", halo " + halo.Opacity + ")");
            }

            // Every meteor layer's dash + gap is exactly one perimeter and the
            // tail is longer than the head - a comet with a tail, not a dot.
            // Each layer's animation must start one dash-length before the ring
            // origin: that is what puts all four leading edges on the same
            // point (head at the front, tail behind it).
            foreach (var path in new[] { halo, tail, mid, head })
            {
                if (path.StrokeDashArray == null || path.StrokeDashArray.Count != 2)
                {
                    throw new InvalidOperationException(path.Name + " has no two-part dash pattern");
                }
                double period = path.StrokeDashArray[0] + path.StrokeDashArray[1];
                double wanted = RingPerimeter((RectangleGeometry)path.Data) / path.StrokeThickness;
                if (Math.Abs(period - wanted) > 1e-6)
                {
                    throw new InvalidOperationException(
                        path.Name + " dash + gap is " + period + " units, wanted one perimeter (" + wanted + ")");
                }

                DoubleAnimation meteorAnimation = GlowAnimation(chrome, path);
                if (meteorAnimation == null || !meteorAnimation.From.HasValue)
                {
                    throw new InvalidOperationException(
                        path.Name + " carries no dash-offset animation");
                }
                if (Math.Abs(meteorAnimation.From.Value - path.StrokeDashArray[0]) > 1e-9)
                {
                    throw new InvalidOperationException(
                        path.Name + " does not start at its leading edge (From " + meteorAnimation.From.Value
                        + ", dash " + path.StrokeDashArray[0] + ")");
                }
            }
            if (!(tail.StrokeDashArray[0] > head.StrokeDashArray[0]))
            {
                throw new InvalidOperationException(
                    "the tail is not longer than the head (" + tail.StrokeDashArray[0]
                    + " vs " + head.StrokeDashArray[0] + ")");
            }

            // The configured fraction (0.5, not the 0.28 token) is what the tail
            // sweeps: the tail layer's share is the whole comet.
            double tailPeriod = RingPerimeter((RectangleGeometry)tail.Data) / tail.StrokeThickness;
            if (Math.Abs(tail.StrokeDashArray[0] - 0.5 * tailPeriod) > 1e-6)
            {
                throw new InvalidOperationException(
                    "the tail sweeps " + tail.StrokeDashArray[0] + " of " + tailPeriod
                    + " dash units, wanted the configured 0.5 of the perimeter");
            }

            // The comet wears the widget colour: a full-alpha head and a dimmed
            // base ring that covers the normal border while loading.
            var headBrush = head.Stroke as SolidColorBrush;
            var trackBrush = track.Stroke as SolidColorBrush;
            if (headBrush == null || trackBrush == null)
            {
                throw new InvalidOperationException("the glow strokes are not solid colour brushes");
            }
            Color orange = Utils.HexToColor("#F97316");
            if (headBrush.Color.R != orange.R || headBrush.Color.G != orange.G || headBrush.Color.B != orange.B
                || headBrush.Color.A != 255)
            {
                throw new InvalidOperationException(
                    "the glow head is not the widget colour at full alpha (" + headBrush.Color + ")");
            }
            if (trackBrush.Color.A >= headBrush.Color.A)
            {
                throw new InvalidOperationException(
                    "the glow track is not dimmer than the head (" + trackBrush.Color + ")");
            }

            // Fix round 1: a second StartGlow while the comet already runs must
            // keep the same clocks. The view calls it on every keystroke and on
            // every RunQuery; re-applying an animation whose From is the dash
            // length snaps the head back to the ring origin (a visible stutter).
            DoubleAnimation runningHead = GlowAnimation(chrome, head);
            object runningGeometry = head.Data;
            chrome.StartGlow();
            if (!ReferenceEquals(GlowAnimation(chrome, head), runningHead))
            {
                throw new InvalidOperationException("a second StartGlow restarted the glow animations");
            }
            if (!ReferenceEquals(head.Data, runningGeometry))
            {
                throw new InvalidOperationException("a second StartGlow rebuilt the glow geometry");
            }

            // ...but a changed timing parameter must rebuild: the running clocks
            // were built for the old seconds/tail fraction.
            chrome.GlowSeconds = 2.5;
            chrome.StartGlow();
            DoubleAnimation reboundHead = GlowAnimation(chrome, head);
            if (ReferenceEquals(reboundHead, runningHead))
            {
                throw new InvalidOperationException(
                    "a changed GlowSeconds did not rebuild the glow animations");
            }
            if (Math.Abs(reboundHead.Duration.TimeSpan.TotalSeconds - 2.5) > 1e-6)
            {
                throw new InvalidOperationException(
                    "the rebuilt glow duration is " + reboundHead.Duration + ", wanted 2.5s");
            }
            chrome.GlowSeconds = 2.0;
            chrome.StartGlow();
            DoubleAnimation restoredHead = GlowAnimation(chrome, head);
            if (ReferenceEquals(restoredHead, reboundHead))
            {
                throw new InvalidOperationException(
                    "restoring GlowSeconds did not rebuild the glow animations");
            }

            chrome.StopGlow();
            if (chrome.IsGlowActive) throw new InvalidOperationException("StopGlow left the glow active");
            if (layer.Visibility != Visibility.Collapsed) throw new InvalidOperationException("StopGlow left the layer visible");
            if (head.HasAnimatedProperties)
            {
                throw new InvalidOperationException("StopGlow left the head animation ticking");
            }

            // A stop/start cycle is a real restart: the stopped clocks are gone,
            // so a new animation instance has to be allocated.
            chrome.StartGlow();
            DoubleAnimation restartedHead = GlowAnimation(chrome, head);
            if (restartedHead == null || ReferenceEquals(restartedHead, restoredHead))
            {
                throw new InvalidOperationException("a restart reused a stopped glow animation");
            }
            chrome.StopGlow();

            // Fix round 1: the whole documented range must keep a usable pattern.
            // GlowTailFraction = 1 used to make the tail's dash exactly one
            // perimeter (no gap, no travel) and silently drop that layer.
            chrome.GlowTailFraction = 1.0;
            chrome.StartGlow();
            foreach (var path in new[] { halo, tail, mid, head })
            {
                if (GlowAnimation(chrome, path) == null)
                {
                    throw new InvalidOperationException(
                        path.Name + " lost its animation at GlowTailFraction = 1");
                }
                if (path.StrokeDashArray == null || path.StrokeDashArray.Count != 2
                    || !(path.StrokeDashArray[1] > 0))
                {
                    throw new InvalidOperationException(
                        path.Name + " has no gap left at GlowTailFraction = 1");
                }
            }
            chrome.StopGlow();
        }

        /// <summary>
        /// Task 3: the view owns the query lifecycle - it turns the chrome glow
        /// on while a query is pending and off once the query settles. The pin
        /// drives the private switch directly (no live search service).
        /// Fix round 1: a hidden panel never lights up, and only the generation
        /// that owns the glow may settle it (a stale superseded query must leave
        /// the newer query's comet running).
        /// </summary>
        private static void SearchQueryDrivesTheGlow()
        {
            ThemeManager.Initialize("dark");

            var widget = new SearchWidget(new SearchData());
            var view = widget.PanelView;
            var chrome = widget.FindName("SearchChrome") as WidgetChrome;
            if (chrome == null) chrome = widget.Content as WidgetChrome;
            if (chrome == null) throw new InvalidOperationException("the search widget has no chrome");
            ArrangeChrome(chrome, 422, 562);

            var setGlow = typeof(SearchPanelView).GetMethod("SetQueryGlow",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (setGlow == null) throw new InvalidOperationException("SearchPanelView.SetQueryGlow was not found");
            var settleGlow = typeof(SearchPanelView).GetMethod("SettleQueryGlow",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (settleGlow == null) throw new InvalidOperationException("SearchPanelView.SettleQueryGlow was not found");

            var layer = chrome.FindName("GlowLayer") as Grid;
            if (layer == null) throw new InvalidOperationException("the chrome has no GlowLayer");

            // A fresh widget has never shown its panel: the debounce can tick
            // after the panel collapsed, so a hidden host must not light up.
            setGlow.Invoke(view, new object[] { true });
            if (chrome.IsGlowActive)
            {
                throw new InvalidOperationException("a hidden panel started the query glow");
            }
            if (layer.Visibility != Visibility.Collapsed)
            {
                throw new InvalidOperationException("a hidden panel lit the glow layer");
            }

            // Open the panel: the view is now the owner of the comet.
            SetPrivateBaseField(widget, "_isExpanded", true);

            setGlow.Invoke(view, new object[] { true });
            if (!chrome.IsGlowActive)
            {
                throw new InvalidOperationException("a pending query did not start the panel glow");
            }
            if (layer.Visibility != Visibility.Visible)
            {
                throw new InvalidOperationException("a pending query left the glow layer hidden");
            }

            setGlow.Invoke(view, new object[] { false });
            if (chrome.IsGlowActive)
            {
                throw new InvalidOperationException("a settled query left the panel glow running");
            }
            if (layer.Visibility != Visibility.Collapsed)
            {
                throw new InvalidOperationException("a settled query left the glow layer visible");
            }

            // The generation rule: a superseded query's continuation sees a newer
            // _queryGeneration and must not stop the current comet; the owning
            // generation does.
            setGlow.Invoke(view, new object[] { true });
            if (!chrome.IsGlowActive)
            {
                throw new InvalidOperationException("the second pending query did not start the panel glow");
            }

            int owner = PrivateField<int>(view, "_queryGeneration");
            SetPrivateField(view, "_queryGeneration", owner + 1);
            settleGlow.Invoke(view, new object[] { owner });
            if (!chrome.IsGlowActive)
            {
                throw new InvalidOperationException("a stale query generation settled the panel glow");
            }
            if (layer.Visibility != Visibility.Visible)
            {
                throw new InvalidOperationException("a stale query generation hid the glow layer");
            }

            settleGlow.Invoke(view, new object[] { owner + 1 });
            if (chrome.IsGlowActive)
            {
                throw new InvalidOperationException("the owning query generation did not settle the panel glow");
            }
            if (layer.Visibility != Visibility.Collapsed)
            {
                throw new InvalidOperationException("the owning query generation left the glow layer visible");
            }
        }

        /// <summary>
        /// Task 4: the glow is not query-only. A full scan (Indexing) and the
        /// periodic reconcile (Reconciling) drive it too, so the loading state
        /// shows even when no query runs; the orange progress line stays. The
        /// query flag is the other input: it wins over a Ready status until it
        /// is cleared, and clearing it settles the comet.
        /// </summary>
        private static void SearchReconcileDrivesTheGlow()
        {
            ThemeManager.Initialize("dark");

            var widget = new SearchWidget(new SearchData());
            var view = widget.PanelView;
            var chrome = widget.FindName("SearchChrome") as WidgetChrome;
            if (chrome == null) chrome = widget.Content as WidgetChrome;
            if (chrome == null) throw new InvalidOperationException("the search widget has no chrome");
            ArrangeChrome(chrome, 422, 562);

            var update = typeof(SearchPanelView).GetMethod("UpdateStatus",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (update == null)
            {
                throw new InvalidOperationException("SearchPanelView.UpdateStatus was not found");
            }
            var setGlow = typeof(SearchPanelView).GetMethod("SetQueryGlow",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (setGlow == null) throw new InvalidOperationException("SearchPanelView.SetQueryGlow was not found");

            var layer = chrome.FindName("GlowLayer") as Grid;
            if (layer == null) throw new InvalidOperationException("the chrome has no GlowLayer");

            SetPrivateBaseField(widget, "_isExpanded", true);

            update.Invoke(view, new object[] { new FileSearchStatus { State = FileSearchState.Reconciling } });
            if (!chrome.IsGlowActive)
            {
                throw new InvalidOperationException("a reconcile did not start the panel glow");
            }
            if (layer.Visibility != Visibility.Visible)
            {
                throw new InvalidOperationException("a reconcile left the glow layer hidden");
            }

            update.Invoke(view, new object[] { new FileSearchStatus { State = FileSearchState.Indexing } });
            if (!chrome.IsGlowActive)
            {
                throw new InvalidOperationException("an index scan did not start the panel glow");
            }

            update.Invoke(view, new object[] { new FileSearchStatus { State = FileSearchState.Ready } });
            if (chrome.IsGlowActive)
            {
                throw new InvalidOperationException("a ready index left the panel glow running");
            }
            if (layer.Visibility != Visibility.Collapsed)
            {
                throw new InvalidOperationException("a ready index left the glow layer visible");
            }

            // The query flag is the other input: while it lasts it wins over a
            // Ready status, and clearing it settles the comet.
            setGlow.Invoke(view, new object[] { true });
            if (!chrome.IsGlowActive)
            {
                throw new InvalidOperationException("a pending query did not start the panel glow");
            }
            update.Invoke(view, new object[] { new FileSearchStatus { State = FileSearchState.Ready } });
            if (!chrome.IsGlowActive)
            {
                throw new InvalidOperationException("a Ready status settled a pending query's glow");
            }

            setGlow.Invoke(view, new object[] { false });
            if (chrome.IsGlowActive)
            {
                throw new InvalidOperationException("a settled query left the panel glow running");
            }
            if (layer.Visibility != Visibility.Collapsed)
            {
                throw new InvalidOperationException("a settled query left the glow layer visible");
            }
        }

        /// <summary>
        /// Task 6 (critical): reopening the panel during a real index scan or
        /// reconcile must relight the comet. The real order is the trap:
        /// <see cref="WidgetWindowBase.ShowPanel"/> calls <c>UpdateUI()</c> -
        /// hence RefreshStatus -> UpdateStatus -> UpdateGlowState - while
        /// <c>_isExpanded</c> is still false, so the state is recorded but
        /// nothing is painted; only <c>_isExpanded = true</c> + OnPanelShown
        /// follow. The pin replays exactly that order and requires the glow
        /// after OnPanelShown (and darkness before it).
        /// </summary>
        private static void SearchReopenRelightsTheGlow()
        {
            ThemeManager.Initialize("dark");

            var widget = new SearchWidget(new SearchData());
            var view = widget.PanelView;
            var chrome = widget.FindName("SearchChrome") as WidgetChrome;
            if (chrome == null) chrome = widget.Content as WidgetChrome;
            if (chrome == null) throw new InvalidOperationException("the search widget has no chrome");
            var layer = chrome.FindName("GlowLayer") as Grid;
            if (layer == null) throw new InvalidOperationException("the chrome has no GlowLayer");

            var update = typeof(SearchPanelView).GetMethod("UpdateStatus",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (update == null)
            {
                throw new InvalidOperationException("SearchPanelView.UpdateStatus was not found");
            }
            var shown = typeof(SearchWidget).GetMethod("OnPanelShown",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (shown == null)
            {
                throw new InvalidOperationException("SearchWidget.OnPanelShown was not found");
            }

            // The view's status snapshot comes from its service; a throwaway
            // service (no database file until a scan starts) reports a running
            // full scan, so the refresh path has a live state to read.
            var service = new FileSearchIndexService(IO.Path.Combine(IO.Path.GetTempPath(),
                "kobold-reopen-" + Guid.NewGuid().ToString("N") + ".db"));
            var serviceStatus = PrivateField<FileSearchStatus>(service, "_status");
            serviceStatus.State = FileSearchState.Indexing;
            SetPrivateField(view, "_service", service);

            // The scan state is known while the panel is still closed.
            update.Invoke(view, new object[] { service.Status });

            // ShowPanel's own first step, with the panel still closed.
            SetPrivateBaseField(widget, "_isExpanded", false);
            widget.UpdateUI();
            if (chrome.IsGlowActive || layer.Visibility != Visibility.Collapsed)
            {
                throw new InvalidOperationException("a closed panel lit the scan glow");
            }

            // ... and then the panel really opens.
            SetPrivateBaseField(widget, "_isExpanded", true);
            shown.Invoke(widget, new object[0]);
            if (!chrome.IsGlowActive)
            {
                throw new InvalidOperationException(
                    "reopening the panel mid-scan did not relight the glow");
            }
            if (layer.Visibility != Visibility.Visible)
            {
                throw new InvalidOperationException(
                    "reopening the panel mid-scan left the glow layer hidden");
            }
        }

        /// <summary>
        /// Task 6: the scan-progress gate. A progress snapshot only rewrites the
        /// status line while the view state is Indexing or Reconciling - the
        /// count line follows the snapshot's own counters - and is ignored in
        /// every other state (a ready line must survive a late progress event),
        /// while a reconcile keeps its own label. The gate is
        /// <c>ApplyProgress</c>, the body of the handler's dispatcher callback;
        /// the pin drives it directly, because pumping the queue here would run
        /// a pending application-shutdown callback (queued by an earlier island
        /// pin when the last window closed) and kill the rest of the run. The
        /// event adapter is checked on the side: raising it must not write.
        /// </summary>
        private static void SearchProgressOnlyRefreshesAnIndexLine()
        {
            ThemeManager.Initialize("dark");

            var view = new SearchWidget(new SearchData()).PanelView;
            var status = view.FindName("StatusText") as TextBlock;
            if (status == null) throw new InvalidOperationException("the search status line is missing");

            var update = typeof(SearchPanelView).GetMethod("UpdateStatus",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (update == null)
            {
                throw new InvalidOperationException("SearchPanelView.UpdateStatus was not found");
            }
            var apply = typeof(SearchPanelView).GetMethod("ApplyProgress",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (apply == null)
            {
                throw new InvalidOperationException("SearchPanelView.ApplyProgress was not found");
            }
            var handler = typeof(SearchPanelView).GetMethod("Service_ProgressChanged",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (handler == null)
            {
                throw new InvalidOperationException("SearchPanelView.Service_ProgressChanged was not found");
            }

            var scan = new ScanProgress { Files = 12, Directories = 4 };

            update.Invoke(view, new object[] { new FileSearchStatus { State = FileSearchState.Indexing } });
            string zeroLine = Localization.Format("Search_Indexing", 0, 0);
            if (status.Text != zeroLine)
            {
                throw new InvalidOperationException(
                    "the indexing line is '" + status.Text + "', wanted '" + zeroLine + "'");
            }

            // The status snapshot was built without counters, so the count line
            // can only come from the progress snapshot.
            apply.Invoke(view, new object[] { scan });
            string counted = Localization.Format("Search_Indexing", 12, 4);
            if (status.Text != counted)
            {
                throw new InvalidOperationException(
                    "a scan progress snapshot left the count line at '" + status.Text
                    + "', wanted '" + counted + "'");
            }

            // The event is the marshalled entry point: it may only post, so the
            // line stays where it was until the callback runs.
            handler.Invoke(view, new object[] { null, new ScanProgress { Files = 99, Directories = 9 } });
            if (status.Text != counted)
            {
                throw new InvalidOperationException(
                    "a scan progress event wrote the line on the raising thread ('" + status.Text + "')");
            }

            // A ready line is not an index state: a late progress snapshot must
            // not overwrite it with stale counters.
            update.Invoke(view, new object[] { new FileSearchStatus { State = FileSearchState.Ready } });
            string ready = status.Text;
            apply.Invoke(view, new object[] { new ScanProgress { Files = 99, Directories = 9 } });
            if (status.Text != ready)
            {
                throw new InvalidOperationException(
                    "a scan progress snapshot overwrote the ready line ('" + status.Text
                    + "' instead of '" + ready + "')");
            }

            // A reconcile reports its own label, never the indexing counters.
            update.Invoke(view, new object[] { new FileSearchStatus { State = FileSearchState.Reconciling } });
            apply.Invoke(view, new object[] { new ScanProgress { Files = 99, Directories = 9 } });
            string reconciling = Localization.Get("Search_Reconciling");
            if (status.Text != reconciling)
            {
                throw new InvalidOperationException(
                    "a reconcile shows '" + status.Text + "' after a progress snapshot, wanted '"
                    + reconciling + "'");
            }
            if (status.Text == Localization.Format("Search_Indexing", 99, 9))
            {
                throw new InvalidOperationException(
                    "a reconcile shows the indexing counters after a progress snapshot");
            }
        }

        /// <summary>
        /// Task 3: Space on a selected result previews it through QuickLook. The
        /// decision lives in TryPreviewSelected so the pin can drive it with a
        /// selected row instead of synthesising key events. A directory, a
        /// missing path, no selection and a refused request all return false so
        /// Space stays unhandled for the scroller.
        /// </summary>
        private static void SearchSpacePreviewsSelectedResult()
        {
            ThemeManager.Initialize("dark");

            var widget = new SearchWidget(new SearchData());
            var view = widget.PanelView;
            var list = view.FindName("ResultsList") as ListBox;
            if (list == null) throw new InvalidOperationException("the search panel has no ResultsList");

            var requestProperty = typeof(SearchPanelView).GetProperty("PreviewRequestForChecks",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (requestProperty == null)
            {
                throw new InvalidOperationException("SearchPanelView.PreviewRequestForChecks was not found");
            }
            var tryPreview = typeof(SearchPanelView).GetMethod("TryPreviewSelected",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (tryPreview == null)
            {
                throw new InvalidOperationException("SearchPanelView.TryPreviewSelected was not found");
            }

            string file = IO.Path.Combine(IO.Path.GetTempPath(), "kobold-preview-" + Guid.NewGuid().ToString("N") + ".txt");
            string directory = IO.Path.Combine(IO.Path.GetTempPath(), "kobold-preview-" + Guid.NewGuid().ToString("N"));
            string missing = IO.Path.Combine(IO.Path.GetTempPath(), "kobold-preview-" + Guid.NewGuid().ToString("N") + ".txt");

            IO.Directory.CreateDirectory(directory);
            IO.File.WriteAllText(file, "preview");

            // Task 7 fix round 1: a successful preview records one frequent-file
            // entry, a refused request records none. Run on a cleared list in the
            // sandbox config and restore the saved block afterwards.
            AppConfig config = WidgetManager.Instance.Config;
            List<FrequentFile> savedFrequent = config.FrequentFiles;
            try
            {
                config.FrequentFiles = null;

                // The row must be in the list for the selection to stick.
                var rows = new List<SearchResultRow>();
                list.ItemsSource = rows;

                string seen = null;
                requestProperty.SetValue(view, new Func<string, bool>(
                    p => { seen = p; return true; }));

                if (!SelectAndPreview(list, rows, tryPreview, view,
                        new SearchResultRow { Entry = new SearchEntry { Path = file, IsDirectory = false } }))
                {
                    throw new InvalidOperationException("a selected file result was not previewed");
                }
                if (!string.Equals(seen, file, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "the preview got '" + seen + "', wanted '" + file + "'");
                }
                if (config.FrequentFiles == null || config.FrequentFiles.Count != 1
                    || !string.Equals(config.FrequentFiles[0].Path, file,
                        StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        "a previewed file was not recorded as one frequent-file entry");
                }

                seen = null;
                if (SelectAndPreview(list, rows, tryPreview, view,
                        new SearchResultRow { Entry = new SearchEntry { Path = directory, IsDirectory = true } }))
                {
                    throw new InvalidOperationException("a directory result was previewed");
                }
                if (seen != null) throw new InvalidOperationException("a directory reached QuickLook ('" + seen + "')");

                seen = null;
                if (SelectAndPreview(list, rows, tryPreview, view,
                        new SearchResultRow { Entry = new SearchEntry { Path = missing, IsDirectory = false } }))
                {
                    throw new InvalidOperationException("a missing path was previewed");
                }
                if (seen != null) throw new InvalidOperationException("a missing path reached QuickLook ('" + seen + "')");

                rows.Clear();
                list.SelectedItem = null;
                if ((bool)tryPreview.Invoke(view, null))
                {
                    throw new InvalidOperationException("Space was handled with no selection");
                }

                // A row with no entry (or no path) is not previewable either.
                if (SelectAndPreview(list, rows, tryPreview, view, new SearchResultRow()))
                {
                    throw new InvalidOperationException("an empty row was previewed");
                }

                // QuickLook refusing (not installed) must leave Space to the
                // scroller: the handled flag follows the request's answer.
                string refused = null;
                config.FrequentFiles = null;
                requestProperty.SetValue(view, new Func<string, bool>(
                    p => { refused = p; return false; }));
                if (SelectAndPreview(list, rows, tryPreview, view,
                        new SearchResultRow { Entry = new SearchEntry { Path = file, IsDirectory = false } }))
                {
                    throw new InvalidOperationException("a refused preview marked Space handled");
                }
                if (!string.Equals(refused, file, StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "the refused preview got '" + refused + "', wanted '" + file + "'");
                }
                if (config.FrequentFiles != null)
                {
                    throw new InvalidOperationException(
                        "a refused preview was recorded as a frequent file");
                }
            }
            finally
            {
                config.FrequentFiles = savedFrequent;
                requestProperty.SetValue(view, null);
                try { IO.File.Delete(file); } catch (Exception) { }
                try { IO.Directory.Delete(directory, true); } catch (Exception) { }
            }
        }

        /// <summary>Puts one row in the result list, selects it and asks the view.</summary>
        private static bool SelectAndPreview(ListBox list, List<SearchResultRow> rows, MethodInfo tryPreview,
            SearchPanelView view, SearchResultRow row)
        {
            rows.Clear();
            rows.Add(row);
            list.SelectedItem = row;
            return (bool)tryPreview.Invoke(view, null);
        }

        /// <summary>
        /// Task 1 (2026-10-27): an empty query lists the frequent files. The
        /// caption above the results is visible and localized, the rows come
        /// from FrequentFiles.Top (count desc, capped at ten) with the parent
        /// directory as their path, every dispatchable state (Ready, Indexing,
        /// Reconciling) keeps them, typing hides the caption at once, a query
        /// swallowed by a state panel never repaints them under its text, and
        /// ClearResults / an empty usage list leave nothing behind.
        /// </summary>
        private static void SearchEmptyQueryListsFrequentFiles()
        {
            ThemeManager.Initialize("dark");

            var widget = new SearchWidget(new SearchData());
            var view = widget.PanelView;
            var list = view.FindName("ResultsList") as ListBox;
            if (list == null) throw new InvalidOperationException("the search panel has no ResultsList");
            var box = view.FindName("SearchBox") as TextBox;
            if (box == null) throw new InvalidOperationException("the search panel has no SearchBox");
            var header = view.FindName("FrequentHeader") as TextBlock;
            if (header == null) throw new InvalidOperationException("the search panel has no FrequentHeader");

            var updateStatus = typeof(SearchPanelView).GetMethod("UpdateStatus",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (updateStatus == null)
            {
                throw new InvalidOperationException("SearchPanelView.UpdateStatus was not found");
            }
            var clearResults = typeof(SearchPanelView).GetMethod("ClearResults",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (clearResults == null)
            {
                throw new InvalidOperationException("SearchPanelView.ClearResults was not found");
            }

            // The view is attached by the widget's constructor: the box's
            // TextChanged path runs for real. Every status is driven by hand so
            // nothing depends on a scan, and the debounce stays parked so no
            // stray RunQuery rewrites the list between assertions.
            Action<FileSearchState> showState = state => updateStatus.Invoke(view,
                new object[] { new FileSearchStatus { State = state } });
            var debounce = PrivateField<System.Windows.Threading.DispatcherTimer>(view, "_debounce");

            string directory = IO.Path.Combine(IO.Path.GetTempPath(),
                "kobold-frequent-" + Guid.NewGuid().ToString("N"));
            IO.Directory.CreateDirectory(directory);
            string alpha = IO.Path.Combine(directory, "alpha.txt");
            string beta = IO.Path.Combine(directory, "beta.txt");
            IO.File.WriteAllText(alpha, "alpha");
            IO.File.WriteAllText(beta, "beta");

            AppConfig config = WidgetManager.Instance.Config;
            List<FrequentFile> savedFrequent = config.FrequentFiles;
            try
            {
                // beta leads on count; the timestamps only keep the order
                // unambiguous should the count ever tie.
                var twoFiles = new List<FrequentFile>
                {
                    new FrequentFile
                    {
                        Path = alpha,
                        Count = 1,
                        LastOpenedUtc = DateTime.UtcNow.AddDays(-2)
                    },
                    new FrequentFile
                    {
                        Path = beta,
                        Count = 5,
                        LastOpenedUtc = DateTime.UtcNow
                    }
                };
                config.FrequentFiles = twoFiles;

                showState(FileSearchState.Ready);

                if (header.Visibility != Visibility.Visible)
                {
                    throw new InvalidOperationException(
                        "the frequent header is " + header.Visibility + " with two frequent files");
                }
                if (header.Text != Localization.Get("Search_Frequent"))
                {
                    throw new InvalidOperationException(
                        "the frequent header shows '" + header.Text + "', wanted '"
                        + Localization.Get("Search_Frequent") + "'");
                }

                if (list.Items.Count != 2)
                {
                    throw new InvalidOperationException(
                        "the empty query lists " + list.Items.Count + " row(s), wanted 2");
                }

                var first = list.Items[0] as SearchResultRow;
                var second = list.Items[1] as SearchResultRow;
                if (first == null || first.Name != "beta.txt")
                {
                    throw new InvalidOperationException("the first frequent row is '"
                        + (first == null ? "null" : first.Name) + "', wanted beta.txt");
                }
                if (second == null || second.Name != "alpha.txt")
                {
                    throw new InvalidOperationException("the second frequent row is '"
                        + (second == null ? "null" : second.Name) + "', wanted alpha.txt");
                }
                if (first.Path != directory || second.Path != directory)
                {
                    throw new InvalidOperationException("a frequent row points at '" + first.Path
                        + "' / '" + second.Path + "', wanted '" + directory + "'");
                }

                // Indexing and reconciling are dispatchable (CanDispatchQuery),
                // so an empty query keeps its frequent list there too - the
                // state line must not wipe it.
                clearResults.Invoke(view, null);
                showState(FileSearchState.Indexing);
                AssertFrequentShown(header, list, 2, "while indexing");
                showState(FileSearchState.Reconciling);
                AssertFrequentShown(header, list, 2, "while reconciling");

                // The caption belongs to an empty query only: it leaves as soon
                // as the text stops being empty, before the debounce dispatches.
                box.Text = "x";
                debounce.Stop();
                if (header.Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException(
                        "the frequent header is " + header.Visibility + " while the box holds text");
                }
                box.Text = string.Empty;
                debounce.Stop();

                clearResults.Invoke(view, null);

                if (header.Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException(
                        "the frequent header is " + header.Visibility + " after ClearResults");
                }
                if (list.Items.Count != 0)
                {
                    throw new InvalidOperationException(
                        "the result list keeps " + list.Items.Count + " row(s) after ClearResults");
                }

                // The state panels keep priority: a non-dispatchable state
                // clears the rows and the caption (no frequent list behind it).
                showState(FileSearchState.NoIndex);
                if (header.Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException(
                        "the frequent header is " + header.Visibility + " in the no-index state");
                }
                if (list.Items.Count != 0)
                {
                    throw new InvalidOperationException(
                        "the no-index state keeps " + list.Items.Count + " frequent row(s)");
                }

                // No remembered files: the caption would label an empty list,
                // so it stays hidden and the list stays empty.
                config.FrequentFiles = new List<FrequentFile>();
                showState(FileSearchState.Ready);
                if (header.Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException(
                        "the frequent header is " + header.Visibility + " with no frequent files");
                }
                if (list.Items.Count != 0)
                {
                    throw new InvalidOperationException(
                        "the empty frequent list shows " + list.Items.Count + " row(s)");
                }

                // The cap: eleven real files with descending counts must yield
                // the ten most used, in count order, and drop the one-off.
                config.FrequentFiles = new List<FrequentFile>();
                for (int i = 1; i <= 11; i++)
                {
                    string path = IO.Path.Combine(directory, "cap-" + i.ToString("D2") + ".txt");
                    IO.File.WriteAllText(path, "cap");
                    config.FrequentFiles.Add(new FrequentFile
                    {
                        Path = path,
                        Count = 12 - i,
                        LastOpenedUtc = DateTime.UtcNow
                    });
                }
                showState(FileSearchState.Ready);

                AssertFrequentShown(header, list, 10, "with eleven frequent files");
                var capFirst = list.Items[0] as SearchResultRow;
                if (capFirst == null || capFirst.Name != "cap-01.txt")
                {
                    throw new InvalidOperationException("the most-used frequent row is '"
                        + (capFirst == null ? "null" : capFirst.Name) + "', wanted cap-01.txt");
                }
                foreach (object item in list.Items)
                {
                    var row = item as SearchResultRow;
                    if (row != null && row.Name == "cap-11.txt")
                    {
                        throw new InvalidOperationException(
                            "the one-off file cap-11.txt is in the top-ten frequent list");
                    }
                }

                // A query typed while a state panel swallowed it never
                // dispatched, so the text stays in the box. A later status must
                // not repaint the frequent rows under that non-empty text.
                // The state panel has already cleared the list, as in life.
                config.FrequentFiles = twoFiles;
                clearResults.Invoke(view, null);
                box.Text = "x";
                debounce.Stop();
                showState(FileSearchState.Ready);

                if (header.Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException(
                        "the frequent header is " + header.Visibility + " with text in the box");
                }
                if (list.Items.Count != 0)
                {
                    throw new InvalidOperationException(
                        "the frequent list paints " + list.Items.Count + " row(s) with text in the box");
                }

                // Clearing the box brings the list back on the next status.
                box.Text = string.Empty;
                debounce.Stop();
                showState(FileSearchState.Ready);

                AssertFrequentShown(header, list, 2, "after the text was cleared");
                var restored = list.Items[0] as SearchResultRow;
                if (restored == null || restored.Name != "beta.txt")
                {
                    throw new InvalidOperationException("the restored frequent row is '"
                        + (restored == null ? "null" : restored.Name) + "', wanted beta.txt");
                }
            }
            finally
            {
                config.FrequentFiles = savedFrequent;
                try { IO.Directory.Delete(directory, true); } catch (Exception) { }
            }
        }

        /// <summary>
        /// Task 2 (2026-10-27): the result menu belongs to a row, not the list.
        /// The list carries no ContextMenu; the seam resolves a real row
        /// container and rejects the list (blank space, scrollbar) and a null
        /// source; the keyboard seam answers Apps / Shift+F10 for the selected
        /// row only (including the Key.System form WPF delivers for Shift+F10;
        /// Space stays QuickLook) but never opens anything; the built
        /// menu keeps the three localized entries while the empty list / a
        /// selected row toggles their enabled state. The Opened route is raised,
        /// never opened, so the check flashes no popup.
        /// </summary>
        private static void SearchResultMenuRequiresTarget()
        {
            ThemeManager.Initialize("dark");

            var widget = new SearchWidget(new SearchData());
            var view = widget.PanelView;
            var list = view.FindName("ResultsList") as ListBox;
            if (list == null) throw new InvalidOperationException("the search panel has no ResultsList");

            // Only a right-click on a result row may open the menu: nothing
            // may hang off the list itself.
            if (list.ContextMenu != null)
            {
                throw new InvalidOperationException(
                    "ResultsList carries a ContextMenu, so a right-click on blank space opens it");
            }

            var seam = typeof(SearchPanelView).GetMethod("ResultMenuTarget",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (seam == null)
            {
                throw new InvalidOperationException("SearchPanelView.ResultMenuTarget was not found");
            }

            var kept = typeof(SearchPanelView).GetField("_resultMenu",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (kept == null)
            {
                throw new InvalidOperationException("SearchPanelView._resultMenu was not found");
            }
            var assigned = kept.GetValue(view) as ContextMenu;
            if (assigned == null)
            {
                throw new InvalidOperationException("the view keeps no built result menu");
            }

            var rows = new List<SearchResultRow>
            {
                new SearchResultRow
                {
                    Entry = new SearchEntry { Path = @"C:\results\alpha.txt", IsDirectory = false },
                    IconId = IconId.File,
                    Name = "alpha.txt",
                    Path = @"C:\results",
                    SizeText = "1 KB",
                    ModifiedText = "2026-10-27 10:00"
                },
                new SearchResultRow
                {
                    Entry = new SearchEntry { Path = @"C:\results\beta.txt", IsDirectory = false },
                    IconId = IconId.File,
                    Name = "beta.txt",
                    Path = @"C:\results",
                    SizeText = "2 KB",
                    ModifiedText = "2026-10-27 11:00"
                }
            };
            list.ItemsSource = rows;

            // Realize a row container: the list must have a finite viewport
            // before the generator produces anything. The view is never shown.
            view.Measure(new Size(422, 562));
            view.Arrange(new Rect(0, 0, 422, 562));
            list.ApplyTemplate();
            view.UpdateLayout();

            var container = list.ItemContainerGenerator.ContainerFromIndex(0) as ListBoxItem;
            if (container == null)
            {
                throw new InvalidOperationException("the result list generated no container for the first row");
            }

            // Blank space / the scrollbar (the list itself), or no source at
            // all, is not a target; the right-clicked row container is.
            if (seam.Invoke(view, new object[] { list }) != null)
            {
                throw new InvalidOperationException("the seam gave the list itself as a menu target");
            }
            if (seam.Invoke(view, new object[] { null }) != null)
            {
                throw new InvalidOperationException("the seam gave a menu target for a null source");
            }
            if (!ReferenceEquals(seam.Invoke(view, new object[] { container }), container))
            {
                throw new InvalidOperationException("the seam lost the row container that was right-clicked");
            }

            // Keyboard invocation: Apps / Shift+F10 open the menu for the
            // selected row only; Space stays QuickLook's key. Shift+F10 reaches
            // WPF as Key.System with SystemKey F10, so the seam takes both
            // forms. The seam decides, so no synthetic key event and no popup.
            var keys = typeof(SearchPanelView).GetMethod("ResultMenuKeyboardTarget",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (keys == null)
            {
                throw new InvalidOperationException("SearchPanelView.ResultMenuKeyboardTarget was not found");
            }
            if (keys.GetParameters().Length != 3)
            {
                throw new InvalidOperationException(
                    "ResultMenuKeyboardTarget takes " + keys.GetParameters().Length
                    + " parameter(s), wanted (key, systemKey, modifiers)");
            }

            list.SelectedIndex = 0;
            if (!ReferenceEquals(keys.Invoke(view, new object[] { Key.Apps, Key.None, ModifierKeys.None }), container))
            {
                throw new InvalidOperationException("Apps did not target the selected row's container");
            }
            if (!ReferenceEquals(keys.Invoke(view, new object[] { Key.F10, Key.None, ModifierKeys.Shift }), container))
            {
                throw new InvalidOperationException("Shift+F10 did not target the selected row's container");
            }
            if (!ReferenceEquals(keys.Invoke(view, new object[] { Key.System, Key.F10, ModifierKeys.Shift }), container))
            {
                throw new InvalidOperationException("the System form of Shift+F10 did not target the row container");
            }
            if (keys.Invoke(view, new object[] { Key.System, Key.F10, ModifierKeys.None }) != null)
            {
                throw new InvalidOperationException("the System form of a bare F10 was treated as a menu key");
            }
            if (!ReferenceEquals(keys.Invoke(view, new object[] { Key.System, Key.Apps, ModifierKeys.None }), container))
            {
                throw new InvalidOperationException("the System form of Apps did not target the row container");
            }

            list.SelectedItem = null;
            if (keys.Invoke(view, new object[] { Key.Apps, Key.None, ModifierKeys.None }) != null)
            {
                throw new InvalidOperationException("the keyboard menu opened with no selection");
            }

            list.SelectedIndex = 0;
            if (keys.Invoke(view, new object[] { Key.Space, Key.None, ModifierKeys.None }) != null)
            {
                throw new InvalidOperationException("Space is treated as a menu key instead of QuickLook");
            }
            if (assigned.IsOpen)
            {
                throw new InvalidOperationException("the keyboard checks opened the result menu");
            }

            // The production handler runs the same seam: a right-click on the
            // list itself (blank space) opens nothing and stays unhandled. A
            // row target would open the real popup, so it is not driven here.
            var rightUp = typeof(SearchPanelView).GetMethod("ResultsList_PreviewMouseRightButtonUp",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (rightUp == null)
            {
                throw new InvalidOperationException("SearchPanelView.ResultsList_PreviewMouseRightButtonUp was not found");
            }
            var press = new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Right)
            {
                RoutedEvent = UIElement.PreviewMouseRightButtonUpEvent
            };
            list.RaiseEvent(press);
            if (press.Handled)
            {
                throw new InvalidOperationException("a right-click on blank space marked the event handled");
            }
            if (assigned.IsOpen)
            {
                throw new InvalidOperationException("a right-click on blank space opened the result menu");
            }

            var build = typeof(SearchPanelView).GetMethod("BuildResultMenu",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (build == null)
            {
                throw new InvalidOperationException("SearchPanelView.BuildResultMenu was not found");
            }
            var menu = (ContextMenu)build.Invoke(view, null);

            string[] headers =
            {
                Localization.Get("Search_Open"),
                Localization.Get("Search_OpenLocation"),
                Localization.Get("Search_CopyPath")
            };
            if (menu.Items.Count != headers.Length)
            {
                throw new InvalidOperationException(
                    "the result menu has " + menu.Items.Count + " item(s), wanted " + headers.Length);
            }
            for (int i = 0; i < headers.Length; i++)
            {
                var item = menu.Items[i] as MenuItem;
                if (item == null || !Equals(item.Header, headers[i]))
                {
                    throw new InvalidOperationException(
                        "result menu entry " + i + " is not '" + headers[i] + "'");
                }
            }

            // The Opened handler is the state seam: raise it without opening.
            list.SelectedItem = null;
            menu.RaiseEvent(new RoutedEventArgs(ContextMenu.OpenedEvent, menu));
            for (int i = 0; i < headers.Length; i++)
            {
                AssertMenuItem(menu, headers[i], false, "the result menu with no selection");
            }

            list.SelectedIndex = 0;
            menu.RaiseEvent(new RoutedEventArgs(ContextMenu.OpenedEvent, menu));
            for (int i = 0; i < headers.Length; i++)
            {
                AssertMenuItem(menu, headers[i], true, "the result menu with a selected row");
            }

            if (assigned.IsOpen)
            {
                throw new InvalidOperationException("the result menu was opened by the check");
            }
        }

        /// <summary>The frequent caption is visible and the list holds exactly <paramref name="count"/> rows.</summary>
        private static void AssertFrequentShown(TextBlock header, ListBox list, int count, string when)
        {
            if (header.Visibility != Visibility.Visible)
            {
                throw new InvalidOperationException(
                    "the frequent header is " + header.Visibility + " " + when + ", wanted Visible");
            }
            if (list.Items.Count != count)
            {
                throw new InvalidOperationException(
                    "the empty query lists " + list.Items.Count + " row(s) " + when
                    + ", wanted " + count);
            }
        }

        private static Path GlowPath(WidgetChrome chrome, string name)
        {
            var path = chrome.FindName(name) as Path;
            if (path == null) throw new InvalidOperationException("the chrome has no " + name);
            return path;
        }

        private static DoubleAnimation GlowAnimation(WidgetChrome chrome, Path path)
        {
            var animations = PrivateField<Dictionary<Path, DoubleAnimation>>(chrome, "_glowAnimations");
            if (animations == null) return null;
            DoubleAnimation animation;
            return animations.TryGetValue(path, out animation) ? animation : null;
        }

        /// <summary>
        /// The perimeter of a rounded rectangle: the four straight runs plus the
        /// four quarter-circle corners.
        /// </summary>
        private static double RingPerimeter(RectangleGeometry geometry)
        {
            Rect rect = geometry.Rect;
            double radius = geometry.RadiusX;
            return 2 * (rect.Width + rect.Height) - 8 * radius + 2 * Math.PI * radius;
        }

        private static bool ContainsTextBlock(DependencyObject root)
        {
            if (root is TextBlock) return true;

            int children = VisualTreeHelper.GetChildrenCount(root);
            for (int i = 0; i < children; i++)
            {
                if (ContainsTextBlock(VisualTreeHelper.GetChild(root, i))) return true;
            }
            return false;
        }

        private static ControlTemplate TemplateOf(Style style)
        {
            foreach (Setter setter in style.Setters)
            {
                if (setter.Property == Control.TemplateProperty) return setter.Value as ControlTemplate;
            }
            return null;
        }

        /// <summary>
        /// Smoke fix round 2/6: the native TextBox focus border/selection and
        /// the selected row think in the widget's own colour. The view replaces
        /// its local SearchAccent and Kobold.Brush.Accent with a frozen brush
        /// from SearchData.Color during Attach.
        /// Fix round 3: a live colour change (menu -> RefreshTheme -> UpdateUI)
        /// repaints the same view through RefreshAccent.
        /// </summary>
        private static void SearchAccentFollowsWidgetColor()
        {
            ThemeManager.Initialize("dark");
            const string orange = "#F97316";
            var data = new SearchData { Color = orange };
            var widget = new SearchWidget(data);
            var view = widget.PanelView;

            var accent = view.Resources["SearchAccent"] as SolidColorBrush;
            if (accent == null)
            {
                throw new InvalidOperationException(
                    "the view did not replace its SearchAccent brush");
            }
            Color wanted = Utils.HexToColor(orange);
            if (accent.Color != wanted)
            {
                throw new InvalidOperationException(
                    "the widget accent is " + accent.Color + ", wanted " + wanted);
            }
            if (!ReferenceEquals(view.Resources["Kobold.Brush.Accent"], accent))
            {
                throw new InvalidOperationException(
                    "the native TextBox accent was not overridden with the widget colour");
            }

            // The menu's colour picker only calls RefreshTheme -> UpdateUI, so
            // the same live view must pick the new colour up without a restart.
            const string green = "#22C55E";
            data.Color = green;
            widget.UpdateUI();

            Color wantedGreen = Utils.HexToColor(green);
            var repainted = view.Resources["SearchAccent"] as SolidColorBrush;
            if (repainted == null || repainted.Color != wantedGreen)
            {
                throw new InvalidOperationException(
                    "a live colour change left the accent at "
                    + DescribeBrush(repainted) + ", wanted " + wantedGreen);
            }
            if (!ReferenceEquals(view.Resources["Kobold.Brush.Accent"], repainted))
            {
                throw new InvalidOperationException(
                    "a live colour change left the native TextBox accent behind");
            }
        }

        /// <summary>
        /// Fix round 3: high contrast must follow the theme's accent resource
        /// (the system highlight), not the fixed brand blue. The state has no
        /// public setter (it comes from SystemParameters), so the check forces
        /// <see cref="ThemeManager.IsHighContrast"/> through its private setter
        /// and swaps the app accent for a sentinel brush - the lookup itself is
        /// what gets pinned. Both are restored in the finally block, so the pin
        /// does not depend on the machine's contrast setting.
        /// </summary>
        private static void SearchAccentFollowsSystemAccent()
        {
            ThemeManager.Initialize("dark");

            PropertyInfo property = typeof(ThemeManager).GetProperty(
                "IsHighContrast", BindingFlags.Static | BindingFlags.Public);
            MethodInfo setter = property == null ? null : property.GetSetMethod(true);
            if (setter == null)
            {
                throw new InvalidOperationException("ThemeManager.IsHighContrast has no setter");
            }

            var resources = Application.Current == null ? null : Application.Current.Resources;
            if (resources == null)
            {
                throw new InvalidOperationException("the app resources are missing");
            }

            var sentinel = new SolidColorBrush(Utils.HexToColor("#00FF7F"));
            sentinel.Freeze();
            object installed = resources["Kobold.Brush.Accent"];

            var view = new SearchWidget(new SearchData { Color = "#F97316" }).PanelView;
            try
            {
                setter.Invoke(null, new object[] { true });
                resources["Kobold.Brush.Accent"] = sentinel;
                view.RefreshAccent();

                var accent = view.Resources["SearchAccent"] as SolidColorBrush;
                if (accent == null || !ReferenceEquals(accent, sentinel))
                {
                    throw new InvalidOperationException(
                        "the high-contrast accent is '" + DescribeBrush(accent)
                        + "', wanted the theme accent resource");
                }
                if (ReferenceEquals(accent, ThemeManager.AccentBlueBrush))
                {
                    throw new InvalidOperationException(
                        "high contrast kept the fixed brand blue instead of the theme accent");
                }
                if (!ReferenceEquals(view.Resources["Kobold.Brush.Accent"], sentinel))
                {
                    throw new InvalidOperationException(
                        "high contrast did not give the native TextBox the theme accent");
                }
            }
            finally
            {
                resources["Kobold.Brush.Accent"] = installed;
                setter.Invoke(null, new object[] { false });
                ThemeManager.Initialize("dark"); // rebuild the live theme brushes
            }
        }

        private static string DescribeBrush(Brush brush)
        {
            var solid = brush as SolidColorBrush;
            if (solid != null) return solid.Color.ToString();
            return brush == null ? "null" : brush.GetType().Name;
        }

        /// <summary>
        /// Smoke fix: dragging a result row publishes the plain FileDrop list
        /// Explorer and the folder widget already understand - one entry, the
        /// row's own path, for a file and for a directory.
        /// </summary>
        private static void SearchDragPayloadCarriesFileDrop()
        {
            const string file = @"C:\work\report.pdf";
            DataObject filePayload = SearchDragPayload.Create(file);
            if (!filePayload.GetDataPresent(DataFormats.FileDrop, true))
            {
                throw new InvalidOperationException("the drag payload carries no FileDrop list");
            }
            StringCollection files = filePayload.GetFileDropList();
            if (files == null || files.Count != 1 || files[0] != file)
            {
                throw new InvalidOperationException(
                    "the drag payload lost its single path (count="
                    + (files == null ? "null" : files.Count.ToString()) + ")");
            }

            const string folder = @"C:\work\folder\";
            DataObject folderPayload = SearchDragPayload.Create(folder);
            StringCollection folders = folderPayload.GetFileDropList();
            if (folders == null || folders.Count != 1 || folders[0] != folder)
            {
                throw new InvalidOperationException(
                    "a directory drag lost its path (count="
                    + (folders == null ? "null" : folders.Count.ToString()) + ")");
            }
        }

        /// <summary>
        /// Smoke fix: rebuild / later use the secondary style and the two start
        /// buttons the primary style - the same instances the rest of the app
        /// resolves from the app resources. Task 6: the clear button is gone, so
        /// it has no style to assert.
        /// </summary>
        private static void SearchButtonsUseAppStyles()
        {
            ThemeManager.Initialize("dark");
            var view = new SearchWidget(new SearchData()).PanelView;

            AssertButtonStyle(view, "RebuildButton", "Kobold.Style.SecondaryButton");
            AssertButtonStyle(view, "StartIndexButton", "Kobold.Style.PrimaryButton");
            AssertButtonStyle(view, "OnboardingStartButton", "Kobold.Style.PrimaryButton");
            AssertButtonStyle(view, "OnboardingLaterButton", "Kobold.Style.SecondaryButton");
        }

        private static void AssertButtonStyle(SearchPanelView view, string name, string styleKey)
        {
            var button = view.FindName(name) as Button;
            if (button == null)
            {
                throw new InvalidOperationException("the search panel has no " + name);
            }

            var wanted = Application.Current.TryFindResource(styleKey) as Style;
            if (wanted == null)
            {
                throw new InvalidOperationException("the app resources have no " + styleKey);
            }
            if (!ReferenceEquals(button.Style, wanted))
            {
                throw new InvalidOperationException(
                    name + " does not wear " + styleKey
                    + " (style=" + (button.Style == null ? "null" : "another instance") + ")");
            }
        }

        /// <summary>
        /// Smoke fix: the row template replaces the default blue ListBoxItem
        /// selection with a themed row - primary ink for the name/glyph,
        /// secondary for path/size/time, the secondary surface on hover and the
        /// control background plus an accent border while selected. The row is
        /// built offscreen and the resolved brushes are compared with the live
        /// theme, so a static colour cannot pass.
        /// </summary>
        private static void SearchRowStyleUsesThemeBrushes()
        {
            ThemeManager.Initialize("dark");
            var view = new SearchWidget(new SearchData()).PanelView;
            var list = view.FindName("ResultsList") as ListBox;
            if (list == null)
            {
                throw new InvalidOperationException("the search panel has no ResultsList");
            }
            if (list.ItemContainerStyle == null)
            {
                throw new InvalidOperationException("the result list has no item container style");
            }

            var row = new SearchResultRow
            {
                Entry = new SearchEntry { Path = @"C:\work\report.pdf", Name = "report.pdf" },
                IconId = IconId.File,
                IconBrush = Brushes.Black,
                Name = "report.pdf",
                Path = @"C:\work",
                SizeText = "12 KB",
                ModifiedText = "2026-10-26 10:00"
            };

            var container = new ListBoxItem
            {
                Style = list.ItemContainerStyle,
                Content = row,
                ContentTemplate = list.ItemTemplate
            };
            var host = new Grid();
            // The row style's selected border asks for the view-local
            // SearchAccent; mirror it onto the offscreen host so the lookup
            // resolves exactly as it does inside the panel.
            var accent = view.Resources["SearchAccent"];
            if (accent != null) host.Resources["SearchAccent"] = accent;
            host.Children.Add(container);
            host.Measure(new Size(360, 44));
            host.Arrange(new Rect(0, 0, 360, 44));
            host.UpdateLayout();
            container.ApplyTemplate();

            var frame = container.Template.FindName("Row", container) as Border;
            if (frame == null)
            {
                throw new InvalidOperationException("the row template has no themed Row border");
            }
            if (frame.BorderThickness.Left != 1 || frame.CornerRadius.TopLeft != 6)
            {
                throw new InvalidOperationException(
                    "the row border is " + frame.BorderThickness.Left + "px / radius "
                    + frame.CornerRadius.TopLeft + ", wanted 1px / 6");
            }

            var textBlocks = new List<TextBlock>();
            CollectTextBlocks(container, textBlocks);
            if (textBlocks.Count != 4)
            {
                throw new InvalidOperationException(
                    "the row has " + textBlocks.Count + " text block(s), wanted 4");
            }

            int primary = 0;
            int secondary = 0;
            foreach (TextBlock block in textBlocks)
            {
                if (SameBrushColor(block.Foreground, ThemeManager.TextBrush)) primary++;
                else if (SameBrushColor(block.Foreground, ThemeManager.SecondaryTextBrush)) secondary++;
            }
            if (primary != 1 || secondary != 3)
            {
                throw new InvalidOperationException(
                    "the row ink is " + primary + " primary / " + secondary
                    + " secondary, wanted 1 / 3");
            }

            // The ListBoxItem realizes its ContentTemplate through a
            // ContentPresenter; build the template root directly so the icon
            // can be read without depending on the list's virtualization.
            var templateRoot = list.ItemTemplate.LoadContent() as FrameworkElement;
            if (templateRoot != null)
            {
                templateRoot.DataContext = row;
                templateRoot.Measure(new Size(360, 44));
                templateRoot.Arrange(new Rect(0, 0, 360, 44));
                templateRoot.UpdateLayout();
            }
            var rowIcon = templateRoot == null ? null : FindVisual<IconPresenter>(templateRoot);
            if (rowIcon == null || rowIcon.Icon != IconId.File || rowIcon.Brush == null)
            {
                throw new InvalidOperationException("the row has no typed file IconPresenter");
            }

            container.IsSelected = true;
            host.UpdateLayout();
            var widgetAccent = view.Resources["SearchAccent"] as SolidColorBrush;
            if (widgetAccent == null || !SameBrushColor(frame.BorderBrush, widgetAccent))
            {
                throw new InvalidOperationException(
                    "the selected row border is not the widget accent brush (got "
                    + DescribeBrush(frame.BorderBrush) + ")");
            }
            if (!SameBrushColor(frame.Background, ThemeManager.ControlBackgroundBrush))
            {
                throw new InvalidOperationException(
                    "the selected row background is not the control background");
            }
        }

        /// <summary>
        /// Smoke fix: after a full scan the periodic reconcile used to claim it
        /// was indexing; the status line must say reconcile for that state while
        /// a full scan keeps the progress counts.
        /// </summary>
        private static void SearchStatusLabelsReconcileSeparately()
        {
            var view = new SearchWidget(new SearchData()).PanelView;
            var update = typeof(SearchPanelView).GetMethod("UpdateStatus",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (update == null)
            {
                throw new InvalidOperationException("SearchPanelView.UpdateStatus was not found");
            }

            var status = view.FindName("StatusText") as TextBlock;
            if (status == null)
            {
                throw new InvalidOperationException("the search status line is missing");
            }

            update.Invoke(view, new object[]
            {
                new FileSearchStatus
                {
                    State = FileSearchState.Indexing,
                    FilesIndexed = 7,
                    DirectoriesScanned = 3
                }
            });
            string indexing = status.Text;
            string wantedIndexing = Localization.Format("Search_Indexing", 7, 3);
            if (indexing != wantedIndexing)
            {
                throw new InvalidOperationException(
                    "the indexing line is '" + indexing + "', wanted '" + wantedIndexing + "'");
            }

            update.Invoke(view, new object[]
            {
                new FileSearchStatus
                {
                    State = FileSearchState.Reconciling,
                    FilesIndexed = 7,
                    DirectoriesScanned = 3
                }
            });
            string reconciling = status.Text;
            string wantedReconciling = Localization.Get("Search_Reconciling");
            if (reconciling != wantedReconciling)
            {
                throw new InvalidOperationException(
                    "the reconcile line is '" + reconciling + "', wanted '" + wantedReconciling + "'");
            }
            if (reconciling == indexing)
            {
                throw new InvalidOperationException(
                    "a reconcile still shows the indexing label");
            }
        }

        /// <summary>
        /// Task 5: the panel's internal activity bar is gone for good - loading
        /// feedback is the chrome's edge glow alone. The old named element and
        /// its SearchProgressStyle resource must be absent, and no ProgressBar
        /// may survive anywhere in the panel's logical or visual tree (a bar
        /// could come back unnamed or inside a template).
        /// </summary>
        private static void SearchPanelHasNoProgressBar()
        {
            ThemeManager.Initialize("dark");
            var view = new SearchWidget(new SearchData()).PanelView;

            if (view.FindName("ScanProgress") != null)
            {
                throw new InvalidOperationException(
                    "the search panel still has a ScanProgress element");
            }
            if (view.TryFindResource("SearchProgressStyle") != null)
            {
                throw new InvalidOperationException(
                    "the search panel still has a SearchProgressStyle resource");
            }

            // Build the visual tree before scanning it: a bar inside a template
            // only appears once the panel has been measured and arranged.
            view.Measure(new Size(422, 562));
            view.Arrange(new Rect(0, 0, 422, 562));
            view.UpdateLayout();

            // Positive control: the walk must reach the status line the bar sat
            // under, so an empty traversal cannot pass this pin by accident.
            if (FindInLogicalTree(view, d => Named(d, "StatusText")) == null)
            {
                throw new InvalidOperationException(
                    "the pin could not reach the search status line");
            }

            DependencyObject bar = FindInLogicalTree(view, d => d is ProgressBar)
                ?? FindInVisualTree(view, d => d is ProgressBar);
            if (bar != null)
            {
                var element = bar as FrameworkElement;
                throw new InvalidOperationException(
                    "the search panel still contains a ProgressBar ("
                    + (element == null ? string.Empty : element.Name) + ")");
            }
        }

        private static bool Named(DependencyObject node, string name)
        {
            var element = node as FrameworkElement;
            return element != null && element.Name == name;
        }

        private static DependencyObject FindInLogicalTree(
            DependencyObject root, Func<DependencyObject, bool> match)
        {
            if (root == null) return null;
            if (match(root)) return root;
            foreach (object child in LogicalTreeHelper.GetChildren(root))
            {
                var found = FindInLogicalTree(child as DependencyObject, match);
                if (found != null) return found;
            }
            return null;
        }

        private static DependencyObject FindInVisualTree(
            DependencyObject root, Func<DependencyObject, bool> match)
        {
            if (root == null) return null;
            if (match(root)) return root;
            int count = VisualTreeHelper.GetChildrenCount(root);
            for (int i = 0; i < count; i++)
            {
                var found = FindInVisualTree(VisualTreeHelper.GetChild(root, i), match);
                if (found != null) return found;
            }
            return null;
        }

        /// <summary>
        /// Fix round 1: the Settings window's file-search status line used to
        /// call a reconcile "indexing". The private label helper is the single
        /// mapper; Indexing keeps the counts, Reconciling says reconcile and
        /// both still carry the needs-rebuild suffix.
        /// </summary>
        private static void SettingsFileSearchStateLabels()
        {
            ThemeManager.Initialize("dark");
            var label = typeof(SettingsWindow).GetMethod("FileSearchStateLabel",
                BindingFlags.Static | BindingFlags.NonPublic);
            if (label == null)
            {
                throw new InvalidOperationException("SettingsWindow.FileSearchStateLabel was not found");
            }

            var indexing = new FileSearchStatus
            {
                State = FileSearchState.Indexing,
                FilesIndexed = 12,
                DirectoriesScanned = 4
            };
            string indexingLabel = (string)label.Invoke(null, new object[] { indexing });
            string wantedIndexing = Localization.Format("Search_Indexing", 12, 4);
            if (indexingLabel != wantedIndexing)
            {
                throw new InvalidOperationException(
                    "the settings indexing label is '" + indexingLabel + "', wanted '" + wantedIndexing + "'");
            }

            var reconciling = new FileSearchStatus
            {
                State = FileSearchState.Reconciling,
                FilesIndexed = 12,
                DirectoriesScanned = 4
            };
            string reconcilingLabel = (string)label.Invoke(null, new object[] { reconciling });
            string wantedReconciling = Localization.Get("Search_Reconciling");
            if (reconcilingLabel != wantedReconciling)
            {
                throw new InvalidOperationException(
                    "the settings reconcile label is '" + reconcilingLabel
                    + "', wanted '" + wantedReconciling + "'");
            }
            if (reconcilingLabel == indexingLabel)
            {
                throw new InvalidOperationException(
                    "the settings reconcile label still shows the indexing text");
            }

            reconciling.NeedsRebuild = true;
            string rebuildLabel = (string)label.Invoke(null, new object[] { reconciling });
            string wantedRebuild = wantedReconciling + " · " + Localization.Get("Search_NeedsRebuild");
            if (rebuildLabel != wantedRebuild)
            {
                throw new InvalidOperationException(
                    "the reconcile label with a pending rebuild is '" + rebuildLabel
                    + "', wanted '" + wantedRebuild + "'");
            }
        }

        private static T FindLogical<T>(DependencyObject root) where T : DependencyObject
        {
            if (root is T) return (T)root;
            foreach (var child in LogicalTreeHelper.GetChildren(root))
            {
                var dependency = child as DependencyObject;
                if (dependency == null) continue;
                var found = FindLogical<T>(dependency);
                if (found != null) return found;
            }
            return null;
        }

        private static void CollectTextBlocks(DependencyObject root, List<TextBlock> found)
        {
            var block = root as TextBlock;
            if (block != null) found.Add(block);

            int children = VisualTreeHelper.GetChildrenCount(root);
            for (int i = 0; i < children; i++)
            {
                CollectTextBlocks(VisualTreeHelper.GetChild(root, i), found);
            }
        }
        #endregion

        #region Task T11: note list pins

        /// <summary>
        /// T11: a card carries the title, the modified time ("g") and the
        /// 80-char excerpt as its stack children; a note with task boxes adds
        /// the progress line as a fourth. The three fixtures cover a heading +
        /// body note, a note with tasks and an empty note (empty title and
        /// excerpt, but a real time).
        /// </summary>
        private static void NoteCardsShowTitleTimeAndExcerpt()
        {
            ThemeManager.Initialize("dark");
            var when = new DateTime(2026, 3, 5, 14, 30, 0);
            var data = new NoteData();
            data.Notes.Add(NewNote("a", "# Shopping\n\n- milk\n- eggs", when));
            data.Notes.Add(NewNote("b", "# Tasks\n\n- [x] a\n- [ ] b", when.AddHours(1)));
            data.Notes.Add(NewNote("c", string.Empty, when.AddHours(2)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            if (NoteCardCount(view) != 3)
                throw new InvalidOperationException("the list rendered " + NoteCardCount(view) + " card(s), wanted 3");

            // Newest first (SortForDisplay): c (16:30), b (15:30), a (14:30).
            AssertNoteCardTexts(view, 0, new[] { string.Empty, when.AddHours(2).ToString("g"), string.Empty });
            AssertNoteCardTexts(view, 1, new[] { "Tasks", when.AddHours(1).ToString("g"), "Tasks a b", "1/2" });
            AssertNoteCardTexts(view, 2, new[] { "Shopping", when.ToString("g"), "Shopping milk eggs" });
        }

        /// <summary>
        /// T11: the progress line counts the parser's task boxes - an open and
        /// a completed box read "✓ 1/2" - and only a note with tasks carries a
        /// fourth line.
        /// </summary>
        private static void NoteTaskShowsProgress()
        {
            ThemeManager.Initialize("dark");
            var when = new DateTime(2026, 3, 5, 14, 30, 0);
            var data = new NoteData();
            data.Notes.Add(NewNote("t", "- [x] a\n- [ ] b", when));

