        }

        /// <summary>
        /// T11: the cards follow SortForDisplay - the newest modification
        /// first - while the source list keeps its own order.
        /// </summary>
        private static void NoteListOrdersByModifiedTime()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            data.Notes.Add(NewNote("a", "First", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Later", new DateTime(2026, 3, 5, 11, 0, 0)));
            data.Notes.Add(NewNote("c", "Middle", new DateTime(2026, 3, 5, 10, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            if (NoteCardCount(view) != 3)
                throw new InvalidOperationException("the list rendered " + NoteCardCount(view) + " card(s), wanted 3");
            if (NoteCardLine(view, 0, 0) != "Later")
                throw new InvalidOperationException("the first card is '" + NoteCardLine(view, 0, 0) + "', wanted 'Later'");
            if (NoteCardLine(view, 1, 0) != "Middle")
                throw new InvalidOperationException("the second card is '" + NoteCardLine(view, 1, 0) + "', wanted 'Middle'");
            if (NoteCardLine(view, 2, 0) != "First")
                throw new InvalidOperationException("the third card is '" + NoteCardLine(view, 2, 0) + "', wanted 'First'");

            if (data.Notes[0].Id != "a" || data.Notes[1].Id != "b" || data.Notes[2].Id != "c")
                throw new InvalidOperationException("the render re-ordered the source list");
        }

        /// <summary>
        /// T11: the card's row menu holds open + delete; clicking delete removes
        /// that note, rebuilds the list, and the undo puts the note back at its
        /// original index (the second note here) with the list rebuilt again.
        /// </summary>
        private static void NoteRowMenuDeletesAndUndoRestores()
        {
            ThemeManager.Initialize("dark");
            var first = NewNote("a", "First", new DateTime(2026, 3, 5, 9, 0, 0));
            var second = NewNote("b", "Second", new DateTime(2026, 3, 5, 11, 0, 0));
            var data = new NoteData();
            data.Notes.Add(first);
            data.Notes.Add(second);

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            if (NoteCardLine(view, 0, 0) != "Second")
                throw new InvalidOperationException("the newest note is not the first card");
            var card = NoteCardAt(view, 0);
            if (card.ContextMenu == null)
                throw new InvalidOperationException("the card carries no row menu");
            if (card.ContextMenu.Items.Count != 2)
                throw new InvalidOperationException("the row menu has " + card.ContextMenu.Items.Count + " item(s)");
            if (HeaderOf(card.ContextMenu.Items[0]) != Localization.Get("Menu_Open"))
                throw new InvalidOperationException(
                    "the row menu's open header is '" + HeaderOf(card.ContextMenu.Items[0]) + "'");
            AssertMenuIcon(card.ContextMenu.Items[0], IconId.Doc);
            string header = HeaderOf(card.ContextMenu.Items[1]);
            if (header != Localization.Get("Menu_DeleteItem"))
                throw new InvalidOperationException("the row menu header is '" + header + "'");
            AssertMenuIcon(card.ContextMenu.Items[1], IconId.Delete);

            ClickMenuItem(card, 1); // delete the newest note through its row menu

            if (data.Notes.Count != 1 || data.Notes[0] != first)
                throw new InvalidOperationException("the menu delete did not remove the newest note");
            if (NoteCardCount(view) != 1)
                throw new InvalidOperationException("the card list did not rebuild after the delete");

            if (!InvokeNoteTryUndo(view))
                throw new InvalidOperationException("TryUndo reported nothing to restore");
            if (data.Notes.Count != 2 || data.Notes[0] != first || data.Notes[1] != second)
                throw new InvalidOperationException("the undo did not put the note back at its index");
            if (NoteCardCount(view) != 2)
                throw new InvalidOperationException("the card list did not rebuild after the undo");
        }

        /// <summary>
        /// The home card's row menu also switches notes: its Open entry opens
        /// that card's note in the detail (the full note list stays in the
        /// detail's right-click menu, not on the home page).
        /// </summary>
        private static void NoteCardRowMenuOpensTheNote()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Beta", new DateTime(2026, 3, 5, 11, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            var card = NoteCardAt(view, 0); // Beta
            if (card.ContextMenu == null || card.ContextMenu.Items.Count != 2)
                throw new InvalidOperationException("the card row menu does not hold open + delete");

            ClickMenuItem(card, 0);
            if (view.IsHome)
                throw new InvalidOperationException("the row menu's open entry did not open the note");
            if (PrivateField<string>(view, "_expandedId") != "b")
                throw new InvalidOperationException("the row menu opened the wrong note");
        }

        /// <summary>
        /// T11: the undo stack is multi-step - two deletes walk back newest
        /// first, each restoring exactly one note in its slot, and the drained
        /// stack reports false.
        /// </summary>
        private static void NoteUndoWalksBackBeyondOneStep()
        {
            ThemeManager.Initialize("dark");
            var a = NewNote("a", "A", new DateTime(2026, 3, 5, 9, 0, 0));
            var b = NewNote("b", "B", new DateTime(2026, 3, 5, 10, 0, 0));
            var c = NewNote("c", "C", new DateTime(2026, 3, 5, 11, 0, 0));
            var data = new NoteData();
            data.Notes.Add(a);
            data.Notes.Add(b);
            data.Notes.Add(c);

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            InvokeNoteDelete(view, c);
            InvokeNoteDelete(view, b);
            if (data.Notes.Count != 1 || data.Notes[0] != a)
                throw new InvalidOperationException("the fixture deletes did not stick");

            if (!InvokeNoteTryUndo(view))
                throw new InvalidOperationException("the second delete did not undo");
            if (data.Notes.Count != 2 || data.Notes[0] != a || data.Notes[1] != b)
                throw new InvalidOperationException("the first undo restored the wrong note or slot");
            if (!InvokeNoteTryUndo(view))
                throw new InvalidOperationException("the first delete did not undo");
            if (data.Notes.Count != 3 || data.Notes[0] != a || data.Notes[1] != b || data.Notes[2] != c)
                throw new InvalidOperationException("the second undo did not restore the order");
            if (InvokeNoteTryUndo(view))
                throw new InvalidOperationException("the drained stack still reported an undo");
        }

        /// <summary>
        /// T11: the stack is capped at twenty - the oldest delete falls off, so
        /// exactly twenty undos succeed (restoring the newest twenty notes in
        /// their order) and the twenty-first reports false with the oldest note
        /// still gone.
        /// </summary>
        private static void NoteUndoStackKeepsOnlyTheNewestTwenty()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            var notes = new List<NoteItem>();
            for (int i = 0; i < 21; i++)
            {
                var note = NewNote("n" + i, "Note " + i, new DateTime(2026, 3, 5, 9, 0, 0).AddMinutes(i));
                notes.Add(note);
                data.Notes.Add(note);
            }

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            foreach (var note in notes) InvokeNoteDelete(view, note);
            if (data.Notes.Count != 0)
                throw new InvalidOperationException("the fixture deletes left " + data.Notes.Count + " note(s)");

            int undone = 0;
            while (InvokeNoteTryUndo(view)) undone++;
            if (undone != 20)
                throw new InvalidOperationException("the stack yielded " + undone + " undos, wanted 20");
            if (data.Notes.Count != 20 || data.Notes.Contains(notes[0]))
                throw new InvalidOperationException(
                    "the cap did not drop the oldest delete: " + data.Notes.Count + " note(s) came back");
            for (int i = 0; i < 20; i++)
            {
                if (data.Notes[i] != notes[i + 1])
                    throw new InvalidOperationException("the undo order broke at index " + i);
            }
        }

        /// <summary>
        /// T4 (spec 3.1): the home is the card list plus its centered empty
        /// state - no add row any more (the title menu owns the create entry).
        /// An empty data set shows the localized hint over an empty list; two
        /// notes fill the list in display order and hide the hint. The hint
        /// follows the live language (the panel rebuild sets it again).
        /// </summary>
        private static void NoteHomeShowsCardsAndTheEmptyState()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            var view = new NoteWidget(data).PanelView;

            var empty = NoteNamed(view, "EmptyState") as TextBlock;
            if (empty == null) throw new InvalidOperationException("the home has no EmptyState text");
            if (empty.Visibility != Visibility.Visible)
                throw new InvalidOperationException("the empty home hides its empty state");
            if (empty.Text != Localization.Get("UI_NoteEmptyHome"))
                throw new InvalidOperationException(
                    "the empty state reads '" + empty.Text + "', wanted the UI_NoteEmptyHome text");
            if (NoteCardCount(view) != 0)
                throw new InvalidOperationException("the empty home rendered " + NoteCardCount(view) + " card(s)");
            if (view.FindName("AddPill") != null)
                throw new InvalidOperationException("the home still carries the retired AddPill row");
            if (NoteNamed(view, "HomeHost").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the empty home hides the home host");
            if (NoteNamed(view, "DetailHost").Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the empty home shows the detail host");

            data.Notes.Add(NewNote("a", "First", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Second", new DateTime(2026, 3, 5, 11, 0, 0)));
            view.Refresh();

            if (NoteCardCount(view) != 2)
                throw new InvalidOperationException(
                    "the two-note fixture rendered " + NoteCardCount(view) + " card(s), wanted 2");
            if (empty.Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the filled home still shows the empty state");
            if (NoteCardLine(view, 0, 0) != "Second" || NoteCardLine(view, 1, 0) != "First")
                throw new InvalidOperationException("the home lost the modified-time order ("
                    + NoteCardLine(view, 0, 0) + ", " + NoteCardLine(view, 1, 0) + ")");

            // The hint is rebuilt with the home, so a language switch lands too.
            Localization.SetLanguage("zh");
            try
            {
                data.Notes.Clear();
                view.Refresh();
                if (empty.Visibility != Visibility.Visible)
                    throw new InvalidOperationException("the emptied home hides the empty state");
                if (empty.Text != Localization.Get("UI_NoteEmptyHome"))
                    throw new InvalidOperationException(
                        "the switched empty state reads '" + empty.Text + "'");
                if (empty.Text == "No notes yet — open the title menu to create one.")
                    throw new InvalidOperationException("the empty state stayed English after the switch");
            }
            finally
            {
                Localization.SetLanguage("en");
            }
        }

        private static NoteItem NewNote(string id, string text, DateTime modifiedAt)
        {
            return new NoteItem { Id = id, Text = text, CreatedAt = modifiedAt, ModifiedAt = modifiedAt };
        }

        private static Panel NoteItemsPanel(NotePanelView view)
        {
            var panel = view.FindName("ItemsPanel") as Panel;
            if (panel == null) throw new InvalidOperationException("NotePanelView has no ItemsPanel");
            return panel;
        }

        private static int NoteCardCount(NotePanelView view)
        {
            return NoteItemsPanel(view).Children.Count;
        }

        private static Border NoteCardAt(NotePanelView view, int index)
        {
            var panel = NoteItemsPanel(view);
            if (panel.Children.Count <= index)
            {
                throw new InvalidOperationException(
                    "note card " + index + " not found (" + panel.Children.Count + " card(s))");
            }
            var card = panel.Children[index] as Border;
            if (card == null) throw new InvalidOperationException("note card " + index + " is not a Border");
            return card;
        }

        private static List<string> NoteCardTexts(NotePanelView view, int index)
        {
            var stack = NoteCardAt(view, index).Child as StackPanel;
            if (stack == null) throw new InvalidOperationException("note card " + index + " has no content stack");

            var texts = new List<string>();
            foreach (var child in stack.Children)
            {
                var text = child as TextBlock;
                if (text != null)
                {
                    texts.Add(text.Text);
                    continue;
                }

                // The task-progress line is an IconPresenter + TextBlock row;
                // keep the text line while the icon carries the check.
                var row = child as StackPanel;
                if (row == null) throw new InvalidOperationException("note card " + index + " has a non-text child");
                foreach (var rowChild in row.Children)
                {
                    var rowText = rowChild as TextBlock;
                    if (rowText != null) texts.Add(rowText.Text);
                }
            }
            return texts;
        }

        private static string NoteCardLine(NotePanelView view, int index, int line)
        {
            var texts = NoteCardTexts(view, index);
            if (texts.Count <= line)
                throw new InvalidOperationException("note card " + index + " has no line " + line);
            return texts[line];
        }

        private static void AssertNoteCardTexts(NotePanelView view, int index, string[] expected)
        {
            var actual = NoteCardTexts(view, index);
            if (actual.Count != expected.Length)
                throw new InvalidOperationException(
                    "note card " + index + " has " + actual.Count + " line(s), wanted " + expected.Length);
            for (int i = 0; i < expected.Length; i++)
            {
                if (actual[i] != expected[i])
                    throw new InvalidOperationException(
                        "note card " + index + " line " + i + " is '" + actual[i] + "', wanted '" + expected[i] + "'");
            }
        }

        /// <summary>
        /// Calls the view's undo through reflection (T11; the RED run has no
        /// such method yet; afterwards it is public, reflection keeps the pin
        /// stable either way - the TodoCalendarView convention).
        /// </summary>
        private static bool InvokeNoteTryUndo(NotePanelView view)
        {
            var method = typeof(NotePanelView).GetMethod("TryUndo",
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            if (method == null) throw new InvalidOperationException("TryUndo not found on NotePanelView");
            return (bool)method.Invoke(view, null);
        }

        /// <summary>Calls the view's private delete (T11; the RED run has no such
        /// method yet).</summary>
        private static void InvokeNoteDelete(NotePanelView view, NoteItem note)
        {
            var method = typeof(NotePanelView).GetMethod("InvokeDelete",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (method == null) throw new InvalidOperationException("InvokeDelete not found on NotePanelView");
            method.Invoke(view, new object[] { note });
        }

        #endregion

        #region Task T12: renderer pins

        /// <summary>
        /// T12: the style the reading view will build - theme tokens plus the
        /// widget colour, injected here (a fixture palette entry, so an accent
        /// that ignores the widget colour fails). No hex literals: every colour
        /// comes from <see cref="UiTokens"/>, <see cref="ThemeManager"/> or a
        /// named system brush.
        /// </summary>
        private static NoteRenderStyle NewRenderStyle(string widgetHex = null)
        {
            ThemeManager.Initialize("dark");
            return new NoteRenderStyle
            {
                Text = ThemeManager.TextBrush,
                Muted = ThemeManager.MutedTextBrush,
                Accent = new SolidColorBrush(Utils.HexToColor(widgetHex ?? UiTokens.DefaultFolderColor)),
                CodeBackground = new SolidColorBrush(Utils.HexToColor(UiTokens.Dark.ControlBackground)),
                Divider = ThemeManager.BorderBrush,
                HighContrast = false,
                BodyFont = new FontFamily("Segoe UI"),
                BaseFontSize = UiTokens.FontBody
            };
        }

        private static FlowDocument RenderDocument(string source, NoteRenderStyle style,
            NoteRenderCallbacks callbacks = null)
        {
            return NoteMarkdownRenderer.Build(MarkdownParser.Parse(source), style, callbacks);
        }

        /// <summary>
        /// T12: H1..H6 step down by the design's ladder (Base times
        /// 1.6/1.4/1.25/1.12/1.05/1.0) and never dip below the body size.
        /// </summary>
        private static void RendererHeadingsStepDown()
        {
            var style = NewRenderStyle();
            var doc = RenderDocument("# one\n## two\n### three\n#### four\n##### five\n###### six", style);

            if (doc.Blocks.Count != 6)
                throw new InvalidOperationException("the six headings produced " + doc.Blocks.Count + " block(s)");

            double[] scale = { 1.6, 1.4, 1.25, 1.12, 1.05, 1.0 };
            double previous = double.MaxValue;
            for (int i = 0; i < scale.Length; i++)
            {
                var heading = ParagraphAt(doc, i);
                double wanted = style.BaseFontSize * scale[i];
                if (Math.Abs(heading.FontSize - wanted) > 0.001)
                    throw new InvalidOperationException(
                        "H" + (i + 1) + " renders at " + heading.FontSize + ", wanted " + wanted);
                if (heading.FontSize < style.BaseFontSize)
                    throw new InvalidOperationException("H" + (i + 1) + " is smaller than the body size");
                if (heading.FontSize >= previous)
                    throw new InvalidOperationException("H" + (i + 1) + " does not step down from H" + i);
                previous = heading.FontSize;
            }
        }

        /// <summary>
        /// T12: a paragraph keeps its source line breaks as <see cref="LineBreak"/>
        /// inlines (the Chinese-note deviation: three lines, two breaks, no
        /// space joining).
        /// </summary>
        private static void RendererParagraphKeepsLineBreaks()
        {
            var doc = RenderDocument("one\ntwo\nthree", NewRenderStyle());
            var paragraph = FirstParagraph(doc);

            int breaks = 0;
            foreach (var inline in paragraph.Inlines)
            {
                if (inline is LineBreak) breaks++;
            }
            if (breaks != 2)
                throw new InvalidOperationException("the three-line paragraph has " + breaks + " line break(s), wanted 2");

            string text = InlineText(paragraph.Inlines);
            if (text != "one\ntwo\nthree")
                throw new InvalidOperationException("the paragraph reads '" + text.Replace("\n", "\\n") + "'");
        }

        /// <summary>T12: the emphasis family lands on Run properties.</summary>
        private static void RendererEmphasisRuns()
        {
            var doc = RenderDocument("**bold** *italic* ~~struck~~", NewRenderStyle());
            var paragraph = FirstParagraph(doc);

            var bold = RunWithText(paragraph, "bold");
            if (bold.FontWeight != FontWeights.Bold)
                throw new InvalidOperationException("the strong run weighs " + bold.FontWeight);

            var italic = RunWithText(paragraph, "italic");
            if (italic.FontStyle != FontStyles.Italic)
                throw new InvalidOperationException("the em run styles " + italic.FontStyle);

            var struck = RunWithText(paragraph, "struck");
            if (struck.TextDecorations == null || struck.TextDecorations.Count == 0
                || struck.TextDecorations[0].Location != TextDecorationLocation.Strikethrough)
                throw new InvalidOperationException("the strike run carries no strikethrough decoration");
        }

        /// <summary>
        /// T12: a code span is monospace on the style's code band, and the
        /// surrounding text stays body-font so the span really is its own run.
        /// </summary>
        private static void RendererInlineCodeIsMonospace()
        {
            var style = NewRenderStyle();
            var doc = RenderDocument("before `code` after", style);
            var paragraph = FirstParagraph(doc);

            var code = RunWithText(paragraph, "code");
            if (code.FontFamily == null
                || code.FontFamily.Source.IndexOf("Consolas", StringComparison.OrdinalIgnoreCase) < 0)
                throw new InvalidOperationException("the code span font is '"
                    + (code.FontFamily == null ? "<null>" : code.FontFamily.Source) + "'");

            var background = code.Background as SolidColorBrush;
            var wanted = style.CodeBackground as SolidColorBrush;
            if (background == null || wanted == null)
                throw new InvalidOperationException("the code span has no background");
            if (background.Color != wanted.Color)
                throw new InvalidOperationException(
                    "the code span background is " + background.Color + ", wanted " + wanted.Color);

            string text = InlineText(paragraph.Inlines);
            if (text != "before code after")
                throw new InvalidOperationException("the inline code paragraph reads '" + text + "'");
        }

        /// <summary>
        /// T12: every task glyph is tagged with its absolute source line, the
        /// completed one grows a check mark the open one does not have, and a
        /// glyph click routes exactly that line (the callback set is optional:
        /// a bare render must stay silent).
        /// </summary>
        private static void RendererTaskGlyphCarriesItsLine()
        {
            var style = NewRenderStyle();
            var doc = RenderDocument("- [ ] open\n- [x] done", style);

            if (doc.Blocks.Count != 2)
                throw new InvalidOperationException("the two task lines produced " + doc.Blocks.Count + " block(s)");

            var openParagraph = ParagraphAt(doc, 0);
            var doneParagraph = ParagraphAt(doc, 1);
            var openBadge = TaskGlyph(openParagraph);
            var doneBadge = TaskGlyph(doneParagraph);

            if (!(openBadge.Tag is int) || (int)openBadge.Tag != 0)
                throw new InvalidOperationException("the open glyph tags " + openBadge.Tag + ", wanted line 0");
            if (!(doneBadge.Tag is int) || (int)doneBadge.Tag != 1)
                throw new InvalidOperationException("the done glyph tags " + doneBadge.Tag + ", wanted line 1");

            if (openBadge.Child != null)
                throw new InvalidOperationException("the open box already carries a mark");
            var doneCheck = doneBadge.Child as IconPresenter;
            if (doneCheck == null || doneCheck.Icon != IconId.Check)
                throw new InvalidOperationException("the completed box carries no Check IconPresenter");

            if (InlineText(openParagraph.Inlines) != "open")
                throw new InvalidOperationException("the open task reads '" + InlineText(openParagraph.Inlines) + "'");
            if (InlineText(doneParagraph.Inlines) != "done")
                throw new InvalidOperationException("the done task reads '" + InlineText(doneParagraph.Inlines) + "'");

            int toggled = -1;
            var callbacks = new NoteRenderCallbacks { ToggleTaskLine = line => { toggled = line; } };
            var clickDoc = RenderDocument("- [ ] open\n- [x] done", style, callbacks);
            var clickBadge = TaskGlyph(ParagraphAt(clickDoc, 1));
            var upArgs = new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent
            };
            clickBadge.RaiseEvent(upArgs);
            if (toggled != 1)
                throw new InvalidOperationException("the glyph click reported line " + toggled + ", wanted 1");
            if (!upArgs.Handled)
                throw new InvalidOperationException("the glyph click was not handled");

            // No callback set: the same click must not throw.
            var bare = NoteMarkdownRenderer.Build(MarkdownParser.Parse("- [ ] open"), style, null);
            TaskGlyph(ParagraphAt(bare, 0)).RaiseEvent(
                new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent
                });
        }

        /// <summary>
        /// T12: the table carries one equal star column per alignment, a header
        /// row plus the body, and every cell aligns to its column's
        /// <see cref="MdAlign"/> (`---` and `:---` read left, `---:` right,
        /// `:---:` centre). The header is bold and underlined.
        /// </summary>
        private static void RendererTableRendersAlignedCells()
        {
            var doc = RenderDocument("| a | b | c | d |\n|---|:---|---:|:---:|\n| 1 | 2 | 3 | 4 |", NewRenderStyle());

            var table = BlockAt(doc.Blocks, 0) as Table;
            if (table == null)
                throw new InvalidOperationException("the table parsed to a " + BlockAt(doc.Blocks, 0).GetType().Name);

            if (table.Columns.Count != 4)
                throw new InvalidOperationException("the table has " + table.Columns.Count + " column(s), wanted 4");
            for (int c = 0; c < table.Columns.Count; c++)
            {
                if (table.Columns[c].Width != new GridLength(1, GridUnitType.Star))
                    throw new InvalidOperationException(
                        "column " + c + " is " + table.Columns[c].Width + ", wanted an equal star");
            }

            if (table.RowGroups.Count != 1)
                throw new InvalidOperationException("the table has " + table.RowGroups.Count + " row group(s), wanted 1");
            var rows = table.RowGroups[0].Rows;
            if (rows.Count != 2)
                throw new InvalidOperationException(
                    "the table has " + rows.Count + " row(s), wanted a header plus one body row");
            for (int r = 0; r < rows.Count; r++)
            {
                if (rows[r].Cells.Count != 4)
                    throw new InvalidOperationException("row " + r + " has " + rows[r].Cells.Count + " cell(s), wanted 4");
            }

            TextAlignment[] wanted =
            {
                TextAlignment.Left, TextAlignment.Left, TextAlignment.Right, TextAlignment.Center
            };
            for (int r = 0; r < rows.Count; r++)
            {
                for (int c = 0; c < wanted.Length; c++)
                {
                    if (rows[r].Cells[c].TextAlignment != wanted[c])
                        throw new InvalidOperationException("row " + r + " cell " + c + " aligns "
                            + rows[r].Cells[c].TextAlignment + ", wanted " + wanted[c]);
                }
            }

            var headerCell = rows[0].Cells[0];
            var headerText = BlockAt(headerCell.Blocks, 0) as Paragraph;
            if (headerText == null || headerText.FontWeight != FontWeights.Bold)
                throw new InvalidOperationException("the header row is not bold");
            if (headerCell.BorderThickness.Bottom <= 0 || headerCell.BorderBrush == null)
                throw new InvalidOperationException("the header row has no bottom rule");
            if (InlineText(headerText.Inlines) != "a")
                throw new InvalidOperationException("the header cell reads '" + InlineText(headerText.Inlines) + "'");
        }

        /// <summary>
        /// T12: a link carries its target, its label and a click that routes the
        /// URL to the callbacks and marks the event handled - the pin raises the
        /// click itself, so a handler that forgets <c>Handled</c> would be the
        /// only thing that could reach a browser.
        /// </summary>
        private static void RendererLinkRoutesUrlOnClick()
        {
            const string url = "https://example.com/a?b=1";
            string recorded = null;
            var callbacks = new NoteRenderCallbacks { OpenLink = target => { recorded = target; } };
            var doc = RenderDocument("see [the site](" + url + ")", NewRenderStyle(), callbacks);

            var link = FirstHyperlink(doc);
            if (link.NavigateUri == null || link.NavigateUri.AbsoluteUri != url)
                throw new InvalidOperationException("the link target is '"
                    + (link.NavigateUri == null ? "<null>" : link.NavigateUri.AbsoluteUri) + "'");
            if (InlineText(link.Inlines) != "the site")
                throw new InvalidOperationException("the link label reads '" + InlineText(link.Inlines) + "'");

            var args = new RoutedEventArgs(Hyperlink.ClickEvent, link);
            link.RaiseEvent(args);

            if (recorded != url)
                throw new InvalidOperationException("the click routed '" + recorded + "', wanted '" + url + "'");
            if (!args.Handled)
                throw new InvalidOperationException("the click was not handled (a browser would open)");

            // No callbacks at all: the same click must stay silent.
            var bare = RenderDocument("[x](https://example.com/bare)", NewRenderStyle());
            var bareLink = FirstHyperlink(bare);
            bareLink.RaiseEvent(new RoutedEventArgs(Hyperlink.ClickEvent, bareLink));
        }

        /// <summary>
        /// T12: with <see cref="NoteRenderStyle.HighContrast"/> on, the style's
        /// own brushes are ignored for the system roles - here a marker colour
        /// no system palette uses proves the paragraph ink and the task box
        /// really swap.
        /// </summary>
        private static void RendererHighContrastUsesSystemColours()
        {
            var style = NewRenderStyle();
            style.HighContrast = true;
            style.Text = Brushes.Magenta;

            var doc = RenderDocument("plain text", style);
            var foreground = FirstParagraph(doc).Foreground as SolidColorBrush;
            if (foreground == null)
                throw new InvalidOperationException("the high-contrast paragraph carries no brush");
            if (foreground.Color != SystemColors.WindowTextColor)
                throw new InvalidOperationException("the high-contrast paragraph ink is " + foreground.Color
                    + ", wanted the system window text colour");

            var taskDoc = RenderDocument("- [ ] a", style);
            var border = TaskGlyph(ParagraphAt(taskDoc, 0)).BorderBrush as SolidColorBrush;
            if (border == null || border.Color != SystemColors.HighlightColor)
                throw new InvalidOperationException("the high-contrast task box wears '"
                    + (border == null ? "<null>" : border.Color.ToString()) + "', wanted the system highlight colour");
        }

        /// <summary>
        /// T12: the accent follows the widget colour - the task box, its check
        /// and a link all wear <c>Utils.HexToColor(data.Color)</c>, not the
        /// default token.
        /// </summary>
        private static void RendererAccentFollowsWidgetColour()
        {
            string widgetHex = UiTokens.FolderPalette[1];
            if (string.Equals(widgetHex, UiTokens.DefaultFolderColor, StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException("the fixture colour is the default token: pick another palette entry");

            var style = NewRenderStyle(widgetHex);
            Color wanted = Utils.HexToColor(widgetHex);

            var badge = TaskGlyph(ParagraphAt(RenderDocument("- [x] done", style), 0));
            var border = badge.BorderBrush as SolidColorBrush;
            if (border == null || border.Color != wanted)
                throw new InvalidOperationException("the task box wears '"
                    + (border == null ? "<null>" : border.Color.ToString()) + "', wanted " + wanted);

            var check = badge.Child as IconPresenter;
            var stroke = check == null ? null : check.Brush as SolidColorBrush;
            if (stroke == null || stroke.Color != wanted)
                throw new InvalidOperationException("the check mark ink is '"
                    + (stroke == null ? "<null>" : stroke.Color.ToString()) + "', wanted " + wanted);

            var link = FirstHyperlink(RenderDocument("[x](https://example.com)", style));
            var linkInk = link.Foreground as SolidColorBrush;
            if (linkInk == null || linkInk.Color != wanted)
                throw new InvalidOperationException("the link ink is '"
                    + (linkInk == null ? "<null>" : linkInk.Color.ToString()) + "', wanted " + wanted);
        }

        /// <summary>
        /// T2: every painted block is tagged with the absolute source line it
        /// stands for, read back through the attached
        /// <see cref="NoteMarkdownRenderer.SourceLineProperty"/>. Headings,
        /// tasks, quotes (the section and its inner block), code, rules and
        /// tables tag their own container; a paragraph tags itself with the
        /// first line and each soft-broken line group's Span with its own, so a
        /// click can be traced to the line it edits.
        /// </summary>
        private static void RendererBlocksCarryTheirSourceLines()
        {
            const string source =
                "one\ntwo\n\n# h\n\n- [ ] t\n\n> q\n\n```\nc\n```\n\n---\n\n| a | b |\n| --- | --- |\n| 1 | 2 |";
            var doc = RenderDocument(source, NewRenderStyle());
            if (doc.Blocks.Count != 7)
                throw new InvalidOperationException("the fixture produced " + doc.Blocks.Count + " block(s), wanted 7");

            var first = ParagraphAt(doc, 0);
            var groups = new List<Span>();
            foreach (var inline in first.Inlines)
            {
                var span = inline as Span;
                if (span != null) groups.Add(span);
            }
            if (groups.Count != 2)
                throw new InvalidOperationException("the first paragraph carries " + groups.Count
                    + " line group(s), wanted 2");
            ExpectSourceLine(groups[0], 0, "the first line group");
            ExpectSourceLine(groups[1], 1, "the second line group");

            ExpectSourceLine(ParagraphAt(doc, 1), 3, "the heading");
            ExpectSourceLine(ParagraphAt(doc, 2), 5, "the task");

            var quote = BlockAt(doc.Blocks, 3) as Section;
            if (quote == null)
                throw new InvalidOperationException("block 3 is a " + BlockAsText(doc.Blocks, 3) + ", not a section");
            ExpectSourceLine(quote, 7, "the quote");
            var quoteBody = BlockAt(quote.Blocks, 0) as Paragraph;
            if (quoteBody == null)
                throw new InvalidOperationException("the quote holds no paragraph");
            ExpectSourceLine(quoteBody, 7, "the quote paragraph");

            ExpectSourceLine(ParagraphAt(doc, 4), 9, "the code block");

            var rule = BlockAt(doc.Blocks, 5);
            if (!(rule is BlockUIContainer))
                throw new InvalidOperationException("block 5 is a " + rule.GetType().Name + ", not a rule");
            ExpectSourceLine(rule, 13, "the thematic break");

            var table = BlockAt(doc.Blocks, 6) as Table;
            if (table == null)
                throw new InvalidOperationException("block 6 is a " + BlockAsText(doc.Blocks, 6) + ", not a table");
            ExpectSourceLine(table, 15, "the table");

            // A list tags each item's paragraph with the item's own line.
            var listDoc = RenderDocument("- a\n- b", NewRenderStyle());
            var list = BlockAt(listDoc.Blocks, 0) as List;
            if (list == null || list.ListItems.Count != 2)
                throw new InvalidOperationException("the two list items did not render to a list");
            int itemIndex = 0;
            foreach (var item in list.ListItems)
            {
                var itemParagraph = BlockAt(item.Blocks, 0) as Paragraph;
                if (itemParagraph == null)
                    throw new InvalidOperationException("list item " + itemIndex + " holds no paragraph");
                ExpectSourceLine(itemParagraph, itemIndex, "list item " + itemIndex);
                itemIndex++;
            }
        }

        /// <summary>
        /// T2: <see cref="NoteMarkdownRenderer.HeadingFontSize"/> is the single
        /// source of truth for the heading ladder (body size times
        /// 1.6/1.4/1.25/1.12/1.05/1.0), with levels clamped to 1..6 so an
        /// out-of-range level can never size a box off the ladder.
        /// </summary>
        private static void RendererHeadingSizeHelperFollowsTheLadder()
        {
            double[] scale = { 1.6, 1.4, 1.25, 1.12, 1.05, 1.0 };
            for (int level = 1; level <= scale.Length; level++)
            {
                double wanted = 16 * scale[level - 1];
                double actual = NoteMarkdownRenderer.HeadingFontSize(level, 16);
                if (Math.Abs(actual - wanted) > 0.001)
                    throw new InvalidOperationException("H" + level + " sizes to " + actual + ", wanted " + wanted);
            }

            if (NoteMarkdownRenderer.HeadingFontSize(0, 16) != NoteMarkdownRenderer.HeadingFontSize(1, 16))
                throw new InvalidOperationException("level 0 does not clamp to H1");
            if (NoteMarkdownRenderer.HeadingFontSize(7, 16) != NoteMarkdownRenderer.HeadingFontSize(6, 16))
                throw new InvalidOperationException("level 7 does not clamp to H6");
        }

        private static void ExpectSourceLine(DependencyObject element, int wanted, string what)
        {
            int line = NoteMarkdownRenderer.GetSourceLine(element);
            if (line != wanted)
                throw new InvalidOperationException(what + " is tagged line " + line + ", wanted " + wanted);
        }

        private static string BlockAsText(BlockCollection blocks, int index)
        {
            var block = BlockAt(blocks, index);
            return block == null ? "<null>" : block.GetType().Name;
        }

        private static Paragraph ParagraphAt(FlowDocument doc, int index)
        {
            if (doc.Blocks.Count <= index)
                throw new InvalidOperationException(
                    "the document has no block " + index + " (" + doc.Blocks.Count + " block(s))");
            var paragraph = BlockAt(doc.Blocks, index) as Paragraph;
            if (paragraph == null)
                throw new InvalidOperationException(
                    "block " + index + " is a " + BlockAt(doc.Blocks, index).GetType().Name + ", not a paragraph");
            return paragraph;
        }

        /// <summary>Blocks by position: a FlowDocument block collection has no
        /// indexer, so walk it (the collection is live and ordered).</summary>
        private static Block BlockAt(BlockCollection blocks, int index)
        {
            foreach (var block in blocks)
            {
                if (index == 0) return block;
                index--;
            }
            throw new InvalidOperationException("the collection holds no block at that position");
        }

        private static Paragraph FirstParagraph(FlowDocument doc)
        {
            return ParagraphAt(doc, 0);
        }

        /// <summary>The task glyph of a task paragraph: the inline UI host whose
        /// child is a Border tagged with its source line.</summary>
        private static Border TaskGlyph(Paragraph paragraph)
        {
            foreach (var inline in paragraph.Inlines)
            {
                var container = inline as InlineUIContainer;
                if (container == null) continue;
                var badge = container.Child as Border;
                if (badge != null && badge.Tag is int) return badge;
            }
            throw new InvalidOperationException("the paragraph carries no task glyph");
        }

        /// <summary>The run that reads <paramref name="text"/>. Paragraphs wrap
        /// each soft-broken line group in a <see cref="Span"/>, so the scan
        /// recurses like <see cref="InlineText"/> does.</summary>
        private static Run RunWithText(Paragraph paragraph, string text)
        {
            var run = FindRunWithText(paragraph.Inlines, text);
            if (run != null) return run;
            throw new InvalidOperationException("no run in the paragraph reads '" + text + "'");
        }

        private static Run FindRunWithText(IEnumerable<Inline> inlines, string text)
        {
            foreach (var inline in inlines)
            {
                var run = inline as Run;
                if (run != null && run.Text == text) return run;

                var span = inline as Span;
                if (span != null)
                {
                    var nested = FindRunWithText(span.Inlines, text);
                    if (nested != null) return nested;
                }
            }
            return null;
        }

        private static Hyperlink FirstHyperlink(FlowDocument doc)
        {
            foreach (var block in doc.Blocks)
            {
                var paragraph = block as Paragraph;
                if (paragraph == null) continue;
                var link = FindHyperlink(paragraph.Inlines);
                if (link != null) return link;
            }
            throw new InvalidOperationException("the document holds no hyperlink");
        }

        private static Hyperlink FindHyperlink(IEnumerable<Inline> inlines)
        {
            foreach (var inline in inlines)
            {
                var link = inline as Hyperlink;
                if (link != null) return link;

                var span = inline as Span;
                if (span != null)
                {
                    var nested = FindHyperlink(span.Inlines);
                    if (nested != null) return nested;
                }
            }
            return null;
        }

        private static string InlineText(IEnumerable<Inline> inlines)
        {
            var text = new StringBuilder();
            AppendInlineText(text, inlines);
            return text.ToString();
        }

        private static void AppendInlineText(StringBuilder text, IEnumerable<Inline> inlines)
        {
            foreach (var inline in inlines)
            {
                var run = inline as Run;
                if (run != null) { text.Append(run.Text); continue; }
                if (inline is LineBreak) { text.Append('\n'); continue; }

                var span = inline as Span;
                if (span != null) AppendInlineText(text, span.Inlines);
            }
        }

        #endregion

        #region Task T4: note home / detail navigation pins

        /// <summary>
        /// T4 (spec 3.1): a card click opens that note's detail page - the home
        /// host (the cards) collapses, the detail host shows the panel's one
        /// surface with the rendered document, the expanded id names the note
        /// and the chrome title switches to its title.
        /// </summary>
        private static void NoteCardClickOpensTheDetail()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            data.Notes.Add(NewNote("a", "# Alpha\n\nbody one", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "# Beta\n\nbody two", new DateTime(2026, 3, 5, 11, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            if (NoteCardLine(view, 0, 0) != "Beta")
                throw new InvalidOperationException(
                    "the fixture order is '" + NoteCardLine(view, 0, 0) + "', wanted 'Beta' first");

            ClickNoteCard(view, 0);

            if (NoteExpandedId(view) != "b")
                throw new InvalidOperationException(
                    "the card click opened '" + NoteExpandedId(view) + "', wanted 'b'");
            if (view.IsHome)
                throw new InvalidOperationException("the card click left the panel home");
            if (NoteNamed(view, "HomeHost").Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the detail still shows the home host");
            if (NoteNamed(view, "DetailHost").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the detail host is hidden");

            var host = NoteHost(view);
            if (!ReferenceEquals(host.Parent, NoteNamed(view, "DetailHost")))
                throw new InvalidOperationException("the surface host is not the detail host's child");
            var surface = NoteSurface(view);
            if (!ReferenceEquals(host.Child, surface))
                throw new InvalidOperationException("the detail host does not carry the panel's surface");

            var document = SurfaceReadingBox(surface).Document;
            if (document == null || document.Blocks.Count == 0)
                throw new InvalidOperationException("the detail holds no rendered document");
            if (view.ChromeTitle != "Beta")
                throw new InvalidOperationException(
                    "the detail title reads '" + view.ChromeTitle + "', wanted 'Beta'");
        }

        /// <summary>
        /// T4 (spec 3.2): the title follows the state - the widget name at home,
        /// the note's own title in the detail, the untitled key for a blank
        /// note, and a committed edit renames it at once. The widget's chrome
        /// carries the same text (home clears the tooltip, the detail fills it).
        /// </summary>
        private static void NoteTitleFollowsHomeAndDetail()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("c", "   ", new DateTime(2026, 3, 5, 10, 0, 0)));

            var widget = new NoteWidget(data);
            var view = widget.PanelView;
            var chrome = NoteChrome(widget);
            view.Refresh();

            if (view.ChromeTitle != "Notebook")
                throw new InvalidOperationException(
                    "the home title reads '" + view.ChromeTitle + "', wanted 'Notebook'");
            if (chrome.Title != "Notebook")
                throw new InvalidOperationException(
                    "the chrome title reads '" + chrome.Title + "', wanted 'Notebook'");
            if (chrome.TitleText.ToolTip != null)
                throw new InvalidOperationException("the home keeps a tooltip on the title");

            ClickNoteCard(view, 1);          // Alpha (card 0 is the blank note)
            if (view.ChromeTitle != "Alpha")
                throw new InvalidOperationException(
                    "the detail title reads '" + view.ChromeTitle + "', wanted 'Alpha'");
            if (chrome.Title != "Alpha")
                throw new InvalidOperationException(
                    "the chrome title reads '" + chrome.Title + "', wanted 'Alpha'");
            if (!object.Equals(chrome.TitleText.ToolTip, "Alpha"))
                throw new InvalidOperationException(
                    "the detail tooltip reads '" + chrome.TitleText.ToolTip + "', wanted 'Alpha'");

            ClickTitleMenuPart(view, "NoteMenuHome");
            ClickNoteCard(view, 0);          // the blank note
            string untitled = Localization.Get("UI_NoteUntitled");
            if (view.ChromeTitle != untitled)
                throw new InvalidOperationException(
                    "the blank note title reads '" + view.ChromeTitle + "', wanted '" + untitled + "'");

            ClickTitleMenuPart(view, "NoteMenuHome");
            if (view.ChromeTitle != "Notebook")
                throw new InvalidOperationException("the home title did not come back");

            ClickNoteCard(view, 0);          // Alpha is now the only note
            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note's paragraph did not enter the block edit");
            SurfaceEditBox(surface).Text = "Renamed";
            var args = RaiseNotePreviewKey(widget, SurfaceEditBox(surface), Key.Escape);
            if (!args.Handled)
                throw new InvalidOperationException("the commit Esc was not handled");

            if (view.ChromeTitle != "Renamed")
                throw new InvalidOperationException(
                    "the committed title reads '" + view.ChromeTitle + "', wanted 'Renamed'");
            if (chrome.Title != "Renamed")
                throw new InvalidOperationException(
                    "the chrome title reads '" + chrome.Title + "', wanted 'Renamed'");
            if (view.IsHome)
                throw new InvalidOperationException("the commit Esc left the detail");
        }

        /// <summary>
        /// T4 (spec 3.2): the note kind is the one that enables the chrome's
        /// title dropdown - the widget turns the flag on and the chevron is
        /// visible (folder / todo leave it off).
        /// </summary>
        private static void NoteWidgetEnablesTheTitleMenu()
        {
            ThemeManager.Initialize("dark");
            var widget = new NoteWidget(new NoteData());
            var chrome = NoteChrome(widget);

            if (!chrome.TitleMenuEnabled)
                throw new InvalidOperationException("the note widget did not enable the title menu");
            var chevron = chrome.FindName("TitleChevron") as FrameworkElement;
            if (chevron == null) throw new InvalidOperationException("WidgetChrome has no TitleChevron");
            if (chevron.Visibility != Visibility.Visible)
                throw new InvalidOperationException("the enabled title chevron is not visible");
        }

        /// <summary>
        /// T4 (spec 3.2): the dropdown is an action block over a title-only
        /// note list - new always, home only in the detail, the entries in
        /// modified-time order, the current one checked and highlighted, and an
        /// empty title spelled through the untitled key.
        /// </summary>
        private static void NoteTitleMenuGroupsActionsAndNotes()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Beta", new DateTime(2026, 3, 5, 11, 0, 0)));
            data.Notes.Add(NewNote("c", "   ", new DateTime(2026, 3, 5, 10, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            var homeMenu = view.BuildTitleMenuContent();
            if (homeMenu == null)
                throw new InvalidOperationException("BuildTitleMenuContent returned null");
            if (!"NoteTitleMenu".Equals(homeMenu.Tag as string))
                throw new InvalidOperationException(
                    "the title menu root is tagged '" + homeMenu.Tag + "', wanted 'NoteTitleMenu'");
            TitleMenuPart(homeMenu, "NoteMenuNew");
            if (TitleMenuContains(homeMenu, "NoteMenuHome"))
                throw new InvalidOperationException("the home title menu shows the home action");

            var homeEntries = NoteMenuEntries(homeMenu);
            AssertNoteMenuOrder(homeEntries, "b", "c", "a");
            foreach (var entry in homeEntries)
            {
                if (NoteMenuCheck(entry).Visibility != Visibility.Collapsed)
                    throw new InvalidOperationException("the home title menu already checks an entry");
            }

            ClickNoteCard(view, 0);          // Beta
            var detailMenu = view.BuildTitleMenuContent();
            TitleMenuPart(detailMenu, "NoteMenuNew");
            TitleMenuPart(detailMenu, "NoteMenuHome");

            var detailEntries = NoteMenuEntries(detailMenu);
            AssertNoteMenuOrder(detailEntries, "b", "c", "a");

            int checks = 0;
            foreach (var entry in detailEntries)
            {
                bool current = "b" == (entry.Tag as string);
                var check = NoteMenuCheck(entry);
                if (current)
                {
                    checks++;
                    if (check.Visibility != Visibility.Visible || check.Icon != IconId.Check)
                        throw new InvalidOperationException("the current entry carries no Check IconPresenter");
                    if (!ReferenceEquals(entry.Background, ThemeManager.SurfaceHoverBrush))
                        throw new InvalidOperationException("the current entry carries no highlight");
                }
                else if (check.Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException(
                        "the entry '" + entry.Tag + "' carries a stray check mark");
                }
            }
            if (checks != 1)
                throw new InvalidOperationException("the detail title menu checks " + checks + " entries");

            var blank = FindTagged(detailMenu, "c") as Button;
            if (blank == null) throw new InvalidOperationException("the untitled entry is missing");
            if (NoteMenuTitle(blank) != Localization.Get("UI_NoteUntitled"))
                throw new InvalidOperationException(
                    "the untitled entry reads '" + NoteMenuTitle(blank) + "'");
        }

        /// <summary>
        /// The title dropdown and the right-click menu both size to their
        /// content instead of stretching to a fixed 220..360 width. A short
        /// note list must not leave a large empty band on the right.
        /// </summary>
        private static void NoteTitleMenuWidthsToItsContent()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            var menu = view.BuildTitleMenuContent() as Border;
            if (menu == null) throw new InvalidOperationException("the title menu is not a Border");
            if (!double.IsNaN(menu.Width))
                throw new InvalidOperationException("the title menu still has a fixed width " + menu.Width);
            if (menu.MaxWidth > 360.01 || menu.MaxWidth <= 0)
                throw new InvalidOperationException("the title menu max width is " + menu.MaxWidth);

            menu.Measure(new Size(360, double.PositiveInfinity));
            if (menu.DesiredSize.Width >= 320)
                throw new InvalidOperationException(
                    "a short note list still measures " + menu.DesiredSize.Width.ToString("0.##") + " wide");
        }

        /// <summary>
        /// Spec 3.3 replacement: in the rendered detail a right-click inside
        /// the note content opens the full note menu (new / home / notes), not
        /// no menu and not the old two-entry blank menu. The current note is
        /// checked; the entries are in modified-time order.
        /// </summary>
        private static void NoteRenderedRightClickOpensTheFullMenu()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Beta", new DateTime(2026, 3, 5, 11, 0, 0)));
            data.Notes.Add(NewNote("c", "Gamma", new DateTime(2026, 3, 5, 10, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0); // Beta

            var root = NoteNamed(view, "Root");
            var opening = typeof(NotePanelView).GetMethod("Root_ContextMenuOpening",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (opening == null)
                throw new InvalidOperationException("Root_ContextMenuOpening not found on NotePanelView");

            var surfaceRoot = SurfaceNamed(NoteSurface(view), "SurfaceRoot");
            RaiseNoteContextMenuOpening(opening, view, root, surfaceRoot);

            var menu = root.ContextMenu;
            if (menu == null)
                throw new InvalidOperationException("a rendered-note right-click opened no menu");
            if (menu.Items.Count != 6)
                throw new InvalidOperationException(
                    "the full note menu has " + menu.Items.Count + " item(s), wanted 6");

            if (!"NoteMenuNew".Equals((menu.Items[0] as MenuItem)?.Tag as string))
                throw new InvalidOperationException("the full note menu has no new entry");
            if (!"NoteMenuHome".Equals((menu.Items[1] as MenuItem)?.Tag as string))
                throw new InvalidOperationException("the full note menu has no home entry");
            if (!(menu.Items[2] is Separator))
                throw new InvalidOperationException("the full note menu has no separator");

            string[] wanted = { "b", "c", "a" };
            string current = PrivateField<string>(view, "_expandedId");
            for (int i = 0; i < wanted.Length; i++)
            {
                var item = menu.Items[3 + i] as MenuItem;
                if (item == null || !wanted[i].Equals(item.Tag as string))
                    throw new InvalidOperationException(
                        "the full note menu entry " + i + " is not '" + wanted[i] + "'");
                bool isCurrent = wanted[i] == current;
                if (item.IsChecked != isCurrent)
                    throw new InvalidOperationException(
                        "the full note menu entry '" + wanted[i] + "' has the wrong check state");
                if (ContextMenuTitle(item) == string.Empty)
                    throw new InvalidOperationException("the full note menu entry has no title");
            }

            int before = data.Notes.Count;
            ((MenuItem)menu.Items[0]).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));
            if (data.Notes.Count != before + 1)
                throw new InvalidOperationException("the full note menu's new entry created no note");
        }

        /// <summary>
        /// The full note menu draws exactly one check per entry: the shared
        /// MenuItem template paints IsChecked in its 26px icon slot, so the
        /// header must not add a second Check IconPresenter of its own.
        /// </summary>
        private static void NoteRenderedMenuChecksOnlyOnce()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Beta", new DateTime(2026, 3, 5, 11, 0, 0)));
            data.Notes.Add(NewNote("c", "Gamma", new DateTime(2026, 3, 5, 10, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0); // Beta

            var menu = view.BuildNoteContextMenu();
            string current = PrivateField<string>(view, "_expandedId");
            int checks = 0;
            foreach (var entry in menu.Items)
            {
                var item = entry as MenuItem;
                if (item == null || item.Tag == null) continue;
                string tag = item.Tag as string;
                if (tag == "NoteMenuNew" || tag == "NoteMenuHome") continue;

                bool isCurrent = tag == current;
                if (item.IsChecked != isCurrent)
                    throw new InvalidOperationException(
                        "the note menu entry '" + tag + "' has the wrong check state");
                if (item.Header is Grid)
                    throw new InvalidOperationException(
                        "the note menu entry '" + tag + "' still carries a custom check column");
                if (!(item.Header is TextBlock))
                    throw new InvalidOperationException(
                        "the note menu entry '" + tag + "' has no plain title header");
                if (isCurrent) checks++;
            }
            if (checks != 1)
                throw new InvalidOperationException("the note menu checks " + checks + " entries");
        }

        /// <summary>
        /// The rendered note's text is a read-only RichTextBox: its built-in
        /// Cut/Copy/Paste menu would swallow the right-click before the panel
        /// sees it. The box must carry the full note menu instead, and that
        /// menu's note entries must switch the open note.
        /// </summary>
        private static void NoteReadingBoxOwnsTheFullNoteMenu()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Beta", new DateTime(2026, 3, 5, 11, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            view.OpenNote("b");

            var reading = SurfaceNamed(NoteSurface(view), "ReadingBox") as RichTextBox;
            if (reading == null)
                throw new InvalidOperationException("the reading box is missing");
            if (reading.ContextMenu == null)
                throw new InvalidOperationException("the reading box still falls back to its built-in text menu");

            RaiseContextMenuOpening(reading);
            var menu = reading.ContextMenu;
            if (menu.Items.Count != 5)
                throw new InvalidOperationException(
                    "the reading-box menu has " + menu.Items.Count + " item(s), wanted 5");
            if (!"NoteMenuNew".Equals((menu.Items[0] as MenuItem)?.Tag as string))
                throw new InvalidOperationException("the reading-box menu has no new entry");
            if (!"NoteMenuHome".Equals((menu.Items[1] as MenuItem)?.Tag as string))
                throw new InvalidOperationException("the reading-box menu has no home entry");
            if (!(menu.Items[2] is Separator))
                throw new InvalidOperationException("the reading-box menu has no separator");

            MenuItem alpha = null;
            for (int i = 3; i < menu.Items.Count; i++)
            {
                var item = menu.Items[i] as MenuItem;
                if (item != null && "a".Equals(item.Tag as string)) alpha = item;
            }
            if (alpha == null)
                throw new InvalidOperationException("the reading-box menu has no note entry");
            alpha.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));
            if (PrivateField<string>(view, "_expandedId") != "a")
                throw new InvalidOperationException("the reading-box menu did not switch notes");
        }

        /// <summary>Raises the real ContextMenuOpening route on one element.</summary>
        private static void RaiseContextMenuOpening(DependencyObject source)
        {
            var args = (ContextMenuEventArgs)Activator.CreateInstance(typeof(ContextMenuEventArgs),
                BindingFlags.Instance | BindingFlags.NonPublic, null, new object[] { source, true }, null);
            args.RoutedEvent = ContextMenuService.ContextMenuOpeningEvent;
            ((UIElement)source).RaiseEvent(args);
        }

        private static string ContextMenuTitle(MenuItem item)
        {
            if (item == null) return string.Empty;

            var text = item.Header as TextBlock;
            if (text != null) return text.Text;

            var header = item.Header as string;
            if (header != null) return header;

            var grid = item.Header as Grid;
            if (grid == null) return string.Empty;
            foreach (var child in grid.Children)
            {
                var childText = child as TextBlock;
                if (childText != null && !"NoteMenuCheck".Equals(childText.Tag as string)) return childText.Text;
            }
            return string.Empty;
        }

        /// <summary>
        /// T1: the note dropdown wears the shared launcher surface
        /// (the window radius and the surface brush) and its rows wear the
        /// shared <c>Kobold.Style.LauncherItem</c> row style - the one the
        /// island's plus menu reuses.
        /// </summary>
        private static void NoteTitleMenuUsesTheLauncherStyle()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            var menu = view.BuildTitleMenuContent() as Border;
            if (menu == null || !"NoteTitleMenu".Equals(menu.Tag as string))
                throw new InvalidOperationException("the title menu is not a tagged Border");
            if (Math.Abs(menu.CornerRadius.TopLeft - UiTokens.RadiusWindow) > 0.01)
                throw new InvalidOperationException("the title menu radius is " + menu.CornerRadius.TopLeft);
            if (!ReferenceEquals(menu.Background, ThemeManager.SurfaceBrush))
                throw new InvalidOperationException("the title menu does not wear the surface brush");

            var style = Application.Current.FindResource("Kobold.Style.LauncherItem") as Style;
            if (style == null) throw new InvalidOperationException("no Kobold.Style.LauncherItem resource");

            var newButton = TitleMenuPart(menu, "NoteMenuNew") as Button;
            if (newButton == null || !ReferenceEquals(newButton.Style, style))
                throw new InvalidOperationException("the new action does not wear the launcher style");
            var entry = NoteMenuEntries(menu)[0];
            if (!ReferenceEquals(entry.Style, style))
                throw new InvalidOperationException("a note entry does not wear the launcher style");
        }

        /// <summary>
        /// T4 (spec 3.2): picking another note commits the open edit, opens the
        /// target in its rendered state and leaves no session behind.
        /// </summary>
        private static void NoteTitleMenuSwitchesNotes()
        {
            ThemeManager.Initialize("dark");
            var older = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(older);
            data.Notes.Add(NewNote("b", "Beta", new DateTime(2026, 3, 5, 11, 0, 0)));

            var widget = new NoteWidget(data);
            var view = widget.PanelView;
            view.Refresh();
            ClickNoteCard(view, 1);          // the older note
            if (NoteExpandedId(view) != "a")
                throw new InvalidOperationException(
                    "the fixture opened '" + NoteExpandedId(view) + "', wanted the older note");

            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note's paragraph did not enter the block edit");
            SurfaceEditBox(surface).Text = "changed";

            // The real entry wiring (close, then OpenNote), picked by Tag.
            ClickTitleMenuEntry(view, "b");

            if (older.Text != "changed")
                throw new InvalidOperationException("the switch left the first note as '"
                    + (older.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (NoteExpandedId(view) != "b")
                throw new InvalidOperationException(
                    "the switch opened '" + NoteExpandedId(view) + "', wanted 'b'");
            if (surface.IsEditing)
                throw new InvalidOperationException("the switch left the first edit session open");
            if (view.IsHome)
                throw new InvalidOperationException("the switch dropped back to the home");
            var document = SurfaceReadingBox(surface).Document;
            if (document == null || document.Blocks.Count == 0)
                throw new InvalidOperationException("the target note holds no rendered document");
            if (view.ChromeTitle != "Beta")
                throw new InvalidOperationException(
                    "the switched title reads '" + view.ChromeTitle + "', wanted 'Beta'");

            // Picking the current note is a no-op: the entry closes the menu
            // but the detail stays on the same rendered note.
            ClickTitleMenuEntry(view, "b");
            if (NoteExpandedId(view) != "b")
                throw new InvalidOperationException("re-picking the current note switched away");
            if (surface.IsEditing)
                throw new InvalidOperationException("re-picking the current note opened an edit");
            if (older.Text != "changed")
                throw new InvalidOperationException("re-picking the current note rewrote the first note");
        }

        /// <summary>
        /// T4 (spec 3.2): the new action commits the open edit, puts a fresh
        /// note at the head of the data and opens it as one empty whole-text
        /// edit in the detail.
        /// </summary>
        private static void NoteTitleMenuStartsANewNote()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(note);

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);
            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note's paragraph did not enter the block edit");
            SurfaceEditBox(surface).Text = "typed";

            ClickTitleMenuPart(view, "NoteMenuNew");

            if (note.Text != "typed")
                throw new InvalidOperationException("the new action lost the open edit ('"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (data.Notes.Count != 2)
                throw new InvalidOperationException("the new action left " + data.Notes.Count + " note(s)");
            var fresh = data.Notes[0];
            if (fresh == note)
                throw new InvalidOperationException("the new note did not take the head of the data");
            if (fresh.Text != string.Empty)
                throw new InvalidOperationException("the fresh note carries '" + fresh.Text + "'");
            if (NoteExpandedId(view) != fresh.Id)
                throw new InvalidOperationException(
                    "the new action opened '" + NoteExpandedId(view) + "', wanted the fresh note");
            if (view.IsHome)
                throw new InvalidOperationException("the new action left the panel home");
            if (!surface.IsEditing)
                throw new InvalidOperationException("the fresh note did not open its whole-text edit");
            if (SurfaceEditBox(surface).Text != string.Empty)
                throw new InvalidOperationException("the fresh edit box carries '"
                    + SurfaceEditBox(surface).Text + "', wanted empty");
            if (view.ChromeTitle != Localization.Get("UI_NoteUntitled"))
                throw new InvalidOperationException(
                    "the fresh note title reads '" + view.ChromeTitle + "'");
        }

        /// <summary>
        /// T4 (spec 3.2/4.5): the home action commits the open edit and rebuilds
        /// the card list in modified-time order; a blank note travelling the
        /// same route is dropped and the drop notifies the host.
        /// </summary>
        private static void NoteTitleMenuReturnsHome()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Name = "Notebook" };
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Beta", new DateTime(2026, 3, 5, 11, 0, 0)));

            var widget = new NoteWidget(data);
            var view = widget.PanelView;
            view.Refresh();

            int notified = 0;
            widget.OnDataChanged += () => notified++;

            ClickNoteCard(view, 1);          // Alpha
            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note did not enter the block edit");
            SurfaceEditBox(surface).Text = "Zulu";

            ClickTitleMenuPart(view, "NoteMenuHome");

            if (data.Notes.Count != 2 || data.Notes[0].Text != "Zulu")
                throw new InvalidOperationException("the home action lost the open edit");
            if (!view.IsHome)
                throw new InvalidOperationException("the home action left the detail open");
            if (NoteNamed(view, "HomeHost").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the home host stayed hidden");
            if (NoteNamed(view, "DetailHost").Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the detail host stayed visible");
            if (view.ChromeTitle != "Notebook")
                throw new InvalidOperationException(
                    "the home title reads '" + view.ChromeTitle + "', wanted 'Notebook'");
            if (NoteCardLine(view, 0, 0) != "Zulu" || NoteCardLine(view, 1, 0) != "Beta")
                throw new InvalidOperationException("the home cards lost the modified-time order ("
                    + NoteCardLine(view, 0, 0) + ", " + NoteCardLine(view, 1, 0) + ")");

            // A blank note leaves through the same action: dropped + notified.
            ClickTitleMenuPart(view, "NoteMenuNew");
            if (data.Notes.Count != 3)
                throw new InvalidOperationException("the fixture never created the blank note");
            ClickTitleMenuPart(view, "NoteMenuHome");

            if (data.Notes.Count != 2)
                throw new InvalidOperationException(
                    "the blank note survived the home action (" + data.Notes.Count + " note(s))");
            if (notified < 1)
                throw new InvalidOperationException("the blank-note drop never notified the host");
            if (!view.IsHome)
                throw new InvalidOperationException("the blank note's home action left the detail open");
        }

        /// <summary>
        /// T4 (spec 3.2): building or opening the title menu never commits the
        /// open edit - the session and its typed text survive until an entry is
        /// really chosen. While the popup is open, the window-level Esc closes
        /// it (the popup never takes focus) without ending the edit; closing is
        /// idempotent. Off-screen the Popup cannot be shown, so its real
        /// open/focus behaviour stays on the smoke list (no fake pin), but the
        /// open flag and the Esc route are exercised whenever it holds.
        /// </summary>
        private static void NoteOpeningTheTitleMenuKeepsTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(note);

            var widget = new NoteWidget(data);
            var view = widget.PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);

            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note did not enter the block edit");
            SurfaceEditBox(surface).Text = "draft";

            if (view.IsTitleMenuOpen)
                throw new InvalidOperationException("the title dropdown is open before it was toggled");

            var content = view.BuildTitleMenuContent();
            if (content == null) throw new InvalidOperationException("the title menu content is null");
            if (!surface.IsEditing)
                throw new InvalidOperationException("building the title menu ended the edit");
            if (SurfaceEditBox(surface).Text != "draft")
                throw new InvalidOperationException("building the title menu rewrote the edit box");
            if (view.IsTitleMenuOpen)
                throw new InvalidOperationException("building the title menu opened the dropdown");

            view.ToggleTitleMenu(NoteNamed(view, "Root"));
            if (!view.IsTitleMenuOpen)
                throw new InvalidOperationException("ToggleTitleMenu did not mark the dropdown open");
            if (!surface.IsEditing)
                throw new InvalidOperationException("opening the title menu ended the edit");
            if (SurfaceEditBox(surface).Text != "draft")
                throw new InvalidOperationException("opening the title menu rewrote the edit box");

            // Raised on the window itself: the window's tunnelling handler is
            // the focus-independent Esc path, and it must run before the
            // panel's router (which would leave the edit).
            var esc = RaiseNotePreviewKey(widget, widget, Key.Escape);
            if (!esc.Handled)
                throw new InvalidOperationException("the open title menu's Esc was not handled");
            if (view.IsTitleMenuOpen)
                throw new InvalidOperationException("the open title menu survived Esc");
            if (!surface.IsEditing)
                throw new InvalidOperationException("the menu Esc ended the edit");
            if (SurfaceEditBox(surface).Text != "draft")
                throw new InvalidOperationException("the menu Esc rewrote the edit box");

            view.CloseTitleMenu();
            if (view.IsTitleMenuOpen)
                throw new InvalidOperationException("CloseTitleMenu left the dropdown open");
            view.CloseTitleMenu();                 // idempotent
            if (view.IsTitleMenuOpen)
                throw new InvalidOperationException("CloseTitleMenu is not idempotent");
            if (!surface.IsEditing)
                throw new InvalidOperationException("closing the title menu ended the edit");
            if (SurfaceEditBox(surface).Text != "draft")
                throw new InvalidOperationException("closing the title menu rewrote the edit box");
            if (note.Text != "one\ntwo")
                throw new InvalidOperationException("the title menu committed the draft");
        }

        /// <summary>
        /// T4 (spec 3.3/4.1): Esc inside a block edit leaves that block alone -
        /// the typed text is spliced into the note (Esc never loses text) and
        /// the detail stays open in the rendered state.
        /// </summary>
        private static void NoteEscLeavesABlockEditWithoutClosingTheDetail()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(note);

            var widget = new NoteWidget(data);
            var view = widget.PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);

            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note's paragraph did not enter the block edit");
            SurfaceEditBox(surface).Text = "changed";

            var args = RaiseNotePreviewKey(widget, SurfaceEditBox(surface), Key.Escape);

            if (!args.Handled)
                throw new InvalidOperationException("the block edit's Esc was not handled");
            if (surface.IsEditing)
                throw new InvalidOperationException("Esc left the block edit session open");
            if (view.IsHome)
                throw new InvalidOperationException("Esc closed the detail");
            if (note.Text != "changed")
                throw new InvalidOperationException("Esc left the note as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (SurfaceNamed(surface, "ReadingBox").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the surface did not render back after the Esc");
        }

        /// <summary>
        /// T4 (spec 4.2): a click on a rendered line of the detail's surface
        /// enters that block's edit. The trigger is the T4 pins' equivalent path
        /// (the content element first, the surface root's handler with the
        /// tagged span as its source when the off-screen runner's content
        /// elements do not walk the event up).
        /// </summary>
        private static void NoteClickingABlockEntersItsEditAtThatLine()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(note);

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);

            var surface = NoteSurface(view);
            ClickTaggedLine(surface, SurfaceReadingBox(surface), 1);

            if (!surface.IsEditing)
                throw new InvalidOperationException("the tagged-line click did not enter the block edit");
            LayoutSurface(surface);
            var edit = SurfaceEditBox(surface);
            if (edit.Text != "one\ntwo")
                throw new InvalidOperationException(
                    "the edit box reads '" + edit.Text.Replace("\n", "\\n") + "', wanted 'one\\ntwo'");
            int line = edit.GetLineIndexFromCharacterIndex(edit.CaretIndex);
            if (line != 1)
                throw new InvalidOperationException("the caret sits on edit line " + line + ", wanted 1");
        }

        /// <summary>
        /// T4 (spec 4.4/5.3): a task glyph clicked in the rendered detail flips
        /// its source line and never opens a block edit (the renderer marks the
        /// click handled and the surface's own handler skips it).
        /// </summary>
        private static void NoteTaskGlyphClickTogglesWithoutEnteringTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "# H\n\npara\n\n- [ ] t", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(note);

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);

            var surface = NoteSurface(view);
            var glyph = TaskGlyph(ParagraphAt(SurfaceReadingBox(surface).Document, 2));
            if (glyph.Child != null)
                throw new InvalidOperationException("the fixture started with a checked box");
            RaiseLeftClick(glyph);

            if (surface.IsEditing)
                throw new InvalidOperationException("the task click opened a block edit");
            if (!(note.Text ?? string.Empty).Contains("[x]"))
                throw new InvalidOperationException("the task click left the source as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
        }

        /// <summary>
        /// T4 (spec 3.3, user decision 7): in the rendered detail a click on the
        /// blank space - the surface host's padding band or the panel root's own
        /// margin - changes nothing: the detail never collapses on a blank
        /// click (the title menu / Esc / Backspace own the way home).
        /// </summary>
        private static void NoteRenderedBlankClicksNoLongerCollapse()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            data.Notes.Add(NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);

            ClickNoteHost(view);
            if (view.IsHome)
                throw new InvalidOperationException("the host-padding click collapsed the detail");

            ClickNoteRoot(view);
            if (view.IsHome)
                throw new InvalidOperationException("the root-margin click collapsed the detail");
            if (NoteExpandedId(view) != "a")
                throw new InvalidOperationException(
                    "the blank clicks moved the detail to '" + NoteExpandedId(view) + "'");
            if (NoteNamed(view, "HomeHost").Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the home host came back on a blank click");
            if (NoteNamed(view, "DetailHost").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the detail host disappeared on a blank click");
            if (SurfaceNamed(NoteSurface(view), "ReadingBox").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the detail left the rendered state");
        }

        /// <summary>
        /// T4 (spec 4.1/user decision 7): while editing, a click outside the
        /// surface - the surface host's padding band or the panel margin -
        /// commits the block and renders back, still in the detail. The second
        /// half re-enters the edit and repeats the click on the root, so both
        /// click-away paths are covered.
        /// </summary>
        private static void NoteBlankClicksLeaveTheEditButStayInTheDetail()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(note);

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);

            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note's paragraph did not enter the block edit");
            SurfaceEditBox(surface).Text = "changed";

            ClickNoteHost(view);
            AssertNoteLeftEdit(view, surface, note, "changed", "the host-padding click");

            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note did not re-enter the block edit");
            SurfaceEditBox(surface).Text = "changed again";

            ClickNoteRoot(view);
            AssertNoteLeftEdit(view, surface, note, "changed again", "the root-margin click");
        }

        private static void AssertNoteLeftEdit(NotePanelView view, NoteSurfaceView surface,
            NoteItem note, string wanted, string what)
        {
            if (surface.IsEditing)
                throw new InvalidOperationException(what + " left the edit open");
            if (view.IsHome)
                throw new InvalidOperationException(what + " collapsed the detail");
            if (note.Text != wanted)
                throw new InvalidOperationException(what + " left the note as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "', wanted '" + wanted + "'");
            if (!ReferenceEquals(NoteHost(view).Child, surface))
                throw new InvalidOperationException(what + " dropped the surface from its host");
            if (SurfaceNamed(surface, "ReadingBox").Visibility != Visibility.Visible)
                throw new InvalidOperationException(what + " did not render back");
        }

        /// <summary>
        /// T4 (spec 3.3): Esc / Backspace close the rendered detail back to the
        /// home; in the detail's edit they only leave the edit; at home they do
        /// nothing at all.
        /// </summary>
        private static void NoteEscAndBackspaceReturnHomeOnlyInTheRenderedDetail()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(note);

            var widget = new NoteWidget(data);
            var view = widget.PanelView;
            view.Refresh();

            ClickNoteCard(view, 0);
            var surface = NoteSurface(view);
            var args = RaiseNotePreviewKey(widget, SurfaceReadingBox(surface), Key.Escape);
            if (!args.Handled)
                throw new InvalidOperationException("the rendered Esc was not handled");
            if (!view.IsHome)
                throw new InvalidOperationException("the rendered Esc left the detail open");

            ClickNoteCard(view, 0);
            args = RaiseNotePreviewKey(widget, SurfaceReadingBox(surface), Key.Back);
            if (!args.Handled)
                throw new InvalidOperationException("the rendered Backspace was not handled");
            if (!view.IsHome)
                throw new InvalidOperationException("the rendered Backspace left the detail open");

            ClickNoteCard(view, 0);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note did not enter the block edit");
            SurfaceEditBox(surface).Text = "committed";
            args = RaiseNotePreviewKey(widget, SurfaceEditBox(surface), Key.Escape);
            if (!args.Handled)
                throw new InvalidOperationException("the edit Esc was not handled");
            if (surface.IsEditing)
                throw new InvalidOperationException("the edit Esc left the session open");
            if (view.IsHome)
                throw new InvalidOperationException("the edit Esc collapsed the detail");
            if (note.Text != "committed")
                throw new InvalidOperationException("the edit Esc lost the text");

            args = RaiseNotePreviewKey(widget, SurfaceReadingBox(surface), Key.Escape);
            if (!args.Handled)
                throw new InvalidOperationException("the second rendered Esc was not handled");
            if (!view.IsHome)
                throw new InvalidOperationException("the second rendered Esc left the detail open");

            args = RaiseNotePreviewKey(widget, SurfaceReadingBox(surface), Key.Escape);
            if (args.Handled)
                throw new InvalidOperationException("the home Esc was handled");
            args = RaiseNotePreviewKey(widget, SurfaceReadingBox(surface), Key.Back);
            if (args.Handled)
                throw new InvalidOperationException("the home Backspace was handled");
            if (!view.IsHome)
                throw new InvalidOperationException("the home keys moved the panel");
        }

        /// <summary>
        /// T4 (spec 3.3): the blank-area menu carries create + the note list at
        /// home, and create + back to the notes + the note list in the detail.
        /// The note item switches the view directly, so the home page's largest
        /// right-click target is also a switch entry.
        /// </summary>
        private static void NoteBlankMenuFollowsTheState()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            string newWanted = Localization.Format(
                "UI_NewWidgetFormat", Localization.Get("UI_WidgetKindNote"));

            var homeMenu = InvokeNoteBlankMenu(view);
            if (homeMenu == null) throw new InvalidOperationException("the home has no blank menu");
            if (homeMenu.Items.Count != 3)
                throw new InvalidOperationException(
                    "the home blank menu has " + homeMenu.Items.Count + " item(s), wanted 3");
            if (HeaderOf(homeMenu.Items[0]) != newWanted)
                throw new InvalidOperationException(
                    "the home blank menu reads '" + HeaderOf(homeMenu.Items[0]) + "'");
            AssertMenuIcon(homeMenu.Items[0], IconId.Plus);
            if (!(homeMenu.Items[1] is Separator))
                throw new InvalidOperationException("the home blank menu has no separator");
            var homeNote = homeMenu.Items[2] as MenuItem;
            if (homeNote == null || !"a".Equals(homeNote.Tag as string))
                throw new InvalidOperationException("the home blank menu has no note entry");
            homeNote.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));
            if (PrivateField<string>(view, "_expandedId") != "a")
                throw new InvalidOperationException("the home blank menu did not switch notes");

            var detailMenu = InvokeNoteBlankMenu(view);
            if (detailMenu == null) throw new InvalidOperationException("the detail has no blank menu");
            if (detailMenu.Items.Count != 4)
                throw new InvalidOperationException(
                    "the detail blank menu has " + detailMenu.Items.Count + " item(s), wanted 4");
            if (HeaderOf(detailMenu.Items[0]) != newWanted)
                throw new InvalidOperationException(
                    "the detail blank menu reads '" + HeaderOf(detailMenu.Items[0]) + "'");
            AssertMenuIcon(detailMenu.Items[0], IconId.Plus);
            if (HeaderOf(detailMenu.Items[1]) != Localization.Get("UI_NoteHome"))
                throw new InvalidOperationException(
                    "the detail blank menu's home entry reads '" + HeaderOf(detailMenu.Items[1]) + "'");
            AssertMenuIcon(detailMenu.Items[1], IconId.Home);
            if (!(detailMenu.Items[2] is Separator))
                throw new InvalidOperationException("the detail blank menu has no separator");
            var detailNote = detailMenu.Items[3] as MenuItem;
            if (detailNote == null || !"a".Equals(detailNote.Tag as string))
                throw new InvalidOperationException("the detail blank menu has no note entry");
            if (!detailNote.IsChecked)
                throw new InvalidOperationException("the detail blank menu does not check the open note");
        }

        /// <summary>
        /// The rendered detail's padding band and note surface both open the
        /// full note menu (new / home / notes); the old two-entry blank menu is
        /// only used while editing or at home.
        /// </summary>
        private static void NoteDetailPaddingBandOpensTheFullNoteMenu()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            ClickNoteCard(view, 0);
            if (view.IsHome)
                throw new InvalidOperationException("the card click did not open the detail");

            var root = NoteNamed(view, "Root");
            var opening = typeof(NotePanelView).GetMethod("Root_ContextMenuOpening",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (opening == null)
                throw new InvalidOperationException("Root_ContextMenuOpening not found on NotePanelView");

            RaiseNoteContextMenuOpening(opening, view, root, NoteHost(view));
            var menu = root.ContextMenu;
            if (menu == null)
                throw new InvalidOperationException("the detail's padding band assigned no menu");
            if (menu.Items.Count != 4)
                throw new InvalidOperationException(
                    "the padding-band menu has " + menu.Items.Count + " item(s), wanted 4");

            string newWanted = Localization.Format(
                "UI_NewWidgetFormat", Localization.Get("UI_WidgetKindNote"));
            if (HeaderOf(menu.Items[0]) != newWanted)
                throw new InvalidOperationException(
                    "the padding-band menu's new entry reads '" + HeaderOf(menu.Items[0]) + "'");
            AssertMenuIcon(menu.Items[0], IconId.Plus);
            if (HeaderOf(menu.Items[1]) != Localization.Get("UI_NoteHome"))
                throw new InvalidOperationException(
                    "the padding-band menu's home entry reads '" + HeaderOf(menu.Items[1]) + "'");
            AssertMenuIcon(menu.Items[1], IconId.Home);
            if (!(menu.Items[2] is Separator))
                throw new InvalidOperationException("the padding-band menu has no separator");
            if (!"a".Equals((menu.Items[3] as MenuItem)?.Tag as string))
                throw new InvalidOperationException("the padding-band menu's note entry is missing");

            RaiseNoteContextMenuOpening(opening, view, root, NoteSurface(view));
            var surfaceMenu = root.ContextMenu;
            if (surfaceMenu == null || surfaceMenu.Items.Count != 4)
                throw new InvalidOperationException(
                    "a right-click inside the rendered note did not open the full menu");
        }

        /// <summary>
        /// Invokes the panel's real ContextMenuOpening handler with the given
        /// hit source. The framework's non-public args constructor carries the
        /// source (its second argument is <c>opening</c>), and the original
        /// source stays unset because the event is dispatched straight to the
        /// handler rather than raised through the tree.
        /// </summary>
        private static void RaiseNoteContextMenuOpening(MethodInfo opening, NotePanelView view,
            FrameworkElement root, DependencyObject source)
        {
            var args = (ContextMenuEventArgs)Activator.CreateInstance(typeof(ContextMenuEventArgs),
                BindingFlags.Instance | BindingFlags.NonPublic, null, new object[] { source, true }, null);
            args.RoutedEvent = ContextMenuService.ContextMenuOpeningEvent;
            opening.Invoke(view, new object[] { root, args });
        }

        /// <summary>
        /// T4 (spec 3.3/6): the blank-area menu's create entry opens a fresh
        /// note straight into the whole-text edit in the detail.
        /// </summary>
        private static void NoteBlankAreaMenuStartsTheSameEdit()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            var menu = InvokeNoteBlankMenu(view);
            if (menu == null) throw new InvalidOperationException("the empty home has no blank-area menu");
            if (menu.Items.Count != 1)
                throw new InvalidOperationException("the blank-area menu has " + menu.Items.Count + " item(s)");

            string header = HeaderOf(menu.Items[0]);
            string wanted = Localization.Format(
                "UI_NewWidgetFormat", Localization.Get("UI_WidgetKindNote"));
            if (header != wanted)
                throw new InvalidOperationException(
                    "the blank-area menu reads '" + header + "', wanted '" + wanted + "'");
            AssertMenuIcon(menu.Items[0], IconId.Plus);

            var entry = menu.Items[0] as MenuItem;
            if (entry == null) throw new InvalidOperationException("the blank-area entry is not a MenuItem");
            entry.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));

            if (data.Notes.Count != 1)
                throw new InvalidOperationException(
                    "the blank-area menu left " + data.Notes.Count + " note(s), wanted 1");
            if (NoteExpandedId(view) != data.Notes[0].Id)
                throw new InvalidOperationException(
                    "the blank-area menu opened '" + NoteExpandedId(view) + "', wanted the fresh note");

            var surface = NoteSurface(view);
            if (!surface.IsEditing)
                throw new InvalidOperationException("the menu-opened note is not being edited");
            if (SurfaceEditBox(surface).Text != string.Empty)
                throw new InvalidOperationException("the menu-opened edit box is not empty");
        }

        /// <summary>
        /// T4 (spec 4.5): a note created by the title menu and left blank is
        /// dropped again on the way home - the data loses it, the drop notifies
        /// the host and the home shows its empty state.
        /// </summary>
        private static void NoteEmptyNewNoteIsDiscardedOnTheWayHome()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            var widget = new NoteWidget(data);
            var view = widget.PanelView;
            view.Refresh();

            int notified = 0;
            widget.OnDataChanged += () => notified++;

            ClickTitleMenuPart(view, "NoteMenuNew");
            if (data.Notes.Count != 1)
                throw new InvalidOperationException("the fixture never created a note");

            // First Esc leaves the whole-text edit (still blank, still there);
            // the second closes the rendered detail and drops the blank note.
            var surface = NoteSurface(view);
            RaiseNotePreviewKey(widget, SurfaceEditBox(surface), Key.Escape);
            if (view.IsHome)
                throw new InvalidOperationException("the edit Esc already left the detail");
            RaiseNotePreviewKey(widget, SurfaceReadingBox(surface), Key.Escape);

            if (data.Notes.Count != 0)
                throw new InvalidOperationException(
                    "the empty note survived the way home (" + data.Notes.Count + " note(s))");
            if (!view.IsHome)
                throw new InvalidOperationException("the discarded note stayed in the detail");
            if (NoteCardCount(view) != 0)
                throw new InvalidOperationException("the empty home rendered " + NoteCardCount(view) + " card(s)");
            if (notified < 1)
                throw new InvalidOperationException("the discard never notified the host");
        }

        /// <summary>
        /// T4 (spec 4.5): clearing an existing note's text (whitespace counts as
        /// nothing) drops that note on the way home too - only that one, and the
        /// removal notifies the host.
        /// </summary>
        private static void NoteEmptyingAnExistingNoteDiscardsItOnTheWayHome()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            data.Notes.Add(NewNote("a", "First", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Second", new DateTime(2026, 3, 5, 11, 0, 0)));

            var widget = new NoteWidget(data);
            var view = widget.PanelView;
            view.Refresh();

            int notified = 0;
            widget.OnDataChanged += () => notified++;

            ClickNoteCard(view, 1);          // the older note (card 0 is "Second")
            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note did not enter the block edit");
            SurfaceEditBox(surface).Text = "   ";

            RaiseNotePreviewKey(widget, SurfaceEditBox(surface), Key.Escape);
            RaiseNotePreviewKey(widget, SurfaceReadingBox(surface), Key.Escape);

            if (data.Notes.Count != 1 || data.Notes[0].Id != "b")
                throw new InvalidOperationException(
                    "the emptied note survived (" + data.Notes.Count + " note(s) left)");
            if (NoteCardCount(view) != 1)
                throw new InvalidOperationException("the home carries " + NoteCardCount(view) + " row(s), wanted 1");
            if (notified < 1)
                throw new InvalidOperationException("the discard never notified the host");
        }

        /// <summary>
        /// T4 (spec 5.2): hiding the panel flushes the pending edit before the
        /// window goes away - the half-typed note is in the data, not lost, and
        /// the block edit session is closed (the detail state survives for the
        /// panel's next opening). The open flag is set reflectively (the base's
        /// own field), so the check never shows a window.
        /// </summary>
        private static void NoteHidingThePanelCommitsAndLeavesTheEdit()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            var widget = new NoteWidget(data);
            var view = widget.PanelView;
            view.Refresh();

            EnsureRealDpi(widget);
            SetPrivateBaseField(widget, "_isExpanded", true);

            ClickTitleMenuPart(view, "NoteMenuNew");
            var surface = NoteSurface(view);
            SurfaceEditBox(surface).Text = "half a thought";
            widget.HidePanel();

            if (data.Notes.Count != 1)
                throw new InvalidOperationException(
                    "the collapse left " + data.Notes.Count + " note(s), wanted 1");
            if (data.Notes[0].Text != "half a thought")
                throw new InvalidOperationException(
                    "the collapse lost the edit ('" + data.Notes[0].Text + "')");
            if (surface.IsEditing)
                throw new InvalidOperationException("the collapse left the block edit open");
            if (NoteExpandedId(view) != data.Notes[0].Id)
                throw new InvalidOperationException(
                    "the collapse dropped the detail note (" + NoteExpandedId(view) + ")");
        }

        /// <summary>
        /// T4 (spec 4.3): a refresh (theme / language / widget update) during an
        /// open block edit repaints the surface but never rewrites the typed text
        /// or drops the session, and the detail stays open.
        /// </summary>
        private static void NoteRefreshDuringAnEditKeepsTheText()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(note);

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);

            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note's paragraph did not enter the block edit");
            var edit = SurfaceEditBox(surface);
            edit.Text = "typed";

            view.Refresh();

            if (edit.Text != "typed")
                throw new InvalidOperationException(
                    "the refresh rewrote the edit box as '" + edit.Text.Replace("\n", "\\n") + "'");
            if (!surface.IsEditing)
                throw new InvalidOperationException("the refresh dropped the block edit session");
            if (view.IsHome)
                throw new InvalidOperationException("the refresh closed the detail");
        }

        /// <summary>
        /// T4 (spec 4.5): the committed edit stamps the note's modified time, so
        /// going home rebuilds the cards with that note on top (SortForDisplay)
        /// and its face carries the fresh title.
        /// </summary>
        private static void NoteOrderFollowsTheLatestEditAfterGoingHome()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            data.Notes.Add(NewNote("a", "Alpha", new DateTime(2026, 3, 5, 9, 0, 0)));
            data.Notes.Add(NewNote("b", "Beta", new DateTime(2026, 3, 5, 11, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            if (NoteCardLine(view, 0, 0) != "Beta")
                throw new InvalidOperationException(
                    "the fixture order is '" + NoteCardLine(view, 0, 0) + "', wanted 'Beta' first");

            ClickNoteCard(view, 1);          // the older note
            var surface = NoteSurface(view);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the note did not enter the block edit");
            SurfaceEditBox(surface).Text = "Zulu";

            ClickTitleMenuPart(view, "NoteMenuHome");

            if (!view.IsHome)
                throw new InvalidOperationException("the home action left a note open");
            if (NoteCardLine(view, 0, 0) != "Zulu")
                throw new InvalidOperationException(
                    "the edited note is card '" + NoteCardLine(view, 0, 0) + "', wanted it on top");
            if (NoteCardLine(view, 1, 0) != "Beta")
                throw new InvalidOperationException(
                    "the untouched note is card '" + NoteCardLine(view, 1, 0) + "', wanted 'Beta'");
        }

        /// <summary>
        /// T4 (spec 5.3): a task box clicked in the detail's rendered surface
        /// writes the flipped source line back, stamps the modified time and
        /// re-renders the document - the stale glyph stays alone (the document
        /// was rebuilt, not mutated in place).
        /// </summary>
        private static void NoteTaskToggleRewritesAndRerendersInPlace()
        {
            ThemeManager.Initialize("dark");
            var when = new DateTime(2026, 3, 5, 9, 0, 0);
            var note = NewNote("a", "# H\n\npara\n\n- [ ] t", when);
            var data = new NoteData();
            data.Notes.Add(note);

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);

            var box = SurfaceReadingBox(NoteSurface(view));
            var before = box.Document;
            var glyph = TaskGlyph(ParagraphAt(before, 2));
            if (glyph.Child != null)
                throw new InvalidOperationException("the fixture started with a checked box");
            RaiseLeftClick(glyph);

            if (!(note.Text ?? string.Empty).Contains("[x]"))
                throw new InvalidOperationException("the toggle left the source as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (note.ModifiedAt < when)
                throw new InvalidOperationException(
                    "the toggle rolled the modified time back (" + note.ModifiedAt + ")");

            var after = box.Document;
            if (ReferenceEquals(after, before))
                throw new InvalidOperationException("the rendered document was not rebuilt");
            var afterCheck = TaskGlyph(ParagraphAt(after, 2)).Child as IconPresenter;
            if (afterCheck == null || afterCheck.Icon != IconId.Check)
                throw new InvalidOperationException("the rebuilt document carries no Check IconPresenter");
        }

        /// <summary>
        /// T4 (spec 5.2): the detail's rendered document keeps each link's
        /// target on Hyperlink.NavigateUri so the click can hand it to the
        /// browser. The pin reads the target only - raising the click would open
        /// one.
        /// </summary>
        private static void NoteRenderedLinkCarriesItsUrl()
        {
            const string url = "https://example.com/panel?p=1";
            ThemeManager.Initialize("dark");
            var data = new NoteData();
            data.Notes.Add(NewNote("a", "see [the site](" + url + ")", new DateTime(2026, 3, 5, 9, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();
            ClickNoteCard(view, 0);

            var link = FirstHyperlink(SurfaceReadingBox(NoteSurface(view)).Document);
            if (link.NavigateUri == null)
                throw new InvalidOperationException("the rendered link carries no url");
            if (link.NavigateUri.AbsoluteUri != url)
                throw new InvalidOperationException("the rendered link carries '"
                    + link.NavigateUri.AbsoluteUri + "', wanted '" + url + "'");
        }

        /// <summary>Opens a note through the real card click (the card face's
        /// MouseLeftButtonUp handler), never a reflection call.</summary>
        private static void ClickNoteCard(NotePanelView view, int index)
        {
            NoteCardAt(view, index).RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent
            });
        }

        private static FrameworkElement NoteNamed(NotePanelView view, string name)
        {
            var element = view.FindName(name) as FrameworkElement;
            if (element == null) throw new InvalidOperationException("NotePanelView has no " + name);
            return element;
        }

        /// <summary>The panel's one surface instance, off the private `_surface`
        /// field (T6).</summary>
        private static NoteSurfaceView NoteSurface(NotePanelView view)
        {
            var surface = NotePrivate(view, "_surface") as NoteSurfaceView;
            if (surface == null) throw new InvalidOperationException("_surface is not a NoteSurfaceView");
            return surface;
        }

        /// <summary>The expanded note's id, off the private `_expandedId` field
        /// (T4): null is the home, anything else the detail.</summary>
        private static string NoteExpandedId(NotePanelView view)
        {
            return NotePrivate(view, "_expandedId") as string;
        }

        private static object NotePrivate(NotePanelView view, string name)
        {
            var field = typeof(NotePanelView).GetField(name,
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (field == null) throw new InvalidOperationException(name + " not found on NotePanelView");
            return field.GetValue(view);
        }

        /// <summary>The detail's permanent surface host (a Border carrying the
        /// panel's one surface), off the private `_surfaceHost` field.</summary>
        private static Border NoteHost(NotePanelView view)
        {
            var host = NotePrivate(view, "_surfaceHost") as Border;
            if (host == null) throw new InvalidOperationException("_surfaceHost is not a Border");
            return host;
        }

        /// <summary>The widget's chrome, off the XAML name (the pin reads the
        /// title the panel pushes onto it).</summary>
        private static WidgetChrome NoteChrome(NoteWidget widget)
        {
            var chrome = widget.FindName("NoteChrome") as WidgetChrome;
            if (chrome == null) throw new InvalidOperationException("the widget has no NoteChrome");
            return chrome;
        }

        /// <summary>Builds the title dropdown through its public builder (the
        /// production popup content), then raises one action's real click.</summary>
        private static void ClickTitleMenuPart(NotePanelView view, string tag)
        {
            var part = TitleMenuPart(view.BuildTitleMenuContent(), tag);
            var button = part as Button;
            if (button == null)
                throw new InvalidOperationException("the title-menu part '" + tag + "' is not a Button");
            button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
        }

        /// <summary>Builds the title dropdown and raises one note entry's real
        /// click, picked by its Tag (the note id) - the same wiring the popup
        /// uses (close the menu, then open the note).</summary>
        private static void ClickTitleMenuEntry(NotePanelView view, string noteId)
        {
            var entry = FindTagged(view.BuildTitleMenuContent(), noteId) as Button;
            if (entry == null)
                throw new InvalidOperationException("the title menu has no note entry '" + noteId + "'");
            entry.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
        }

        /// <summary>The first element in the title menu tagged with
        /// <paramref name="tag"/>; throws when the menu has none.</summary>
        private static FrameworkElement TitleMenuPart(FrameworkElement root, string tag)
        {
            var found = FindTagged(root, tag);
            if (found == null)
                throw new InvalidOperationException("the title menu has no part tagged '" + tag + "'");
            return found;
        }

        private static bool TitleMenuContains(FrameworkElement root, string tag)
        {
            return FindTagged(root, tag) != null;
        }

        private static FrameworkElement FindTagged(DependencyObject node, string tag)
        {
            var element = node as FrameworkElement;
            if (element != null && string.Equals(element.Tag as string, tag, StringComparison.Ordinal))
                return element;
            foreach (var child in LogicalTreeHelper.GetChildren(node))
            {
                var dependency = child as DependencyObject;
                if (dependency == null) continue;
                var found = FindTagged(dependency, tag);
                if (found != null) return found;
            }
            return null;
        }

        /// <summary>The title menu's note entries in presentation order - every
        /// Button that is not one of the two action tags (its Tag is the note
        /// id).</summary>
        private static List<Button> NoteMenuEntries(FrameworkElement root)
        {
            var buttons = new List<Button>();
            CollectButtons(root, buttons);

            var entries = new List<Button>();
            foreach (var button in buttons)
            {
                string tag = button.Tag as string;
                if (tag == "NoteMenuNew" || tag == "NoteMenuHome") continue;
                entries.Add(button);
            }
            return entries;
        }

        private static void CollectButtons(DependencyObject node, List<Button> found)
        {
            var button = node as Button;
            if (button != null) found.Add(button);
            foreach (var child in LogicalTreeHelper.GetChildren(node))
            {
                var dependency = child as DependencyObject;
                if (dependency != null) CollectButtons(dependency, found);
            }
        }

        private static void AssertNoteMenuOrder(List<Button> entries, params string[] ids)
        {
            if (entries.Count != ids.Length)
                throw new InvalidOperationException(
                    "the title menu lists " + entries.Count + " note(s), wanted " + ids.Length);
            for (int i = 0; i < ids.Length; i++)
            {
                string tag = entries[i].Tag as string;
                if (tag != ids[i])
                    throw new InvalidOperationException(
                        "the title menu entry " + i + " is '" + tag + "', wanted '" + ids[i] + "'");
            }
        }

        /// <summary>The check IconPresenter of one note entry (collapsed when
        /// the entry is not the current note).</summary>
        private static IconPresenter NoteMenuCheck(Button entry)
        {
            var grid = entry.Content as Grid;
            if (grid == null) throw new InvalidOperationException("the note entry has no content grid");
            foreach (var child in grid.Children)
            {
                var icon = child as IconPresenter;
                if (icon != null && "NoteMenuCheck".Equals(icon.Tag as string)) return icon;
            }
            throw new InvalidOperationException("the note entry carries no check mark element");
        }

        /// <summary>The title TextBlock of one note entry (the one that is not
        /// the check icon).</summary>
        private static string NoteMenuTitle(Button entry)
        {
            var grid = entry.Content as Grid;
            if (grid == null) throw new InvalidOperationException("the note entry has no content grid");
            foreach (var child in grid.Children)
            {
                var text = child as TextBlock;
                if (text != null) return text.Text;
            }
            throw new InvalidOperationException("the note entry carries no title element");
        }

        /// <summary>A left click on the detail's surface host padding band: the
        /// root sees its own direct-event copy, so the hit is the host (never a
        /// surface descendant).</summary>
        private static void ClickNoteHost(NotePanelView view)
        {
            NoteNamed(view, "Root").RaiseEvent(new MouseButtonEventArgs(
                Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonDownEvent,
                Source = NoteHost(view)
            });
        }

        /// <summary>A left click on the panel's own margin.</summary>
        private static void ClickNoteRoot(NotePanelView view)
        {
            NoteNamed(view, "Root").RaiseEvent(new MouseButtonEventArgs(
                Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonDownEvent
            });
        }

        /// <summary>
        /// The note panel's rendered-detail key input: the same real
        /// presentation source the surface reading pins built (EnsureHandle
        /// creates the HwndSource), raised as the tunnelling PreviewKeyDown on
        /// the surface's own box - the document box is no TextBox, so the todo
        /// helper's signature does not fit. Returns the args so the pin can read
        /// Handled.
        /// </summary>
        private static KeyEventArgs RaiseNotePreviewKey(Window window, FrameworkElement target, Key key)
        {
            EnsureRealDpi(window);
            IntPtr handle = new System.Windows.Interop.WindowInteropHelper(window).Handle;
            PresentationSource source = System.Windows.Interop.HwndSource.FromHwnd(handle);
            if (source == null) throw new InvalidOperationException("no presentation source for key input");

            var args = new KeyEventArgs(Keyboard.PrimaryDevice, source, 0, key)
            {
                RoutedEvent = UIElement.PreviewKeyDownEvent
            };
            target.RaiseEvent(args);
            return args;
        }

        /// <summary>Builds the blank-area menu through its private builder (the
        /// real ContextMenuOpening route only opens what it returns).</summary>
        private static ContextMenu InvokeNoteBlankMenu(NotePanelView view)
        {
            var method = typeof(NotePanelView).GetMethod("BuildBlankMenu",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (method == null) throw new InvalidOperationException("BuildBlankMenu not found on NotePanelView");
            return (ContextMenu)method.Invoke(view, null);
        }

        #endregion

        #region Task T5: note key helpers shared with the surface menu pins

        /// <summary>The <c>Note_TableColumnFormat</c> value one language at a
        /// time (the brief's three forms), with the language put back.</summary>
        private static void AssertTableColumnFormat(string language, string wanted)
        {
            Localization.SetLanguage(language);
            try
            {
                string templated = Localization.Get("Note_TableColumnFormat");
                if (templated != wanted)
                    throw new InvalidOperationException(
                        language + ": the table column key reads '" + templated + "', wanted '" + wanted + "'");
            }
            finally
            {
                Localization.SetLanguage("en");
            }
        }

        #endregion

        #region Task T3: note surface pins

        /// <summary>
        /// T3 (spec 4.1): Attach binds the note and paints the rendered state -
        /// the single read-only document box is visible with one block per
        /// top-level markdown block, while the three editing panes (the before
        /// / after renders and the source box) stay collapsed until T4 enters a
        /// block.
        /// </summary>
        private static void SurfaceAttachRendersTheDocument()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "# H\n\npara\n\n- [ ] t", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (SurfaceNamed(surface, "ReadingBox").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the reading box is hidden after Attach");
            string[] panes = { "BeforeBox", "EditBox", "AfterBox" };
            foreach (string pane in panes)
            {
                if (SurfaceNamed(surface, pane).Visibility != Visibility.Collapsed)
                    throw new InvalidOperationException(pane + " is visible in the rendered state");
            }

            var box = SurfaceReadingBox(surface);
            int blocks = box.Document == null ? -1 : box.Document.Blocks.Count;
            if (blocks != 3)
                throw new InvalidOperationException("the rendered document holds " + blocks + " block(s), wanted 3");
        }

        /// <summary>
        /// T3 (spec 4.1/5.3): a task box click writes the flipped source line
        /// back, stamps the modified time, notifies the host exactly once and
        /// re-renders so the fresh glyph carries its check; the stale glyph is
        /// left alone (the document was rebuilt, not mutated in place).
        /// </summary>
        private static void SurfaceTaskClickRewritesAndRerenders()
        {
            ThemeManager.Initialize("dark");
            var when = new DateTime(2026, 3, 5, 9, 0, 0);
            var note = NewNote("a", "# H\n\npara\n\n- [ ] t", when);
            var surface = NewSurface(new NoteData(), note);

            int changed = 0;
            surface.DataChanged += () => changed++;

            var box = SurfaceReadingBox(surface);
            var before = box.Document;
            var open = TaskGlyph(ParagraphAt(before, 2));
            if (open.Child != null)
                throw new InvalidOperationException("the fixture started with a checked box");

            open.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent
            });

            if (!(note.Text ?? string.Empty).Contains("[x]"))
            {
                throw new InvalidOperationException("the toggle left the source as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            }
            if (note.ModifiedAt < when)
                throw new InvalidOperationException("the toggle rolled the modified time back (" + note.ModifiedAt + ")");
            if (changed != 1)
                throw new InvalidOperationException("the toggle notified the host " + changed + " time(s), wanted 1");

            var after = box.Document;
            if (ReferenceEquals(after, before))
                throw new InvalidOperationException("the surface was not re-rendered after the toggle");
            var afterCheck = TaskGlyph(ParagraphAt(after, 2)).Child as IconPresenter;
            if (afterCheck == null || afterCheck.Icon != IconId.Check)
                throw new InvalidOperationException("the re-rendered box carries no Check IconPresenter");
        }

        /// <summary>
        /// T3 (spec 4.1/5.2): the rendered link keeps its target on
        /// Hyperlink.NavigateUri so the surface can hand it to the browser; the
        /// pin reads the target only - raising the click would open one.
        /// </summary>
        private static void SurfaceLinkCarriesItsUrl()
        {
            const string url = "https://example.com/surface?p=1";
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "see [the site](" + url + ")", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            var link = FirstHyperlink(SurfaceReadingBox(surface).Document);
            if (link.NavigateUri == null)
                throw new InvalidOperationException("the rendered link carries no url");
            if (link.NavigateUri.AbsoluteUri != url)
                throw new InvalidOperationException("the rendered link carries '"
                    + link.NavigateUri.AbsoluteUri + "', wanted '" + url + "'");
        }

        /// <summary>
        /// T3 (spec 4.1): Repaint is the theme/language repaint path - it
        /// rebuilds the rendered document off the live theme while leaving the
        /// note itself untouched (the editing guard arrives with T4).
        /// </summary>
        private static void SurfaceRepaintRerendersTheDocument()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "# H\n\npara", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);
            var before = SurfaceReadingBox(surface).Document;

            ThemeManager.Initialize("light");
            surface.Repaint();

            var after = SurfaceReadingBox(surface).Document;
            if (after == null || after.Blocks.Count == 0)
                throw new InvalidOperationException("Repaint left the rendered document empty");
            if (ReferenceEquals(after, before))
                throw new InvalidOperationException("Repaint did not rebuild the rendered document");
        }

        /// <summary>
        /// T3: a surface attached to one note of a widget's data - the new
        /// component's own entry, no host window or panel needed.
        /// </summary>
        private static NoteSurfaceView NewSurface(NoteData data, NoteItem note)
        {
            var surface = new NoteSurfaceView();
            surface.Attach(data, note);
            return surface;
        }

        private static FrameworkElement SurfaceNamed(NoteSurfaceView surface, string name)
        {
            var element = surface.FindName(name) as FrameworkElement;
            if (element == null) throw new InvalidOperationException("NoteSurfaceView has no " + name);
            return element;
        }

        private static RichTextBox SurfaceReadingBox(NoteSurfaceView surface)
        {
            var named = surface.FindName("ReadingBox");
            if (named == null) throw new InvalidOperationException("NoteSurfaceView has no ReadingBox");
            var box = named as RichTextBox;
            if (box == null)
                throw new InvalidOperationException("ReadingBox is a " + named.GetType().Name + ", not a RichTextBox");
            return box;
        }

        #endregion

        #region Task T4: note surface edit pins

        /// <summary>The block-edit fixture: a heading, a two-line paragraph
        /// (source lines 2 and 3) and a task. The parser's ranges own the blank
        /// run between blocks (spec 5.4), so the paragraph's region is [2,5) and
        /// its box text keeps the trailing blank line.</summary>
        private const string SurfaceEditFixture = "# h\n\none\ntwo\n\n- x";

        /// <summary>
        /// T4 (spec 4.2/4.3): a line click enters the block edit - the target
        /// block's source range lands in the box, the panes before/after it
        /// render statically (no callbacks) and the reading box gives way.
        /// </summary>
        private static void SurfaceEnteringEditSwapsInThePanes()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", SurfaceEditFixture, new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(3))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            if (!surface.IsEditing)
                throw new InvalidOperationException("IsEditing stayed false after TryBeginEditAt(3)");

            var edit = SurfaceEditBox(surface);
            if (edit.Text != "one\ntwo\n")
            {
                throw new InvalidOperationException("the edit box reads '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted 'one\\ntwo\\n'");
            }

            int before = SurfaceBeforeBox(surface).Document.Blocks.Count;
            int after = SurfaceAfterBox(surface).Document.Blocks.Count;
            if (before != 1)
                throw new InvalidOperationException("the before pane rendered " + before + " block(s), wanted 1");
            if (after != 1)
                throw new InvalidOperationException("the after pane rendered " + after + " block(s), wanted 1");

            if (SurfaceNamed(surface, "ReadingBox").Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the reading box stayed visible in edit");
            string[] panes = { "BeforeBox", "EditBox", "AfterBox" };
            foreach (string pane in panes)
            {
                if (SurfaceNamed(surface, pane).Visibility != Visibility.Visible)
                    throw new InvalidOperationException(pane + " is hidden while editing");
            }
        }

        /// <summary>
        /// T4 (spec 4.2): the caret lands on the line that was clicked, not at
        /// the top - line 3 sits one line into the [2,5) region.
        /// </summary>
        private static void SurfaceCaretLandsOnTheClickedLine()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", SurfaceEditFixture, new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(3))
                throw new InvalidOperationException("the paragraph block did not enter edit");

            LayoutSurface(surface);
            var edit = SurfaceEditBox(surface);
            int line = edit.GetLineIndexFromCharacterIndex(edit.CaretIndex);
            if (line != 1)
                throw new InvalidOperationException("the caret sits on edit line " + line + ", wanted 1");
        }

        /// <summary>
        /// T4 (spec 4.2/4.3): the source box wears the edited block's own type -
        /// a heading its ladder size and weight, a fenced block the renderer's
        /// monospace family, a paragraph the plain body size.
        /// </summary>
        private static void SurfaceEditBoxMatchesTheBlockType()
        {
            ThemeManager.Initialize("dark");
            var when = new DateTime(2026, 3, 5, 9, 0, 0);

            var heading = NewSurface(new NoteData(), NewNote("h", "# Head\n\ntail", when));
            if (!heading.TryBeginEditAt(0))
                throw new InvalidOperationException("the heading block did not enter edit");
            var headingBox = SurfaceEditBox(heading);
            double wanted = NoteMarkdownRenderer.HeadingFontSize(1, UiTokens.FontBody);
            if (Math.Abs(headingBox.FontSize - wanted) > 0.01)
            {
                throw new InvalidOperationException("the heading box is " + headingBox.FontSize
                    + "pt, wanted " + wanted);
            }
            if (headingBox.FontWeight != FontWeights.SemiBold)
                throw new InvalidOperationException("the heading box is not semi-bold (" + headingBox.FontWeight + ")");

            var code = NewSurface(new NoteData(), NewNote("c", "pre\n\n```\ncode\n```", when));
            if (!code.TryBeginEditAt(2))
                throw new InvalidOperationException("the code block did not enter edit");
            var codeBox = SurfaceEditBox(code);
            if (codeBox.FontFamily.Source.IndexOf("Consolas", StringComparison.Ordinal) < 0)
            {
                throw new InvalidOperationException("the code box uses '" + codeBox.FontFamily.Source
                    + "', wanted the monospace family");
            }

            var body = NewSurface(new NoteData(), NewNote("b", SurfaceEditFixture, when));
            if (!body.TryBeginEditAt(3))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            var bodyBox = SurfaceEditBox(body);
            if (Math.Abs(bodyBox.FontSize - UiTokens.FontBody) > 0.01)
                throw new InvalidOperationException("the body box is " + bodyBox.FontSize
                    + "pt, wanted " + UiTokens.FontBody);
        }

        /// <summary>
        /// T4 (spec 4.3): typing arms the 400ms throttle - the tick is what
        /// splices, so the data is still untouched right after the keystroke.
        /// </summary>
        private static void SurfaceTypingSchedulesTheThrottle()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            SurfaceEditBox(surface).Text = "changed";

            if (!SurfaceThrottle(surface).IsEnabled)
                throw new InvalidOperationException("typing did not start the throttle");
            if (note.Text != "one\ntwo")
                throw new InvalidOperationException("the data changed before the tick: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
        }

        /// <summary>
        /// T4 (spec 4.3/5.1): the throttle tick splices the region back into the
        /// note, stamps the modified time and notifies the host once.
        /// </summary>
        private static void SurfaceThrottleTickCommitsTheRegion()
        {
            ThemeManager.Initialize("dark");
            var when = new DateTime(2026, 3, 5, 9, 0, 0);
            var note = NewNote("a", "one\ntwo", when);
            var surface = NewSurface(new NoteData(), note);

            int changed = 0;
            surface.DataChanged += () => changed++;

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            SurfaceEditBox(surface).Text = "changed";
            InvokeNoteSurface(surface, "Throttle_Tick", null, EventArgs.Empty);

            if (note.Text != "changed")
                throw new InvalidOperationException("the tick left the note as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (note.ModifiedAt < when)
                throw new InvalidOperationException("the tick rolled the modified time back (" + note.ModifiedAt + ")");
            if (changed != 1)
                throw new InvalidOperationException("the tick notified the host " + changed + " time(s), wanted 1");
        }

        /// <summary>
        /// T4 (spec 5.2): Flush splices the pending region at once but keeps the
        /// edit session (the panel-hide / close path).
        /// </summary>
        private static void SurfaceFlushCommitsWithoutLeaving()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            SurfaceEditBox(surface).Text = "changed";
            surface.Flush();

            if (note.Text != "changed")
                throw new InvalidOperationException("Flush left the note as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (!surface.IsEditing)
                throw new InvalidOperationException("Flush left the edit session");
        }

        /// <summary>
        /// T4 (spec 4.3): leaving splices the pending region, drops the session
        /// and renders the whole note again off the fresh data.
        /// </summary>
        private static void SurfaceLeavingTheEditSplicesAndRerenders()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            SurfaceEditBox(surface).Text = "changed";
            surface.LeaveEdit();

            if (surface.IsEditing)
                throw new InvalidOperationException("the session survived LeaveEdit");
            if (note.Text != "changed")
                throw new InvalidOperationException("leaving left the note as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (SurfaceNamed(surface, "ReadingBox").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the reading box stayed hidden after leaving");
            if (SurfaceEditBox(surface).Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the edit box stayed visible after leaving");

            string shown = SurfaceDocumentText(SurfaceReadingBox(surface));
            if (shown.IndexOf("changed", StringComparison.Ordinal) < 0)
                throw new InvalidOperationException("the re-rendered document reads '" + shown + "'");
        }

        /// <summary>
        /// T4 (spec 4.3/5.3): entering and leaving without a keystroke touches
        /// neither the text nor the modified time and notifies nobody (the
        /// entry-text guard).
        /// </summary>
        private static void SurfaceLeavingWithoutChangesKeepsTextAndTime()
        {
            ThemeManager.Initialize("dark");
            var when = new DateTime(2026, 3, 5, 9, 0, 0);
            var note = NewNote("a", "one\ntwo", when);
            var surface = NewSurface(new NoteData(), note);

            int changed = 0;
            surface.DataChanged += () => changed++;

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            surface.LeaveEdit();

            if (note.Text != "one\ntwo")
                throw new InvalidOperationException("leaving rewrote the text as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (note.ModifiedAt != when)
                throw new InvalidOperationException("leaving bumped the modified time (" + note.ModifiedAt + ")");
            if (changed != 0)
                throw new InvalidOperationException("leaving notified the host " + changed + " time(s), wanted 0");
        }

        /// <summary>
        /// T4 (spec 5.4): an empty note has no block range, so a click can never
        /// enter a block edit there (the new-note flow uses BeginEditWhole).
        /// </summary>
        private static void SurfaceEnteringEditOnAnEmptyNoteFails()
        {
            ThemeManager.Initialize("dark");
            var surface = NewSurface(new NoteData(), NewNote("a", "", new DateTime(2026, 3, 5, 9, 0, 0)));

            if (surface.TryBeginEditAt(0))
                throw new InvalidOperationException("an empty note entered a block edit");
            if (surface.IsEditing)
                throw new InvalidOperationException("IsEditing turned true on an empty note");
        }

        /// <summary>
        /// T4 (spec 4.2/4.4): a click on a rendered line bubbles to the surface
        /// root and enters that line's block edit, caret on the clicked line.
        /// </summary>
        private static void SurfaceClickingATaggedLineEntersItsEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            ClickTaggedLine(surface, SurfaceReadingBox(surface), 1);

            if (!surface.IsEditing)
                throw new InvalidOperationException("the tagged-line click did not enter the edit");
            LayoutSurface(surface);
            var edit = SurfaceEditBox(surface);
            if (edit.Text != "one\ntwo")
                throw new InvalidOperationException("the box reads '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted 'one\\ntwo'");
            int line = edit.GetLineIndexFromCharacterIndex(edit.CaretIndex);
            if (line != 1)
                throw new InvalidOperationException("the caret sits on edit line " + line + ", wanted 1");
        }

        /// <summary>
        /// T4 (spec 8.1 #5): a click on a block's first line opens exactly that
        /// block - the caret lands at its start, not at the note's start.
        /// </summary>
        private static void SurfaceClickingABlocksFirstLineOpensThatBlock()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "# one\n\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            ClickTaggedLine(surface, SurfaceReadingBox(surface), 2);

            if (!surface.IsEditing)
                throw new InvalidOperationException("the second block's first line did not enter the edit");
            var edit = SurfaceEditBox(surface);
            if (edit.Text != "two")
                throw new InvalidOperationException("the box reads '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted 'two'");
            if (edit.CaretIndex != 0)
                throw new InvalidOperationException("the caret sits at " + edit.CaretIndex + ", wanted 0");
        }

        /// <summary>
        /// T4 (spec 4.4): clicking another block while editing commits the
        /// current region first and then opens the clicked one.
        /// </summary>
        private static void SurfaceClickingAnotherBlockSwitchesTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo\n\nthree", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the first paragraph did not enter edit");
            // The region owns the blank run up to the next block (spec 5.4), so
            // the typed text keeps that separator.
            SurfaceEditBox(surface).Text = "changed\n";

            // The other block a reader can click while editing is the pane after
            // the edited block (what is visible), not the collapsed reading box.
            ClickTaggedLine(surface, SurfaceAfterBox(surface), 3);

            if (!surface.IsEditing)
                throw new InvalidOperationException("the switch dropped the edit session");
            if (note.Text != "changed\n\nthree")
                throw new InvalidOperationException("the first region was not committed: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            var edit = SurfaceEditBox(surface);
            if (edit.Text != "three")
                throw new InvalidOperationException("the box now reads '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted 'three'");
        }

        /// <summary>
        /// T4 (spec 4.3/4.4, final-review I1): the after pane was painted from
        /// the entry document and keeps those line tags while the edit grows the
        /// region. The click must resolve to the block it names - here the
        /// fourth paragraph "d", which after the splice sits behind the three
        /// blocks the edited region produced, rather than landing inside the
        /// edit. The trailing newline keeps the separator the region owns
        /// (spec 5.4) so "c" stays a block of its own.
        /// </summary>
        private static void SurfaceClickingAfterPaneAfterGrowthOpensTheRightBlock()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "a\n\nb\n\nc\n\nd", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(2))
                throw new InvalidOperationException("the second paragraph did not enter edit");
            SurfaceEditBox(surface).Text = "b\n\nx\n\ny\n";

            // The after pane still paints the entry blocks "c" (line 4) and
            // "d" (line 6); click the fourth paragraph.
            ClickTaggedLine(surface, SurfaceAfterBox(surface), 6);

            if (!surface.IsEditing)
                throw new InvalidOperationException("the switch dropped the edit session");
            if (note.Text != "a\n\nb\n\nx\n\ny\n\nc\n\nd")
                throw new InvalidOperationException("the grown region was not committed: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            var edit = SurfaceEditBox(surface);
            if (edit.Text != "d")
            {
                throw new InvalidOperationException("the after-pane click opened '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted the fourth paragraph 'd'");
            }
        }

        /// <summary>
        /// T4 (spec 4.2): a task box click is handled by the renderer's glyph -
        /// the toggle writes the line back and no edit session opens. This is the
        /// rendered-state toggle assertion; the root hop with the handled mark is
        /// pinned once, by SurfaceHandledGlyphClickDoesNotEnterTheEdit.
        /// </summary>
        private static void SurfaceHandledClickDoesNotEnterTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "# H\n\npara\n\n- [ ] t", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            var box = SurfaceReadingBox(surface);
            var glyph = TaskGlyph(ParagraphAt(box.Document, 2));
            RaiseLeftClick(glyph);

            if (surface.IsEditing)
                throw new InvalidOperationException("the handled glyph click opened an edit");
            if (!(note.Text ?? string.Empty).Contains("[x]"))
                throw new InvalidOperationException("the glyph click did not toggle the task: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
        }

        /// <summary>
        /// Post-smoke fix A (spec 4.2/4.4): the reading box marks its mouse-up
        /// handled once it holds the focus (LeaveEdit hands it back), so the
        /// surface's root handler is attached with handledEventsToo. The very
        /// event a focused RichTextBox would swallow must still open the clicked
        /// block. Raised on the root itself, with the tagged span as its source
        /// and Handled already set - only a handledEventsToo wiring sees it.
        /// </summary>
        private static void SurfaceHandledClickOnTaggedLineEntersTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);
            var span = SpanWithLine(SurfaceReadingBox(surface).Document, 1);

            SurfaceNamed(surface, "SurfaceRoot").RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                Source = span,
                Handled = true
            });

            if (!surface.IsEditing)
                throw new InvalidOperationException(
                    "a handled click on a tagged line did not enter the edit (the root wiring is not handledEventsToo)");
            var edit = SurfaceEditBox(surface);
            if (edit.Text != "one\ntwo")
                throw new InvalidOperationException("the box reads '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted 'one\\ntwo'");
        }

        /// <summary>
        /// Real-mouse regression (spec 4.2): a real mouse release reports the
        /// reading box itself as OriginalSource, so the tagged span is never on
        /// the hit chain - the WPF hit test that produced the event stopped at
        /// the box. The surface therefore resolves the clicked line from the
        /// point. Layout the surface for real, take the line-1 span's own
        /// character rect and hand that point to <c>LineAtPoint</c>: a box
        /// without the point resolution answers -1 (its OriginalSource walk
        /// finds no tag on the box) and this pin fails.
        /// </summary>
        private static void SurfaceLineAtPointResolvesAParagraph()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);
            LayoutSurface(surface);

            var box = SurfaceReadingBox(surface);
            var span = SpanWithLine(box.Document, 1);
            Rect rect = span.ContentStart.GetCharacterRect(LogicalDirection.Forward);
            if (rect.IsEmpty)
                throw new InvalidOperationException(
                    "the line-1 span has no character rect after layout (the pin has no stable point)");

            var method = typeof(NoteSurfaceView).GetMethod("LineAtPoint",
                BindingFlags.Static | BindingFlags.NonPublic);
            if (method == null)
                throw new InvalidOperationException("NoteSurfaceView has no LineAtPoint");
            // The off-screen char rect is degenerate in X (width 0), so a nudge
            // past its left edge is all that is needed; Y + 2 lands inside the
            // line box, which is what must resolve to the line.
            var point = new Point(rect.X + 1, rect.Y + 2);
            int line = (int)method.Invoke(null, new object[] { box, point });

            if (line != 1)
                throw new InvalidOperationException("the point " + point.X.ToString("0") + ","
                    + point.Y.ToString("0") + " resolved to line " + line + ", wanted 1");
        }

        /// <summary>
        /// Task 1B (spec 4.2): a click also names the character inside the
        /// line, so the caret lands exactly there instead of on the line's
        /// first column. The paragraph's source starts at its own line start,
        /// so column 8 is the clicked 'o' of "two".
        /// </summary>
        private static void SurfaceCaretLandsOnTheClickedCharacter()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "# H\n\none **two** three", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(2, 8))
                throw new InvalidOperationException("the paragraph did not enter edit");

            var edit = SurfaceEditBox(surface);
            if (edit.Text != "one **two** three")
                throw new InvalidOperationException("the box reads '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted the paragraph source");
            if (edit.CaretIndex != 8)
                throw new InvalidOperationException("the caret sits at " + edit.CaretIndex + ", wanted 8");
        }

        /// <summary>
        /// Task 1B (spec 4.2): a heading's source carries its `# ` marker, so
        /// the column the caller names is already a source column - column 4
        /// is the 'a' of "Head".
        /// </summary>
        private static void SurfaceHeadingCaretSkipsTheMarker()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "# Head\n\nbody", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(0, 4))
                throw new InvalidOperationException("the heading did not enter edit");

            var edit = SurfaceEditBox(surface);
            if (edit.Text != "# Head\n")
                throw new InvalidOperationException("the box reads '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted the heading source");
            if (edit.CaretIndex != 4)
                throw new InvalidOperationException("the caret sits at " + edit.CaretIndex + ", wanted 4");
        }

        /// <summary>
        /// Task 1B (spec 4.2): a task line's source carries `- [ ] `, so the
        /// caller's column 8 is the 's' of "task" inside the source line.
        /// </summary>
        private static void SurfaceTaskCaretSkipsTheBox()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "- [ ] task", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(0, 8))
                throw new InvalidOperationException("the task did not enter edit");

            var edit = SurfaceEditBox(surface);
            if (edit.Text != "- [ ] task")
                throw new InvalidOperationException("the box reads '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted the task source");
            if (edit.CaretIndex != 8)
                throw new InvalidOperationException("the caret sits at " + edit.CaretIndex + ", wanted 8");
        }

        /// <summary>
        /// Task 1B (spec 4.2): the click point names a visible character
        /// offset inside the tagged line, which is what the root handler hands
        /// to <see cref="NoteCaretMap"/>. Layout the surface for real, take the
        /// line-1 Run's third character rect and hand that point to
        /// <c>CaretAtPoint</c>: the offset must be the character's own. Counting
        /// from the Run (not the span's symbol offsets) keeps the pin honest.
        /// </summary>
        private static void SurfaceCaretAtPointNamesTheVisualOffset()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);
            LayoutSurface(surface);

            var box = SurfaceReadingBox(surface);
            var span = SpanWithLine(box.Document, 1);
            var run = FindRunWithText(span.Inlines, "two");
            if (run == null)
                throw new InvalidOperationException("the line-1 span has no 'two' run");

            var point = CharacterPoint(run.ContentStart.GetPositionAtOffset(2), "the line-1 third character");
            var result = InvokeCaretAtPoint(box, point);

            if (!result.Resolved)
                throw new InvalidOperationException("CaretAtPoint resolved nothing at " + point.X.ToString("0")
                    + "," + point.Y.ToString("0"));
            if (result.Line != 1)
                throw new InvalidOperationException("CaretAtPoint named line " + result.Line + ", wanted 1");
            if (result.VisualOffset != 2)
                throw new InvalidOperationException("CaretAtPoint named visual offset "
                    + result.VisualOffset + ", wanted 2");
        }

        /// <summary>
        /// Task 1B review fix: a task box is an InlineUIContainer and occupies no
        /// visible character, so clicking the first visible character of "task"
        /// must name offset 0, not the glyph's symbol offset 1. The count is
        /// structural because this runtime's TextRange.Text reads the container
        /// back as U+0020, which a plain text-length count would mistake for a
        /// visible space.
        /// </summary>
        private static void SurfaceCaretAtPointSubtractsATaskGlyph()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "- [ ] task", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);
            LayoutSurface(surface);

            var box = SurfaceReadingBox(surface);
            var paragraph = ParagraphAt(box.Document, 0);
            var run = RunWithText(paragraph, "task");

            var point = CharacterPoint(run.ContentStart, "the task text's first character");
            var result = InvokeCaretAtPoint(box, point);

            if (!result.Resolved)
                throw new InvalidOperationException("CaretAtPoint resolved nothing at " + point.X.ToString("0")
                    + "," + point.Y.ToString("0"));
            if (result.Line != 0)
                throw new InvalidOperationException("CaretAtPoint named line " + result.Line + ", wanted 0");
            if (result.VisualOffset != 0)
                throw new InvalidOperationException("CaretAtPoint named visual offset "
                    + result.VisualOffset + ", wanted 0 (the glyph is not a visible character)");
        }

        /// <summary>
        /// Task 1B review fix: emphasis is flattened into runs, so a click in
        /// the "two" run of "one **two** three" counts the characters of the
        /// whole visible line ("one tw" = 6), not the run's local offset.
        /// </summary>
        private static void SurfaceCaretAtPointCountsFormattedLineCharacters()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one **two** three", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);
            LayoutSurface(surface);

            var box = SurfaceReadingBox(surface);
            var span = SpanWithLine(box.Document, 0);
            var run = FindRunWithText(span.Inlines, "two");
            if (run == null)
                throw new InvalidOperationException("the line-0 span has no 'two' run");

            var point = CharacterPoint(run.ContentStart.GetPositionAtOffset(2), "the formatted third character");
            var result = InvokeCaretAtPoint(box, point);

            if (!result.Resolved)
                throw new InvalidOperationException("CaretAtPoint resolved nothing at " + point.X.ToString("0")
                    + "," + point.Y.ToString("0"));
            if (result.Line != 0)
                throw new InvalidOperationException("CaretAtPoint named line " + result.Line + ", wanted 0");
            if (result.VisualOffset != 6)
                throw new InvalidOperationException("CaretAtPoint named visual offset "
                    + result.VisualOffset + ", wanted 6");
        }

        /// <summary>The point at a character's own rect, nudged inside its line
        /// box (the off-screen rect is degenerate in X).</summary>
        private static Point CharacterPoint(TextPointer pointer, string what)
        {
            if (pointer == null)
                throw new InvalidOperationException(what + " has no character position");

            Rect rect = pointer.GetCharacterRect(LogicalDirection.Forward);
            if (rect.IsEmpty)
                throw new InvalidOperationException(
                    what + " has no rect after layout (the pin has no stable point)");
            return new Point(rect.X + 1, rect.Y + 2);
        }

        /// <summary>Invokes the production point resolver by reflection.</summary>
        private static (bool Resolved, int Line, int VisualOffset) InvokeCaretAtPoint(
            RichTextBox box, Point point)
        {
            var method = typeof(NoteSurfaceView).GetMethod("CaretAtPoint",
                BindingFlags.Static | BindingFlags.NonPublic);
            if (method == null)
                throw new InvalidOperationException("NoteSurfaceView has no CaretAtPoint");

            var args = new object[] { box, point, -1, 0 };
            bool resolved = (bool)method.Invoke(null, args);
            return (resolved, (int)args[2], (int)args[3]);
        }

        /// <summary>
        /// Post-smoke fix A (spec 4.2/4.4): the glyph's own handler sets Handled
        /// and toggles, and the root (seeing handled events now) must not turn
        /// that same release into an edit. The click route is the glyph's own,
        /// never a reflection call.
        /// </summary>
        private static void SurfaceHandledGlyphClickDoesNotEnterTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "# H\n\npara\n\n- [ ] t", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            int changed = 0;
            surface.DataChanged += () => changed++;

            var glyph = TaskGlyph(ParagraphAt(SurfaceReadingBox(surface).Document, 2));
            var args = new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent
            };
            glyph.RaiseEvent(args);

            if (!args.Handled)
                throw new InvalidOperationException("the glyph handler did not mark its click handled");
            if (surface.IsEditing)
                throw new InvalidOperationException("the handled glyph click opened an edit");
            if (!(note.Text ?? string.Empty).Contains("[x]"))
                throw new InvalidOperationException("the glyph click did not toggle the task: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (changed != 1)
                throw new InvalidOperationException("the glyph click notified the host " + changed + " time(s), wanted 1");

            // MouseLeftButtonUp is a direct event: the input system re-raises it
            // per element, and the root's copy arrives already handled with the
            // glyph as its source. Hand that hop to the root - the toggle above
            // must not turn into an edit.
            SurfaceNamed(surface, "SurfaceRoot").RaiseEvent(new MouseButtonEventArgs(
                Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                Source = glyph,
                Handled = true
            });

            if (surface.IsEditing)
                throw new InvalidOperationException("the handled glyph click reached the block handler");
        }

        /// <summary>
        /// Post-smoke fix B (spec 4.3/4.4): with the edit open, a click on the
        /// card's chrome - the stack / padding, no tagged line under it - commits
        /// the region and returns to the rendered state, while the card itself
        /// stays expanded (no collapse request, the reading document is back).
        /// </summary>
        private static void SurfaceClickingChromeWhileEditingLeavesTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo\n\nthree", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the first paragraph did not enter edit");
            SurfaceEditBox(surface).Text = "changed\n";

            SurfaceNamed(surface, "SurfaceRoot").RaiseEvent(
                new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                    Source = SurfaceNamed(surface, "SurfaceStack")
                });

            if (surface.IsEditing)
                throw new InvalidOperationException("a chrome click left the edit session open");
            if (note.Text != "changed\n\nthree")
                throw new InvalidOperationException("the chrome click did not commit the region: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (SurfaceNamed(surface, "ReadingBox").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the reading box stayed hidden after the click-away");
            if (SurfaceEditBox(surface).Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the edit box stayed visible after the click-away");
            var document = SurfaceReadingBox(surface).Document;
            if (document == null || document.Blocks.Count == 0)
                throw new InvalidOperationException("the card lost its rendered note after the click-away");
        }

        /// <summary>
        /// Post-smoke fix B (spec 4.3/4.4): a click inside the source box is
        /// typing surface, not click-away - the edit stays open.
        /// </summary>
        private static void SurfaceClickingInsideTheBoxKeepsTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");

            SurfaceNamed(surface, "SurfaceRoot").RaiseEvent(
                new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                    Source = SurfaceEditBox(surface)
                });

            if (!surface.IsEditing)
                throw new InvalidOperationException("a click inside the source box left the edit");
        }

        /// <summary>
        /// Fix round 1 (spec 4.3/4.4): the scrollbar and its thumb own their
        /// drag; their untagged release is not the in-card click-away. Raised as
        /// the root's handled copy with each chrome element as the hit, the same
        /// shape the direct-event route carries.
        /// </summary>
        private static void SurfaceScrollbarClickKeepsTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");

            var root = SurfaceNamed(surface, "SurfaceRoot");
            var chrome = new DependencyObject[] { new ScrollBar(), new Thumb() };
            foreach (var hit in chrome)
            {
                root.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                    Source = hit
                });

                if (!surface.IsEditing)
                    throw new InvalidOperationException("a " + hit.GetType().Name + " click left the edit");
            }
        }

        /// <summary>
        /// T4 (spec 6): the new-note flow opens the whole text as one edit region
        /// with both surrounding renders empty.
        /// </summary>
        private static void SurfaceBeginWholeTextEditCoversTheFullText()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            surface.BeginEditWhole();

            if (!surface.IsEditing)
                throw new InvalidOperationException("BeginEditWhole did not enter the edit");
            var edit = SurfaceEditBox(surface);
            if (edit.Text != "one\ntwo")
                throw new InvalidOperationException("the box reads '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted 'one\\ntwo'");
            int before = SurfaceBeforeBox(surface).Document.Blocks.Count;
            int after = SurfaceAfterBox(surface).Document.Blocks.Count;
            if (before != 0 || after != 0)
                throw new InvalidOperationException("the surrounding panes render " + before + "/" + after + " block(s)");
        }

        /// <summary>
        /// T4 (spec 4.3) / post-smoke fix B: the before/after renders are static
        /// - their task boxes carry no callback, so a click there writes nothing.
        /// The glyph is still a control: while editing it sits outside the edited
        /// block, so the root treats its release as the click-away - the session
        /// commits and renders back, data untouched.
        /// </summary>
        private static void SurfaceBeforeAndAfterPanesAreInert()
        {
            ThemeManager.Initialize("dark");
            string text = "- [ ] first\n\npara\n\n- [ ] last";
            var note = NewNote("a", text, new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(2))
                throw new InvalidOperationException("the paragraph block did not enter edit");

            var glyph = TaskGlyph(ParagraphAt(SurfaceBeforeBox(surface).Document, 0));
            RaiseLeftClick(glyph);

            if (note.Text != text)
                throw new InvalidOperationException("the inert before pane wrote the data: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");

            SurfaceNamed(surface, "SurfaceRoot").RaiseEvent(
                new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                    Source = glyph,
                    Handled = true
                });

            if (surface.IsEditing)
                throw new InvalidOperationException("the pane glyph click did not leave the edit");
            if (note.Text != text)
                throw new InvalidOperationException("leaving the edit wrote the inert pane's task: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (SurfaceNamed(surface, "ReadingBox").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the reading box stayed hidden after the pane glyph click");
        }

        /// <summary>
        /// T4 (spec 4.3): a repaint while editing rebuilds the panes' style but
        /// never touches the typed text or the session.
        /// </summary>
        private static void SurfaceRepaintDuringEditKeepsTheBoxText()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", SurfaceEditFixture, new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(3))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            var edit = SurfaceEditBox(surface);
            edit.Text = "edited";
            var before = SurfaceBeforeBox(surface).Document;

            ThemeManager.Initialize("light");
            surface.Repaint();

            if (edit.Text != "edited")
                throw new InvalidOperationException("the repaint rewrote the box as '"
                    + edit.Text.Replace("\n", "\\n") + "'");
            if (!surface.IsEditing)
                throw new InvalidOperationException("the repaint dropped the edit session");
            if (SurfaceNamed(surface, "ReadingBox").Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the repaint showed the reading box");
            var after = SurfaceBeforeBox(surface).Document;
            if (after == null || after.Blocks.Count != 1)
                throw new InvalidOperationException("the repaint left the before pane without its block");
            if (ReferenceEquals(after, before))
                throw new InvalidOperationException("the repaint did not rebuild the before pane");
        }

        /// <summary>
        /// T4 (spec 5.2): splicing the same region text twice converges - the
        /// second call is a no-op and the host is notified once.
        /// </summary>
        private static void SurfaceTwoSplicesConverge()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            int changed = 0;
            surface.DataChanged += () => changed++;

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            SurfaceEditBox(surface).Text = "changed";
            surface.Flush();
            string text = note.Text;
            DateTime time = note.ModifiedAt;

            surface.Flush();

            if (note.Text != text)
                throw new InvalidOperationException("the second splice rewrote the note: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (note.ModifiedAt != time)
                throw new InvalidOperationException("the second splice bumped the modified time");
            if (changed != 1)
                throw new InvalidOperationException("the splices notified the host " + changed + " time(s), wanted 1");
        }

        #endregion

        #region Task 5: note surface append pins

        /// <summary>
        /// Task 5 (spec 4.1/4.2): the end-of-text blank is an editing-only
        /// surface - rendered (just attached) it is collapsed, an open block
        /// edit shows it, and leaving the edit collapses it again.
        /// </summary>
        private static void SurfaceAppendZoneOnlyVisibleWhileEditing()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);
            var zone = SurfaceAppendZone(surface);

            if (zone.Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the append zone is visible in the rendered state");

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            if (zone.Visibility != Visibility.Visible)
                throw new InvalidOperationException("the append zone is hidden while editing");

            surface.LeaveEdit();
            if (zone.Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the append zone stayed visible after leaving the edit");
        }

        /// <summary>
        /// Task 5 (spec 4.2): a click on the end-of-text blank commits the open
        /// block and opens a fresh block after the whole text - the box is empty,
        /// every existing block paints in the before pane and the after pane is
        /// empty. Typing then appends the new block one blank line below the
        /// text, stamped and notified once.
        /// </summary>
        private static void SurfaceAppendZoneStartsANewBlock()
        {
            ThemeManager.Initialize("dark");
            var when = new DateTime(2026, 3, 5, 9, 0, 0);
            var note = NewNote("a", "one\ntwo", when);
            var surface = NewSurface(new NoteData(), note);

            int changed = 0;
            surface.DataChanged += () => changed++;

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            ClickAppendZone(surface);

            if (!surface.IsEditing)
                throw new InvalidOperationException("the append click dropped the edit session");
            var edit = SurfaceEditBox(surface);
            if (edit.Text != "")
                throw new InvalidOperationException("the append box opened with '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted empty");

            int before = SurfaceBeforeBox(surface).Document.Blocks.Count;
            int after = SurfaceAfterBox(surface).Document.Blocks.Count;
            if (before != 1)
                throw new InvalidOperationException("the before pane rendered " + before + " block(s), wanted 1");
            if (after != 0)
                throw new InvalidOperationException("the after pane rendered " + after + " block(s), wanted 0");

            edit.Text = "new";
            surface.Flush();

            if (note.Text != "one\ntwo\n\nnew")
                throw new InvalidOperationException("the append wrote '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "', wanted 'one\\ntwo\\n\\nnew'");
            if (note.ModifiedAt <= when)
                throw new InvalidOperationException("the append did not stamp the modified time (still " + note.ModifiedAt + ")");
            if (changed != 1)
                throw new InvalidOperationException("the append notified the host " + changed + " time(s), wanted 1");
        }

        /// <summary>
        /// Task 5 (spec 4.2): the append entry commits the block that is open
        /// first. A dirty box must land in the note before the append session
        /// snapshots its prefix - otherwise the typed block change would be
        /// silently dropped by the empty new box.
        /// </summary>
        private static void SurfaceAppendZoneCommitsADirtyBlockFirst()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            SurfaceEditBox(surface).Text = "changed";

            ClickAppendZone(surface);

            if (note.Text != "changed")
                throw new InvalidOperationException("the dirty block was not committed before the append: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (!surface.IsEditing)
                throw new InvalidOperationException("the append click dropped the edit session");
            if (SurfaceEditBox(surface).Text != "")
                throw new InvalidOperationException("the append box opened with '"
                    + SurfaceEditBox(surface).Text.Replace("\n", "\\n") + "', wanted empty");
        }

        /// <summary>
        /// Task 5 (spec 4.2): the append commit is idempotent - a later Flush /
        /// LeaveEdit / pane switch with the same box text must not append the
        /// body twice nor notify the host again.
        /// </summary>
        private static void SurfaceAppendDoubleCommitKeepsOneBlock()
        {
            ThemeManager.Initialize("dark");

            // Flush (the throttle's commit), then LeaveEdit (its own Flush).
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);
            int changed = 0;
            surface.DataChanged += () => changed++;

            if (!surface.TryBeginAppendEdit())
                throw new InvalidOperationException("the append session did not open");
            SurfaceEditBox(surface).Text = "new";
            surface.Flush();
            surface.LeaveEdit();

            if (note.Text != "one\ntwo\n\nnew")
                throw new InvalidOperationException("the double commit wrote '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "', wanted one appended block");
            if (changed != 1)
                throw new InvalidOperationException("the double commit notified the host " + changed + " time(s), wanted 1");

            // Flush, then a pane switch (the switch commits the append again).
            var switched = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var other = NewSurface(new NoteData(), switched);
            int switchedChanged = 0;
            other.DataChanged += () => switchedChanged++;

            if (!other.TryBeginAppendEdit())
                throw new InvalidOperationException("the append session did not open on the switch fixture");
            SurfaceEditBox(other).Text = "new";
            other.Flush();
            ClickTaggedLine(other, SurfaceBeforeBox(other), 1);

            if (switched.Text != "one\ntwo\n\nnew")
                throw new InvalidOperationException("the switch double commit wrote '"
                    + (switched.Text ?? string.Empty).Replace("\n", "\\n") + "', wanted one appended block");
            if (switchedChanged != 1)
                throw new InvalidOperationException("the switch double commit notified the host "
                    + switchedChanged + " time(s), wanted 1");
        }

        /// <summary>
        /// Task 5 (spec 4.2 layout): the zone is the grid's second row under the
        /// pane stack, at least 48px tall, and the scroller stretches its
        /// content so a short note lets the zone fill the rest of the viewport.
        /// The pixel height itself is never asserted off-screen.
        /// </summary>
        private static void SurfaceAppendZoneIsTheStretchRowBelowThePanes()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);
            var zone = SurfaceAppendZone(surface);

            if (Grid.GetRow(zone) != 1)
                throw new InvalidOperationException("the append zone sits in grid row " + Grid.GetRow(zone) + ", wanted 1");

            var stack = SurfaceNamed(surface, "SurfaceStack") as Grid;
            if (stack == null)
                throw new InvalidOperationException("SurfaceStack is not a Grid");
            if (!ReferenceEquals(zone.Parent, stack))
                throw new InvalidOperationException("the append zone is not a child of SurfaceStack");
            if (zone.MinHeight < 48)
                throw new InvalidOperationException("the append zone's MinHeight is " + zone.MinHeight + ", wanted >= 48");

            var scroller = SurfaceNamed(surface, "SurfaceScroller") as ScrollViewer;
            if (scroller == null)
                throw new InvalidOperationException("SurfaceScroller is not a ScrollViewer");
            if (scroller.VerticalContentAlignment != VerticalAlignment.Stretch)
                throw new InvalidOperationException("SurfaceScroller's VerticalContentAlignment is "
                    + scroller.VerticalContentAlignment + ", wanted Stretch");
        }

        /// <summary>
        /// Task 5 (spec 4.2): an append session that types nothing leaves the
        /// note exactly as it was - no empty block, no stamp, no notification.
        /// </summary>
        private static void SurfaceEmptyAppendWritesNothing()
        {
            ThemeManager.Initialize("dark");
            var when = new DateTime(2026, 3, 5, 9, 0, 0);
            var note = NewNote("a", "one\ntwo", when);
            var surface = NewSurface(new NoteData(), note);

            int changed = 0;
            surface.DataChanged += () => changed++;

            if (!surface.TryBeginAppendEdit())
                throw new InvalidOperationException("the append session did not open");
            surface.LeaveEdit();

            if (note.Text != "one\ntwo")
                throw new InvalidOperationException("the empty append rewrote the text as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (note.ModifiedAt != when)
                throw new InvalidOperationException("the empty append bumped the modified time (" + note.ModifiedAt + ")");
            if (changed != 0)
                throw new InvalidOperationException("the empty append notified the host " + changed + " time(s), wanted 0");
        }

        /// <summary>
        /// Task 5 (spec 4.2): the append always leaves exactly one blank line
        /// between the prefix and the new body, and keeps the source's own line
        /// ending - an LF prefix stays LF, a CRLF prefix stays CRLF and a prefix
        /// that already ends in a blank run gains nothing, and an empty prefix
        /// starts the note with the body alone.
        /// </summary>
        private static void SurfaceAppendSeparatorKeepsOneBlankLine()
        {
            ThemeManager.Initialize("dark");
            var fixtures = new (string Source, string Expected)[]
            {
                ("one", "one\n\nnew"),
                ("one\n", "one\n\nnew"),
                ("one\n\n", "one\n\nnew"),
                ("one\r\n", "one\r\n\r\nnew"),
                ("one\r\n\r\n", "one\r\n\r\nnew"),
                ("", "new")
            };

            foreach (var fixture in fixtures)
            {
                var note = NewNote("a", fixture.Source, new DateTime(2026, 3, 5, 9, 0, 0));
                var surface = NewSurface(new NoteData(), note);

                if (!surface.TryBeginAppendEdit())
                    throw new InvalidOperationException("the append session did not open on '"
                        + fixture.Source.Replace("\r", "\\r").Replace("\n", "\\n") + "'");
                SurfaceEditBox(surface).Text = "new";
                surface.Flush();

                if (note.Text != fixture.Expected)
                    throw new InvalidOperationException("appending to '"
                        + fixture.Source.Replace("\r", "\\r").Replace("\n", "\\n") + "' wrote '"
                        + (note.Text ?? string.Empty).Replace("\r", "\\r").Replace("\n", "\\n")
                        + "', wanted '" + fixture.Expected.Replace("\r", "\\r").Replace("\n", "\\n") + "'");
            }
        }

        /// <summary>
        /// Task 5 (spec 4.2): a whole-text edit is already the whole note, so
        /// the end-of-text blank is a no-op there - the box and the session stay
        /// exactly as they were.
        /// </summary>
        private static void SurfaceAppendInWholeTextEditIsANoOp()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            surface.BeginEditWhole();
            var edit = SurfaceEditBox(surface);
            string wasText = edit.Text;

            ClickAppendZone(surface);

            if (!surface.IsEditing)
                throw new InvalidOperationException("the append click dropped the whole-text edit");
            if (edit.Text != wasText)
                throw new InvalidOperationException("the append click rewrote the whole-text box as '"
                    + edit.Text.Replace("\n", "\\n") + "'");
            if (note.Text != "one\ntwo")
                throw new InvalidOperationException("the append click wrote the note as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
        }

        /// <summary>
        /// Task 5 (spec 4.2/4.4): a pane click while appending commits the new
        /// block first and then switches the edit to the clicked block.
        /// </summary>
        private static void SurfaceSwitchingFromAnAppendCommitsIt()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo\n\nthree", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginAppendEdit())
                throw new InvalidOperationException("the append session did not open");
            SurfaceEditBox(surface).Text = "new";

            ClickTaggedLine(surface, SurfaceBeforeBox(surface), 0);

            if (!surface.IsEditing)
                throw new InvalidOperationException("the pane switch dropped the edit session");
            if (note.Text != "one\ntwo\n\nthree\n\nnew")
                throw new InvalidOperationException("the append was not committed: '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            var edit = SurfaceEditBox(surface);
            if (edit.Text != "one\ntwo\n")
                throw new InvalidOperationException("the switch opened '"
                    + edit.Text.Replace("\n", "\\n") + "', wanted the clicked block 'one\\ntwo\\n'");
        }

        /// <summary>
        /// Task 5 (spec 4.1/4.4): a click in the blank run between the panes (the
        /// surface stack, not the append zone and not a tagged line) commits and
        /// leaves the edit, and the surface stays in the detail (the rendered
        /// document is back).
        /// </summary>
        private static void SurfaceBlockGapClickLeavesTheEdit()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            if (!surface.TryBeginEditAt(1))
                throw new InvalidOperationException("the paragraph block did not enter edit");

            ClickSurfaceBlank(surface);

            if (surface.IsEditing)
                throw new InvalidOperationException("the block-gap click kept the edit open");
            if (SurfaceNamed(surface, "ReadingBox").Visibility != Visibility.Visible)
                throw new InvalidOperationException("the block-gap click did not render the detail back");
        }

        /// <summary>
        /// Task 5 (spec 4.1): rendered, the same blank click is inert - the
        /// collapsed append zone never opens an edit and nothing else happens.
        /// </summary>
        private static void SurfaceAppendZoneClickAwayInRenderedStateIsANoOp()
        {
            ThemeManager.Initialize("dark");
            var note = NewNote("a", "one\ntwo", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(new NoteData(), note);

            ClickSurfaceBlank(surface);

            if (surface.IsEditing)
                throw new InvalidOperationException("the rendered blank click opened an edit");
            if (note.Text != "one\ntwo")
                throw new InvalidOperationException("the rendered blank click wrote the note as '"
                    + (note.Text ?? string.Empty).Replace("\n", "\\n") + "'");
            if (SurfaceAppendZone(surface).Visibility != Visibility.Collapsed)
                throw new InvalidOperationException("the rendered blank click showed the append zone");
        }

        /// <summary>The end-of-text blank: the transparent border below the panes.</summary>
        private static Border SurfaceAppendZone(NoteSurfaceView surface)
        {
            var named = surface.FindName("AppendZone");
            if (named == null) throw new InvalidOperationException("NoteSurfaceView has no AppendZone");
            var border = named as Border;
            if (border == null)
                throw new InvalidOperationException("AppendZone is a " + named.GetType().Name + ", not a Border");
            return border;
        }

        /// <summary>
        /// A click on the end-of-text blank. MouseLeftButtonUp is a direct event
        /// the input system re-raises per element along the real mouse route:
        /// first on the zone itself (its own handler opens the append session),
        /// then on the root with the zone as its source (the root's
        /// classification must leave the click to the zone).
        /// </summary>
        private static void ClickAppendZone(NoteSurfaceView surface)
        {
            var zone = SurfaceAppendZone(surface);
            RaiseLeftClick(zone);
            SurfaceNamed(surface, "SurfaceRoot").RaiseEvent(
                new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                    Source = zone,
                    Handled = true
                });
        }

        /// <summary>
        /// A click on the surface's blank - the stack between / below the panes,
        /// no tagged line under it. The root's own copy of the direct mouse-up,
        /// the stack as its source (the same shape the chrome pin uses).
        /// </summary>
        private static void ClickSurfaceBlank(NoteSurfaceView surface)
        {
            SurfaceNamed(surface, "SurfaceRoot").RaiseEvent(
                new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                    Source = SurfaceNamed(surface, "SurfaceStack")
                });
        }

        #endregion

        #region Task T4 helpers: surface clicks and lookups

        /// <summary>
        /// T4: the equivalent of a click on a rendered line. The pin first raises
        /// the event on the span, the way a real hit starts; the off-screen
        /// runner's content elements do not walk a direct MouseLeftButtonUp up to
        /// the surface root (WPF only re-raises it per element along the real
        /// mouse route), so it then hands the root its own copy - the span as the
        /// source and Handled already set, the same shape the focused box
        /// produces. Raising it on SurfaceRoot means every caller exercises the
        /// production ctor subscription; deleting that subscription fails the
        /// pins instead of being masked by a reflection call.
        /// </summary>
        private static void ClickTaggedLine(NoteSurfaceView surface, RichTextBox box, int line)
        {
            var span = SpanWithLine(box.Document, line);
            bool wasEditing = surface.IsEditing;
            string wasText = SurfaceEditBox(surface).Text;

            ((IInputElement)span).RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                Source = span
            });
            if (surface.IsEditing != wasEditing || SurfaceEditBox(surface).Text != wasText) return;

            SurfaceNamed(surface, "SurfaceRoot").RaiseEvent(
                new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                    Source = span,
                    Handled = true
                });
        }

        /// <summary>Lays the surface out at a real width so the boxes carry their
        /// line metrics (the off-screen runner never does a layout pass).</summary>
        private static void LayoutSurface(NoteSurfaceView surface)
        {
            surface.Measure(new Size(360, double.PositiveInfinity));
            surface.Arrange(new Rect(0, 0, 360, surface.DesiredSize.Height));
            surface.UpdateLayout();
        }

        /// <summary>The first inline span tagged with <paramref name="line"/>,
        /// recursing into nesting spans like the renderer builds them.</summary>
        private static Span SpanWithLine(FlowDocument doc, int line)
        {
            foreach (var block in doc.Blocks)
            {
                var paragraph = block as Paragraph;
                if (paragraph == null) continue;
                var span = FindSpanWithLine(paragraph.Inlines, line);
                if (span != null) return span;
            }
            throw new InvalidOperationException("the document holds no span for line " + line);
        }

        private static Span FindSpanWithLine(IEnumerable<Inline> inlines, int line)
        {
            foreach (var inline in inlines)
            {
                var span = inline as Span;
                if (span == null) continue;
                if (NoteMarkdownRenderer.GetSourceLine(span) == line) return span;
                var nested = FindSpanWithLine(span.Inlines, line);
                if (nested != null) return nested;
            }
            return null;
        }

        /// <summary>The visible text a rendered box paints (task glyphs skipped).</summary>
        private static string SurfaceDocumentText(RichTextBox box)
        {
            var text = new StringBuilder();
            foreach (var block in box.Document.Blocks)
            {
                var paragraph = block as Paragraph;
                if (paragraph != null) AppendInlineText(text, paragraph.Inlines);
            }
            return text.ToString();
        }

        private static TextBox SurfaceEditBox(NoteSurfaceView surface)
        {
            var named = surface.FindName("EditBox");
            if (named == null) throw new InvalidOperationException("NoteSurfaceView has no EditBox");
            var box = named as TextBox;
            if (box == null)
                throw new InvalidOperationException("EditBox is a " + named.GetType().Name + ", not a TextBox");
            return box;
        }

        private static RichTextBox SurfaceBox(NoteSurfaceView surface, string name)
        {
            var named = surface.FindName(name);
            if (named == null) throw new InvalidOperationException("NoteSurfaceView has no " + name);
            var box = named as RichTextBox;
            if (box == null)
                throw new InvalidOperationException(name + " is a " + named.GetType().Name + ", not a RichTextBox");
            return box;
        }

        private static RichTextBox SurfaceBeforeBox(NoteSurfaceView surface)
        {
            return SurfaceBox(surface, "BeforeBox");
        }

        private static RichTextBox SurfaceAfterBox(NoteSurfaceView surface)
        {
            return SurfaceBox(surface, "AfterBox");
        }

        private static System.Windows.Threading.DispatcherTimer SurfaceThrottle(NoteSurfaceView surface)
        {
            var field = typeof(NoteSurfaceView).GetField("_throttle",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (field == null) throw new InvalidOperationException("NoteSurfaceView has no _throttle");
            return (System.Windows.Threading.DispatcherTimer)field.GetValue(surface);
        }

        private static object InvokeNoteSurface(NoteSurfaceView surface, string name, params object[] args)
        {
            var type = typeof(NoteSurfaceView);
            foreach (var method in type.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic))
            {
                if (method.Name != name) continue;
                if (method.GetParameters().Length != (args == null ? 0 : args.Length)) continue;
                return method.Invoke(surface, args);
            }
            throw new InvalidOperationException("NoteSurfaceView has no method " + name);
        }

        private static void RaiseLeftClick(object source)
        {
            var element = source as IInputElement;
            if (element == null) throw new InvalidOperationException("the click target is not an input element");
            element.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent
            });
        }

        #endregion

        #region Task T5: note surface insert-menu pins

        /// <summary>
        /// T5 (spec 6.4): the surface's source box opens with the standard four
        /// clipboard commands - Cut / Copy / Paste / Select All - as COMMAND
        /// BINDINGS, followed by the separator that starts the insert block.
        /// The four are read, never invoked: running one would touch the system
        /// clipboard, which the checks must never do. This pin enters through
        /// the block edit (TryBeginEditAt), so the menu's carry is pinned on
        /// that entry too.
        /// </summary>
        private static void SurfaceMenuOffersTheStandardFour()
        {
            ThemeManager.Initialize("dark");
            var surface = SurfaceBlockEditorOn("x", new NoteData());

            var menu = OpenSurfaceEditorMenu(surface);
            if (menu.Items.Count < 5)
                throw new InvalidOperationException(
                    "the surface menu carries " + menu.Items.Count
                    + " entr(ies), wanted the standard four plus a separator");

            var commands = new[]
            {
                ApplicationCommands.Cut, ApplicationCommands.Copy,
                ApplicationCommands.Paste, ApplicationCommands.SelectAll
            };
            for (int i = 0; i < commands.Length; i++)
            {
                var item = menu.Items[i] as MenuItem;
                if (item == null)
                    throw new InvalidOperationException("surface menu entry " + i + " is not a MenuItem");
                if (!ReferenceEquals(item.Command, commands[i]))
                    throw new InvalidOperationException("entry " + i + " ('" + item.Header + "') is bound to "
                        + (item.Command == null ? "<no command>" : item.Command.ToString())
                        + ", wanted " + commands[i].Name);
            }

            if (!(menu.Items[4] is Separator))
                throw new InvalidOperationException("the standard four are not followed by a separator");
        }

        /// <summary>
        /// T5 (spec 6.4): the 标题 submenu carries the six levels through
        /// <c>Menu_InsertHeading</c>, and picking level 3 writes the marker on
        /// the caret's line and parks the caret after it. This pin enters
        /// through the whole-text edit (BeginEditWhole), the new-note entry.
        /// </summary>
        private static void SurfaceMenuHeadingSubmenuWritesALevel()
        {
            ThemeManager.Initialize("dark");
            var surface = SurfaceEditorOn("x", new NoteData());
            var box = SurfaceEditBox(surface);
            box.SelectionStart = 0;
            box.SelectionLength = 0;

            var heading = SurfaceEditorSubmenu(OpenSurfaceEditorMenu(surface), "Menu_Heading");
            if (heading.Items.Count != 6)
                throw new InvalidOperationException(
                    "the heading submenu carries " + heading.Items.Count + " entr(ies), wanted 1-6");

            var level3 = heading.Items[2] as MenuItem;
            if (level3 == null)
                throw new InvalidOperationException("the heading submenu's third entry is not a MenuItem");
            string wantedLabel = Localization.Format("Menu_InsertHeading", 3);
            if ((level3.Header as string) != wantedLabel)
                throw new InvalidOperationException(
                    "the level-3 entry reads '" + level3.Header + "', wanted '" + wantedLabel + "'");
            level3.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));

            if (box.Text != "### x")
                throw new InvalidOperationException(
                    "the level-3 pick wrote '" + box.Text.Replace("\n", "\\n") + "', wanted '### x'");
            if (box.SelectionStart != 4 || box.SelectionLength != 0)
                throw new InvalidOperationException("the level-3 pick left the caret at "
                    + box.SelectionStart + "/" + box.SelectionLength + ", wanted 4/0");
        }

        /// <summary>
        /// T5 (spec 6.4 / §3.3): the same list entry twice toggles the marker
        /// away again - the second pick reads the box the first one wrote.
        /// </summary>
        private static void SurfaceMenuSameListTwiceRemovesIt()
        {
            ThemeManager.Initialize("dark");
            var surface = SurfaceEditorOn("x", new NoteData());
            var box = SurfaceEditBox(surface);
            box.SelectionStart = 0;
            box.SelectionLength = 0;

            ClickSurfaceEditorEntry(surface, "Menu_InsertBullets");
            if (box.Text != "- x")
                throw new InvalidOperationException(
                    "the bullet pick wrote '" + box.Text + "', wanted '- x'");

            ClickSurfaceEditorEntry(surface, "Menu_InsertBullets");
            if (box.Text != "x")
                throw new InvalidOperationException(
                    "the second bullet pick wrote '" + box.Text + "', wanted the original 'x'");
        }

        /// <summary>
        /// T5 (spec 6.4): the table entry lays the T9 skeleton down after a
        /// non-empty line (one newline - the ops' own block convention, the
        /// same one <c>NoteEditorOps.InsertTable</c> pins) and parks the caret
        /// in the first body cell. The two column words come from the
        /// three-language <c>Note_TableColumnFormat</c> key.
        /// </summary>
        private static void SurfaceMenuTableEntryLaysOutTheSkeleton()
        {
            ThemeManager.Initialize("dark");
            AssertTableColumnFormat("zh", "列 {0}");
            AssertTableColumnFormat("en", "Column {0}");
            AssertTableColumnFormat("ja", "列 {0}");

            var surface = SurfaceEditorOn("x", new NoteData());
            var box = SurfaceEditBox(surface);
            box.SelectionStart = 1;          // the line end of the fixture
            box.SelectionLength = 0;

            ClickSurfaceEditorEntry(surface, "Menu_InsertTable");

            string col1 = Localization.Format("Note_TableColumnFormat", 1);
            string col2 = Localization.Format("Note_TableColumnFormat", 2);
            string expected = "x\n| " + col1 + " | " + col2 + " |\n| --- | --- |\n|  |  |";
            if (box.Text != expected)
                throw new InvalidOperationException("the table pick wrote '"
                    + box.Text.Replace("\n", "\\n") + "', wanted '" + expected.Replace("\n", "\\n") + "'");

            int caret = expected.IndexOf("|  |  |", StringComparison.Ordinal) + 2;
            if (box.SelectionStart != caret || box.SelectionLength != 0)
                throw new InvalidOperationException("the table pick left the caret at "
                    + box.SelectionStart + "/" + box.SelectionLength + ", wanted " + caret + "/0");
        }

        /// <summary>
        /// T5 (spec 6.4): a selection is what the wrap family wraps - bold puts
        /// the markers around the selected character and keeps it selected so
        /// the next insert still aims at it.
        /// </summary>
        private static void SurfaceMenuWrappingASelectionBoldsIt()
        {
            ThemeManager.Initialize("dark");
            var surface = SurfaceEditorOn("x", new NoteData());
            var box = SurfaceEditBox(surface);
            box.SelectionStart = 0;
            box.SelectionLength = 1;

            ClickSurfaceEditorEntry(surface, "Menu_FormatBold");

            if (box.Text != "**x**")
                throw new InvalidOperationException(
                    "the bold pick wrote '" + box.Text + "', wanted '**x**'");
            if (box.SelectionStart != 2 || box.SelectionLength != 1 || box.SelectedText != "x")
                throw new InvalidOperationException("the bold pick left the selection at "
                    + box.SelectionStart + "/" + box.SelectionLength + " ('" + box.SelectedText
                    + "'), wanted the wrapped 'x'");
        }

        /// <summary>
        /// T5 (spec 6.4): with an empty selection the wrap family inserts the
        /// three-language placeholder and selects it, so typing replaces it.
        /// </summary>
        private static void SurfaceMenuEmptySelectionInsertsThePlaceholder()
        {
            ThemeManager.Initialize("dark");
            var surface = SurfaceEditorOn("x", new NoteData());
            var box = SurfaceEditBox(surface);
            box.SelectionStart = 1;
            box.SelectionLength = 0;

            ClickSurfaceEditorEntry(surface, "Menu_FormatBold");

            string placeholder = Localization.Get("Note_PlaceholderBold");
            if (placeholder == "Note_PlaceholderBold")
                throw new InvalidOperationException("the localization table has no Note_PlaceholderBold key");
            if (box.Text != "x**" + placeholder + "**")
                throw new InvalidOperationException(
                    "the empty-selection bold wrote '" + box.Text + "', wanted 'x**" + placeholder + "**'");
            if (box.SelectedText != placeholder)
                throw new InvalidOperationException(
                    "the placeholder is not selected ('" + box.SelectedText + "')");
        }

        /// <summary>
        /// T5 (spec 6.4): every insert must be undoable with the box's OWN undo
        /// - the write-back is one replacement through the box's editing stack
        /// inside one change block, never a raw <c>Text</c> set (a bare
        /// programmatic write registers no unit at all: WPF only records one
        /// while a parent unit is open, and it flushes the stack otherwise).
        /// The fixture enters the edit on the note's own text, so the undo's own
        /// return value is the proof: rolling the insert back lands on the
        /// fixture, not on an empty box.
        /// </summary>
        private static void SurfaceMenuInsertIsUndoableWithTheBoxUndo()
        {
            ThemeManager.Initialize("dark");
            var surface = SurfaceEditorOn("x", new NoteData());
            var box = SurfaceEditBox(surface);
            box.SelectionStart = 1;
            box.SelectionLength = 0;

            ClickSurfaceEditorEntry(surface, "Menu_InsertTable");
            if (box.Text == "x")
                throw new InvalidOperationException("the table pick wrote nothing");
            if (!box.CanUndo)
                throw new InvalidOperationException("the insert never entered the box's own undo stack");

            box.Undo();
            if (box.Text != "x")
                throw new InvalidOperationException("the box's own undo left '"
                    + box.Text.Replace("\n", "\\n") + "', wanted the original 'x'");
        }

        /// <summary>
        /// Claude Warm removed the widget-colour menu wash: a menu is a neutral
        /// floating surface regardless of the host widget's colour.
        /// </summary>
        private static void SurfaceMenuStaysUntinted()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { Color = UiTokens.FolderPalette[1] };
            var surface = SurfaceEditorOn("x", data);

            var menu = OpenSurfaceEditorMenu(surface);
            if (menu.Resources.Contains(ThemeManager.BrushKeyPrefix + "OverlayBackground") ||
                menu.Resources.Contains(ThemeManager.BrushKeyPrefix + "OverlayHover"))
            {
                throw new InvalidOperationException("the surface menu still carries a widget-colour overlay tint");
            }

            var background = Application.Current.Resources[ThemeManager.BrushKeyPrefix + "OverlayBackground"] as SolidColorBrush;
            if (background == null || background.Color != ThemeManager.OverlayBackgroundBrush.Color)
                throw new InvalidOperationException("the app overlay background is not the live theme surface");
        }

        /// <summary>The surface sitting in the whole-text edit on the note's own
        /// text (BeginEditWhole, the new-note entry), already carrying its
        /// insert menu.</summary>
        private static NoteSurfaceView SurfaceEditorOn(string source, NoteData data)
        {
            var note = NewNote("a", source, new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(data, note);
            surface.BeginEditWhole();
            if (!surface.IsEditing)
                throw new InvalidOperationException("BeginEditWhole never entered the edit");
            // Templated the way the app's box stands (the off-screen runner
            // never lays the control out), so the box's own editing stack is
            // live for the undo pin.
            SurfaceEditBox(surface).ApplyTemplate();
            return surface;
        }

        /// <summary>The surface sitting in a block edit on the note's own text
        /// (TryBeginEditAt, the line-click entry), already carrying its insert
        /// menu.</summary>
        private static NoteSurfaceView SurfaceBlockEditorOn(string source, NoteData data)
        {
            var note = NewNote("a", source, new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(data, note);
            if (!surface.TryBeginEditAt(0))
                throw new InvalidOperationException("the block did not enter edit");
            return surface;
        }

        /// <summary>
        /// The surface's insert menu, opened through the box's own
        /// ContextMenuOpening route. The carry is checked first - the box must
        /// already own one the moment the edit opened, because WPF's own
        /// text-editor handler only stands aside for a box that carries a custom
        /// ContextMenu - and then the box rebuilds it per opening, so the pin
        /// drives the real path rather than a private builder. WPF gives the
        /// event args no public constructor, so the pin builds the same shape
        /// through the framework's own non-public one - its second argument is
        /// <c>opening</c>, so <c>true</c> raises the opening event.
        /// </summary>
        private static ContextMenu OpenSurfaceEditorMenu(NoteSurfaceView surface)
        {
            var box = SurfaceEditBox(surface);
            if (box.ContextMenu == null)
                throw new InvalidOperationException(
                    "the source box carries no menu from the moment the edit opened");
            var args = (ContextMenuEventArgs)Activator.CreateInstance(typeof(ContextMenuEventArgs),
                BindingFlags.Instance | BindingFlags.NonPublic, null, new object[] { box, true }, null);
            box.RaiseEvent(args);
            if (box.ContextMenu == null)
                throw new InvalidOperationException("ContextMenuOpening left the source box without a menu");
            return box.ContextMenu;
        }

        /// <summary>One submenu of the surface menu by its header key (the 标题 /
        /// 格式 parents are reached through their localized headers).</summary>
        private static MenuItem SurfaceEditorSubmenu(ContextMenu menu, string headerKey)
        {
            string wanted = Localization.Get(headerKey);
            foreach (object entry in menu.Items)
            {
                var item = entry as MenuItem;
                if (item != null && (item.Header as string) == wanted) return item;
            }
            throw new InvalidOperationException(
                "the surface menu has no '" + wanted + "' (" + headerKey + ") submenu");
        }

        /// <summary>Picks one insert / format entry by its localization key -
        /// the flat block first, then the two submenus (so a pin names an entry
        /// the way the design does, not by its position).</summary>
        private static void ClickSurfaceEditorEntry(NoteSurfaceView surface, string labelKey)
        {
            var menu = OpenSurfaceEditorMenu(surface);
            string wanted = Localization.Get(labelKey);
            foreach (object entry in menu.Items)
            {
                var item = entry as MenuItem;
                if (item == null) continue;
                if ((item.Header as string) == wanted)
                {
                    item.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));
                    return;
                }
                foreach (object nested in item.Items)
                {
                    var sub = nested as MenuItem;
                    if (sub != null && (sub.Header as string) == wanted)
                    {
                        sub.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));
                        return;
                    }
                }
            }
            throw new InvalidOperationException("the surface menu has no entry labelled '" + wanted + "' (" + labelKey + ")");
        }

        #endregion

        #region Task 6: note font scale pins

        /// <summary>
        /// Task 6 (spec 6.2): the widget's font step scales the whole rendered
        /// document off one base - the FlowDocument's own body size and the
        /// heading ladder derived from it - and the inline edit box opens on
        /// that same base, so entering an edit never jumps the type.
        /// </summary>
        private static void SurfaceFontScaleScalesTheDocumentAndTheEditBox()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { FontScale = NoteFontScale.Large };
            var note = NewNote("a", "# H\n\nbody", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(data, note);
            double baseSize = UiTokens.FontBody * NoteFontScale.Large;

            var reading = SurfaceReadingBox(surface);
            if (reading.Document == null)
                throw new InvalidOperationException("the rendered document is null");
            if (Math.Abs(reading.Document.FontSize - baseSize) > 0.01)
                throw new InvalidOperationException("the rendered document is "
                    + reading.Document.FontSize + "pt, wanted " + baseSize);

            double heading = ParagraphAt(reading.Document, 0).FontSize;
            double wantedHeading = NoteMarkdownRenderer.HeadingFontSize(1, baseSize);
            if (Math.Abs(heading - wantedHeading) > 0.01)
                throw new InvalidOperationException("the heading is " + heading
                    + "pt, wanted " + wantedHeading);

            if (!surface.TryBeginEditAt(2))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            var edit = SurfaceEditBox(surface);
            if (Math.Abs(edit.FontSize - baseSize) > 0.01)
                throw new InvalidOperationException("the edit box is " + edit.FontSize
                    + "pt, wanted " + baseSize);
        }

        /// <summary>
        /// Task 6 (spec 6.2): changing the step while a block is being edited
        /// only repaints - Repaint re-applies the panes and the box's type but
        /// never rewrites the typed text, drops the session or moves the caret.
        /// </summary>
        private static void SurfaceScaleChangeDuringEditKeepsTextAndCaret()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { FontScale = NoteFontScale.Large };
            var note = NewNote("a", "# H\n\nbody", new DateTime(2026, 3, 5, 9, 0, 0));
            var surface = NewSurface(data, note);

            if (!surface.TryBeginEditAt(2))
                throw new InvalidOperationException("the paragraph block did not enter edit");
            var edit = SurfaceEditBox(surface);
            edit.Text = "typed";
            edit.CaretIndex = 2;

            data.FontScale = NoteFontScale.Small;
            surface.Repaint();

            if (!surface.IsEditing)
                throw new InvalidOperationException("the scale change closed the edit session");
            if (edit.Text != "typed")
                throw new InvalidOperationException("the scale change rewrote the box text to '"
                    + edit.Text.Replace("\n", "\\n") + "'");
            if (edit.CaretIndex != 2)
                throw new InvalidOperationException("the scale change moved the caret to "
                    + edit.CaretIndex);
            double wanted = UiTokens.FontBody * NoteFontScale.Small;
            if (Math.Abs(edit.FontSize - wanted) > 0.01)
                throw new InvalidOperationException("the edit box is " + edit.FontSize
                    + "pt, wanted " + wanted);
        }

        /// <summary>
        /// Task 6 (spec 6.2): the home card keeps its own type - the title stays
        /// 14 semibold, the time and the two-line excerpt keep 11 / 12 - no
        /// matter which step the widget renders its document with.
        /// </summary>
        private static void NoteCardIgnoresTheFontScale()
        {
            ThemeManager.Initialize("dark");
            var data = new NoteData { FontScale = NoteFontScale.Large };
            data.Notes.Add(NewNote("a", "# Title\n\nbody", new DateTime(2026, 3, 5, 9, 0, 0)));

            var view = new NoteWidget(data).PanelView;
            view.Refresh();

            var stack = NoteCardAt(view, 0).Child as StackPanel;
            if (stack == null) throw new InvalidOperationException("note card 0 has no content stack");
            double[] wanted = { 14, 11, 12 };
            if (stack.Children.Count < wanted.Length)
                throw new InvalidOperationException("the card has " + stack.Children.Count + " line(s)");
            for (int i = 0; i < wanted.Length; i++)
            {
                var text = stack.Children[i] as TextBlock;
                if (text == null)
                    throw new InvalidOperationException("card line " + i + " is not a TextBlock");
                if (Math.Abs(text.FontSize - wanted[i]) > 0.01)
                    throw new InvalidOperationException("card line " + i + " is "
                        + text.FontSize + "pt, wanted " + wanted[i]);
            }
        }

        /// <summary>
        /// Task 6 (spec 6.3): the note menu's 字号 submenu lists the three
        /// localized steps in order, checks the current one (medium by default)
        /// and sits before the delete separator. A pick writes the data, trails
        /// exactly one change notification through the widget, re-renders the
        /// detail at the new size and is checked when the menu is rebuilt.
        /// </summary>
        private static void NoteFontMenuChecksAndWrites()
        {
            ThemeManager.Initialize("dark");
            Localization.SetLanguage("en");
            try
            {
                var data = new NoteData { Name = "Notebook" };
                data.Notes.Add(NewNote("a", "# H\n\nbody", new DateTime(2026, 3, 5, 9, 0, 0)));
                var widget = new NoteWidget(data);
                var view = widget.PanelView;
                view.Refresh();
                ClickNoteCard(view, 0);

                var menu = WidgetMenuBuilder.Build(widget, null);
                var submenu = FindMenuByHeader(menu, Localization.Get("Menu_NoteFontSize"));
                if (submenu == null)
                    throw new InvalidOperationException("the 字号 submenu is missing from the note menu");

                string[] keys = { "Note_FontSmall", "Note_FontMedium", "Note_FontLarge" };
                if (submenu.Items.Count != keys.Length)
                    throw new InvalidOperationException("the 字号 submenu has "
                        + submenu.Items.Count + " item(s), wanted " + keys.Length);
                for (int i = 0; i < keys.Length; i++)
                {
                    var item = submenu.Items[i] as MenuItem;
                    if (item == null || (item.Header as string) != Localization.Get(keys[i]))
                        throw new InvalidOperationException("font entry " + i + " is '"
                            + (item == null ? "<not a MenuItem>" : item.Header as string)
                            + "', wanted '" + Localization.Get(keys[i]) + "'");
                    bool wanted = i == 1; // the default step is medium
                    if (item.IsChecked != wanted)
                        throw new InvalidOperationException("font entry " + i + " check state is "
                            + item.IsChecked + ", wanted " + wanted);
                }

                int fontIndex = menu.Items.IndexOf(submenu);
                int separator = -1;
                for (int i = 0; i < menu.Items.Count; i++)
                {
                    if (menu.Items[i] is Separator) { separator = i; break; }
                }
                if (separator < 0 || fontIndex > separator)
                    throw new InvalidOperationException("the 字号 submenu sits at "
                        + fontIndex + ", after the delete separator at " + separator);

                int changed = 0;
                widget.OnDataChanged += () => changed++;
                ((MenuItem)submenu.Items[2]).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));

                if (Math.Abs(data.FontScale - NoteFontScale.Large) > 0.001)
                    throw new InvalidOperationException("the large pick left FontScale at "
                        + data.FontScale);
                if (changed != 1)
                    throw new InvalidOperationException("the pick notified the host "
                        + changed + " time(s), wanted 1");

                double wantedSize = UiTokens.FontBody * NoteFontScale.Large;
                var document = SurfaceReadingBox(NoteSurface(view)).Document;
                if (document == null || Math.Abs(document.FontSize - wantedSize) > 0.01)
                    throw new InvalidOperationException("the re-rendered document is "
                        + (document == null ? "<null>" : document.FontSize.ToString())
                        + "pt, wanted " + wantedSize);

                var reopened = WidgetMenuBuilder.Build(widget, null);
                var reopenedMenu = FindMenuByHeader(reopened, Localization.Get("Menu_NoteFontSize"));
                if (reopenedMenu == null)
                    throw new InvalidOperationException("the rebuilt note menu lost the 字号 submenu");
                if (!((MenuItem)reopenedMenu.Items[2]).IsChecked ||
                    ((MenuItem)reopenedMenu.Items[1]).IsChecked)
                    throw new InvalidOperationException(
                        "reopening the menu does not reflect the stored large step");
            }
            finally
            {
                Localization.SetLanguage("en");
            }
        }

        /// <summary>
        /// Task 6 (spec 6.3): the folder menu keeps its own appendix only - no
        /// note 字号 submenu leaks into another kind's menu.
        /// </summary>
        private static void FolderMenuHasNoNoteFontSubmenu()
        {
            ThemeManager.Initialize("dark");
            Localization.SetLanguage("en");

            var widget = new FolderWidget(new FolderData());
            var menu = WidgetMenuBuilder.Build(widget, null);
            if (FindMenuByHeader(menu, Localization.Get("Menu_NoteFontSize")) != null)
                throw new InvalidOperationException("the folder menu carries the note 字号 submenu");
        }

        #endregion

        #region View host (Task T2)

        /// <summary>
        /// A host the pins control by hand: it records the title pushes and the
        /// data-change notifications and hands the view an explicit content
        /// height, so the layout no longer has to come from a real window.
        /// </summary>
        private sealed class FakeViewHost : IWidgetViewHost
        {
            public FakeViewHost(WidgetData data)
            {
                Data = data;
                PanelSize = (340, 400);
            }

            public WidgetData Data { get; set; }

            public WidgetChrome Chrome { get; set; }

            public bool IsPanelOpen { get; set; }

            public double ContentWidth { get; set; }

            public double ContentHeight { get; set; }

            public (double width, double height) PanelSize { get; set; }

            public int NotifyCount { get; private set; }

            public List<string> Titles { get; } = new List<string>();

            public int PersistSelectionCount { get; private set; }

            public int MenuCount { get; private set; }

            public (double width, double height) GetPanelSize()
            {
                return PanelSize;
            }

            public void NotifyDataChanged()
            {
                NotifyCount++;
            }

            public void RefreshChromeTitle(string title = null)
            {
                Titles.Add(title);
            }

            public void PersistSelection()
            {
                PersistSelectionCount++;
            }

            public void ShowWidgetMenu()
            {
                MenuCount++;
            }
        }

        /// <summary>
        /// T2: the todo layout follows whatever content height the host
        /// publishes - no window is involved. The 300-high host renders one
        /// pinned row and does not throw; the 500-high host must grow the list
        /// viewport. The view lives in an invisible offscreen HwndSource so the
        /// layout is real.
        /// </summary>
        private static void TodoViewFollowsHostContentHeight()
        {
            ThemeManager.Initialize("dark");

            DateTime today = DateTime.Today;
            var data = new TodoData { SelectedDate = today };
            for (int i = 1; i <= 12; i++) TodoListOps.AddItem(data, "Item " + i, today);

            var host = new FakeViewHost(data)
            {
                ContentWidth = 340,
                ContentHeight = 300
            };
            var view = new TodoCalendarView();
            var face = (IWidgetContentView)view;
            face.Attach(data, host);

            var source = new System.Windows.Interop.HwndSource(
                new System.Windows.Interop.HwndSourceParameters("xamlloadcheck-t2-todo")
                {
                    WindowStyle = 0,
                    Width = 400,
                    Height = 700,
                    PositionX = -10000,
                    PositionY = -10000
                });
            source.RootVisual = view;
            try
            {
                var scroller = view.FindName("ItemsScroller") as ScrollViewer;
                if (scroller == null) throw new InvalidOperationException("ItemsScroller not found");

                view.Refresh();
                view.UpdateLayout();
                double small = scroller.ActualHeight;
                if (double.IsNaN(small) || small <= 0)
                {
                    throw new InvalidOperationException(
                        "a 300-high host laid out a " + small + " list viewport");
                }

                host.ContentHeight = 500;
                view.Refresh();
                view.UpdateLayout();
                double large = scroller.ActualHeight;
                if (large <= small)
                {
                    throw new InvalidOperationException(
                        "the list viewport did not follow the host: " + small + " -> " + large);
                }
            }
            finally
            {
                source.RootVisual = null;
                source.Dispose();
            }
        }

        /// <summary>
        /// T2: the note view works off the interface alone - the exposed title
        /// matches the concrete property, a title refresh reaches the host, a
        /// flush is safe on a home view, and the interface undo restores a
        /// deleted note.
        /// </summary>
        private static void NoteViewRunsThroughTheInterface()
        {
            ThemeManager.Initialize("dark");

            var first = NewNote("a", "First", new DateTime(2026, 3, 5, 9, 0, 0));
            var data = new NoteData();
            data.Notes.Add(first);

            var host = new FakeViewHost(data);
            var view = new NotePanelView();
            var face = (IWidgetContentView)view;
            face.Attach(data, host);

            if (face.ChromeTitle != view.ChromeTitle)
            {
                throw new InvalidOperationException(
                    "the interface title '" + face.ChromeTitle + "' differs from the view title '" +
                    view.ChromeTitle + "'");
            }
            if (!face.HasTitleMenu)
            {
                throw new InvalidOperationException("the note view reports no title menu");
            }

            int titlesBefore = host.Titles.Count;
            face.RefreshChromeTitle();
            if (host.Titles.Count != titlesBefore + 1 || host.Titles[host.Titles.Count - 1] != view.ChromeTitle)
            {
                throw new InvalidOperationException(
                    "the host received " + host.Titles.Count + " title(s), wanted the view's current title");
            }

            face.FlushPendingEdit(); // home view: safe no-op
            if (!view.IsHome)
            {
                throw new InvalidOperationException("the home flush navigated the view");
            }

            InvokeNoteDelete(view, first);
            if (data.Notes.Count != 0)
            {
                throw new InvalidOperationException("the fixture delete did not stick");
            }
            if (!face.TryUndo())
            {
                throw new InvalidOperationException("the interface undo reported nothing to restore");
            }
            if (data.Notes.Count != 1 || data.Notes[0] != first)
            {
                throw new InvalidOperationException("the interface undo did not restore the note");
            }
        }

        /// <summary>
        /// T2: the search view resolves its chrome through the host - the query
        /// glow lights the host's chrome and the deactivate path stops it. No
        /// service or scan is touched.
        /// </summary>
        private static void SearchViewUsesTheHostChrome()
        {
            ThemeManager.Initialize("dark");

            var data = new SearchData { Name = "Search check" };
            var chrome = new WidgetChrome();
            ArrangeChrome(chrome, 422, 562);

            var host = new FakeViewHost(data)
            {
                Chrome = chrome,
                IsPanelOpen = true,
                ContentWidth = 420,
                ContentHeight = 500,
                PanelSize = (422, 562)
            };
            var view = new SearchPanelView();
            var face = (IWidgetContentView)view;
            face.Attach(data, host);

            if (face.ChromeTitle != data.Name)
            {
                throw new InvalidOperationException(
                    "the search view title is '" + face.ChromeTitle + "'");
            }
            if (face.HasTitleMenu)
            {
                throw new InvalidOperationException("the search view reports a title menu");
            }

            view.RefreshAccent(); // the accent path must run off the interface host

            var setGlow = typeof(SearchPanelView).GetMethod("SetQueryGlow",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (setGlow == null) throw new InvalidOperationException("SearchPanelView.SetQueryGlow was not found");

            setGlow.Invoke(view, new object[] { true });
            if (!chrome.IsGlowActive)
            {
                throw new InvalidOperationException("the query did not light the host's chrome");
            }

            face.Deactivate();
            if (chrome.IsGlowActive)
            {
                throw new InvalidOperationException("deactivate left the host's chrome glowing");
            }

            face.FlushPendingEdit();
            face.HandleMouseDownOutsideEditor(chrome);
            if (face.TryUndo())
            {
                throw new InvalidOperationException("the search view reports an undo");
            }
        }

        /// <summary>
        /// T2: the kind-to-view registry - the three migrated kinds build their
        /// real view, while folder (T3a) and an unknown datum have none.
        /// </summary>
        private static void WidgetViewFactoryMapsKindData()
        {
            ThemeManager.Initialize("dark");

            if (!(WidgetViewFactory.Create(new TodoData()) is TodoCalendarView))
            {
                throw new InvalidOperationException("todo data did not map to TodoCalendarView");
            }
            if (!(WidgetViewFactory.Create(new NoteData()) is NotePanelView))
            {
                throw new InvalidOperationException("note data did not map to NotePanelView");
            }
            if (!(WidgetViewFactory.Create(new SearchData()) is SearchPanelView))
            {
                throw new InvalidOperationException("search data did not map to SearchPanelView");
            }
            if (!(WidgetViewFactory.Create(new FolderData()) is FolderPanelView))
            {
                throw new InvalidOperationException("folder data did not map to FolderPanelView");
            }
            if (WidgetViewFactory.Create(new UnknownData()) != null)
            {
                throw new InvalidOperationException("unknown data mapped to a view");
            }
            if (WidgetViewFactory.Create(null) != null)
            {
                throw new InvalidOperationException("null data mapped to a view");
            }
        }

        #endregion

        #region View rebind lifecycle (Task P0-A1)

        /// <summary>
        /// P0-A1: a bound note view changes hosts without re-attaching. The
        /// rebind itself pushes no title (no AttachCore), the next explicit
        /// title refresh reaches the new host only, and a second rebind is
        /// still a single push - no duplicate subscriptions.
        /// </summary>
        private static void NoteViewRebindsToTheNewHost()
        {
            ThemeManager.Initialize("dark");

            var data = new NoteData { Name = "Rebind note" };
            var hostA = new FakeViewHost(data);
            var hostB = new FakeViewHost(data);
            var view = new NotePanelView();
            var face = (IWidgetContentView)view;

            face.Attach(data, hostA);
            if (hostA.Titles.Count != 1)
            {
                throw new InvalidOperationException(
                    "attach pushed " + hostA.Titles.Count + " title(s), wanted 1");
            }

            face.RebindHost(hostB);
            if (hostB.Titles.Count != 0)
            {
                throw new InvalidOperationException(
                    "rebind re-attached the view: " + hostB.Titles.Count + " title push(es)");
            }

            face.RebindHost(hostB); // a second rebind must not duplicate anything
            face.RefreshChromeTitle();
            if (hostB.Titles.Count != 1 || hostB.Titles[0] != view.ChromeTitle)
            {
                throw new InvalidOperationException(
                    "the new host received " + hostB.Titles.Count +
                    " title(s), wanted one current title");
            }
            if (hostA.Titles.Count != 1)
            {
                throw new InvalidOperationException(
                    "the old host kept receiving title pushes (" + hostA.Titles.Count + ")");
            }
        }

        /// <summary>
        /// P0-A1: the search view's chrome lookups follow RebindHost - its
        /// Deactivate stops the new host's glow and leaves the old host's
        /// glow untouched.
        /// </summary>
        private static void SearchViewRebindMovesTheChromeOwnership()
        {
            ThemeManager.Initialize("dark");

            var data = new SearchData { Name = "Rebind search" };
            var chromeA = new WidgetChrome();
            ArrangeChrome(chromeA, 422, 562);
            var hostA = new FakeViewHost(data)
            {
                Chrome = chromeA,
                IsPanelOpen = true,
                ContentWidth = 420,
                ContentHeight = 500,
                PanelSize = (422, 562)
            };

            var chromeB = new WidgetChrome();
            ArrangeChrome(chromeB, 422, 562);
            var hostB = new FakeViewHost(data)
            {
                Chrome = chromeB,
                IsPanelOpen = true,
                ContentWidth = 420,
                ContentHeight = 500,
                PanelSize = (422, 562)
            };

            var view = new SearchPanelView();
            var face = (IWidgetContentView)view;
            face.Attach(data, hostA);

            var setGlow = typeof(SearchPanelView).GetMethod("SetQueryGlow",
                BindingFlags.Instance | BindingFlags.NonPublic);
            if (setGlow == null)
            {
                throw new InvalidOperationException("SearchPanelView.SetQueryGlow was not found");
            }

            setGlow.Invoke(view, new object[] { true });
            if (!chromeA.IsGlowActive)
            {
                throw new InvalidOperationException("the query did not light the original host's chrome");
            }

            face.RebindHost(hostB);
            setGlow.Invoke(view, new object[] { true });
            if (!chromeB.IsGlowActive)
            {
                throw new InvalidOperationException("the rebound host's chrome did not light");
            }
            if (!chromeA.IsGlowActive)
            {
                throw new InvalidOperationException("the old host's glow stopped before deactivate");
            }

            face.Deactivate();
            if (chromeB.IsGlowActive)
            {
                throw new InvalidOperationException("deactivate left the new host's chrome glowing");
            }
            if (!chromeA.IsGlowActive)
            {
                throw new InvalidOperationException("deactivate stopped the old host's chrome");
            }
        }

        /// <summary>
        /// P0-A1: a todo window releases its live calendar into a null content
        /// slot and a new window adopts the same instance without a re-attach.
        /// </summary>
        private static void TodoViewReleasesAndAdoptsIntoANewWindow()
        {
            ThemeManager.Initialize("dark");

            var data = new TodoData { Name = "Adopt todo", SelectedDate = DateTime.Today };
            TodoListOps.AddItem(data, "Keep me", DateTime.Today);

            var original = new TodoWidget(data);
            var view = original.CalendarView;
            if (view == null)
            {
                throw new InvalidOperationException("TodoWidget exposes no calendar view");
            }
            if (!ReferenceEquals(original.PanelChrome.ContentHost.Content, view))
            {
                throw new InvalidOperationException("the original window does not host its calendar view");
            }

            var released = original.ReleaseContentView();
            if (!ReferenceEquals(released, view))
            {
                throw new InvalidOperationException("ReleaseContentView returned a different view");
            }
            if (original.PanelChrome.ContentHost.Content != null)
            {
                throw new InvalidOperationException("the released content slot is not empty");
            }
            if (!original.HasReleasedContentView)
            {
                throw new InvalidOperationException("the window does not report its released content");
            }

            var adopted = new TodoWidget(data, released);
            if (!ReferenceEquals(adopted.CalendarView, view))
            {
                throw new InvalidOperationException("the adopted window built a different calendar view");
            }
            if (!ReferenceEquals(adopted.PanelChrome.ContentHost.Content, view))
            {
                throw new InvalidOperationException("the adopted window does not host the live view");
            }
        }

        /// <summary>
        /// P0-A1: the note hand-off keeps the live detail state - the adopted
        /// window mounts the same view, not a rebuilt home.
        /// </summary>
        private static void NoteViewReleasesAndAdoptsIntoANewWindow()
        {
            ThemeManager.Initialize("dark");

            var data = new NoteData { Name = "Adopt note" };
            data.Notes.Add(NewNote("adopt-1", "First", new DateTime(2026, 3, 5, 9, 0, 0)));

            var original = new NoteWidget(data);
            var view = original.PanelView;
            view.OpenNote("adopt-1");
            if (view.IsHome)
            {
                throw new InvalidOperationException("the note detail did not open");
            }

            var released = original.ReleaseContentView();
            if (!ReferenceEquals(released, view))
            {
                throw new InvalidOperationException("ReleaseContentView returned a different view");
            }
            if (original.PanelChrome.ContentHost.Content != null)
            {
                throw new InvalidOperationException("the released content slot is not empty");
            }

            var adopted = new NoteWidget(data, released);
            if (!ReferenceEquals(adopted.PanelView, view))
            {
                throw new InvalidOperationException("the adopted window built a different note view");
            }
            if (!ReferenceEquals(adopted.PanelChrome.ContentHost.Content, view))
            {
                throw new InvalidOperationException("the adopted window does not host the live view");
            }
            if (view.IsHome)
            {
                throw new InvalidOperationException("the adopted view lost its open note");
            }
        }

        /// <summary>
        /// P0-A1 review: releasing a view then hiding the old standalone
        /// window must not deactivate the view now owned by the new host. The
        /// note's open title menu and the search chrome's glow are the cheap
        /// observables of Deactivate(): both survive the old window's
        /// OnPanelHidden path only when that hook honours HasReleasedContentView.
        /// </summary>
        private static void ReleasedViewSurvivesTheOldWindowsHide()
        {
            ThemeManager.Initialize("dark");

            // Note: Deactivate() closes the title menu.
            var noteData = new NoteData { Name = "Hide note" };
            noteData.Notes.Add(NewNote("hide-note", "First", new DateTime(2026, 3, 5, 9, 0, 0)));
            var oldNote = new NoteWidget(noteData);
            var noteView = oldNote.PanelView;
            noteView.OpenNote("hide-note");

            var releasedNote = oldNote.ReleaseContentView();
            var newNote = new NoteWidget(noteData, releasedNote);
            try
            {
                if (!ReferenceEquals(newNote.PanelView, noteView))
                {
                    throw new InvalidOperationException("the note window did not adopt the live view");
                }
                if (noteView.IsHome)
                {
                    throw new InvalidOperationException("the adoption lost the open note detail");
                }

                // An open menu in the new host is the observable Deactivate()
                // would close; it is opened after the hand-off because the
                // release itself correctly deactivates the view.
                noteView.ToggleTitleMenu(NoteNamed(noteView, "Root"));
                if (!noteView.IsTitleMenuOpen)
                {
                    throw new InvalidOperationException("the note title menu did not open");
                }

                // The old window's real collapse path: OnPanelHidden runs at
                // the top of HidePanel, before its fade.
                SetPrivateBaseField(oldNote, "_isExpanded", true);
                oldNote.HidePanel();
                if (!noteView.IsTitleMenuOpen)
                {
                    throw new InvalidOperationException(
                        "the old note window's hide deactivated the adopted view");
                }
            }
            finally
            {
                newNote.Close();
            }

            // Search: Deactivate() stops the chrome glow of the live host.
            var searchData = new SearchData { Name = "Hide search" };
            var oldSearch = new SearchWidget(searchData);
            var searchView = oldSearch.PanelView;
            var releasedSearch = oldSearch.ReleaseContentView();
            var newSearch = new SearchWidget(searchData, releasedSearch);
            try
            {
                if (!ReferenceEquals(newSearch.PanelView, searchView))
                {
                    throw new InvalidOperationException("the search window did not adopt the live view");
                }

                // The adopted search view paints on the new window's chrome;
                // an open panel lets the glow state run.
                SetPrivateBaseField(newSearch, "_isExpanded", true);
                var setGlow = typeof(SearchPanelView).GetMethod("SetQueryGlow",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                if (setGlow == null)
                {
                    throw new InvalidOperationException("SearchPanelView.SetQueryGlow was not found");
                }
                setGlow.Invoke(searchView, new object[] { true });
                if (!newSearch.PanelChrome.IsGlowActive)
                {
                    throw new InvalidOperationException("the adopted search view did not light the new chrome");
                }

                SetPrivateBaseField(oldSearch, "_isExpanded", true);
                oldSearch.HidePanel();
                if (!newSearch.PanelChrome.IsGlowActive)
                {
                    throw new InvalidOperationException(
                        "the old search window's hide stopped the adopted view's glow");
                }
            }
            finally
            {
                newSearch.Close();
            }
        }

        /// <summary>
        /// P0-A1: the kind factory adopts a released view through the widget
        /// constructor overload and returns the same instance.
        /// </summary>
        private static void WidgetFactoryAdoptsALiveView()
        {
            ThemeManager.Initialize("dark");

            var data = new TodoData { Name = "Factory adopt", SelectedDate = DateTime.Today };
            var original = new TodoWidget(data);
            var view = original.CalendarView;
            var released = original.ReleaseContentView();

            var created = WidgetWindowFactory.Create(data, released) as TodoWidget;
            if (created == null)
            {
                throw new InvalidOperationException("the factory did not build a todo window");
            }
            if (!ReferenceEquals(created.CalendarView, view))
            {
                throw new InvalidOperationException("the factory built a different calendar view");
            }
            if (!ReferenceEquals(created.PanelChrome.ContentHost.Content, view))
            {
                throw new InvalidOperationException("the factory window does not host the live view");
            }
        }

        #endregion

        #region Task T4 group window pins

        /// <summary>
        /// A two-member group (todo + note) at the default 760x540. The member
        /// colours are explicit so the tab underline pin can name its hex.
        /// </summary>
        private static WidgetGroupWindow NewGroupWindow(out WidgetGroup group, out TodoData todo, out NoteData note)
        {
            ThemeManager.Initialize("dark");

            todo = new TodoData
            {
                Id = "todo-1",
                Name = "Todo",
                Color = "#6A9BCC",
                SelectedDate = DateTime.Today
            };
            for (int i = 0; i < 10; i++)
            {
                TodoListOps.AddItem(todo, "Item " + (i + 1), DateTime.Today);
            }

            note = new NoteData { Id = "note-1", Name = "Note", Color = "#788C5D" };

            group = new WidgetGroup
            {
                Id = "g1",
                ActiveWidgetId = "todo-1",
                PanelWidth = 760,
                PanelHeight = 540
            };

            return new WidgetGroupWindow(group, new List<WidgetData> { todo, note });
        }

        /// <summary>Shows the group offscreen so its real chrome and slots arrange.</summary>
        private static void ShowGroupWindow(WidgetGroupWindow window)
        {
            window.WindowStartupLocation = WindowStartupLocation.Manual;
            window.Left = -32000;
            window.Top = -32000;
            window.ShowActivated = false;
            window.Show();
            window.UpdateLayout();
        }

        private static bool IsTransparent(Brush brush)
        {
            if (brush == null) return true;
            var solid = brush as SolidColorBrush;
            return solid != null && solid.Color.A == 0;
        }

        /// <summary>
        /// The shell is the shared 40px chrome; above it a 32px bare tab row
        /// (no pill, no Path marker, no 3px colour strip) carries one tab per
        /// member with exactly one 2px member-coloured, tab-wide, bottom
        /// underline. The group id is the window id while Data is the active
        /// member.
        /// </summary>
        private static void GroupWindowHostsBareTabs()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);

                if (window.WidgetId != "g1")
                {
                    throw new InvalidOperationException("the group window id is " + window.WidgetId);
                }
                var active = window.Data as TodoData;
                if (active == null || active.Id != "todo-1")
                {
                    throw new InvalidOperationException("Data is not the active todo member");
                }

                var strip = window.TabStrip;
                if (strip == null) throw new InvalidOperationException("the tab strip is missing");
                if (Math.Abs(strip.Height - 32) > 0.01)
                {
                    throw new InvalidOperationException("the tab row is " + strip.Height + " high, wanted 32");
                }
                if (Math.Abs(window.GroupChrome.Header.ActualHeight - 40) > 0.01)
                {
                    throw new InvalidOperationException(
                        "the chrome header is " + window.GroupChrome.Header.ActualHeight + " high, wanted 40");
                }
                if (strip.TabButtons.Count != 2)
                {
                    throw new InvalidOperationException(
                        "the strip has " + strip.TabButtons.Count + " tabs, wanted 2");
                }

                int visible = 0;
                int visibleIndex = -1;
                for (int i = 0; i < strip.Underlines.Count; i++)
                {
                    if (strip.Underlines[i].Visibility != Visibility.Visible) continue;
                    visible++;
                    visibleIndex = i;
                }
                if (visible != 1)
                {
                    throw new InvalidOperationException(visible + " underlines are visible, wanted exactly 1");
                }

                Border underline = strip.Underlines[visibleIndex];
                if (Math.Abs(underline.Height - 2) > 0.01)
                {
                    throw new InvalidOperationException("the underline is " + underline.Height + " high, wanted 2");
                }
                if (Math.Abs(underline.CornerRadius.TopLeft - 1) > 0.01)
                {
                    throw new InvalidOperationException("the underline radius is " + underline.CornerRadius.TopLeft);
                }
                if (underline.VerticalAlignment != VerticalAlignment.Bottom)
                {
                    throw new InvalidOperationException("the underline is not bottom-aligned");
                }

                var brush = underline.Background as SolidColorBrush;
                Color wanted = Utils.HexToColor("#6A9BCC");
                if (brush == null || brush.Color != wanted)
                {
                    throw new InvalidOperationException(
                        "the active underline is " + (brush == null ? "<null>" : Describe(brush.Color)) +
                        ", wanted " + Describe(wanted));
                }

                double tabWidth = strip.TabButtons[visibleIndex].ActualWidth;
                if (Math.Abs(underline.ActualWidth - tabWidth) > 0.5)
                {
                    throw new InvalidOperationException(
                        "the underline is " + underline.ActualWidth + " wide, the tab is " + tabWidth);
                }

                for (int i = 0; i < strip.TabButtons.Count; i++)
                {
                    Grid tab = strip.TabButtons[i];
                    if (!IsTransparent(tab.Background))
                    {
                        throw new InvalidOperationException("tab " + i + " is not transparent");
                    }
                    foreach (var child in tab.Children)
                    {
                        if (child is Path)
                        {
                            throw new InvalidOperationException("tab " + i + " carries a Path marker");
                        }
                        var border = child as Border;
                        if (border != null && !ReferenceEquals(border, strip.Underlines[i]) &&
                            border.Height > 0 && border.Height <= 3)
                        {
                            throw new InvalidOperationException(
                                "tab " + i + " carries a " + border.Height + "px colour strip");
                        }
                    }
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// Switching a tab only toggles Visibility: the real view instances stay
        /// put, the active member feeds Data, the title follows its context and
        /// the window never resizes.
        /// </summary>
        private static void GroupTabSwitchKeepsTheViewAndWindowSize()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);

                var slots = window.ContentSlots;
                if (slots.Count != 2)
                {
                    throw new InvalidOperationException("the group has " + slots.Count + " content slots");
                }
                object todoView = slots[0].Content;
                object noteView = slots[1].Content;
                if (!(todoView is TodoCalendarView) || !(noteView is NotePanelView))
                {
                    throw new InvalidOperationException("the slots do not host the real views");
                }
                if (slots[0].Visibility != Visibility.Visible || slots[1].Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException("the initial slots are not todo-visible / note-collapsed");
                }

                double width = window.Width;
                double height = window.Height;

                window.SetActive(1);
                window.UpdateLayout();

                if (slots[1].Visibility != Visibility.Visible || slots[0].Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException("the note tab did not reveal its slot");
                }
                var activeNote = window.Data as NoteData;
                if (activeNote == null || activeNote.Id != "note-1")
                {
                    throw new InvalidOperationException("Data did not switch to the note member");
                }
                if (window.GroupChrome.Title != ((NotePanelView)noteView).ChromeTitle)
                {
                    throw new InvalidOperationException(
                        "the title is '" + window.GroupChrome.Title + "', wanted the note ChromeTitle");
                }
                if (!ReferenceEquals(slots[0].Content, todoView) || !ReferenceEquals(slots[1].Content, noteView))
                {
                    throw new InvalidOperationException("a tab switch recreated a view");
                }
                if (window.Width != width || window.Height != height)
                {
                    throw new InvalidOperationException(
                        "a tab switch resized the window to " + window.Width + "x" + window.Height);
                }

                window.SetActive(0);
                window.UpdateLayout();

                if (slots[0].Visibility != Visibility.Visible || slots[1].Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException("switching back did not restore the todo slot");
                }
                if (!(window.Data is TodoData) || !ReferenceEquals(slots[0].Content, todoView))
                {
                    throw new InvalidOperationException("the todo tab did not come back intact");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// R6: several rapid switches on a live group leave the last requested
        /// tab active, the final slot visible and the window usable. A token
        /// captured before the last switch is stale, a same-index SetActive
        /// issues no new activation request, and closing stales the latest token.
        /// </summary>
        private static void RapidTabSwitchesKeepTheLastActivation()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            bool closed = false;
            try
            {
                ShowGroupWindow(window);

                window.SetActive(1);
                window.UpdateLayout();

                int stale = window.ActivationTokenForChecks;
                if (stale == 0 || !window.IsActivationTokenCurrentForChecks(stale))
                {
                    throw new InvalidOperationException("the current tab has no current activation token");
                }

                window.SetActive(0);
                window.SetActive(1);
                window.SetActive(0);
                window.SetActive(1);
                window.UpdateLayout();

                if (window.ActiveIndex != 1 || !string.Equals(window.ActiveMemberId, "note-1", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "the rapid switch ended on " + window.ActiveIndex + "/" +
                        (window.ActiveMemberId ?? "<null>") + ", wanted 1/note-1");
                }
                if (window.IsActivationTokenCurrentForChecks(stale))
                {
                    throw new InvalidOperationException("a token from before the last switch is still current");
                }
                if (window.ActivationTokenForChecks == stale)
                {
                    throw new InvalidOperationException("the last switch did not issue a new token");
                }
                if (window.ContentSlots[1].Visibility != Visibility.Visible ||
                    window.ContentSlots[0].Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException("the final tab's slot is not visible");
                }

                int latest = window.ActivationTokenForChecks;
                window.SetActive(1);
                window.UpdateLayout();
                if (window.ActivationTokenForChecks != latest)
                {
                    throw new InvalidOperationException("a same-index SetActive issued a new activation token");
                }
                if (window.ActiveIndex != 1)
                {
                    throw new InvalidOperationException("the group window is not usable after the rapid switch");
                }

                int beforeClose = window.ActivationTokenForChecks;
                window.Close();
                closed = true;
                if (window.IsActivationTokenCurrentForChecks(beforeClose))
                {
                    throw new InvalidOperationException("closing the group did not invalidate its pending token");
                }
            }
            finally
            {
                if (!closed) window.Close();
            }
        }

        /// <summary>
        /// The chrome title is the active context (date / note title), and the
        /// note's title chevron is only offered on the note tab and opens the
        /// note's own title menu.
        /// </summary>
        private static void GroupTitleFollowsTheActiveView()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);

                var todoView = (TodoCalendarView)window.ContentSlots[0].Content;
                if (window.GroupChrome.Title != todoView.ChromeTitle)
                {
                    throw new InvalidOperationException(
                        "the todo title is '" + window.GroupChrome.Title + "', wanted '" + todoView.ChromeTitle + "'");
                }
                if (window.GroupChrome.TitleMenuEnabled)
                {
                    throw new InvalidOperationException("the todo tab offers a title menu");
                }

                window.SetActive(1);
                window.UpdateLayout();

                var noteView = (NotePanelView)window.ContentSlots[1].Content;
                if (!window.GroupChrome.TitleMenuEnabled)
                {
                    throw new InvalidOperationException("the note tab does not enable the title chevron");
                }
                if (window.GroupChrome.Title != noteView.ChromeTitle)
                {
                    throw new InvalidOperationException(
                        "the note title is '" + window.GroupChrome.Title + "', wanted '" + noteView.ChromeTitle + "'");
                }

                var chevron = window.GroupChrome.TitleChevron;
                chevron.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonDownEvent
                });
                chevron.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                {
                    RoutedEvent = UIElement.MouseLeftButtonUpEvent
                });
                if (!noteView.IsTitleMenuOpen)
                {
                    throw new InvalidOperationException("the title chevron did not open the note title menu");
                }
                noteView.CloseTitleMenu();

                window.SetActive(0);
                if (window.GroupChrome.TitleMenuEnabled)
                {
                    throw new InvalidOperationException("the title chevron stayed enabled on the todo tab");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// Lock and pin are group-level: the state lives on WidgetGroup and the
        /// shared chrome mirrors it (a locked header refuses the drag, a locked
        /// chrome hides the resize layer).
        /// </summary>
        private static void GroupLockAndPinFollowTheGroup()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);

                if (window.GroupChrome.IsLocked || window.GroupChrome.IsPinned)
                {
                    throw new InvalidOperationException("the fresh group chrome is locked or pinned");
                }

                window.ToggleLock();
                if (!group.IsLocked || !window.GroupChrome.IsLocked)
                {
                    throw new InvalidOperationException("ToggleLock did not reach the group and the chrome");
                }
                if (window.GroupChrome.Header.Cursor != Cursors.No)
                {
                    throw new InvalidOperationException("the locked header does not show the forbidden cursor");
                }
                if (window.GroupChrome.ResizeLayer.IsHitTestVisible)
                {
                    throw new InvalidOperationException("the locked chrome still hit-tests its resize layer");
                }

                window.TogglePin();
                if (!group.IsPanelPinned || !window.GroupChrome.IsPinned)
                {
                    throw new InvalidOperationException("TogglePin did not reach the group and the chrome");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// A group resize re-fits the views: the host content box follows the
        /// window, the todo view re-lays out its list viewport, and a tab switch
        /// leaves the window size alone.
        /// </summary>
        private static void GroupResizeFlowsIntoTheMemberViews()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);

                window.SetActive(0);
                window.UpdateLayout();
                var todoView = (TodoCalendarView)window.ContentSlots[0].Content;
                double initial = ((IWidgetViewHost)window).ContentHeight;
                double viewportInitial = todoView.ItemsScroller.Height;
                if (initial <= 0 || viewportInitial <= 0)
                {
                    throw new InvalidOperationException(
                        "the initial group content box is " + initial + " / viewport " + viewportInitial);
                }

                window.Width = 700;
                window.Height = 500;
                window.UpdateLayout();
                double small = ((IWidgetViewHost)window).ContentHeight;
                double viewportSmall = todoView.ItemsScroller.Height;
                if (small <= 0 || Math.Abs(small - initial) < 0.5)
                {
                    throw new InvalidOperationException(
                        "the content box did not follow the 700x500 resize: " + initial + " -> " + small);
                }
                if (Math.Abs(todoView.ActualHeight - small) > 1.5)
                {
                    throw new InvalidOperationException(
                        "the todo view is " + todoView.ActualHeight + " high, wanted the content box " + small);
                }
                if (Math.Abs(viewportSmall - viewportInitial) < 0.5)
                {
                    throw new InvalidOperationException(
                        "the todo list viewport stayed " + viewportInitial + " after the resize");
                }

                window.Width = 820;
                window.Height = 600;
                window.UpdateLayout();
                double large = ((IWidgetViewHost)window).ContentHeight;
                double viewportLarge = todoView.ItemsScroller.Height;
                if (large <= 0 || Math.Abs(large - small) < 0.5)
                {
                    throw new InvalidOperationException(
                        "the content box did not follow the 820x600 resize: " + small + " -> " + large);
                }
                if (Math.Abs(viewportLarge - viewportSmall) < 0.5)
                {
                    throw new InvalidOperationException(
                        "the todo list viewport stayed " + viewportSmall + " after growing");
                }

                double width = window.Width;
                double height = window.Height;
                window.SetActive(1);
                window.UpdateLayout();
                if (window.Width != width || window.Height != height)
                {
                    throw new InvalidOperationException("a tab switch after a resize changed the window size");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// The group menu carries one switch entry per member (checked on the
        /// active one), the live detach entry (T6: enabled for an unlocked
        /// pair, reaching the window's detach seam) and the hide-group entry.
        /// </summary>
        private static void GroupMenuCarriesTheSwitchDetachAndHide()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                var menu = window.BuildWidgetMenu(null);
                int switches = 0;
                int checkedSwitches = 0;
                MenuItem detach = null;
                MenuItem hide = null;

                foreach (var entry in menu.Items)
                {
                    var item = entry as MenuItem;
                    if (item == null) continue;
                    var header = item.Header as string;
                    if (header != null && header.StartsWith("切换到该标签", StringComparison.Ordinal))
                    {
                        switches++;
                        if (item.IsChecked) checkedSwitches++;
                    }
                    else if (header == "分离此组件")
                    {
                        detach = item;
                    }
                    else if (header == "隐藏整组")
                    {
                        hide = item;
                    }
                }

                if (switches != 2)
                {
                    throw new InvalidOperationException("the group menu has " + switches + " switch entries, wanted 2");
                }
                if (checkedSwitches != 1)
                {
                    throw new InvalidOperationException(
                        "the group menu checks " + checkedSwitches + " switch entries, wanted 1");
                }
                if (detach == null)
                {
                    throw new InvalidOperationException("the group menu has no detach entry");
                }
                if (!detach.IsEnabled)
                {
                    throw new InvalidOperationException("the detach entry is disabled for an unlocked pair");
                }
                if (hide == null)
                {
                    throw new InvalidOperationException("the group menu has no hide-group entry");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// Task B: the group title row opens the active member's normal widget
        /// menu - the kind appendices and actions come from the active datum,
        /// never from the group menu (no switch entry). The active tab decides
        /// which kind's appendix is present.
        /// </summary>
        private static void GroupTitleMenuShowsTheActiveMemberMenu()
        {
            ThemeManager.Initialize("dark");

            var search = new SearchData { Id = "search-1", Name = "Search", Color = "#6A9BCC" };
            var note = new NoteData { Id = "note-1", Name = "Note", Color = "#788C5D" };
            var folder = new FolderData { Id = "folder-1", Name = "Folder", Color = "#CC785C" };
            var todo = new TodoData
            {
                Id = "todo-1",
                Name = "Todo",
                Color = "#D4A017",
                SelectedDate = DateTime.Today
            };
            var group = new WidgetGroup { Id = "g-title-menu", ActiveWidgetId = "search-1" };
            var window = new WidgetGroupWindow(
                group, new List<WidgetData> { search, note, folder, todo });
            try
            {
                ContextMenu captured = null;
                window.MenuOpenedForChecks = menu => captured = menu;

                RaiseHeaderRightClick(window);
                if (captured == null)
                {
                    throw new InvalidOperationException("the title right click opened no menu");
                }
                AssertMenuHasHeader(captured, "Search_Rebuild");
                AssertMenuHasHeader(captured, "Search_Cancel");
                if (FindMenuByHeader(captured, Localization.Get("Search_Pause")) == null &&
                    FindMenuByHeader(captured, Localization.Get("Search_Resume")) == null)
                {
                    throw new InvalidOperationException(
                        "the search title menu has neither Search_Pause nor Search_Resume");
                }
                AssertNoSwitchEntry(captured, "search");

                window.SetActive(1);
                captured = null;
                RaiseHeaderRightClick(window);
                AssertMenuHasHeader(captured, "Menu_NoteFontSize");
                AssertNoSwitchEntry(captured, "note");

                window.SetActive(2);
                captured = null;
                RaiseHeaderRightClick(window);
                AssertMenuHasHeader(captured, "Menu_ItemSize");
                AssertNoSwitchEntry(captured, "folder");

                window.SetActive(3);
                captured = null;
                RaiseHeaderRightClick(window);
                AssertMenuHasHeader(captured, "Menu_HolidayRegion");
                AssertNoSwitchEntry(captured, "todo");
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// Task B: the tab strip keeps the group menu - a tab right click still
        /// carries the switch entries and the detach entry.
        /// </summary>
        private static void GroupTabRightClickStillShowsTheGroupMenu()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ContextMenu captured = null;
                window.MenuOpenedForChecks = menu => captured = menu;

                window.TabStrip.TabButtons[0].RaiseEvent(
                    new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Right)
                    {
                        RoutedEvent = UIElement.MouseRightButtonDownEvent
                    });

                if (captured == null)
                {
                    throw new InvalidOperationException("the tab right click opened no menu");
                }

                int switches = 0;
                foreach (var raw in captured.Items)
                {
                    var item = raw as MenuItem;
                    var header = item == null ? null : item.Header as string;
                    if (header != null && header.StartsWith("切换到该标签", StringComparison.Ordinal))
                    {
                        switches++;
                    }
                }
                if (switches == 0)
                {
                    throw new InvalidOperationException("the tab menu has no switch entry");
                }
                if (FindGroupMenuItem(captured, WidgetGroupMenuBuilder.DetachHeader) == null)
                {
                    throw new InvalidOperationException("the tab menu has no detach entry");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// Task B: the removed member's view is discarded through the manager,
        /// so a folder member must eject its stored files first.
        /// </summary>
        private static void GroupMemberDeleteEjectsFolderFiles()
        {
            var fake = new FolderLifecycleContentViewFake();
            WidgetManager.DiscardContentView(fake);

            if (fake.OnDeletingCount != 1)
            {
                throw new InvalidOperationException(
                    "DiscardContentView ran OnDeleting " + fake.OnDeletingCount + " time(s), wanted 1");
            }
        }

        private static void RaiseHeaderRightClick(WidgetGroupWindow window)
        {
            window.GroupChrome.Header.RaiseEvent(
                new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Right)
                {
                    RoutedEvent = UIElement.MouseRightButtonDownEvent
                });
        }

        private static void AssertMenuHasHeader(ContextMenu menu, string localizationKey)
        {
            if (menu == null)
            {
                throw new InvalidOperationException("no menu was captured for " + localizationKey);
            }
            if (FindMenuByHeader(menu, Localization.Get(localizationKey)) == null)
            {
                throw new InvalidOperationException(
                    "the title menu has no '" + Localization.Get(localizationKey) +
                    "' entry (wanted " + localizationKey + ")");
            }
        }

        private static void AssertNoSwitchEntry(ContextMenu menu, string kind)
        {
            if (menu == null)
            {
                throw new InvalidOperationException("no menu was captured for the " + kind + " tab");
            }
            foreach (var raw in menu.Items)
            {
                var item = raw as MenuItem;
                var header = item == null ? null : item.Header as string;
                if (header != null && header.StartsWith("切换到该标签", StringComparison.Ordinal))
                {
                    throw new InvalidOperationException(
                        "the " + kind + " title menu carries the group switch entry '" + header + "'");
                }
            }
        }

        /// <summary>
        /// A deterministic content view that also owns folder lifecycle hooks;
        /// the delete path must call OnDeleting exactly once.
        /// </summary>
        private sealed class FolderLifecycleContentViewFake : IWidgetContentView, IFolderPanelLifecycle
        {
            public int OnDeletingCount { get; private set; }

            public WidgetData Data => null;

            public FrameworkElement View => null;

            public string ChromeTitle => null;

            public bool HasTitleMenu => false;

            public string ChromeTitleTooltip => null;

            public void Attach(WidgetData data, IWidgetViewHost host) { }

            public void RebindHost(IWidgetViewHost host) { }

            public void Activate() { }

            public void Deactivate() { }

            public void Refresh() { }

            public void RefreshChromeTitle() { }

            public void ToggleTitleMenu(FrameworkElement anchor) { }

            public bool HandlePreviewKeyDown(KeyEventArgs e) => false;

            public void HandleMouseDownOutsideEditor(object source) { }

            public void FlushPendingEdit() { }

            public bool TryUndo() => false;

            public void HandleKeyDown(KeyEventArgs e) { }

            public void HandleDeactivated() { }

            public void HandleSourceInitialized() { }

            public void ApplyAdaptiveLayout() { }

            public void OnDeleting() { OnDeletingCount++; }

            public void DeactivateForPanelHide() { }
        }

        /// <summary>
        /// T6: the detach entry is enabled for an unlocked pair and its click
        /// reaches the window's detach seam (<see cref="WidgetGroupWindow.DetachRequested"/>);
        /// a locked group disables the entry and refuses the same request.
        /// </summary>
        private static void GroupDetachMenuFollowsTheLock()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                var requested = new List<string>();
                window.DetachRequested += id => requested.Add(id);

                MenuItem detach = FindGroupMenuItem(window.BuildWidgetMenu(null), "分离此组件");
                if (detach == null) throw new InvalidOperationException("the unlocked menu has no detach entry");
                if (!detach.IsEnabled)
                    throw new InvalidOperationException("the unlocked menu disables detach");

                detach.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));
                if (requested.Count != 1 || requested[0] != "todo-1")
                {
                    throw new InvalidOperationException(
                        "the detach click reached " + requested.Count + " request(s), wanted the active todo-1");
                }

                group.IsLocked = true;
                MenuItem lockedDetach = FindGroupMenuItem(window.BuildWidgetMenu(null), "分离此组件");
                if (lockedDetach == null) throw new InvalidOperationException("the locked menu has no detach entry");
                if (lockedDetach.IsEnabled)
                    throw new InvalidOperationException("the locked menu still enables detach");

                requested.Clear();
                lockedDetach.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));
                if (window.RequestDetachActive())
                    throw new InvalidOperationException("a locked group accepted a detach request");
                if (requested.Count != 0)
                    throw new InvalidOperationException("a locked group raised a detach request");
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>T6: the merge hint is a theme-token border repaint that restores exactly.</summary>
        private static void SetMergeHintHighlightsAndRestoresTheShellBorder()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);

                var shell = window.GroupChrome.Shell;
                var baseline = shell.BorderBrush as SolidColorBrush;
                if (baseline == null) throw new InvalidOperationException("the shell has no border brush");
                Thickness thickness = shell.BorderThickness;

                window.SetMergeHint(true);
                var hinted = shell.BorderBrush as SolidColorBrush;
                if (hinted == null) throw new InvalidOperationException("the merge hint cleared the border brush");
                if (hinted.Color == baseline.Color)
                    throw new InvalidOperationException("the merge hint did not repaint the shell border");
                if (shell.BorderThickness != thickness)
                    throw new InvalidOperationException("the merge hint changed the shell border thickness");

                window.SetMergeHint(true); // repeated calls are safe
                var hintedAgain = shell.BorderBrush as SolidColorBrush;
                if (hintedAgain == null || hintedAgain.Color != hinted.Color)
                    throw new InvalidOperationException("a repeated merge hint changed the border brush");

                window.SetMergeHint(false);
                var restored = shell.BorderBrush as SolidColorBrush;
                if (restored == null || restored.Color != baseline.Color)
                    throw new InvalidOperationException("the merge hint did not restore the shell border");

                window.SetMergeHint(false);
                var restoredAgain = shell.BorderBrush as SolidColorBrush;
                if (restoredAgain == null || restoredAgain.Color != baseline.Color)
                    throw new InvalidOperationException("a repeated merge clear changed the shell border");
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// T6 tab drag gesture seam: the 12 DIP threshold, the sub-threshold
        /// press/up (no event, no detach), the in-window drag (event, no
        /// detach) and the out-of-window drag (event -> detach request), plus
        /// the locked-group refusal. The real mouse gesture is a manual smoke
        /// item; this pin drives the same gesture methods.
        /// </summary>
        private static void TabStripDragGestureRespectsTheThreshold()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);

                var strip = window.TabStrip;
                if (strip == null) throw new InvalidOperationException("the group has no tab strip");
                if (Math.Abs(WidgetGroupTabStrip.DragThreshold - GroupDragPolicy.DefaultDragThreshold) > 0.001)
                {
                    throw new InvalidOperationException(
                        "the strip threshold is " + WidgetGroupTabStrip.DragThreshold + ", wanted "
                        + GroupDragPolicy.DefaultDragThreshold);
                }

                var completions = new List<KeyValuePair<int, bool>>();
                strip.TabDragCompleted += (index, outside) =>
                    completions.Add(new KeyValuePair<int, bool>(index, outside));

                var reorders = new List<KeyValuePair<int, int>>();
                strip.TabReorderRequested += (from, to) =>
                    reorders.Add(new KeyValuePair<int, int>(from, to));

                var detaches = new List<string>();
                window.DetachRequested += id => detaches.Add(id);

                // Below threshold: the press and release are a click, not a drag.
                if (!strip.BeginTabDrag(1, new Point(10, 10)))
                    throw new InvalidOperationException("the strip refused a valid tab press");
                if (strip.UpdateTabDrag(new Point(15, 13)))
                    throw new InvalidOperationException("a sub-threshold move started a drag");
                if (strip.EndTabDrag(new Point(15, 13)))
                    throw new InvalidOperationException("a sub-threshold release completed a drag");
                if (completions.Count != 0 || detaches.Count != 0)
                    throw new InvalidOperationException("a sub-threshold press/release detached a tab");
                if (strip.IsTabDragActive)
                    throw new InvalidOperationException("the strip stayed in a drag after the release");

                // Above threshold but released inside the group: no detach.
                strip.BeginTabDrag(1, new Point(10, 10));
                if (!strip.UpdateTabDrag(new Point(40, 10)))
                    throw new InvalidOperationException("an over-threshold move did not start a drag");
                if (!strip.IsTabDragActive)
                    throw new InvalidOperationException("the strip did not record the active drag");
                if (!strip.EndTabDrag(new Point(40, 10)))
                    throw new InvalidOperationException("an over-threshold release did not complete the drag");
                if (completions.Count != 1 || completions[0].Key != 1 || completions[0].Value)
                    throw new InvalidOperationException("an in-window release reported an outside drag");
                if (detaches.Count != 0)
                    throw new InvalidOperationException("an in-window release detached a tab");

                // Above threshold, released outside the window: detach request.
                // An outside release is never a reorder.
                reorders.Clear();
                strip.BeginTabDrag(0, new Point(10, 10));
                strip.UpdateTabDrag(new Point(40, 10));
                if (!strip.EndTabDrag(new Point(100000, 100000)))
                    throw new InvalidOperationException("an outside release did not complete the drag");
                if (completions.Count != 2 || completions[1].Key != 0 || !completions[1].Value)
                    throw new InvalidOperationException("the outside release was not reported as outside");
                if (detaches.Count != 1 || detaches[0] != "todo-1")
                    throw new InvalidOperationException("the outside release did not request the tab's detach");
                if (reorders.Count != 0)
                    throw new InvalidOperationException("an outside release requested a tab reorder");
                if (strip.IsInsertIndicatorVisible)
                    throw new InvalidOperationException("the insertion line stayed visible after an outside release");

                // Locked group: the gesture still completes but nothing detaches.
                group.IsLocked = true;
                detaches.Clear();
                strip.BeginTabDrag(0, new Point(10, 10));
                strip.UpdateTabDrag(new Point(40, 10));
                strip.EndTabDrag(new Point(100000, 100000));
                if (detaches.Count != 0)
                    throw new InvalidOperationException("a locked group detached a dragged-out tab");
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// R1: the blank area of the 32px tab row is the same whole-window drag
        /// surface as the 40px header - a real press on the TabHost raises the
        /// shared start, the private drag seam moves the group, and the release
        /// ends it. A tab press keeps its own click/drag semantics and marks the
        /// event handled, so it never starts a window drag. A locked group
        /// refuses the blank press like the header (forbidden cursor, no move).
        /// </summary>
        private static void GroupTabRowBlankAreaDragsTheWindow()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            WidgetChrome chrome = ChromeOf(window);

            try
            {
                ShowGroupWindow(window);
                // Keep the check off the desktop; -10000 DIP stays inside the
                // Win32 window-coordinate range on normal DPI scales.
                window.Left = -10000;
                window.Top = -10000;
                double startLeft = window.Left;
                double startTop = window.Top;

                MethodInfo moved = PrivateBaseMethod("OnHeaderDragMoved");

                // The real TabHost press: capture, start event, drag flag.
                chrome.TabHost.RaiseEvent(NewMouseLeftButtonEvent(UIElement.MouseLeftButtonDownEvent));
                if (!PrivateField<bool>(chrome, "_isDragActive"))
                {
                    throw new InvalidOperationException(
                        "a press on the blank tab row did not start a whole-window drag");
                }
                if (!ReferenceEquals(Mouse.OverrideCursor, CursorHelper.GrabHand))
                {
                    throw new InvalidOperationException(
                        "the tab-row drag wears " + CursorName(Mouse.OverrideCursor) +
                        ", wanted the shared grab hand");
                }

                Point anchor = PrivateBaseField<Point>(window, "_dragStartCursor");
                double scale = VisualTreeHelper.GetDpi(window).DpiScaleX;
                moved.Invoke(window,
                    new object[] { new Point(anchor.X + 40 * scale, anchor.Y + 30 * scale) });
                if (Math.Abs(window.Left - (startLeft + 40)) > 0.5 ||
                    Math.Abs(window.Top - (startTop + 30)) > 0.5)
                {
                    throw new InvalidOperationException(
                        "the tab-row blank drag moved the group to " + window.Left + "," + window.Top +
                        " (wanted " + (startLeft + 40) + "," + (startTop + 30) + ")");
                }

                chrome.TabHost.RaiseEvent(NewMouseLeftButtonEvent(UIElement.MouseLeftButtonUpEvent));
                if (PrivateField<bool>(chrome, "_isDragActive"))
                {
                    throw new InvalidOperationException("the tab-row release left the drag running");
                }
                if (Mouse.OverrideCursor != null)
                {
                    throw new InvalidOperationException(
                        "the tab-row release left the override cursor stuck");
                }

                // A tab press still switches/arms its own gesture and never
                // starts the whole-window drag.
                double leftAfterBlankDrag = window.Left;
                double topAfterBlankDrag = window.Top;
                Grid tab = window.TabStrip.TabButtons[0];
                tab.RaiseEvent(NewMouseLeftButtonEvent(UIElement.MouseLeftButtonDownEvent));
                try
                {
                    if (PrivateField<bool>(chrome, "_isDragActive"))
                    {
                        throw new InvalidOperationException("a tab press started a whole-window drag");
                    }
                    if (window.Left != leftAfterBlankDrag || window.Top != topAfterBlankDrag)
                    {
                        throw new InvalidOperationException("a tab press moved the group window");
                    }
                }
                finally
                {
                    tab.RaiseEvent(NewMouseLeftButtonEvent(UIElement.MouseLeftButtonUpEvent));
                }

                // Locked: the same press flashes the lock and moves nothing.
                group.IsLocked = true;
                window.UpdateUI();
                if (chrome.TabHost.Cursor != Cursors.No || chrome.Header.Cursor != Cursors.No)
                {
                    throw new InvalidOperationException(
                        "the locked group wears " + CursorName(chrome.TabHost.Cursor) + "/" +
                        CursorName(chrome.Header.Cursor) + " on its tab row/header, wanted the forbidden cursor");
                }
                double lockedLeft = window.Left;
                double lockedTop = window.Top;
                chrome.TabHost.RaiseEvent(NewMouseLeftButtonEvent(UIElement.MouseLeftButtonDownEvent));
                if (PrivateField<bool>(chrome, "_isDragActive"))
                {
                    throw new InvalidOperationException("a locked tab-row press started a window drag");
                }
                if (window.Left != lockedLeft || window.Top != lockedTop)
                {
                    throw new InvalidOperationException("a locked tab-row press moved the window");
                }
            }
            finally
            {
                Mouse.Capture(null);
                Mouse.OverrideCursor = null;
                window.Close();
            }
        }

        /// <summary>
        /// R1: every group drag affordance wears the same grab-hand pair -
        /// CursorHelper.OpenHand at rest (the very same instance the header
        /// uses) and CursorHelper.GrabHand while a real tab drag runs, with
        /// the open hand restored on release and on cancel. The locked header
        /// and tab row wear the forbidden cursor.
        /// </summary>
        private static void GroupDragUsesTheSharedHandCursors()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            WidgetChrome chrome = ChromeOf(window);

            try
            {
                ShowGroupWindow(window);
                WidgetGroupTabStrip strip = window.TabStrip;

                if (!ReferenceEquals(chrome.Header.Cursor, CursorHelper.OpenHand))
                {
                    throw new InvalidOperationException(
                        "the header cursor is " + CursorName(chrome.Header.Cursor) +
                        ", wanted the shared open hand");
                }
                if (!ReferenceEquals(chrome.TabHost.Cursor, CursorHelper.OpenHand))
                {
                    throw new InvalidOperationException(
                        "the tab-row blank cursor is " + CursorName(chrome.TabHost.Cursor) +
                        ", wanted the shared open hand");
                }
                for (int i = 0; i < strip.TabButtons.Count; i++)
                {
                    if (!ReferenceEquals(strip.TabButtons[i].Cursor, CursorHelper.OpenHand))
                    {
                        throw new InvalidOperationException(
                            "tab " + i + " wears " + CursorName(strip.TabButtons[i].Cursor) +
                            ", wanted the same open-hand instance as the header");
                    }
                }

                // A real tab drag lifts to the grab hand and restores on release.
                strip.BeginTabDrag(0, new Point(10, 10));
                if (!strip.UpdateTabDrag(new Point(40, 10)))
                {
                    throw new InvalidOperationException("the over-threshold tab move did not start a drag");
                }
                if (!ReferenceEquals(strip.TabButtons[0].Cursor, CursorHelper.GrabHand))
                {
                    throw new InvalidOperationException(
                        "a tab drag wears " + CursorName(strip.TabButtons[0].Cursor) +
                        ", wanted the shared grab hand");
                }
                strip.EndTabDrag(new Point(40, 10));
                if (!ReferenceEquals(strip.TabButtons[0].Cursor, CursorHelper.OpenHand))
                {
                    throw new InvalidOperationException(
                        "the tab cursor did not return to the open hand after the release");
                }

                // The cancel path restores it too.
                strip.BeginTabDrag(1, new Point(10, 10));
                strip.UpdateTabDrag(new Point(40, 10));
                strip.CancelTabDrag();
                if (!ReferenceEquals(strip.TabButtons[1].Cursor, CursorHelper.OpenHand))
                {
                    throw new InvalidOperationException(
                        "a cancelled tab drag left the grab hand on the tab");
                }

                // The whole-window drag lifts Mouse.OverrideCursor and clears it.
                try
                {
                    chrome.TabHost.RaiseEvent(NewMouseLeftButtonEvent(UIElement.MouseLeftButtonDownEvent));
                    if (!ReferenceEquals(Mouse.OverrideCursor, CursorHelper.GrabHand))
                    {
                        throw new InvalidOperationException(
                            "a window drag wears " + CursorName(Mouse.OverrideCursor) +
                            ", wanted the shared grab hand");
                    }
                    chrome.TabHost.RaiseEvent(NewMouseLeftButtonEvent(UIElement.MouseLeftButtonUpEvent));
                    if (Mouse.OverrideCursor != null)
                    {
                        throw new InvalidOperationException(
                            "the window drag release left the override cursor set");
                    }
                }
                finally
                {
                    Mouse.Capture(null);
                    Mouse.OverrideCursor = null;
                }

                // Locked: header and blank tab row share the forbidden cursor.
                chrome.IsLocked = true;
                if (chrome.Header.Cursor != Cursors.No || chrome.TabHost.Cursor != Cursors.No)
                {
                    throw new InvalidOperationException(
                        "the locked affordances wear " + CursorName(chrome.Header.Cursor) + "/" +
                        CursorName(chrome.TabHost.Cursor) + ", wanted the forbidden cursor");
                }
                chrome.IsLocked = false;
                if (!ReferenceEquals(chrome.TabHost.Cursor, CursorHelper.OpenHand))
                {
                    throw new InvalidOperationException("unlocking did not restore the tab-row open hand");
                }
            }
            finally
            {
                Mouse.Capture(null);
                Mouse.OverrideCursor = null;
                window.Close();
            }
        }

        /// <summary>
        /// R2: dragging a tab outside the group wears an Explorer-folder-style
        /// ghost at the cursor's lower-right - the dragged tab's live view in a
        /// small chrome shell. It appears only for the outside detach gesture,
        /// follows the synthetic outside drag (offset + clamp), and is gone on
        /// re-entry, release, cancel, locked groups, HidePanel and after a
        /// whole-window drag (which never shows it).
        /// </summary>
        private static void TabDetachGhostFollowsTheCursor()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);

            try
            {
                ShowGroupWindow(window);
                // The group stays off the desktop; the synthetic outside drag
                // points still map to real screen coordinates for the clamp.
                window.Left = -10000;
                window.Top = -10000;

                // An explicit pre-group standalone size, different from the
                // 760x540 group: the ghost must preview this, not the tab's
                // group-layout view.
                todo.PanelWidth = 320;
                todo.PanelHeight = 400;

                window.SetActive(0);
                window.UpdateLayout();

                WidgetGroupTabStrip strip = window.TabStrip;
                if (window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("the group wears a drag ghost before any drag");
                }
                if (window.DragGhost != null)
                {
                    throw new InvalidOperationException("a ghost window exists before any drag");
                }

                // A click and an in-window drag never show the ghost.
                strip.BeginTabDrag(0, new Point(10, 10));
                strip.UpdateTabDrag(new Point(20, 12));
                if (window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("a click-sized tab move showed the drag ghost");
                }
                strip.UpdateTabDrag(new Point(40, 12));
                if (window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("an in-window reorder showed the drag ghost");
                }
                strip.EndTabDrag(new Point(40, 12));
                if (window.DragGhost != null)
                {
                    throw new InvalidOperationException("an in-window reorder kept a ghost window");
                }

                // Whole-window (header/tab-row) drags never show it.
                MethodInfo started = PrivateBaseMethod("OnHeaderDragStarted");
                MethodInfo moved = PrivateBaseMethod("OnHeaderDragMoved");
                MethodInfo ended = PrivateBaseMethod("OnHeaderDragEnded");
                double scale = VisualTreeHelper.GetDpi(window).DpiScaleX;
                started.Invoke(window, new object[] { new Point(100, 100) });
                moved.Invoke(window,
                    new object[] { new Point(100 + 30 * scale, 100 + 20 * scale) });
                if (window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("a whole-window drag showed the tab ghost");
                }
                ended.Invoke(window,
                    new object[] { new Point(100 + 30 * scale, 100 + 20 * scale) });

                // Outside: the ghost appears with the dragged tab's live view.
                Point outsideA = new Point(20000, 20000);
                strip.BeginTabDrag(0, new Point(10, 10));
                strip.UpdateTabDrag(outsideA);
                if (!window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("an outside tab drag shows no ghost");
                }

                DragGhostWindow ghost = window.DragGhost;
                if (ghost == null || !ghost.IsVisible)
                {
                    throw new InvalidOperationException("the visible drag ghost is not a live window");
                }
                if (ghost.ShowInTaskbar)
                {
                    throw new InvalidOperationException("the drag ghost takes a taskbar slot");
                }
                if (Math.Abs(ghost.Opacity - 0.7) > 0.05)
                {
                    throw new InvalidOperationException(
                        "the drag ghost opacity is " + ghost.Opacity + ", wanted about 0.7");
                }
                if (ghost.Width <= 0 || ghost.Height <= 0 ||
                    ghost.Width > 320.5 || ghost.Height > 230.5)
                {
                    throw new InvalidOperationException(
                        "the drag ghost is " + ghost.Width + "x" + ghost.Height +
                        ", wanted at most 320x230");
                }

                // The dragged todo carries a pre-group 320x400 standalone size,
                // different from the 760x540 group: its content box is 318x358,
                // letterboxed into the scaled 320x230 ghost.
                BitmapSource rendered = GhostSeamOrNull<BitmapSource>(ghost, "PreviewBitmap");
                if (rendered == null)
                {
                    throw new InvalidOperationException(
                        "the drag ghost has no rendered original-size preview");
                }
                if (!rendered.IsFrozen)
                {
                    throw new InvalidOperationException("the drag ghost preview bitmap is not frozen");
                }
                if (rendered.PixelWidth != 318 || rendered.PixelHeight != 358)
                {
                    throw new InvalidOperationException(
                        "the drag ghost preview is " + rendered.PixelWidth + "x" + rendered.PixelHeight +
                        ", wanted the 320x400 content box 318x358");
                }
                if (ghost.PreviewSource != null || ghost.PreviewBrush != null)
                {
                    throw new InvalidOperationException(
                        "the drag ghost kept the live view next to its bitmap");
                }
                if (GhostSeamStretch(ghost, "BitmapStretch", Stretch.Fill) != Stretch.Uniform)
                {
                    throw new InvalidOperationException(
                        "the drag ghost body does not stretch the bitmap uniformly");
                }

                double standaloneAspect = 320.0 / 400.0;
                if (Math.Abs(ghost.Width / ghost.Height - standaloneAspect) > 0.02)
                {
                    throw new InvalidOperationException(
                        "the drag ghost aspect is " + (ghost.Width / ghost.Height) +
                        ", wanted the standalone " + standaloneAspect);
                }
                double ghostScale = Math.Min(1.0, Math.Min(320.0 / 320.0, 230.0 / 400.0));
                double expectedHeader = Math.Max(18.0, 40.0 * ghostScale);
                double ghostHeader = GhostSeamDouble(ghost, "HeaderHeight", -1);
                if (Math.Abs(ghostHeader - expectedHeader) > 1.0)
                {
                    throw new InvalidOperationException(
                        "the drag ghost header is " + ghostHeader +
                        ", wanted the scaled " + expectedHeader);
                }

                Point cursorA = ghost.LastCursorScreen;
                Point expectedA = strip.PointToScreen(outsideA);
                if (PointDistance(cursorA, expectedA) > 1.0)
                {
                    throw new InvalidOperationException(
                        "the drag ghost followed " + cursorA + " instead of the cursor " + expectedA);
                }
                AssertGhostPlacedAt(ghost, expectedA, "after the first outside move");
                double leftA = ghost.Left;
                double topA = ghost.Top;

                // Still outside, now far the other way: follows the cursor and
                // clamps to the opposite work-area corner.
                Point outsideB = new Point(-20000, -20000);
                strip.UpdateTabDrag(outsideB);
                if (!window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("the drag ghost vanished while still outside");
                }
                if (!ReferenceEquals(window.DragGhost, ghost))
                {
                    throw new InvalidOperationException("the drag ghost was recreated mid-drag");
                }
                Point cursorB = ghost.LastCursorScreen;
                Point expectedB = strip.PointToScreen(outsideB);
                if (PointDistance(cursorB, expectedB) > 1.0)
                {
                    throw new InvalidOperationException(
                        "the drag ghost did not follow the second outside move: " + cursorB +
                        " vs " + expectedB);
                }
                AssertGhostPlacedAt(ghost, expectedB, "after the followed outside move");
                if (Math.Abs(ghost.Left - leftA) < 0.5 && Math.Abs(ghost.Top - topA) < 0.5)
                {
                    throw new InvalidOperationException(
                        "the drag ghost stayed at one clamped corner across two outside moves");
                }

                // Re-enter: hidden and closed.
                strip.UpdateTabDrag(new Point(40, 12));
                if (window.IsDragGhostVisible || window.DragGhost != null)
                {
                    throw new InvalidOperationException("the drag ghost survived re-entering the group");
                }

                // Outside again, then an outside release: cleaned up at detach.
                strip.UpdateTabDrag(outsideA);
                if (!window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("the second outside drag shows no ghost");
                }
                strip.EndTabDrag(outsideA);
                if (window.IsDragGhostVisible || window.DragGhost != null)
                {
                    throw new InvalidOperationException("the outside release left the drag ghost alive");
                }

                // Capture loss / cancel.
                strip.BeginTabDrag(0, new Point(10, 10));
                strip.UpdateTabDrag(outsideA);
                if (!window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("the cancel scenario shows no ghost");
                }
                strip.CancelTabDrag();
                if (window.IsDragGhostVisible || window.DragGhost != null)
                {
                    throw new InvalidOperationException("cancelling the tab drag left the ghost alive");
                }

                // A locked group never shows it.
                group.IsLocked = true;
                window.UpdateUI();
                strip.BeginTabDrag(0, new Point(10, 10));
                strip.UpdateTabDrag(outsideA);
                if (window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("a locked group showed the detach ghost");
                }
                strip.CancelTabDrag();

                // HidePanel is another exit path.
                group.IsLocked = false;
                window.UpdateUI();
                strip.BeginTabDrag(0, new Point(10, 10));
                strip.UpdateTabDrag(outsideA);
                if (!window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("the HidePanel scenario shows no ghost");
                }
                window.HidePanel();
                if (window.IsDragGhostVisible || window.DragGhost != null)
                {
                    throw new InvalidOperationException("HidePanel left the drag ghost alive");
                }
                strip.CancelTabDrag();
            }
            finally
            {
                Mouse.Capture(null);
                Mouse.OverrideCursor = null;
                window.Close();
            }
        }

        /// <summary>
        /// The ghost origin is the cursor + 16 DIP, clamped into the cursor
        /// monitor's work area; this repeats the placement contract with the
        /// public monitor maths so multi-DPI stays honest.
        /// </summary>
        private static void AssertGhostPlacedAt(Window ghost, Point cursorDevice, string context)
        {
            MonitorInfo monitor = MonitorInterop.GetMonitorForDevicePoint(cursorDevice);
            double scale = monitor != null && monitor.DpiScale > 0 ? monitor.DpiScale : 1.0;
            Rect work = monitor != null ? monitor.WorkAreaDevice : new Rect(0, 0, 1920, 1080);

            double width = ghost.Width * scale;
            double height = ghost.Height * scale;
            double x = cursorDevice.X + 16 * scale;
            double y = cursorDevice.Y + 16 * scale;
            if (width >= work.Width) x = work.X;
            else x = Math.Max(work.X, Math.Min(x, work.Right - width));
            if (height >= work.Height) y = work.Y;
            else y = Math.Max(work.Y, Math.Min(y, work.Bottom - height));

            Rect expected = PanelPlacement.ToDipRect(new Rect(x, y, width, height), monitor);
            if (Math.Abs(ghost.Left - expected.X) > 1.0 || Math.Abs(ghost.Top - expected.Y) > 1.0)
            {
                throw new InvalidOperationException(
                    "the drag ghost is at " + ghost.Left + "," + ghost.Top + " " + context +
                    ", wanted " + expected.X + "," + expected.Y);
            }
        }

        private static double PointDistance(Point a, Point b)
        {
            double dx = a.X - b.X;
            double dy = a.Y - b.Y;
            return Math.Sqrt(dx * dx + dy * dy);
        }

        /// <summary>
        /// R3: the offscreen renderer produces a frozen bitmap of the component
        /// at its pre-group content box (full size minus the 1px border per side
        /// and the 40px chrome header), uses a fresh clone per call (no data or
        /// handler duplication, no Loaded/live-tree service start) and falls
        /// back to the 360x420 standalone default when a size is missing.
        /// </summary>
        private static void WidgetGhostRendererRendersOriginalSizes()
        {
            ThemeManager.Initialize("dark");

            var todo = new TodoData
            {
                Id = "r3-render-todo",
                Name = "R3 Todo",
                Color = "#6A9BCC",
                SelectedDate = DateTime.Today,
                PanelWidth = 320,
                PanelHeight = 400
            };
            TodoListOps.AddItem(todo, "One", DateTime.Today);
            int todoItems = todo.Items.Count;

            BitmapSource todoRender = RenderGhostPreview(todo);
            if (todoRender == null)
            {
                throw new InvalidOperationException("the todo ghost render returned no bitmap");
            }
            if (todoRender.PixelWidth != 318 || todoRender.PixelHeight != 358)
            {
                throw new InvalidOperationException(
                    "the todo ghost render is " + todoRender.PixelWidth + "x" + todoRender.PixelHeight +
                    ", wanted the 320x400 content box 318x358");
            }
            if (!todoRender.IsFrozen)
            {
                throw new InvalidOperationException("the todo ghost render is not frozen");
            }
            if (!HasVisiblePixels(todoRender))
            {
                throw new InvalidOperationException("the todo ghost render is blank");
            }
            if (DistinctVisibleColors(todoRender) < 8)
            {
                throw new InvalidOperationException(
                    "the todo ghost render has no component detail (too few colours)");
            }
            if (todo.Items.Count != todoItems)
            {
                throw new InvalidOperationException("the todo ghost render changed the widget's items");
            }
            if (GhostRendererFlag("LastCloneWasLoaded"))
            {
                throw new InvalidOperationException(
                    "the todo ghost clone was loaded (a live tree could start services)");
            }

            // A second render is a fresh clone, not a shared/cached view.
            BitmapSource todoAgain = RenderGhostPreview(todo);
            if (todoAgain == null || ReferenceEquals(todoRender, todoAgain))
            {
                throw new InvalidOperationException(
                    "the renderer reused its bitmap instead of rendering a fresh clone");
            }
            if (todo.Items.Count != todoItems)
            {
                throw new InvalidOperationException("the second todo ghost render changed the widget's items");
            }

            var note = new NoteData
            {
                Id = "r3-render-note",
                Name = "R3 Note",
                Color = "#788C5D",
                PanelWidth = 320,
                PanelHeight = 400
            };
            note.Notes.Add(NewNote("r3-render-note-1", "Hello", DateTime.Today));
            int noteCount = note.Notes.Count;

            BitmapSource noteRender = RenderGhostPreview(note);
            if (noteRender == null || noteRender.PixelWidth != 318 || noteRender.PixelHeight != 358)
            {
                throw new InvalidOperationException(
                    "the note ghost render is not the 320x400 content box 318x358");
            }
            if (!noteRender.IsFrozen || note.Notes.Count != noteCount)
            {
                throw new InvalidOperationException(
                    "the note ghost render was not frozen or changed the widget's notes");
            }
            if (!HasVisiblePixels(noteRender))
            {
                throw new InvalidOperationException("the note ghost render is blank");
            }
            if (DistinctVisibleColors(noteRender) < 8)
            {
                throw new InvalidOperationException(
                    "the note ghost render has no component detail (too few colours)");
            }
            if (GhostRendererFlag("LastCloneWasLoaded"))
            {
                throw new InvalidOperationException(
                    "the note ghost clone was loaded (a live tree could start services)");
            }

            // No persisted size: the 360x420 standalone default is rendered.
            var legacy = new NoteData { Id = "r3-render-legacy", Name = "Legacy" };
            BitmapSource legacyRender = RenderGhostPreview(legacy);
            if (legacyRender == null || legacyRender.PixelWidth != 358 || legacyRender.PixelHeight != 378)
            {
                throw new InvalidOperationException(
                    "the missing-size ghost render did not use the 360x420 default");
            }

            var search = new SearchData
            {
                Id = "r3-render-search",
                Name = "R3 Search",
                Color = "#4A7BB5",
                PanelWidth = 340,
                PanelHeight = 420
            };
            BitmapSource searchRender = RenderGhostPreview(search);
            if (searchRender == null || searchRender.PixelWidth != 338 || searchRender.PixelHeight != 378)
            {
                throw new InvalidOperationException(
                    "the search ghost render is not the 340x420 content box 338x378");
            }
            if (GhostRendererFlag("LastCloneWasLoaded"))
            {
                throw new InvalidOperationException(
                    "the search ghost clone was loaded (the search service could start)");
            }
        }

        /// <summary>
        /// R3 review: the search ghost preview paints the empty-query state of a
        /// real standalone panel, including the 常用文件 list. The sandbox config
        /// gets one existing file (this check assembly), the clone renders the
        /// 422x562 search panel, and the list must carry rows without the view
        /// ever being loaded (the service must not start). The config list is
        /// restored afterwards.
        /// </summary>
        private static void SearchGhostPreviewShowsFrequentFiles()
        {
            ThemeManager.Initialize("dark");

            WidgetManager manager = WidgetManager.Instance;
            List<FrequentFile> before = manager.Config.FrequentFiles;
            string existingFile = typeof(Program).Assembly.Location;
            manager.Config.FrequentFiles = new List<FrequentFile>
            {
                new FrequentFile
                {
                    Path = existingFile,
                    Count = 7,
                    LastOpenedUtc = DateTime.UtcNow
                }
            };

            try
            {
                var search = new SearchData
                {
                    Id = "r3-preview-search",
                    Name = "Preview Search",
                    Color = "#4A7BB5",
                    PanelWidth = 422,
                    PanelHeight = 562
                };

                BitmapSource preview = RenderGhostPreview(search);
                if (preview == null)
                {
                    throw new InvalidOperationException("the search ghost preview returned no bitmap");
                }
                if (preview.PixelWidth != 420 || preview.PixelHeight != 520)
                {
                    throw new InvalidOperationException(
                        "the 422x562 search preview is " + preview.PixelWidth + "x" +
                        preview.PixelHeight + ", wanted the 420x520 content box");
                }
                if (!HasVisiblePixels(preview) || DistinctVisibleColors(preview) < 8)
                {
                    throw new InvalidOperationException("the search ghost preview is blank or flat");
                }

                int rows = GhostRendererInt("LastSearchFrequentRows");
                if (rows <= 0)
                {
                    throw new InvalidOperationException(
                        "the search ghost preview shows no frequent-file rows");
                }
                if (GhostRendererFlag("LastCloneWasLoaded"))
                {
                    throw new InvalidOperationException(
                        "the search ghost clone was loaded (the search service could start)");
                }
            }
            finally
            {
                manager.Config.FrequentFiles = before;
            }
        }

        /// <summary>
        /// R3: when the offscreen render is unavailable the ghost still binds
        /// the dragged tab's live view through the existing VisualBrush, at the
        /// same original-size outer aspect. `Prepare` never shows the window,
        /// so the check cannot flash a ghost on the desktop.
        /// </summary>
        private static void TabDetachGhostFallsBackToTheLiveView()
        {
            ThemeManager.Initialize("dark");

            var ghost = new DragGhostWindow();
            var live = new Border { Width = 200, Height = 120, Background = Brushes.Transparent };
            var member = new NoteData
            {
                Id = "r3-fallback",
                Name = "Fallback",
                Color = "#788C5D",
                PanelWidth = 360,
                PanelHeight = 420
            };

            try
            {
                MethodInfo prepare = typeof(DragGhostWindow).GetMethod("Prepare",
                    BindingFlags.Instance | BindingFlags.NonPublic);
                if (prepare == null)
                {
                    throw new InvalidOperationException(
                        "DragGhostWindow has no Prepare(live view, null bitmap) seam");
                }
                prepare.Invoke(ghost,
                    new object[] { null, new Point(-10000, -10000), live, member, null });
                // Show it so the check exercises the real overlay teardown,
                // not a never-shown Window close.
                ghost.Show();

                if (!ReferenceEquals(ghost.PreviewSource, live))
                {
                    throw new InvalidOperationException(
                        "the null-render fallback did not keep the live view");
                }
                if (ghost.PreviewBrush == null || !ReferenceEquals(ghost.PreviewBrush.Visual, live))
                {
                    throw new InvalidOperationException(
                        "the null-render fallback did not paint the live VisualBrush");
                }
                if (GhostSeamOrNull<BitmapSource>(ghost, "PreviewBitmap") != null)
                {
                    throw new InvalidOperationException("the null-render fallback reused a bitmap");
                }
                if (Math.Abs(ghost.Width / ghost.Height - 360.0 / 420.0) > 0.02)
                {
                    throw new InvalidOperationException(
                        "the null-render fallback does not use the standalone aspect");
                }

                // A standalone smaller than the 320x230 box is never upscaled.
                var small = new NoteData
                {
                    Id = "r3-fallback-small",
                    Name = "Small",
                    Color = "#788C5D",
                    PanelWidth = 300,
                    PanelHeight = 200
                };
                prepare.Invoke(ghost,
                    new object[] { null, new Point(-10000, -10000), live, small, null });
                if (Math.Abs(ghost.Width - 300) > 0.5 || Math.Abs(ghost.Height - 200) > 0.5)
                {
                    throw new InvalidOperationException(
                        "a small standalone preview was upscaled to " + ghost.Width + "x" + ghost.Height);
                }
            }
            finally
            {
                ghost.DetachPreview();
                ghost.Close();
            }
        }

        private static Type GhostRendererType()
        {
            var type = typeof(WidgetGroupWindow).Assembly.GetType(
                "Kobold.Helpers.WidgetGhostRenderer", false);
            if (type == null) throw new InvalidOperationException("WidgetGhostRenderer does not exist yet");
            return type;
        }

        private static BitmapSource RenderGhostPreview(WidgetData member)
        {
            var method = GhostRendererType().GetMethod("Render",
                BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public);
            if (method == null) throw new InvalidOperationException("WidgetGhostRenderer.Render not found");
            return method.Invoke(null, new object[] { member }) as BitmapSource;
        }

        private static bool GhostRendererFlag(string name)
        {
            var property = GhostRendererType().GetProperty(name,
                BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public);
            if (property == null) return false;
            object value = property.GetValue(null);
            return value is bool flag && flag;
        }

        private static int GhostRendererInt(string name)
        {
            var property = GhostRendererType().GetProperty(name,
                BindingFlags.Static | BindingFlags.NonPublic | BindingFlags.Public);
            if (property == null) return 0;
            object value = property.GetValue(null);
            return value is int number ? number : 0;
        }

        /// <summary>True when a rendered bitmap carries at least one visible pixel.</summary>
        private static bool HasVisiblePixels(BitmapSource bitmap)
        {
            if (bitmap == null) return false;

            int stride = bitmap.PixelWidth * 4;
            var pixels = new byte[stride * bitmap.PixelHeight];
            bitmap.CopyPixels(pixels, stride, 0);
            for (int i = 3; i < pixels.Length; i += 4)
            {
                if (pixels[i] > 8) return true;
            }
            return false;
        }

        /// <summary>
        /// Distinct visible ARGB values: a blank/flat render has one or two,
        /// while a real calendar/note render carries text, borders and accents.
        /// </summary>
        private static int DistinctVisibleColors(BitmapSource bitmap)
        {
            if (bitmap == null) return 0;

            int stride = bitmap.PixelWidth * 4;
            var pixels = new byte[stride * bitmap.PixelHeight];
            bitmap.CopyPixels(pixels, stride, 0);

            var colors = new HashSet<int>();
            for (int i = 0; i + 3 < pixels.Length; i += 4)
            {
                if (pixels[i + 3] <= 8) continue;
                int color = pixels[i] | (pixels[i + 1] << 8) | (pixels[i + 2] << 16) | (pixels[i + 3] << 24);
                colors.Add(color);
            }
            return colors.Count;
        }

        private static T GhostSeamOrNull<T>(object ghost, string name) where T : class
        {
            var property = ghost.GetType().GetProperty(name,
                BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
            return property == null ? null : property.GetValue(ghost) as T;
        }

        private static double GhostSeamDouble(object ghost, string name, double fallback)
        {
            var property = ghost.GetType().GetProperty(name,
                BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
            if (property == null) return fallback;
            object value = property.GetValue(ghost);
            return value is double number ? number : fallback;
        }

        private static Stretch GhostSeamStretch(object ghost, string name, Stretch fallback)
        {
            var property = ghost.GetType().GetProperty(name,
                BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
            if (property == null) return fallback;
            object value = property.GetValue(ghost);
            return value is Stretch stretch ? stretch : fallback;
        }

        private static MouseButtonEventArgs NewMouseLeftButtonEvent(RoutedEvent routedEvent)
        {
            return new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
            {
                RoutedEvent = routedEvent
            };
        }

        /// <summary>
        /// P1 strip pin: an over-threshold drag shows the 2px, member-coloured,
        /// hit-test-transparent insertion line in the gap, then an end-gap
        /// release raises TabReorderRequested(from, last) and the ordinary
        /// in-window TabDragCompleted(from, false); the line hides again.
        /// </summary>
        private static void TabStripReorderReportsTheEndGapAndShowsTheInsertionLine()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);
                var third = NewExtraNote("p1-note-2", "Third", "#B5654A");
                window.AddMember(third);
                window.UpdateLayout();
                window.SetActive(0);
                window.UpdateLayout();

                var strip = window.TabStrip;
                if (strip.TabButtons.Count != 3)
                    throw new InvalidOperationException("the strip does not carry three tabs");

                var reorders = new List<KeyValuePair<int, int>>();
                strip.TabReorderRequested += (from, to) =>
                    reorders.Add(new KeyValuePair<int, int>(from, to));
                var completions = new List<KeyValuePair<int, bool>>();
                strip.TabDragCompleted += (index, outside) =>
                    completions.Add(new KeyValuePair<int, bool>(index, outside));

                if (!strip.IsReorderEnabled)
                    throw new InvalidOperationException("an unlocked strip starts with reorder disabled");
                if (strip.InsertIndicator == null)
                    throw new InvalidOperationException("the strip exposes no insertion indicator");
                if (strip.InsertIndicator.IsHitTestVisible)
                    throw new InvalidOperationException("the insertion indicator takes hit testing");
                if (strip.IsInsertIndicatorVisible ||
                    strip.InsertIndicator.Visibility != Visibility.Collapsed)
                    throw new InvalidOperationException("the insertion indicator is visible at rest");
                if (Math.Abs(strip.InsertIndicator.Width - 2) > 0.01)
                    throw new InvalidOperationException(
                        "the insertion indicator is " + strip.InsertIndicator.Width + " wide, wanted 2");

                // The gap between tab 0 and tab 1: the pointer sits before
                // tab 1's centre, so the insertion gap is 1.
                double gapX = (TabEdgeInStrip(strip, 0, true) + TabEdgeInStrip(strip, 1, false)) / 2;
                var start = new Point(TabCenterInStrip(strip, 0), 10);
                var drag = new Point(gapX, 10);
                if (strip.GetInsertionIndex(drag) != 1)
                    throw new InvalidOperationException(
                        "the gap point resolves to " + strip.GetInsertionIndex(drag) + ", wanted 1");

                if (!strip.BeginTabDrag(0, start))
                    throw new InvalidOperationException("the strip refused the first tab press");
                if (!strip.UpdateTabDrag(drag))
                    throw new InvalidOperationException("an over-threshold gap move did not start a drag");
                if (!strip.IsInsertIndicatorVisible ||
                    strip.InsertIndicator.Visibility != Visibility.Visible)
                    throw new InvalidOperationException("the insertion indicator did not appear");

                var border = strip.InsertIndicator as Border;
                var brush = border == null ? null : border.Background as SolidColorBrush;
                if (brush == null || brush.Color != Utils.HexToColor("#6A9BCC"))
                    throw new InvalidOperationException("the insertion line does not wear the dragged tab's colour");
                double lineLeft = strip.InsertIndicator.Margin.Left;
                if (lineLeft < TabEdgeInStrip(strip, 0, true) ||
                    lineLeft > TabEdgeInStrip(strip, 1, false))
                    throw new InvalidOperationException("the insertion line is not in the gap between the tabs");

                // Release past the last tab's centre: the end gap (count).
                var end = new Point(TabCenterInStrip(strip, 2) + 40, 10);
                if (strip.GetInsertionIndex(end) != 3)
                    throw new InvalidOperationException(
                        "the end point resolves to " + strip.GetInsertionIndex(end) + ", wanted 3");
                if (!strip.EndTabDrag(end))
                    throw new InvalidOperationException("the end-gap release did not complete the drag");

                if (completions.Count != 1 || completions[0].Key != 0 || completions[0].Value)
                    throw new InvalidOperationException(
                        "the in-window reorder release did not report (0, false)");
                if (reorders.Count != 1 || reorders[0].Key != 0 || reorders[0].Value != 2)
                    throw new InvalidOperationException(
                        "the end-gap release did not request (0, 2): " + DescribePairs(reorders));
                if (strip.IsInsertIndicatorVisible ||
                    strip.InsertIndicator.Visibility != Visibility.Collapsed)
                    throw new InvalidOperationException("the insertion indicator stayed visible after the release");
                if (strip.IsTabDragActive)
                    throw new InvalidOperationException("the strip stayed in a drag after the release");
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// P1 strip pin: a sub-threshold click raises no event and reorders
        /// nothing, and both no-op spellings of the source's own gap
        /// (insertion == from and insertion == from + 1) complete the drag but
        /// raise no TabReorderRequested.
        /// </summary>
        private static void TabStripReorderSameGapAndClickAreNoOps()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);
                var third = NewExtraNote("p1-note-2", "Third", "#B5654A");
                window.AddMember(third);
                window.UpdateLayout();

                var strip = window.TabStrip;
                var reorders = new List<KeyValuePair<int, int>>();
                strip.TabReorderRequested += (from, to) =>
                    reorders.Add(new KeyValuePair<int, int>(from, to));
                var completions = new List<KeyValuePair<int, bool>>();
                strip.TabDragCompleted += (index, outside) =>
                    completions.Add(new KeyValuePair<int, bool>(index, outside));

                // Below threshold: press + small move + release is a click.
                var center = new Point(TabCenterInStrip(strip, 1), 10);
                strip.BeginTabDrag(1, center);
                if (strip.UpdateTabDrag(new Point(center.X + 5, center.Y + 3)))
                    throw new InvalidOperationException("a sub-threshold move started a drag");
                if (strip.IsInsertIndicatorVisible)
                    throw new InvalidOperationException("a sub-threshold move showed the insertion line");
                if (strip.EndTabDrag(new Point(center.X + 5, center.Y + 3)))
                    throw new InvalidOperationException("a sub-threshold release completed a drag");
                if (reorders.Count != 0 || completions.Count != 0)
                    throw new InvalidOperationException("a click reordered or completed a drag");

                // insertion == from: release just left of tab 1's centre.
                strip.BeginTabDrag(1, center);
                strip.UpdateTabDrag(new Point(center.X + 30, center.Y));
                if (strip.GetInsertionIndex(new Point(center.X - 1, center.Y)) != 1)
                    throw new InvalidOperationException("the left-of-centre point is not the source gap");
                strip.EndTabDrag(new Point(center.X - 1, center.Y));
                if (completions.Count != 1 || completions[0].Key != 1 || completions[0].Value)
                    throw new InvalidOperationException("the same-gap release did not report (1, false)");
                if (reorders.Count != 0)
                    throw new InvalidOperationException("insertion == from requested a reorder");

                // insertion == from + 1: release exactly on tab 1's centre.
                strip.BeginTabDrag(1, center);
                strip.UpdateTabDrag(new Point(center.X + 30, center.Y));
                if (strip.GetInsertionIndex(center) != 2)
                    throw new InvalidOperationException("the centre point is not the next gap");
                strip.EndTabDrag(center);
                if (completions.Count != 2 || completions[1].Key != 1 || completions[1].Value)
                    throw new InvalidOperationException("the second same-gap release did not report (1, false)");
                if (reorders.Count != 0)
                    throw new InvalidOperationException("insertion == from + 1 requested a reorder");
                if (strip.IsInsertIndicatorVisible)
                    throw new InvalidOperationException("the insertion line stayed visible");
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// P1 strip pin: a locked group's UpdateUI/RefreshLocalization pushes
        /// IsReorderEnabled = false, so a directly driven in-strip drag shows no
        /// insertion line and raises no reorder. The member order is unchanged.
        /// </summary>
        private static void TabStripReorderIsRefusedWhenLocked()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);
                var third = NewExtraNote("p1-note-2", "Third", "#B5654A");
                window.AddMember(third);
                window.UpdateLayout();

                var strip = window.TabStrip;
                var before = new List<string>();
                foreach (var member in window.Members) before.Add(member == null ? null : member.Id);

                group.IsLocked = true;
                window.UpdateUI();
                window.RefreshLocalization();
                if (strip.IsReorderEnabled)
                    throw new InvalidOperationException("a locked group left reorder enabled");

                var reorders = new List<KeyValuePair<int, int>>();
                strip.TabReorderRequested += (from, to) =>
                    reorders.Add(new KeyValuePair<int, int>(from, to));
                var detaches = new List<string>();
                window.DetachRequested += id => detaches.Add(id);

                var start = new Point(TabCenterInStrip(strip, 0), 10);
                var end = new Point(TabCenterInStrip(strip, 2) + 40, 10);
                strip.BeginTabDrag(0, start);
                strip.UpdateTabDrag(new Point(TabCenterInStrip(strip, 2), 10));
                if (strip.IsInsertIndicatorVisible)
                    throw new InvalidOperationException("a locked group showed the insertion line");
                strip.EndTabDrag(end);

                if (reorders.Count != 0)
                    throw new InvalidOperationException("a locked group requested a reorder");
                if (detaches.Count != 0)
                    throw new InvalidOperationException("an in-window release detached from a locked group");
                if (strip.IsInsertIndicatorVisible)
                    throw new InvalidOperationException("the insertion line stayed visible after a locked release");

                for (int i = 0; i < before.Count; i++)
                {
                    if (!string.Equals(before[i], window.Members[i].Id, StringComparison.Ordinal))
                        throw new InvalidOperationException("a locked group reordered its members");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// P1 manager pin: ReorderGroupMember moves the live member/view/slot
        /// entries of a real three-tab group in place, keeps the same window and
        /// open state, keeps the dragged (first) tab active, renumbers
        /// GroupOrder and writes it to the config. A no-op, an invalid index, a
        /// missing group and a locked group are refused without touching the
        /// order or the size.
        /// </summary>
        private static void ManagerReordersGroupMembersInPlace()
        {
            WidgetManager manager = null;
            TodoData todo;
            NoteData firstNote;
            NoteData secondNote;
            SetUpP0BStandaloneWidgets(out manager, out todo, out firstNote, out secondNote);

            try
            {
                WidgetGroupWindow groupHost = OpenP0BGroup(manager, todo, firstNote);
                IWidgetWindow secondHost = manager.FindHostForWidget(secondNote.Id);
                if (secondHost == null || !manager.MergeWidgets(secondHost, groupHost))
                    throw new InvalidOperationException("the third standalone did not merge into the group");

                groupHost.SetActive(0);
                groupHost.UpdateLayout();
                if (groupHost.Members.Count != 3 ||
                    groupHost.Views.Count != 3 ||
                    groupHost.ContentSlots.Count != 3 ||
                    groupHost.TabStrip.TabButtons.Count != 3)
                    throw new InvalidOperationException("the visual does not carry three tabs");
                if (groupHost.ActiveMemberId != todo.Id)
                    throw new InvalidOperationException("the first tab is not active before the reorder");

                string groupId = groupHost.WidgetId;
                var viewsBefore = new List<IWidgetContentView>(groupHost.Views);
                var slotsBefore = new List<ContentControl>(groupHost.ContentSlots);
                var visibilityBefore = new List<Visibility>();
                foreach (var slot in groupHost.ContentSlots) visibilityBefore.Add(slot.Visibility);                double widthBefore = groupHost.Width;
                double heightBefore = groupHost.Height;
                bool openBefore = groupHost.IsPanelOpen;
                bool closed = false;
                groupHost.Closed += (s, e) => closed = true;

                if (!manager.ReorderGroupMember(groupId, 0, 2))
                    throw new InvalidOperationException("the first-to-last reorder was refused");

                var same = manager.FindHostForWidget(todo.Id) as WidgetGroupWindow;
                if (!ReferenceEquals(same, groupHost) || closed || !same.IsVisible)
                    throw new InvalidOperationException("the reorder closed or recreated the group window");
                if (same.IsPanelOpen != openBefore)
                    throw new InvalidOperationException("the reorder changed the open state");
                if (same.Members.Count != 3 ||
                    !ReferenceEquals(same.Members[0], firstNote) ||
                    !ReferenceEquals(same.Members[1], secondNote) ||
                    !ReferenceEquals(same.Members[2], todo))
                    throw new InvalidOperationException("the member order is not note-1/note-2/todo");
                for (int i = 0; i < same.Members.Count; i++)
                {
                    if (same.Members[i].GroupOrder != i)
                        throw new InvalidOperationException(
                            "GroupOrder at " + i + " is " + same.Members[i].GroupOrder);
                }
                if (same.ActiveMemberId != todo.Id || same.ActiveIndex != 2)
                    throw new InvalidOperationException(
                        "the dragged member did not stay active: " + same.ActiveMemberId +
                        " at " + same.ActiveIndex);
                if (same.Group.ActiveWidgetId != todo.Id)
                    throw new InvalidOperationException("Group.ActiveWidgetId did not follow the dragged tab");

                if (!ReferenceEquals(same.Views[2], viewsBefore[0]) ||
                    !ReferenceEquals(same.Views[0], viewsBefore[1]) ||
                    !ReferenceEquals(same.Views[1], viewsBefore[2]))
                    throw new InvalidOperationException("the reorder recreated or misplaced a view");
                if (!ReferenceEquals(same.ContentSlots[2].Content, slotsBefore[0].Content) ||
                    !ReferenceEquals(same.ContentSlots[0].Content, slotsBefore[1].Content) ||
                    !ReferenceEquals(same.ContentSlots[1].Content, slotsBefore[2].Content))
                    throw new InvalidOperationException("the reorder recreated or misplaced a slot");
                for (int i = 0; i < slotsBefore.Count; i++)
                {
                    if (slotsBefore[i].Visibility != visibilityBefore[i])
                        throw new InvalidOperationException(
                            "the reorder toggled the slot visibility at " + i);
                }
                int visibleSlots = 0;
                foreach (var slot in same.ContentSlots)
                {
                    if (slot.Visibility == Visibility.Visible) visibleSlots++;
                }
                if (visibleSlots != 1 || same.ContentSlots[2].Visibility != Visibility.Visible)
                    throw new InvalidOperationException(
                        "the dragged tab's slot is not the single visible slot after the reorder");
                if (Math.Abs(same.Width - widthBefore) > 0.01 || Math.Abs(same.Height - heightBefore) > 0.01)
                    throw new InvalidOperationException("the reorder resized the group");

                if (ConfigWidget(manager, todo.Id).GroupOrder != 2 ||
                    ConfigWidget(manager, firstNote.Id).GroupOrder != 0 ||
                    ConfigWidget(manager, secondNote.Id).GroupOrder != 1)
                    throw new InvalidOperationException("the reorder did not persist the config GroupOrder");
                if (manager.Config.Groups == null ||
                    !manager.Config.Groups.Contains(same.Group))
                    throw new InvalidOperationException("the reorder lost the group state");

                if (manager.ReorderGroupMember(groupId, 2, 2))
                    throw new InvalidOperationException("a no-op reorder was accepted");
                if (manager.ReorderGroupMember(groupId, -1, 1) ||
                    manager.ReorderGroupMember(groupId, 0, 3) ||
                    manager.ReorderGroupMember(groupId, 0, -1))
                    throw new InvalidOperationException("an invalid reorder index was accepted");
                if (manager.ReorderGroupMember("p1-missing-group", 0, 1))
                    throw new InvalidOperationException("a missing group accepted a reorder");

                groupHost.Group.IsLocked = true;
                if (manager.ReorderGroupMember(groupId, 2, 0))
                    throw new InvalidOperationException("a locked group accepted a reorder");
                groupHost.Group.IsLocked = false;
                if (!ReferenceEquals(same.Members[0], firstNote) ||
                    !ReferenceEquals(same.Members[2], todo))
                    throw new InvalidOperationException("a refused reorder changed the member order");
            }
            finally
            {
                CleanUpP0B(manager);
            }
        }

        /// <summary>
        /// R4: every tab press snapshots the ordered member ids as a deep copy.
        /// Adding a member after the press changes the live strip but never the
        /// snapshot; a fresh press snapshots the new membership. A click and a
        /// cancel raise no reorder, and an outside detach drag keeps the
        /// press-time snapshot.
        /// </summary>
        private static void TabDragSnapshotsTheMembershipAtPress()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);
                var third = NewExtraNote("r4-note-2", "Third", "#B5654A");
                window.AddMember(third);
                window.UpdateLayout();

                if (Math.Abs(WidgetGroupTabStrip.DetachEdgeMargin - 8) > 0.001)
                {
                    throw new InvalidOperationException(
                        "the detach edge margin is " + WidgetGroupTabStrip.DetachEdgeMargin + ", wanted 8");
                }

                var strip = window.TabStrip;
                var reorders = new List<KeyValuePair<int, int>>();
                strip.TabReorderRequested += (from, to) =>
                    reorders.Add(new KeyValuePair<int, int>(from, to));

                strip.BeginTabDrag(0, new Point(10, 10));
                var snapshot = new List<string>(strip.DragMemberSnapshot);
                if (!SameIds(snapshot, new[] { todo.Id, note.Id, third.Id }))
                {
                    throw new InvalidOperationException(
                        "the press snapshot is " + DescribeIds(snapshot) +
                        ", wanted todo-1/note-1/r4-note-2");
                }

                // Membership changes after the press: the deep copy stays put.
                var fourth = NewExtraNote("r4-note-3", "Fourth", "#4A7BB5");
                window.AddMember(fourth);
                window.UpdateLayout();
                snapshot = new List<string>(strip.DragMemberSnapshot);
                if (!SameIds(snapshot, new[] { todo.Id, note.Id, third.Id }))
                {
                    throw new InvalidOperationException(
                        "the snapshot followed a membership change to " + DescribeIds(snapshot));
                }

                // A sub-threshold press/release stays a click.
                strip.EndTabDrag(new Point(10, 10));
                if (reorders.Count != 0)
                {
                    throw new InvalidOperationException("a click on a snapshotting strip reordered");
                }

                // A fresh press snapshots the live membership again.
                strip.BeginTabDrag(0, new Point(10, 10));
                snapshot = new List<string>(strip.DragMemberSnapshot);
                if (!SameIds(snapshot, new[] { todo.Id, note.Id, third.Id, fourth.Id }))
                {
                    throw new InvalidOperationException(
                        "the second press snapshot is " + DescribeIds(snapshot));
                }
                strip.CancelTabDrag();
                if (reorders.Count != 0)
                {
                    throw new InvalidOperationException("a cancelled drag reordered");
                }

                // An outside detach drag carries the same press-time snapshot.
                strip.BeginTabDrag(0, new Point(10, 10));
                strip.UpdateTabDrag(new Point(100000, 100000));
                snapshot = new List<string>(strip.DragMemberSnapshot);
                if (!SameIds(snapshot, new[] { todo.Id, note.Id, third.Id, fourth.Id }))
                {
                    throw new InvalidOperationException("an outside drag lost its press snapshot");
                }
                strip.EndTabDrag(new Point(100000, 100000));
                if (reorders.Count != 0)
                {
                    throw new InvalidOperationException("an outside detach drag requested a reorder");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// R4 manager pin: the group window hands the press-time snapshot to
        /// <see cref="WidgetManager.ReorderGroupMember(string,int,int,IReadOnlyList{string})"/>.
        /// A current snapshot reorders normally; a same-count snapshot in the
        /// wrong order and a snapshot whose membership changed mid-drag are
        /// both no-ops that leave members, GroupOrder and config unchanged.
        /// </summary>
        private static void StaleTabDragSnapshotRefusesTheReorder()
        {
            WidgetManager manager = null;
            TodoData todo;
            NoteData firstNote;
            NoteData secondNote;
            SetUpP0BStandaloneWidgets(out manager, out todo, out firstNote, out secondNote);

            try
            {
                WidgetGroupWindow groupHost = OpenP0BGroup(manager, todo, firstNote);
                IWidgetWindow secondHost = manager.FindHostForWidget(secondNote.Id);
                if (secondHost == null || !manager.MergeWidgets(secondHost, groupHost))
                {
                    throw new InvalidOperationException("the third standalone did not merge into the group");
                }
                groupHost.SetActive(0);
                groupHost.UpdateLayout();

                WidgetGroupTabStrip strip = groupHost.TabStrip;
                string groupId = groupHost.WidgetId;
                if (!SameIds(MemberIds(groupHost), new[] { todo.Id, firstNote.Id, secondNote.Id }))
                {
                    throw new InvalidOperationException(
                        "the group does not start todo/note-1/note-2: " + DescribeIds(MemberIds(groupHost)));
                }

                Point start = new Point(TabCenterInStrip(strip, 0), 10);
                Point endGap = new Point(TabCenterInStrip(strip, strip.TabButtons.Count - 1) + 40, 10);

                // A current snapshot still reorders normally.
                strip.BeginTabDrag(0, start);
                var current = new List<string>(strip.DragMemberSnapshot);
                if (!SameIds(current, new[] { todo.Id, firstNote.Id, secondNote.Id }))
                {
                    throw new InvalidOperationException(
                        "the current drag snapshot is " + DescribeIds(current));
                }
                strip.UpdateTabDrag(endGap);
                strip.EndTabDrag(endGap);

                if (!ReferenceEquals(groupHost.Members[0], firstNote) ||
                    !ReferenceEquals(groupHost.Members[1], secondNote) ||
                    !ReferenceEquals(groupHost.Members[2], todo))
                {
                    throw new InvalidOperationException(
                        "a current snapshot did not reorder to note-1/note-2/todo");
                }
                if (firstNote.GroupOrder != 0 || secondNote.GroupOrder != 1 || todo.GroupOrder != 2)
                {
                    throw new InvalidOperationException("the current-snapshot reorder did not renumber GroupOrder");
                }
                if (ConfigWidget(manager, todo.Id).GroupOrder != 2)
                {
                    throw new InvalidOperationException("the current-snapshot reorder did not persist GroupOrder");
                }

                // Same count, wrong order: refused before any index/lock work.
                var wrongOrder = new[] { secondNote.Id, firstNote.Id, todo.Id };
                if (manager.ReorderGroupMember(groupId, 0, 1, wrongOrder))
                {
                    throw new InvalidOperationException("a wrong-order snapshot was accepted");
                }
                if (!SameIds(MemberIds(groupHost), new[] { firstNote.Id, secondNote.Id, todo.Id }) ||
                    firstNote.GroupOrder != 0 || secondNote.GroupOrder != 1 || todo.GroupOrder != 2)
                {
                    throw new InvalidOperationException("a wrong-order snapshot changed the member order");
                }

                // Membership changed after the press: the stale snapshot is a no-op.
                start = new Point(TabCenterInStrip(strip, 0), 10);
                strip.BeginTabDrag(0, start);
                var stale = new List<string>(strip.DragMemberSnapshot);
                var intruder = new NoteData
                {
                    Id = "r4-stale-note",
                    Name = "Intruder",
                    Color = "#4A7BB5"
                };
                groupHost.AddMember(intruder);
                groupHost.UpdateLayout();
                // Member names make the tabs wider than the kind labels did, so
                // the "past the last tab centre" probe can fall outside this
                // small group. Clamp it inside the host: this pin exercises the
                // stale snapshot refusing the reorder, not the detach gesture.
                double endX = TabCenterInStrip(strip, strip.TabButtons.Count - 1) + 40;
                double hostRight = Math.Max(0, groupHost.ActualWidth - 4);
                endGap = new Point(Math.Min(endX, hostRight), 10);
                strip.UpdateTabDrag(endGap);
                strip.EndTabDrag(endGap);

                if (!SameIds(stale, new[] { firstNote.Id, secondNote.Id, todo.Id }))
                {
                    throw new InvalidOperationException(
                        "the stale snapshot changed to " + DescribeIds(stale));
                }
                if (groupHost.Members.Count != 4 ||
                    !ReferenceEquals(groupHost.Members[0], firstNote) ||
                    !ReferenceEquals(groupHost.Members[1], secondNote) ||
                    !ReferenceEquals(groupHost.Members[2], todo) ||
                    !ReferenceEquals(groupHost.Members[3], intruder))
                {
                    throw new InvalidOperationException(
                        "a stale snapshot reordered the members: " + DescribeIds(MemberIds(groupHost)));
                }
                if (firstNote.GroupOrder != 0 || secondNote.GroupOrder != 1 || todo.GroupOrder != 2)
                {
                    throw new InvalidOperationException("a stale snapshot renumbered GroupOrder");
                }
                if (ConfigWidget(manager, firstNote.Id).GroupOrder != 0 ||
                    ConfigWidget(manager, secondNote.Id).GroupOrder != 1 ||
                    ConfigWidget(manager, todo.Id).GroupOrder != 2)
                {
                    throw new InvalidOperationException("a stale snapshot changed the config GroupOrder");
                }

                if (manager.ReorderGroupMember(groupId, 0, 2, stale))
                {
                    throw new InvalidOperationException("the manager accepted a stale snapshot directly");
                }
                if (!SameIds(MemberIds(groupHost), new[] { firstNote.Id, secondNote.Id, todo.Id, intruder.Id }))
                {
                    throw new InvalidOperationException("the direct stale reorder changed the member order");
                }
            }
            finally
            {
                CleanUpP0B(manager);
            }
        }

        /// <summary>
        /// R4: the 8 DIP detach edge band is not outside. A 4 DIP outside
        /// release neither detaches nor reorders and shows no ghost, while a
        /// 20 DIP outside release still detaches.
        /// </summary>
        private static void TabDetachEdgeBandDoesNotDetachOrReorder()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);
                var third = NewExtraNote("r4-band-note", "Third", "#B5654A");
                window.AddMember(third);
                window.UpdateLayout();
                window.SetActive(0);
                window.UpdateLayout();

                WidgetGroupTabStrip strip = window.TabStrip;
                Point originInWindow = strip.TranslatePoint(new Point(0, 0), window);
                Point bandPoint = window.TranslatePoint(
                    new Point(originInWindow.X - 4, originInWindow.Y + 10), strip);
                Point beyondPoint = window.TranslatePoint(
                    new Point(originInWindow.X - 20, originInWindow.Y + 10), strip);

                if (!strip.IsOutsideHost(bandPoint))
                {
                    throw new InvalidOperationException("the 4 DIP point is not physically outside the window");
                }
                if (strip.IsOutsideHost(bandPoint, WidgetGroupTabStrip.DetachEdgeMargin))
                {
                    throw new InvalidOperationException("a 4 DIP outside point counts as outside the detach margin");
                }
                if (!strip.IsOutsideHost(beyondPoint, WidgetGroupTabStrip.DetachEdgeMargin))
                {
                    throw new InvalidOperationException("a 20 DIP outside point is not outside the detach margin");
                }

                var completions = new List<KeyValuePair<int, bool>>();
                strip.TabDragCompleted += (index, outside) =>
                    completions.Add(new KeyValuePair<int, bool>(index, outside));
                var reorders = new List<KeyValuePair<int, int>>();
                strip.TabReorderRequested += (from, to) =>
                    reorders.Add(new KeyValuePair<int, int>(from, to));
                var detaches = new List<string>();
                window.DetachRequested += id => detaches.Add(id);

                var before = MemberIds(window);
                strip.BeginTabDrag(0, new Point(TabCenterInStrip(strip, 0), 10));
                strip.UpdateTabDrag(bandPoint);
                if (window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("a 4 DIP outside move showed the detach ghost");
                }
                strip.EndTabDrag(bandPoint);

                if (detaches.Count != 0)
                {
                    throw new InvalidOperationException("a 4 DIP outside release detached a tab");
                }
                if (reorders.Count != 0)
                {
                    throw new InvalidOperationException("a 4 DIP outside release requested a reorder");
                }
                if (completions.Count != 1 || completions[0].Key != 0 || completions[0].Value)
                {
                    throw new InvalidOperationException(
                        "a 4 DIP outside release was not reported as an in-group drag");
                }
                if (!SameIds(MemberIds(window), before))
                {
                    throw new InvalidOperationException("a 4 DIP outside release reordered the members");
                }
                if (window.IsDragGhostVisible || window.DragGhost != null)
                {
                    throw new InvalidOperationException("a 4 DIP outside release left the ghost alive");
                }

                // Beyond the band: the ordinary detach still runs.
                detaches.Clear();
                completions.Clear();
                strip.BeginTabDrag(0, new Point(TabCenterInStrip(strip, 0), 10));
                strip.UpdateTabDrag(beyondPoint);
                if (!window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("a 20 DIP outside drag showed no detach ghost");
                }
                strip.EndTabDrag(beyondPoint);
                if (detaches.Count != 1 || detaches[0] != todo.Id)
                {
                    throw new InvalidOperationException("a 20 DIP outside release did not detach the tab");
                }
                if (completions.Count != 1 || completions[0].Key != 0 || !completions[0].Value)
                {
                    throw new InvalidOperationException("a 20 DIP outside release was not reported as outside");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// R4: Escape during an outside tab drag cancels the gesture through
        /// the window's key route, marks the key handled, closes the ghost and
        /// never detaches; a later release is inert. A capture-loss cancel is
        /// equally detach-free.
        /// </summary>
        private static void EscapeCancelsTheTabDragAndHidesTheGhost()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);
                window.Left = -10000;
                window.Top = -10000;
                window.UpdateLayout();

                WidgetGroupTabStrip strip = window.TabStrip;
                var completions = new List<KeyValuePair<int, bool>>();
                strip.TabDragCompleted += (index, outside) =>
                    completions.Add(new KeyValuePair<int, bool>(index, outside));
                var detaches = new List<string>();
                window.DetachRequested += id => detaches.Add(id);

                var far = new Point(100000, 100000);
                strip.BeginTabDrag(0, new Point(TabCenterInStrip(strip, 0), 10));
                strip.UpdateTabDrag(far);
                if (!window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("the Esc scenario shows no detach ghost");
                }
                if (window.CancelTabDragFromEscape(Key.A))
                {
                    throw new InvalidOperationException("a non-Escape key cancelled the tab drag");
                }
                if (!strip.IsTabDragActive || !window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("a non-Escape key disturbed the tab drag");
                }

                // The seam is what Window_PreviewKeyDown calls before routing
                // to the active view; it cancels without an OS key event.
                if (!window.CancelTabDragFromEscape(Key.Escape))
                {
                    throw new InvalidOperationException("the Escape seam did not cancel the tab drag");
                }
                if (strip.IsTabDragActive)
                {
                    throw new InvalidOperationException("Esc left the tab drag active");
                }
                if (window.IsDragGhostVisible || window.DragGhost != null)
                {
                    throw new InvalidOperationException("Esc left the detach ghost alive");
                }
                if (detaches.Count != 0)
                {
                    throw new InvalidOperationException("Esc detached a tab");
                }
                if (completions.Count != 0)
                {
                    throw new InvalidOperationException("Esc completed a drag");
                }
                if (strip.EndTabDrag(far))
                {
                    throw new InvalidOperationException("a release after Esc completed the cancelled drag");
                }
                if (detaches.Count != 0)
                {
                    throw new InvalidOperationException("a release after Esc detached a tab");
                }

                // Capture loss / cancel: the drag dies without a detach.
                strip.BeginTabDrag(1, new Point(TabCenterInStrip(strip, 1), 10));
                strip.UpdateTabDrag(far);
                if (!window.IsDragGhostVisible)
                {
                    throw new InvalidOperationException("the capture-loss scenario shows no ghost");
                }
                strip.CancelTabDrag();
                if (window.IsDragGhostVisible || window.DragGhost != null)
                {
                    throw new InvalidOperationException("the capture-loss cancel left the ghost alive");
                }
                if (strip.EndTabDrag(far) || detaches.Count != 0 || completions.Count != 0)
                {
                    throw new InvalidOperationException("a capture-loss cancel still detached or completed");
                }
            }
            finally
            {
                Mouse.Capture(null);
                Mouse.OverrideCursor = null;
                window.Close();
            }
        }

        /// <summary>The centre of one tab in strip coordinates (the tab must be laid out).</summary>
        private static double TabCenterInStrip(WidgetGroupTabStrip strip, int index)
        {
            Grid tab = strip.TabButtons[index];
            return tab.TranslatePoint(new Point(Math.Max(0, tab.ActualWidth) / 2, 0), strip).X;
        }

        /// <summary>The left or right edge of one tab in strip coordinates.</summary>
        private static double TabEdgeInStrip(WidgetGroupTabStrip strip, int index, bool right)
        {
            Grid tab = strip.TabButtons[index];
            double x = right ? Math.Max(0, tab.ActualWidth) : 0;
            return tab.TranslatePoint(new Point(x, 0), strip).X;
        }

        private static string DescribePairs(List<KeyValuePair<int, int>> pairs)
        {
            var text = new StringBuilder();
            foreach (var pair in pairs)
            {
                if (text.Length > 0) text.Append(", ");
                text.Append("(").Append(pair.Key).Append(", ").Append(pair.Value).Append(")");
            }
            return text.ToString();
        }

        /// <summary>The member ids of a group window, in tab order.</summary>
        private static List<string> MemberIds(WidgetGroupWindow window)
        {
            var ids = new List<string>();
            foreach (var member in window.Members) ids.Add(member == null ? null : member.Id);
            return ids;
        }

        private static bool SameIds(IReadOnlyList<string> actual, IReadOnlyList<string> expected)
        {
            if (actual == null || expected == null || actual.Count != expected.Count) return false;
            for (int i = 0; i < actual.Count; i++)
            {
                if (!string.Equals(actual[i], expected[i], StringComparison.Ordinal)) return false;
            }
            return true;
        }

        private static string DescribeIds(IReadOnlyList<string> ids)
        {
            if (ids == null) return "<null>";
            var text = new StringBuilder();
            foreach (var id in ids)
            {
                if (text.Length > 0) text.Append("/");
                text.Append(id ?? "<null>");
            }
            return text.ToString();
        }

        private static WidgetData ConfigWidget(WidgetManager manager, string id)
        {
            foreach (var widget in manager.Config.Widgets)
            {
                if (widget != null && string.Equals(widget.Id, id, StringComparison.Ordinal)) return widget;
            }
            throw new InvalidOperationException("the config lost the widget " + id);
        }

        /// <summary>
        /// T6: the real group window is rejected as a merge source while an
        /// unlocked group stays a valid target and a locked one is refused.
        /// <see cref="GroupDragPolicy"/>'s pure pins live in WidgetGroupsCheck.
        /// </summary>
        private static void GroupDragPolicyRejectsARealGroupSource()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            var standalone = new NoteWidget(new NoteData { Id = "t6-standalone", Name = "Solo", Color = "#788C5D" });
            try
            {
                if (GroupDragPolicy.CanMerge(window, standalone))
                    throw new InvalidOperationException("the real group window is accepted as a merge source");
                if (!GroupDragPolicy.CanMerge(standalone, window))
                    throw new InvalidOperationException("an unlocked group was refused as a merge target");

                group.IsLocked = true;
                if (GroupDragPolicy.CanMerge(standalone, window))
                    throw new InvalidOperationException("a locked group was accepted as a merge target");
            }
            finally
            {
                standalone.Close();
                window.Close();
            }
        }

        /// <summary>
        /// T6 hit-test pin (the geometry part of the pure policy; it needs
        /// WindowsBase, which the no-WPF WidgetGroupsCheck project does not
        /// reference): the source is skipped, the first supplied screen rect
        /// containing the cursor wins, and null/invalid inputs are safe.
        /// </summary>
        private static void GroupDragPolicyFindsTheDropTarget()
        {
            ThemeManager.Initialize("dark");

            var source = new TodoWidget(new TodoData { Id = "ft-source", Name = "S", Color = "#6A9BCC" });
            var first = new NoteWidget(new NoteData { Id = "ft-first", Name = "F", Color = "#788C5D" });
            var second = new NoteWidget(new NoteData { Id = "ft-second", Name = "G", Color = "#B5654A" });
            var third = new NoteWidget(new NoteData { Id = "ft-third", Name = "H", Color = "#4A7BB5" });
            try
            {
                var rects = new Dictionary<IWidgetWindow, Rect>
                {
                    { first, new Rect(0, 0, 100, 80) },
                    { second, new Rect(200, 120, 90, 70) },
                    { third, new Rect(400, 300, 60, 60) }
                };
                Func<IWidgetWindow, Rect> bounds = window =>
                {
                    Rect rect;
                    return rects.TryGetValue(window, out rect) ? rect : Rect.Empty;
                };
                var candidates = new IWidgetWindow[] { source, first, second, third, null };

                if (!ReferenceEquals(GroupDragPolicy.FindTarget(new Point(10, 10), source, candidates, bounds), first))
                    throw new InvalidOperationException("the rect containing the cursor did not win");
                if (GroupDragPolicy.FindTarget(new Point(10, 10), first, candidates, bounds) != null)
                    throw new InvalidOperationException("the source targeted itself");
                if (!ReferenceEquals(GroupDragPolicy.FindTarget(new Point(250, 140), source, candidates, bounds), second))
                    throw new InvalidOperationException("a later candidate's rect was not found");
                if (GroupDragPolicy.FindTarget(new Point(900, 900), source, candidates, bounds) != null)
                    throw new InvalidOperationException("a point outside every rect found a target");

                if (GroupDragPolicy.FindTarget(new Point(10, 10), source, new IWidgetWindow[] { null }, bounds) != null)
                    throw new InvalidOperationException("a null candidate became a target");
                if (GroupDragPolicy.FindTarget(new Point(10, 10), source, candidates, window => Rect.Empty) != null)
                    throw new InvalidOperationException("an empty rect became a target");
                if (GroupDragPolicy.FindTarget(new Point(10, 10), source, null, bounds) != null
                    || GroupDragPolicy.FindTarget(new Point(10, 10), source, candidates, null) != null)
                    throw new InvalidOperationException("a null candidate list/bounds was not safe");
            }
            finally
            {
                source.Close();
                first.Close();
                second.Close();
                third.Close();
            }
        }

        /// <summary>
        /// T6 live hint: while the header drag is over an eligible panel it
        /// wears the accent border, moving away restores it, an ineligible
        /// candidate (locked widget, locked group, Folder) never hints, a
        /// move within the same target does not repaint it again, and the
        /// release clears the hint. The windows are shown offscreen (no
        /// activation); the candidate list is the check seam, so no host has
        /// to be registered with the singleton.
        /// </summary>
        private static void MergeHintFollowsTheHoveredTargetDuringTheDrag()
        {
            ThemeManager.Initialize("dark");

            var source = new TodoWidget(new TodoData { Id = "hint-source", Name = "S", Color = "#6A9BCC" });
            var note = new NoteWidget(new NoteData { Id = "hint-note", Name = "N", Color = "#788C5D" });
            var locked = new NoteWidget(new NoteData { Id = "hint-locked", Name = "L", Color = "#B5654A" });
            var folder = new FolderWidget(new FolderData { Id = "hint-folder", Name = "F", Color = "#4A7BB5" });
            WidgetGroup group;
            TodoData groupTodo;
            NoteData groupNote;
            var groupWindow = NewGroupWindow(out group, out groupTodo, out groupNote);

            try
            {
                EnsureRealDpi(source);
                // Windows clamps window coordinates near +/-32767 *physical*
                // pixels, so the offscreen DIP positions must scale with the
                // monitor DPI; 900 DIP apart still separates every panel size.
                const double spacing = 900;
                double start = -(spacing * 4) - 200;
                ShowOffscreenWindow(note, start);
                ShowOffscreenWindow(locked, start + spacing);
                ShowOffscreenWindow(folder, start + spacing * 2);
                ShowOffscreenWindow(groupWindow, start + spacing * 3);
                locked.Data.IsLocked = true;

                source.MergeCandidatesOverride = new IWidgetWindow[]
                {
                    note, locked, folder, groupWindow
                };

                MethodInfo started = PrivateBaseMethod("OnHeaderDragStarted");
                MethodInfo moved = PrivateBaseMethod("OnHeaderDragMoved");
                MethodInfo ended = PrivateBaseMethod("OnHeaderDragEnded");

                Point noteCenter = ScreenCenterOf(note);
                Point lockedCenter = ScreenCenterOf(locked);
                Point folderCenter = ScreenCenterOf(folder);
                Point groupCenter = ScreenCenterOf(groupWindow);
                if (noteCenter == lockedCenter || noteCenter == folderCenter
                    || lockedCenter == folderCenter || folderCenter == groupCenter)
                {
                    throw new InvalidOperationException(
                        "the offscreen check windows overlap: " + noteCenter + " / " + lockedCenter
                        + " / " + folderCenter + " / " + groupCenter);
                }

                Color noteBase = ShellBorderColor(note);
                Color lockedBase = ShellBorderColor(locked);
                Color folderBase = ShellBorderColor(folder);
                Color groupBase = ShellBorderColor(groupWindow);

                started.Invoke(source, new object[] { new Point(noteCenter.X - 3000, noteCenter.Y) });
                if (CachedMergePreviewOf(source) != null || MergePreviewWasRendered(source))
                    throw new InvalidOperationException(
                        "the drag start kept a cached merge preview");
                moved.Invoke(source, new object[] { noteCenter });
                if (ShellBorderColor(note) == noteBase)
                    throw new InvalidOperationException("the hovered note did not show the merge hint");
                AssertMergePreviewShown(note, "the hovered note");
                ImageSource cachedPreview = CachedMergePreviewOf(source);
                if (cachedPreview == null)
                    throw new InvalidOperationException(
                        "the drag did not pre-render the dragged component");
                if (!ReferenceEquals(MergePreviewImageOf(note.PanelChrome).Source, cachedPreview))
                    throw new InvalidOperationException(
                        "the target did not paint the drag's cached preview");

                // The same-target move must leave the painted border alone: a
                // sentinel survives unless the hint re-applies the theme. The
                // per-drag preview must also survive: only start/end reset it.
                var sentinel = new SolidColorBrush(Colors.Magenta);
                sentinel.Freeze();
                note.PanelChrome.Shell.BorderBrush = sentinel;
                moved.Invoke(source, new object[] { new Point(noteCenter.X + 2, noteCenter.Y + 2) });
                if (!ReferenceEquals(note.PanelChrome.Shell.BorderBrush, sentinel))
                    throw new InvalidOperationException("a same-target move repainted the hint again");
                AssertMergePreviewShown(note, "the same-target move");
                if (!ReferenceEquals(CachedMergePreviewOf(source), cachedPreview))
                    throw new InvalidOperationException(
                        "a same-target move dropped the cached merge preview");

                moved.Invoke(source, new object[] { lockedCenter });
                if (ShellBorderColor(note) != noteBase)
                    throw new InvalidOperationException("leaving the note did not restore its border");
                if (ShellBorderColor(locked) != lockedBase)
                    throw new InvalidOperationException("a locked widget showed the merge hint");
                AssertMergePreviewCleared(note, "leaving the note for a locked target");
                AssertMergePreviewCleared(locked, "the locked target");

                moved.Invoke(source, new object[] { folderCenter });
                if (ShellBorderColor(folder) == folderBase)
                    throw new InvalidOperationException("an unlocked Folder target did not show the merge hint");
                if (ShellBorderColor(note) != noteBase)
                    throw new InvalidOperationException("leaving the note for the folder did not restore the note border");
                AssertMergePreviewShown(folder, "the hovered folder");
                AssertMergePreviewCleared(note, "leaving the note for the folder");

                moved.Invoke(source, new object[] { groupCenter });
                if (ShellBorderColor(groupWindow) == groupBase)
                    throw new InvalidOperationException("an unlocked group did not show the merge hint");
                AssertMergePreviewShown(groupWindow, "the hovered group");
                AssertMergePreviewCleared(folder, "leaving the folder for the group");

                group.IsLocked = true;
                moved.Invoke(source, new object[] { new Point(groupCenter.X + 2, groupCenter.Y) });
                if (ShellBorderColor(groupWindow) != groupBase)
                    throw new InvalidOperationException("a locked group kept the merge hint");
                AssertMergePreviewCleared(groupWindow, "the locked group");
                group.IsLocked = false;

                moved.Invoke(source, new object[] { noteCenter });
                if (ShellBorderColor(note) == noteBase)
                    throw new InvalidOperationException("the note hint did not come back");
                AssertMergePreviewShown(note, "the returning note");
                AssertMergePreviewCleared(groupWindow, "leaving the group for the note");

                ended.Invoke(source, new object[] { noteCenter });
                if (ShellBorderColor(note) != noteBase)
                    throw new InvalidOperationException("the release left the merge hint painted");
                AssertMergePreviewCleared(note, "the release");
                if (CachedMergePreviewOf(source) != null || MergePreviewWasRendered(source))
                    throw new InvalidOperationException(
                        "the drag end kept a cached merge preview");
            }
            finally
            {
                try { source.MergeCandidatesOverride = null; } catch { }
                source.Close();
                note.Close();
                locked.Close();
                folder.Close();
                groupWindow.Close();
            }
        }

        /// <summary>
        /// P2-5: a merge target paints the dragged component's pre-rendered
        /// bitmap inside the chrome preview layer with the localized drop
        /// label; clearing the hint collapses the layer and drops the image.
        /// </summary>
        private static void MergePreviewShowsTheDraggedComponent()
        {
            var target = new TodoWidget(new TodoData
            {
                Id = "preview-target",
                Name = "Preview target",
                Color = "#6A9BCC"
            });
            try
            {
                var preview = NewMergePreviewBitmap();
                target.SetMergeHint(true, preview);

                WidgetChrome chrome = ChromeOf(target);
                Grid layer = MergePreviewLayerOf(chrome);
                if (layer.Visibility != Visibility.Visible)
                    throw new InvalidOperationException("the merge preview layer is hidden");
                Image image = MergePreviewImageOf(chrome);
                if (!ReferenceEquals(image.Source, preview))
                    throw new InvalidOperationException("the merge preview image is not the rendered source");
                TextBlock label = MergePreviewLabelOf(chrome);
                if (label.Text != Localization.Get("UI_MergeDropHint"))
                    throw new InvalidOperationException(
                        "the merge preview label is '" + label.Text + "'");

                target.SetMergeHint(false);
                if (layer.Visibility != Visibility.Collapsed)
                    throw new InvalidOperationException("the merge preview layer stayed visible");
                if (image.Source != null)
                    throw new InvalidOperationException("the hidden merge preview kept its image");
            }
            finally
            {
                target.Close();
            }
        }

        /// <summary>
        /// P2-5: without a bitmap the hint is the existing accent border only
        /// (no empty preview layer); a bitmap that arrives after the border
        /// still paints, because the guard compares the preview too.
        /// </summary>
        private static void MergePreviewWithoutImageKeepsTheBorderOnly()
        {
            var target = new TodoWidget(new TodoData
            {
                Id = "preview-border-only",
                Name = "Border only",
                Color = "#6A9BCC"
            });
            try
            {
                Color baseline = ShellBorderColor(target);
                target.SetMergeHint(true);

                WidgetChrome chrome = ChromeOf(target);
                Grid layer = MergePreviewLayerOf(chrome);
                if (layer.Visibility != Visibility.Collapsed)
                    throw new InvalidOperationException("an image-less hint painted an empty preview layer");
                if (ShellBorderColor(target) == baseline)
                    throw new InvalidOperationException("the image-less hint did not paint the accent border");

                var preview = NewMergePreviewBitmap();
                target.SetMergeHint(true, preview);
                if (layer.Visibility != Visibility.Visible)
                    throw new InvalidOperationException("a late preview image did not paint");
                if (!ReferenceEquals(MergePreviewImageOf(chrome).Source, preview))
                    throw new InvalidOperationException("the late preview image is not the rendered source");

                target.SetMergeHint(false);
                if (layer.Visibility != Visibility.Collapsed)
                    throw new InvalidOperationException("the cleared preview layer stayed visible");
                if (ShellBorderColor(target) != baseline)
                    throw new InvalidOperationException("the cleared hint did not restore the shell border");
            }
            finally
            {
                target.Close();
            }
        }

        /// <summary>
        /// P2-5: the preview layer is chrome-level, so a group window merge
        /// target paints the dragged component too.
        /// </summary>
        private static void MergePreviewWorksOnAGroupTarget()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowGroupWindow(window);
                var preview = NewMergePreviewBitmap();
                window.SetMergeHint(true, preview);

                WidgetChrome chrome = ChromeOf(window);
                Grid layer = MergePreviewLayerOf(chrome);
                if (layer.Visibility != Visibility.Visible)
                    throw new InvalidOperationException("the group merge preview layer is hidden");
                if (!ReferenceEquals(MergePreviewImageOf(chrome).Source, preview))
                    throw new InvalidOperationException("the group preview image is not the rendered source");

                window.SetMergeHint(false);
                if (layer.Visibility != Visibility.Collapsed)
                    throw new InvalidOperationException("the group merge preview layer stayed visible");
            }
            finally
            {
                window.Close();
            }
        }

        private static WriteableBitmap NewMergePreviewBitmap()
        {
            var bitmap = new WriteableBitmap(40, 30, 96, 96, PixelFormats.Pbgra32, null);
            bitmap.Freeze();
            return bitmap;
        }

        private static Grid MergePreviewLayerOf(WidgetChrome chrome)
        {
            var layer = chrome.FindName("MergePreviewLayer") as Grid;
            if (layer == null)
                throw new InvalidOperationException("the chrome has no MergePreviewLayer");
            return layer;
        }

        private static Image MergePreviewImageOf(WidgetChrome chrome)
        {
            var image = chrome.FindName("MergePreviewImage") as Image;
            if (image == null)
                throw new InvalidOperationException("the chrome has no MergePreviewImage");
            return image;
        }

        private static TextBlock MergePreviewLabelOf(WidgetChrome chrome)
        {
            var label = chrome.FindName("MergePreviewLabel") as TextBlock;
            if (label == null)
                throw new InvalidOperationException("the chrome has no MergePreviewLabel");
            return label;
        }

        /// <summary>The target is painting the dragged component's bitmap.</summary>
        private static void AssertMergePreviewShown(WidgetWindowBase target, string context)
        {
            WidgetChrome chrome = ChromeOf(target);
            if (MergePreviewLayerOf(chrome).Visibility != Visibility.Visible)
                throw new InvalidOperationException(context + " did not show the merge preview layer");
            if (MergePreviewImageOf(chrome).Source == null)
                throw new InvalidOperationException(context + " showed the preview layer without an image");
        }

        /// <summary>The target dropped both the layer and its bitmap.</summary>
        private static void AssertMergePreviewCleared(WidgetWindowBase target, string context)
        {
            WidgetChrome chrome = ChromeOf(target);
            if (MergePreviewLayerOf(chrome).Visibility != Visibility.Collapsed)
                throw new InvalidOperationException(context + " kept the merge preview layer visible");
            if (MergePreviewImageOf(chrome).Source != null)
                throw new InvalidOperationException(context + " kept the merge preview image");
        }

        private static ImageSource CachedMergePreviewOf(WidgetWindowBase source)
        {
            return PrivateBaseField<ImageSource>(source, "_mergePreviewImage");
        }

        private static bool MergePreviewWasRendered(WidgetWindowBase source)
        {
            return PrivateBaseField<bool>(source, "_mergePreviewRendered");
        }

        /// <summary>Shows a window far offscreen without activation (a real handle/rect).</summary>
        private static void ShowOffscreenWindow(Window window, double left)
        {
            window.WindowStartupLocation = WindowStartupLocation.Manual;
            window.Left = left;
            window.Top = -32000;
            window.ShowActivated = false;
            window.Show();
            window.UpdateLayout();
        }

        private static Point ScreenCenterOf(Window window)
        {
            Point origin = window.PointToScreen(new Point(0, 0));
            DpiScale dpi = VisualTreeHelper.GetDpi(window);
            double width = (window.ActualWidth > 0 ? window.ActualWidth : window.Width) * dpi.DpiScaleX;
            double height = (window.ActualHeight > 0 ? window.ActualHeight : window.Height) * dpi.DpiScaleY;
            return new Point(origin.X + width / 2, origin.Y + height / 2);
        }

        private static Color ShellBorderColor(WidgetWindowBase window)
        {
            var brush = window.PanelChrome == null ? null : window.PanelChrome.Shell.BorderBrush as SolidColorBrush;
            if (brush == null) throw new InvalidOperationException("a window has no shell border brush");
            return brush.Color;
        }

        private static MenuItem FindGroupMenuItem(ContextMenu menu, string header)        {
            foreach (var entry in menu.Items)
            {
                var item = entry as MenuItem;
                if (item != null && string.Equals(item.Header as string, header, StringComparison.Ordinal))
                    return item;
            }
            return null;
        }

        #endregion

        #region Group membership and tab order mutation (Task P0-A2)

        /// <summary>
        /// Shows the group offscreen and marks its panel open. The private
        /// expanded flag is the same seam the standalone pins use; showing the
        /// window gives the slots and tab row a real layout without running
        /// the open fade.
        /// </summary>
        private static void ShowOpenGroupWindow(WidgetGroupWindow window)
        {
            ShowGroupWindow(window);
            SetPrivateBaseField(window, "_isExpanded", true);
            if (window.Group != null) window.Group.IsExpanded = true;
        }

        private static NoteData NewExtraNote(string id, string name, string color,
            double? panelWidth = null, double? panelHeight = null)
        {
            return new NoteData
            {
                Id = id,
                Name = name,
                Color = color,
                PanelWidth = panelWidth,
                PanelHeight = panelHeight
            };
        }

        private static void AssertSameViewPrefix(WidgetGroupWindow window,
            IReadOnlyList<IWidgetContentView> views, IReadOnlyList<ContentControl> slots,
            string context)
        {
            for (int i = 0; i < views.Count; i++)
            {
                if (!ReferenceEquals(window.Views[i], views[i]))
                {
                    throw new InvalidOperationException(context + " recreated the view at " + i);
                }
                if (!ReferenceEquals(window.ContentSlots[i].Content, slots[i].Content))
                {
                    throw new InvalidOperationException(context + " recreated the slot content at " + i);
                }
            }
        }

        private static void AssertSingleActiveUnderline(WidgetGroupWindow window, int index, string context)
        {
            int visible = 0;
            int visibleIndex = -1;
            var underlines = window.TabStrip.Underlines;
            for (int i = 0; i < underlines.Count; i++)
            {
                if (underlines[i].Visibility != Visibility.Visible) continue;
                visible++;
                visibleIndex = i;
            }

            if (visible != 1 || visibleIndex != index)
            {
                throw new InvalidOperationException(
                    context + " shows " + visible + " underline(s) at " + visibleIndex +
                    ", wanted exactly one at " + index);
            }
        }

        /// <summary>
        /// Adding a member appends one tab and one live view to the same
        /// window. Every existing view and slot stays the exact reference, the
        /// active tab does not change, and a member whose own panel is larger
        /// grows the group without a close/reopen or an open animation.
        /// </summary>
        private static void GroupAddMemberKeepsTheWindowAndViews()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowOpenGroupWindow(window);

                var viewsBefore = new List<IWidgetContentView>(window.Views);
                var slotsBefore = new List<ContentControl>(window.ContentSlots);
                double widthBefore = window.Width;
                double heightBefore = window.Height;
                string activeBefore = window.ActiveMemberId;

                var bigger = NewExtraNote("note-2", "Bigger note", "#B5654A", 900, 620);
                window.AddMember(bigger);
                window.UpdateLayout();

                if (!window.IsLoaded || !window.IsVisible)
                {
                    throw new InvalidOperationException("the group window was hidden or recreated by AddMember");
                }
                if (!window.IsPanelOpen)
                {
                    throw new InvalidOperationException("AddMember closed the panel");
                }
                if (window.WidgetId != "g1" || !ReferenceEquals(window.Group, group))
                {
                    throw new InvalidOperationException("AddMember did not keep the same group window");
                }
                if (window.Members.Count != 3 || !ReferenceEquals(window.Members[2], bigger))
                {
                    throw new InvalidOperationException(
                        "the new member is not the last of " + window.Members.Count + " members");
                }
                if (window.Views.Count != 3 || window.ContentSlots.Count != 3)
                {
                    throw new InvalidOperationException(
                        "the group has " + window.Views.Count + " views / " +
                        window.ContentSlots.Count + " slots after AddMember");
                }

                AssertSameViewPrefix(window, viewsBefore, slotsBefore, "AddMember");
                if (!ReferenceEquals(window.Views[2].Data, bigger))
                {
                    throw new InvalidOperationException("the new view does not carry the added member");
                }
                if (!ReferenceEquals(window.ContentSlots[2].Content, window.Views[2].View))
                {
                    throw new InvalidOperationException("the new slot does not host the new view");
                }
                if (window.TabStrip.TabButtons.Count != 3 ||
                    !ReferenceEquals(window.TabStrip.TabButtons[2].Tag, bigger))
                {
                    throw new InvalidOperationException("the new tab is not appended to the strip");
                }

                if (window.ActiveMemberId != activeBefore || window.ActiveIndex != 0)
                {
                    throw new InvalidOperationException(
                        "AddMember changed the active tab to " + window.ActiveMemberId);
                }
                AssertSingleActiveUnderline(window, 0, "the group after AddMember");

                if (window.Width <= widthBefore || window.Height <= heightBefore)
                {
                    throw new InvalidOperationException(
                        "a larger member did not grow the group: " + widthBefore + "x" + heightBefore +
                        " -> " + window.Width + "x" + window.Height);
                }
                if (Math.Abs(window.Width - 900) > 0.01 || Math.Abs(window.Height - 652) > 0.01)
                {
                    throw new InvalidOperationException(
                        "the grown group is " + window.Width + "x" + window.Height + ", wanted 900x652");
                }
                if (group.PanelWidth != window.Width || group.PanelHeight != window.Height)
                {
                    throw new InvalidOperationException("the group state does not remember the grown size");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// Removing an inactive member returns its exact live view, drops one
        /// tab and one slot, keeps every survivor reference-equal, leaves the
        /// active member alone and never shrinks the group.
        /// </summary>
        private static void GroupRemoveInactiveMemberHandsBackTheLiveView()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowOpenGroupWindow(window);

                var bigger = NewExtraNote("note-2", "Bigger note", "#B5654A", 900, 620);
                window.AddMember(bigger);
                window.UpdateLayout();

                var viewsBefore = new List<IWidgetContentView>(window.Views);
                var slotsBefore = new List<ContentControl>(window.ContentSlots);
                double widthBefore = window.Width;
                double heightBefore = window.Height;
                string activeBefore = window.ActiveMemberId;
                string groupActiveBefore = group.ActiveWidgetId;
                IWidgetContentView removedView = window.Views[2];

                IWidgetContentView detached = window.RemoveMember("note-2");
                window.UpdateLayout();

                if (!ReferenceEquals(detached, removedView))
                {
                    throw new InvalidOperationException("RemoveMember did not return the live view");
                }
                if (!window.IsLoaded || !window.IsVisible || !window.IsPanelOpen)
                {
                    throw new InvalidOperationException("RemoveMember closed or hid the group window");
                }
                if (window.Members.Count != 2 || window.Views.Count != 2 || window.ContentSlots.Count != 2)
                {
                    throw new InvalidOperationException(
                        "the group still has " + window.Members.Count + " members / " +
                        window.Views.Count + " views / " + window.ContentSlots.Count + " slots");
                }

                AssertSameViewPrefix(window,
                    viewsBefore.GetRange(0, 2), slotsBefore.GetRange(0, 2), "RemoveMember");
                if (window.ActiveMemberId != activeBefore || window.ActiveIndex != 0)
                {
                    throw new InvalidOperationException(
                        "removing an inactive member changed the active tab to " + window.ActiveMemberId);
                }
                if (group.ActiveWidgetId != groupActiveBefore)
                {
                    throw new InvalidOperationException("removing an inactive member changed Group.ActiveWidgetId");
                }
                if (window.TabStrip.TabButtons.Count != 2)
                {
                    throw new InvalidOperationException("the tab was not removed from the strip");
                }
                AssertSingleActiveUnderline(window, 0, "the group after an inactive removal");

                if (window.Width != widthBefore || window.Height != heightBefore)
                {
                    throw new InvalidOperationException(
                        "an inactive removal resized the group: " + widthBefore + "x" + heightBefore +
                        " -> " + window.Width + "x" + window.Height);
                }
                for (int i = 0; i < window.ContentSlots.Count; i++)
                {
                    if (ReferenceEquals(window.ContentSlots[i].Content, detached.View))
                    {
                        throw new InvalidOperationException("the returned view is still hosted in the group");
                    }
                }
                if (window.RemoveMember("note-2") != null)
                {
                    throw new InvalidOperationException("removing a non-member returned a view");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// Removing the active middle tab activates the member that takes its
        /// index and writes that id to <see cref="WidgetGroup.ActiveWidgetId"/>;
        /// the surviving views stay put.
        /// </summary>
        private static void GroupRemoveActiveMemberActivatesTheNearestSurvivor()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowOpenGroupWindow(window);

                var third = NewExtraNote("note-2", "Third", "#B5654A");
                window.AddMember(third);
                window.SetActive(1);
                window.UpdateLayout();

                var viewsBefore = new List<IWidgetContentView>(window.Views);
                var slotsBefore = new List<ContentControl>(window.ContentSlots);
                IWidgetContentView removedView = window.Views[1];

                IWidgetContentView detached = window.RemoveMember("note-1");
                window.UpdateLayout();

                if (!ReferenceEquals(detached, removedView))
                {
                    throw new InvalidOperationException("RemoveMember did not return the active live view");
                }
                if (window.Members.Count != 2 || window.Views.Count != 2)
                {
                    throw new InvalidOperationException("the active removal left the wrong member count");
                }
                if (window.ActiveMemberId != "note-2" || window.ActiveIndex != 1)
                {
                    throw new InvalidOperationException(
                        "the nearest survivor is not active: " + window.ActiveMemberId +
                        " at " + window.ActiveIndex);
                }
                if (group.ActiveWidgetId != "note-2")
                {
                    throw new InvalidOperationException(
                        "Group.ActiveWidgetId is " + group.ActiveWidgetId + ", wanted note-2");
                }
                var active = window.Data as NoteData;
                if (active == null || active.Id != "note-2")
                {
                    throw new InvalidOperationException("Data is not the surviving note");
                }

                if (!ReferenceEquals(window.Views[0], viewsBefore[0]) ||
                    !ReferenceEquals(window.Views[1], viewsBefore[2]))
                {
                    throw new InvalidOperationException("the active removal recreated a surviving view");
                }
                if (!ReferenceEquals(window.ContentSlots[0].Content, slotsBefore[0].Content) ||
                    !ReferenceEquals(window.ContentSlots[1].Content, slotsBefore[2].Content))
                {
                    throw new InvalidOperationException("the active removal recreated surviving slot content");
                }
                if (window.ContentSlots[1].Visibility != Visibility.Visible ||
                    window.ContentSlots[0].Visibility != Visibility.Collapsed)
                {
                    throw new InvalidOperationException("the survivor's slot is not the visible one");
                }
                if (window.TabStrip.TabButtons.Count != 2)
                {
                    throw new InvalidOperationException("the active tab was not removed from the strip");
                }
                AssertSingleActiveUnderline(window, 1, "the group after an active removal");
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// Reordering moves the member/view/slot/focus bookkeeping and the tab
        /// visual, renumbers GroupOrder, keeps the dragged member active, and
        /// adjusts another active member's index. A moved tab still switches
        /// its own member because the handler resolves the current index.
        /// </summary>
        private static void GroupReorderMemberMovesTheViewsAndFollowsTheActiveTab()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowOpenGroupWindow(window);

                var third = NewExtraNote("note-2", "Third", "#B5654A");
                window.AddMember(third);
                window.UpdateLayout();

                var viewsBefore = new List<IWidgetContentView>(window.Views);
                var slotsBefore = new List<ContentControl>(window.ContentSlots);
                var tabsBefore = new List<Grid>(window.TabStrip.TabButtons);
                double widthBefore = window.Width;
                double heightBefore = window.Height;

                window.SetActive(0);
                window.ReorderMember(0, 2);
                window.UpdateLayout();

                if (window.ActiveMemberId != "todo-1" || window.ActiveIndex != 2)
                {
                    throw new InvalidOperationException(
                        "the dragged member did not stay active at its new index: " +
                        window.ActiveMemberId + " at " + window.ActiveIndex);
                }
                if (group.ActiveWidgetId != "todo-1")
                {
                    throw new InvalidOperationException("Group.ActiveWidgetId did not follow the dragged tab");
                }
                if (window.Members.Count != 3 ||
                    window.Members[0].Id != "note-1" ||
                    window.Members[1].Id != "note-2" ||
                    window.Members[2].Id != "todo-1")
                {
                    throw new InvalidOperationException("the member order is not note/note-2/todo");
                }
                for (int i = 0; i < window.Members.Count; i++)
                {
                    if (window.Members[i].GroupOrder != i)
                    {
                        throw new InvalidOperationException(
                            "GroupOrder at " + i + " is " + window.Members[i].GroupOrder);
                    }
                }

                if (!ReferenceEquals(window.Views[2], viewsBefore[0]) ||
                    !ReferenceEquals(window.Views[0], viewsBefore[1]) ||
                    !ReferenceEquals(window.Views[1], viewsBefore[2]))
                {
                    throw new InvalidOperationException("the reorder rebuilt or misplaced a view");
                }
                if (!ReferenceEquals(window.ContentSlots[2].Content, slotsBefore[0].Content) ||
                    !ReferenceEquals(window.ContentSlots[0].Content, slotsBefore[1].Content) ||
                    !ReferenceEquals(window.ContentSlots[1].Content, slotsBefore[2].Content))
                {
                    throw new InvalidOperationException("the reorder rebuilt or misplaced a slot");
                }
                if (!ReferenceEquals(window.TabStrip.TabButtons[0], tabsBefore[1]) ||
                    !ReferenceEquals(window.TabStrip.TabButtons[1], tabsBefore[2]) ||
                    !ReferenceEquals(window.TabStrip.TabButtons[2], tabsBefore[0]))
                {
                    throw new InvalidOperationException("the tab visuals did not move with their members");
                }
                for (int i = 0; i < window.TabStrip.TabButtons.Count; i++)
                {
                    if (!ReferenceEquals(window.TabStrip.TabButtons[i].Tag, window.Members[i]))
                    {
                        throw new InvalidOperationException("the tab at " + i + " is not tagged with its member");
                    }
                }
                AssertSingleActiveUnderline(window, 2, "the group after the first reorder");

                int visibleSlots = 0;
                for (int i = 0; i < window.ContentSlots.Count; i++)
                {
                    if (window.ContentSlots[i].Visibility == Visibility.Visible) visibleSlots++;
                }
                if (visibleSlots != 1)
                {
                    throw new InvalidOperationException(
                        "the reorder left " + visibleSlots + " visible content slots");
                }
                if (window.Width != widthBefore || window.Height != heightBefore)
                {
                    throw new InvalidOperationException("the reorder resized the group");
                }
                if (!window.IsPanelOpen)
                {
                    throw new InvalidOperationException("the reorder closed the panel");
                }

                // A moved tab must switch its own member: the handler resolves
                // the member index at event time, not the construction index.
                window.SetActive(0);
                Grid movedTab = window.TabStrip.TabButtons[2];
                try
                {
                    movedTab.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice, 0, MouseButton.Left)
                    {
                        RoutedEvent = UIElement.MouseLeftButtonDownEvent
                    });
                }
                finally
                {
                    window.TabStrip.CancelTabDrag();
                    if (movedTab.IsMouseCaptured) movedTab.ReleaseMouseCapture();
                }
                if (window.ActiveMemberId != "todo-1" || window.ActiveIndex != 2)
                {
                    throw new InvalidOperationException(
                        "the moved tab switched to the stale index instead of its member: " +
                        window.ActiveMemberId + " at " + window.ActiveIndex);
                }

                // Another tab stays active: moving the first tab to the end
                // shifts its own index down instead of changing the member.
                window.SetActive(0);
                if (window.ActiveMemberId != "note-1")
                {
                    throw new InvalidOperationException("the note tab did not become active");
                }
                window.ReorderMember(2, 0);
                window.UpdateLayout();

                if (window.Members[0].Id != "todo-1" ||
                    window.Members[1].Id != "note-1" ||
                    window.Members[2].Id != "note-2")
                {
                    throw new InvalidOperationException("the second reorder did not restore todo/note/note-2");
                }
                for (int i = 0; i < window.Members.Count; i++)
                {
                    if (window.Members[i].GroupOrder != i)
                    {
                        throw new InvalidOperationException(
                            "GroupOrder after the second reorder at " + i + " is " + window.Members[i].GroupOrder);
                    }
                }
                if (window.ActiveMemberId != "note-1" || window.ActiveIndex != 1)
                {
                    throw new InvalidOperationException(
                        "another active tab did not follow the move: " + window.ActiveMemberId +
                        " at " + window.ActiveIndex);
                }
                if (group.ActiveWidgetId != "note-1")
                {
                    throw new InvalidOperationException("Group.ActiveWidgetId changed while another tab stayed active");
                }
                if (!ReferenceEquals(window.Views[0], viewsBefore[0]) ||
                    !ReferenceEquals(window.Views[1], viewsBefore[1]) ||
                    !ReferenceEquals(window.Views[2], viewsBefore[2]))
                {
                    throw new InvalidOperationException("the second reorder rebuilt a view");
                }
                if (window.Width != widthBefore || window.Height != heightBefore)
                {
                    throw new InvalidOperationException("the second reorder resized the group");
                }
                AssertSingleActiveUnderline(window, 1, "the group after the second reorder");
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// Removing every member leaves an empty but still open, un-hidden
        /// group: no throw, no views/slots/tabs, no active member. The manager
        /// is the one that closes the shell afterwards.
        /// </summary>
        private static void GroupRemoveAllMembersLeavesAnEmptyOpenGroup()
        {
            WidgetGroup group;
            TodoData todo;
            NoteData note;
            var window = NewGroupWindow(out group, out todo, out note);
            try
            {
                ShowOpenGroupWindow(window);

                var viewsBefore = new List<IWidgetContentView>(window.Views);
                IWidgetContentView first = window.RemoveMember("todo-1");
                if (!ReferenceEquals(first, viewsBefore[0]))
                {
                    throw new InvalidOperationException("the first removal did not return the todo view");
                }
                if (window.ActiveMemberId != "note-1" || group.ActiveWidgetId != "note-1")
                {
                    throw new InvalidOperationException("the surviving note did not become active");
                }

                IWidgetContentView second = window.RemoveMember("note-1");
                if (!ReferenceEquals(second, viewsBefore[1]))
                {
                    throw new InvalidOperationException("the second removal did not return the note view");
                }
                window.UpdateLayout();

                if (window.Members.Count != 0 || window.Views.Count != 0 || window.ContentSlots.Count != 0)
                {
                    throw new InvalidOperationException(
                        "the empty group still has " + window.Members.Count + " members / " +
                        window.Views.Count + " views / " + window.ContentSlots.Count + " slots");
                }
                if (window.ActiveMemberId != null || window.ActiveIndex != -1)
                {
                    throw new InvalidOperationException(
                        "the empty group still has the active member " + window.ActiveMemberId);
                }
                if (group.ActiveWidgetId != null)
                {
                    throw new InvalidOperationException("Group.ActiveWidgetId is still " + group.ActiveWidgetId);
                }
                if (window.TabStrip.TabButtons.Count != 0 || window.TabStrip.Underlines.Count != 0)
                {
                    throw new InvalidOperationException("the empty group still shows tabs");
                }
                if (!window.IsPanelOpen || !window.IsVisible)
                {
                    throw new InvalidOperationException("removing the last member closed or hid the group");
                }

                // The strip's SetActive tolerates an out-of-range index by
                // clearing the underline instead of throwing.
                window.TabStrip.SetActive(0);
                window.TabStrip.SetActive(-1);
                for (int i = 0; i < window.TabStrip.Underlines.Count; i++)
                {
                    if (window.TabStrip.Underlines[i].Visibility == Visibility.Visible)
                        throw new InvalidOperationException("an empty strip kept an active underline");
                }

                if (window.RemoveMember(null) != null || window.RemoveMember("missing") != null)
                {
                    throw new InvalidOperationException("removing a non-member returned a view");
                }
            }
            finally
            {
                window.Close();
            }
        }

        /// <summary>
        /// The group constructor and the factory overload adopt already
        /// attached live views: the same instance is put in the slot, no
        /// Attach/rebuild runs, and AddMember adopts a released view the same
        /// way.
        /// </summary>
        private static void GroupAdoptsReleasedViews()
        {
            ThemeManager.Initialize("dark");

            var todoData = new TodoData
            {
                Id = "adopt-todo",
                Name = "Adopted todo",
                Color = "#6A9BCC",
                SelectedDate = DateTime.Today
            };
            TodoListOps.AddItem(todoData, "Keep me", DateTime.Today);
            var noteData = new NoteData { Id = "adopt-note", Name = "Adopted note", Color = "#788C5D" };

            var source = new TodoWidget(todoData);
            var live = source.CalendarView;
            var released = source.ReleaseContentView();

            var group = new WidgetGroup
            {
                Id = "adopt-group",
                ActiveWidgetId = todoData.Id,
                PanelWidth = 760,
                PanelHeight = 540
            };
            var window = new WidgetGroupWindow(group,
                new List<WidgetData> { todoData, noteData },
                new List<IWidgetContentView> { released, null });

            var factoryTodo = new TodoData
            {
                Id = "factory-todo",
                Name = "Factory todo",
                Color = "#6A9BCC",
                SelectedDate = DateTime.Today
            };
            var factoryNote = new NoteData { Id = "factory-note", Name = "Factory note", Color = "#788C5D" };
            var factorySource = new TodoWidget(factoryTodo);
            var factoryLive = factorySource.CalendarView;
            var factoryReleased = factorySource.ReleaseContentView();
            var factoryGroup = new WidgetGroup
            {
                Id = "factory-group",
                ActiveWidgetId = factoryTodo.Id,
                PanelWidth = 760,
                PanelHeight = 540
            };
            var factoryWindow = WidgetWindowFactory.CreateGroup(factoryGroup,
                new List<WidgetData> { factoryTodo, factoryNote },
                new List<IWidgetContentView> { factoryReleased, null }) as WidgetGroupWindow;

            var adoptedNoteData = new NoteData { Id = "adopt-note-2", Name = "Added note", Color = "#B5654A" };
            var noteSource = new NoteWidget(adoptedNoteData);
            var noteLive = noteSource.PanelView;
            var noteReleased = noteSource.ReleaseContentView();

            try
            {
                if (!ReferenceEquals(window.Views[0], released))
                {
                    throw new InvalidOperationException("the group constructor did not adopt the live todo view");
                }
                if (!ReferenceEquals(window.ContentSlots[0].Content, live))
                {
                    throw new InvalidOperationException("the adopted todo view is not in the first slot");
                }
                if (window.Views[1] == null || window.Views[1] is TodoCalendarView)
                {
                    throw new InvalidOperationException("the null content entry did not create a fresh note view");
                }
                if (window.IsPanelOpen)
                {
                    throw new InvalidOperationException("a never-shown group reports an open panel");
                }

                if (factoryWindow == null)
                {
                    throw new InvalidOperationException("the factory overload did not create a group window");
                }
                if (!ReferenceEquals(factoryWindow.Views[0], factoryReleased) ||
                    !ReferenceEquals(factoryWindow.ContentSlots[0].Content, factoryLive))
                {
                    throw new InvalidOperationException("the factory overload did not adopt the live view");
                }

                int before = window.Members.Count;
                window.AddMember(adoptedNoteData, noteReleased);
                if (!ReferenceEquals(window.Views[before], noteReleased) ||
                    !ReferenceEquals(window.ContentSlots[before].Content, noteLive))
                {
                    throw new InvalidOperationException("AddMember rebuilt a released view instead of adopting it");
                }
                if (!ReferenceEquals(window.Members[before], adoptedNoteData))
                {
                    throw new InvalidOperationException("the adopted member is not the appended member");
                }
                if (window.Members.Count != before + 1)
                {
                    throw new InvalidOperationException("AddMember did not append the adopted member");
                }
            }
            finally
            {
                window.Close();
                if (factoryWindow != null) factoryWindow.Close();
                source.Close();
                factorySource.Close();
                noteSource.Close();
            }
        }

        #endregion

        #region Widget host transitions (Task P0-B)

        /// <summary>
        /// Stands three note/todo widgets up through the real manager in the
        /// throwaway check sandbox. The data carries explicit panel geometry
        /// (far offscreen) so every host has a real arranged size and no test
        /// panel lands on the desktop.
        /// </summary>
        private static void SetUpP0BStandaloneWidgets(
            out WidgetManager manager, out TodoData todo, out NoteData firstNote, out NoteData secondNote)
        {
            ThemeManager.Initialize("dark");
            manager = WidgetManager.Instance;

            // Drop every host/config entry the preceding manager pins left.
            foreach (var host in manager.Widgets.ToList())
            {
                if (host.WidgetId != null) manager.RemoveWidget(host.WidgetId);
            }
            manager.Config.Widgets.Clear();
            manager.Config.Groups = null;

            todo = new TodoData
            {
                Id = "p0b-todo",
                Name = "P0B Todo",
                Color = "#6A9BCC",
                SelectedDate = DateTime.Today,
                PanelX = -32000,
                PanelY = -32000,
                PanelWidth = 380,
                PanelHeight = 480
            };
            firstNote = new NoteData
            {
                Id = "p0b-note-1",
                Name = "P0B Note 1",
                Color = "#788C5D",
                PanelX = -32000,
                PanelY = -32000,
                PanelWidth = 320,
                PanelHeight = 400
            };
            secondNote = new NoteData
            {
                Id = "p0b-note-2",
                Name = "P0B Note 2",
                Color = "#B5654A",
                PanelX = -32000,
                PanelY = -32000,
                PanelWidth = 340,
                PanelHeight = 420
            };

            manager.Config.Widgets.Add(todo);
            manager.Config.Widgets.Add(firstNote);
            manager.Config.Widgets.Add(secondNote);
            manager.Initialize();
        }

        /// <summary>Removes every host and config entry a P0-B manager pin made.</summary>
        private static void CleanUpP0B(WidgetManager manager)
        {
            if (manager == null) return;

            foreach (var host in manager.Widgets.ToList())
            {
                if (!string.IsNullOrEmpty(host.WidgetId)) manager.RemoveWidget(host.WidgetId);
            }

            // A failed transition may have left a config-only entry behind;
            // the sandbox config is throwaway, so clearing it is safe.
            manager.Config.Widgets.Clear();
            manager.Config.Groups = null;
        }

        /// <summary>
        /// Builds the open two-member group every manager pin starts from:
        /// note 1 merges into the todo target, and the group is shown offscreen
        /// with the no-fade seam.
        /// </summary>
        private static WidgetGroupWindow OpenP0BGroup(WidgetManager manager, TodoData todo, NoteData firstNote)
        {
            IWidgetWindow todoHost = manager.FindHostForWidget(todo.Id);
            IWidgetWindow noteHost = manager.FindHostForWidget(firstNote.Id);
            if (todoHost == null || noteHost == null)
            {
                throw new InvalidOperationException("a standalone host was not created");
            }
            if (!manager.MergeWidgets(noteHost, todoHost))
            {
                throw new InvalidOperationException("the two standalones did not merge");
            }

            var groupHost = manager.FindHostForWidget(todo.Id) as WidgetGroupWindow;
            if (groupHost == null)
            {
                throw new InvalidOperationException("the merge produced no group host");
            }

            groupHost.ShowPanel(-32000, -32000, activate: false, animate: false);
            groupHost.UpdateLayout();
            return groupHost;
        }

        /// <summary>
        /// MERGING a standalone into an already-open group mutates that group
        /// in place: the same window instance stays open, every existing view
        /// is the same reference, the new tab is appended and the active tab
        /// does not move.
        /// </summary>
        private static void P0BMergeIntoOpenGroupKeepsTheLiveHostAndViews()
        {
            WidgetManager manager = null;
            TodoData todo;
            NoteData firstNote;
            NoteData secondNote;
            SetUpP0BStandaloneWidgets(out manager, out todo, out firstNote, out secondNote);

            try
            {
                WidgetGroupWindow groupHost = OpenP0BGroup(manager, todo, firstNote);
                var viewsBefore = new List<IWidgetContentView>(groupHost.Views);
                string activeBefore = groupHost.ActiveMemberId;
                double widthBefore = groupHost.Width;
                double heightBefore = groupHost.Height;
                bool groupClosed = false;
                groupHost.Closed += (s, e) => groupClosed = true;

                IWidgetWindow secondHost = manager.FindHostForWidget(secondNote.Id);
                if (secondHost == null)
                {
                    throw new InvalidOperationException("the third standalone host was not created");
                }

                if (!manager.MergeWidgets(secondHost, groupHost))
                {
                    throw new InvalidOperationException("the third standalone did not merge into the open group");
                }

                var same = manager.FindHostForWidget(todo.Id) as WidgetGroupWindow;
                if (!ReferenceEquals(same, groupHost))
                {
                    throw new InvalidOperationException("the open group was closed and recreated");
                }
                if (groupClosed || !same.IsVisible || !same.IsPanelOpen)
                {
                    throw new InvalidOperationException("the open group stopped being open/visible during the merge");
                }
                if (same.Members.Count != 3 || !ReferenceEquals(same.Members[2], secondNote))
                {
                    throw new InvalidOperationException("the merged widget is not the appended tab");
                }
                if (!ReferenceEquals(same.Views[0], viewsBefore[0]) ||
                    !ReferenceEquals(same.Views[1], viewsBefore[1]))
                {
                    throw new InvalidOperationException("the merge recreated an existing member view");
                }
                if (same.ActiveMemberId != activeBefore || same.ActiveIndex != 0)
                {
                    throw new InvalidOperationException("the merge changed the active tab to " + same.ActiveMemberId);
                }
                if (secondNote.GroupId != same.WidgetId || secondNote.GroupOrder != 2)
                {
                    throw new InvalidOperationException("the appended member did not get the last group slot");
                }
                if (!ReferenceEquals(manager.FindHostForWidget(secondNote.Id), same))
                {
                    throw new InvalidOperationException("the merged source kept a host of its own");
                }
                if (Math.Abs(same.Width - widthBefore) > 0.01 || Math.Abs(same.Height - heightBefore) > 0.01)
                {
                    throw new InvalidOperationException("a smaller member resized the open group");
                }
            }
            finally
            {
                CleanUpP0B(manager);
            }
        }

        /// <summary>
        /// R1: merging a standalone whose panel is larger than the open group
        /// appends its tab/view but never touches the group's own geometry -
        /// Width/Height and WidgetGroup.PanelWidth/PanelHeight stay exactly as
        /// they were, and the source keeps its remembered size.
        /// </summary>
        private static void P0BMergeLargerStandaloneKeepsTheGroupSize()
        {
            WidgetManager manager = null;
            TodoData todo;
            NoteData firstNote;
            NoteData secondNote;
            SetUpP0BStandaloneWidgets(out manager, out todo, out firstNote, out secondNote);

            try
            {
                WidgetGroupWindow groupHost = OpenP0BGroup(manager, todo, firstNote);

                // A standalone clearly larger than the two-member group.
                double sourceWidth = groupHost.Width + 260;
                double sourceHeight = groupHost.Height + 200;
                secondNote.PanelWidth = sourceWidth;
                secondNote.PanelHeight = sourceHeight;

                IWidgetWindow secondHost = manager.FindHostForWidget(secondNote.Id);
                if (secondHost == null)
                {
                    throw new InvalidOperationException("the larger standalone host was not created");
                }

                double widthBefore = groupHost.Width;
                double heightBefore = groupHost.Height;
                double? panelWidthBefore = groupHost.Group.PanelWidth;
                double? panelHeightBefore = groupHost.Group.PanelHeight;
                int tabsBefore = groupHost.TabStrip.TabButtons.Count;

                if (!manager.MergeWidgets(secondHost, groupHost))
                {
                    throw new InvalidOperationException("the larger standalone did not merge into the group");
                }

                var same = manager.FindHostForWidget(todo.Id) as WidgetGroupWindow;
                if (!ReferenceEquals(same, groupHost))
                {
                    throw new InvalidOperationException("the merge replaced the open group");
                }
                if (same.Members.Count != tabsBefore + 1 ||
                    same.Views.Count != tabsBefore + 1 ||
                    same.TabStrip.TabButtons.Count != tabsBefore + 1 ||
                    !ReferenceEquals(same.Members[same.Members.Count - 1], secondNote) ||
                    !ReferenceEquals(same.Views[same.Views.Count - 1].Data, secondNote))
                {
                    throw new InvalidOperationException(
                        "the larger standalone was not appended as the last tab/view");
                }
                if (same.Width != widthBefore || same.Height != heightBefore)
                {
                    throw new InvalidOperationException(
                        "merging a larger standalone resized the group from " + widthBefore + "x" +
                        heightBefore + " to " + same.Width + "x" + same.Height);
                }
                if (same.Group.PanelWidth != panelWidthBefore ||
                    same.Group.PanelHeight != panelHeightBefore)
                {
                    throw new InvalidOperationException(
                        "merging a larger standalone rewrote the group panel size (" +
                        same.Group.PanelWidth + "x" + same.Group.PanelHeight + ", wanted " +
                        panelWidthBefore + "x" + panelHeightBefore + ")");
                }
                if (secondNote.PanelWidth != sourceWidth || secondNote.PanelHeight != sourceHeight)
                {
                    throw new InvalidOperationException(
                        "the merged widget's remembered size was rewritten (" +
                        secondNote.PanelWidth + "x" + secondNote.PanelHeight + ")");
                }
            }
            finally
            {
                CleanUpP0B(manager);
            }
        }

        /// <summary>
        /// DETACHING from a three-member group keeps the group window and its
        /// surviving views; the detached standalone hosts the exact view the
        /// group tab owned, at the group's cascade.
        /// </summary>
        private static void P0BDetachKeepsTheGroupAndMovesTheLiveView()
        {
            WidgetManager manager = null;
            TodoData todo;
            NoteData firstNote;
            NoteData secondNote;
            SetUpP0BStandaloneWidgets(out manager, out todo, out firstNote, out secondNote);

            try
            {
                WidgetGroupWindow groupHost = OpenP0BGroup(manager, todo, firstNote);
                IWidgetWindow secondHost = manager.FindHostForWidget(secondNote.Id);
                if (!manager.MergeWidgets(secondHost, groupHost))
                {
                    throw new InvalidOperationException("the third standalone did not merge into the group");
                }

                string groupId = groupHost.WidgetId;
                var viewsBefore = new List<IWidgetContentView>(groupHost.Views);
                double widthBefore = groupHost.Width;
                double heightBefore = groupHost.Height;
                string activeBefore = groupHost.ActiveMemberId;
                bool groupClosed = false;
                groupHost.Closed += (s, e) => groupClosed = true;

                if (!manager.DetachWidget(groupId, secondNote.Id))
                {
                    throw new InvalidOperationException("detaching the third tab was refused");
                }

                var same = manager.FindHostForWidget(todo.Id) as WidgetGroupWindow;
                if (!ReferenceEquals(same, groupHost))
                {
                    throw new InvalidOperationException("detaching closed/recreated the surviving group");
                }
                if (groupClosed || !same.IsVisible || !same.IsPanelOpen)
                {
                    throw new InvalidOperationException("the surviving group stopped being open/visible");
                }
                if (same.Members.Count != 2 || same.ContainsWidget(secondNote.Id))
                {
                    throw new InvalidOperationException("the surviving group carries the wrong tabs");
                }
                if (!ReferenceEquals(same.Views[0], viewsBefore[0]) ||
                    !ReferenceEquals(same.Views[1], viewsBefore[1]))
                {
                    throw new InvalidOperationException("detaching recreated a surviving member view");
                }
                if (same.ActiveMemberId != activeBefore)
                {
                    throw new InvalidOperationException("detaching an inactive tab changed the active tab");
                }
                if (Math.Abs(same.Width - widthBefore) > 0.01 || Math.Abs(same.Height - heightBefore) > 0.01)
                {
                    throw new InvalidOperationException("detaching resized the surviving group");
                }
                if (secondNote.GroupId != null || secondNote.GroupOrder != null)
                {
                    throw new InvalidOperationException("the detached member kept its membership");
                }

                var detached = manager.FindHostForWidget(secondNote.Id) as WidgetWindowBase;
                if (detached == null || detached is WidgetGroupWindow)
                {
                    throw new InvalidOperationException("the detached member got no standalone host");
                }
                if (!ReferenceEquals(detached.PanelChrome.ContentHost.Content, viewsBefore[2].View))
                {
                    throw new InvalidOperationException("the detached standalone hosts a recreated view");
                }
                if (!detached.IsPanelOpen)
                {
                    throw new InvalidOperationException("the detached standalone was not shown before the swap");
                }
            }
            finally
            {
                CleanUpP0B(manager);
            }
        }

        /// <summary>
        /// Detaching the ACTIVE tab must leave the surviving group open. The
        /// detached host is shown without activation: activating it would
        /// deactivate an unpinned group and its existing Window_Deactivated
        /// rule would collapse the group.
        /// </summary>
        private static void P0BDetachActiveTabKeepsTheGroupOpen()
        {
            WidgetManager manager = null;
            TodoData todo;
            NoteData firstNote;
            NoteData secondNote;
            SetUpP0BStandaloneWidgets(out manager, out todo, out firstNote, out secondNote);

            try
            {
                WidgetGroupWindow groupHost = OpenP0BGroup(manager, todo, firstNote);
                IWidgetWindow secondHost = manager.FindHostForWidget(secondNote.Id);
                if (!manager.MergeWidgets(secondHost, groupHost))
                {
                    throw new InvalidOperationException("the third standalone did not merge into the group");
                }

                string groupId = groupHost.WidgetId;
                if (groupHost.ActiveMemberId != todo.Id)
                {
                    throw new InvalidOperationException("the fixture's active tab is not the one being detached");
                }

                // Make the group the active window so the removed
                // activate-detached branch would actually deactivate it.
                groupHost.Activate();

                bool groupClosed = false;
                groupHost.Closed += (s, e) => groupClosed = true;

                if (!manager.DetachWidget(groupId, todo.Id))
                {
                    throw new InvalidOperationException("detaching the active tab was refused");
                }

                var same = manager.FindHostForWidget(firstNote.Id) as WidgetGroupWindow;
                if (!ReferenceEquals(same, groupHost))
                {
                    throw new InvalidOperationException("detaching the active tab closed/recreated the group");
                }
                if (groupClosed || !same.IsVisible || !same.IsPanelOpen)
                {
                    throw new InvalidOperationException("detaching the active tab collapsed the surviving group");
                }
                if (same.ActiveMemberId != firstNote.Id)
                {
                    throw new InvalidOperationException(
                        "the active tab after detaching is " + same.ActiveMemberId + ", wanted the survivor");
                }
                if (same.Members.Count != 2 || same.ContainsWidget(todo.Id))
                {
                    throw new InvalidOperationException("the surviving group carries the wrong tabs");
                }
                if (todo.GroupId != null || todo.GroupOrder != null)
                {
                    throw new InvalidOperationException("the detached active tab kept its membership");
                }

                var detached = manager.FindHostForWidget(todo.Id) as WidgetWindowBase;
                if (detached == null || detached is WidgetGroupWindow)
                {
                    throw new InvalidOperationException("the detached active tab got no standalone host");
                }
                if (!detached.IsPanelOpen)
                {
                    throw new InvalidOperationException("the detached active tab was not shown");
                }
            }
            finally
            {
                CleanUpP0B(manager);
            }
        }

        /// <summary>
        /// The LAST-PAIR DISSOLVE takes both live views out of the group, shows
        /// both standalone hosts and then closes the group. Each standalone
        /// hosts the exact view instance the group had.
        /// </summary>
        private static void P0BLastPairDissolveMovesBothLiveViews()
        {
            WidgetManager manager = null;
            TodoData todo;
            NoteData firstNote;
            NoteData secondNote;
            SetUpP0BStandaloneWidgets(out manager, out todo, out firstNote, out secondNote);

            try
            {
                WidgetGroupWindow groupHost = OpenP0BGroup(manager, todo, firstNote);
                string groupId = groupHost.WidgetId;
                var viewsBefore = new List<IWidgetContentView>(groupHost.Views);
                bool groupClosed = false;
                groupHost.Closed += (s, e) => groupClosed = true;

                if (!manager.DetachWidget(groupId, firstNote.Id))
                {
                    throw new InvalidOperationException("the last-pair detach was refused");
                }

                if (!groupClosed)
                {
                    throw new InvalidOperationException("the dissolved group window was not closed");
                }
                if (manager.FindHostForWidget(groupId) != null)
                {
                    throw new InvalidOperationException("the dissolved group still resolves to a host");
                }
                if (manager.Config.Groups != null && manager.Config.Groups.Count != 0)
                {
                    throw new InvalidOperationException("the dissolved group kept its config entry");
                }

                var todoHost = manager.FindHostForWidget(todo.Id) as WidgetWindowBase;
                var noteHost = manager.FindHostForWidget(firstNote.Id) as WidgetWindowBase;
                if (todoHost == null || todoHost is WidgetGroupWindow)
                {
                    throw new InvalidOperationException("the survivor did not become a standalone host");
                }
                if (noteHost == null || noteHost is WidgetGroupWindow)
                {
                    throw new InvalidOperationException("the detached member did not become a standalone host");
                }
                if (!ReferenceEquals(todoHost.PanelChrome.ContentHost.Content, viewsBefore[0].View))
                {
                    throw new InvalidOperationException("the survivor hosts a recreated view");
                }
                if (!ReferenceEquals(noteHost.PanelChrome.ContentHost.Content, viewsBefore[1].View))
                {
                    throw new InvalidOperationException("the detached member hosts a recreated view");
                }
                if (!todoHost.IsPanelOpen || !noteHost.IsPanelOpen)
                {
                    throw new InvalidOperationException("an open group's dissolve left a standalone closed");
                }
                if (todo.GroupId != null || firstNote.GroupId != null)
                {
                    throw new InvalidOperationException("a dissolved member kept its group membership");
                }
                if (todo.IsPanelPinned != groupHost.Group.IsPanelPinned ||
                    firstNote.IsPanelPinned != groupHost.Group.IsPanelPinned)
                {
                    throw new InvalidOperationException("the dissolved members did not inherit the group pin");
                }
            }
            finally
            {
                CleanUpP0B(manager);
            }
        }

        /// <summary>
        /// A same-group refresh must repaint the folded tile without replacing
        /// the row: a member rename/pin, a thumbnail colour change, a merge and
        /// a detach keep the same group Border, its open outline and its updated
        /// 2x2 thumbnails/tooltip. Dissolving the group still replaces the row
        /// with the standalone tiles.
        /// </summary>
        private static void P0BIslandRefreshesGroupTileInPlace()
        {
            ThemeManager.Initialize("dark");
            var first = new FolderData { Id = "p0b-tile-a", Name = "P0B member A", Color = "#B5654A" };
            var second = new NoteData { Id = "p0b-tile-b", Name = "P0B member B", Color = "#4A7BB5" };
            var solo = new TodoData { Id = "p0b-tile-solo", Name = "P0B solo", Color = "#788C5D" };
            var group = new WidgetGroup { Id = "p0b-tile-g", ActiveWidgetId = first.Id };
            first.GroupId = group.Id; second.GroupId = group.Id;
            first.GroupOrder = 0; second.GroupOrder = 1;
            var widgets = new List<WidgetData> { solo, first, second };
            var island = new IslandWindow();
            try
            {
                island.SetWidgets(widgets, GroupHostPolicy.BuildIslandGroupTiles(
                    new[] { group }, widgets, id => false));
                island.ShowIsland();
                island.UpdateLayout();

                var panel = TilePanelOf(island);
                if (panel.Children.Count != 2)
                    throw new InvalidOperationException("the island built " + panel.Children.Count +
                        " tiles for one group plus one standalone, wanted 2");
                var groupTile = FindIslandGroupTile(island, group.Id);
                if (groupTile == null)
                    throw new InvalidOperationException("the membership refresh did not fold the group");
                if (FindGroupBadge(groupTile) != null)
                    throw new InvalidOperationException("the folded tile still carries a count badge");

                island.SetOpenStates(new[] { group.Id });
                island.SetWidgets(widgets, GroupHostPolicy.BuildIslandGroupTiles(
                    new[] { group }, widgets, id => id == group.Id));
                island.UpdateLayout();

                if (!ReferenceEquals(groupTile, FindIslandGroupTile(island, group.Id)))
                    throw new InvalidOperationException("a same-group refresh replaced the group tile");
                if (groupTile.BorderThickness.Left != 1.5)
                    throw new InvalidOperationException("the refresh dropped the group's open outline");

                // Rename and pin a member: the folded tile keeps its Border,
                // repaints its tooltip and keeps the open outline.
                first.Name = "P0B renamed member A";
                first.IsPanelPinned = true;
                island.SetWidgets(widgets, GroupHostPolicy.BuildIslandGroupTiles(
                    new[] { group }, widgets, id => id == group.Id));
                island.UpdateLayout();

                if (!ReferenceEquals(groupTile, FindIslandGroupTile(island, group.Id)))
                    throw new InvalidOperationException("a member rename replaced the group tile");
                string tooltip = groupTile.ToolTip as string ?? string.Empty;
                if (!tooltip.Contains("P0B renamed member A") || tooltip.Contains("P0B member A"))
                    throw new InvalidOperationException("the in-place refresh did not update the member names: " + tooltip);
                if (groupTile.BorderThickness.Left != 1.5)
                    throw new InvalidOperationException("a member rename dropped the group's open outline");

                // Thumbnail content changes in place too.
                var oldFirstIcon = GroupMemberIcons(groupTile).FirstOrDefault();
                first.Color = "#D4A017";
                island.SetWidgets(widgets, GroupHostPolicy.BuildIslandGroupTiles(
                    new[] { group }, widgets, id => id == group.Id));
                island.UpdateLayout();

                if (!ReferenceEquals(groupTile, FindIslandGroupTile(island, group.Id)))
                    throw new InvalidOperationException("a member colour change replaced the group tile");
                var newFirstIcon = GroupMemberIcons(groupTile).FirstOrDefault();
                if (oldFirstIcon == null || newFirstIcon == null
                    || IconFingerprint(oldFirstIcon.Child) == IconFingerprint(newFirstIcon.Child)
                    || !IconFingerprint(newFirstIcon.Child).Contains(Describe(Utils.HexToColor(first.Color))))
                    throw new InvalidOperationException("the in-place refresh did not repaint the member thumbnail");

                // Merge a new member into the same group: the projected row is
                // still [standalone, group], so only the group content changes.
                var third = new TodoData
                {
                    Id = "p0b-tile-c", Name = "P0B member C", Color = "#6A9BCC", GroupOrder = 2
                };
                third.GroupId = group.Id;
                widgets.Add(third);
                island.SetWidgets(widgets, GroupHostPolicy.BuildIslandGroupTiles(
                    new[] { group }, widgets, id => id == group.Id));
                island.UpdateLayout();

                if (!ReferenceEquals(groupTile, FindIslandGroupTile(island, group.Id)))
                    throw new InvalidOperationException("a same-group merge replaced the group tile");
                if (GroupMemberIcons(groupTile).Count != 3)
                    throw new InvalidOperationException("the merged member did not appear in the 2x2 grid");
                if (!(groupTile.ToolTip as string ?? string.Empty).Contains("P0B member C"))
                    throw new InvalidOperationException("the merged member did not reach the tooltip");
                if (groupTile.BorderThickness.Left != 1.5)
                    throw new InvalidOperationException("the merge dropped the group's open outline");

                // Detach that member while the group survives: same Border,
                // one fewer thumbnail, no stale member name.
                widgets.Remove(third);
                island.SetWidgets(widgets, GroupHostPolicy.BuildIslandGroupTiles(
                    new[] { group }, widgets, id => id == group.Id));
                island.UpdateLayout();

                if (!ReferenceEquals(groupTile, FindIslandGroupTile(island, group.Id)))
                    throw new InvalidOperationException("a same-group detach replaced the group tile");
                if (GroupMemberIcons(groupTile).Count != 2)
                    throw new InvalidOperationException("the detached member stayed in the 2x2 grid");
                if ((groupTile.ToolTip as string ?? string.Empty).Contains("P0B member C"))
                    throw new InvalidOperationException("the detached member stayed in the tooltip");
                if (groupTile.BorderThickness.Left != 1.5)
                    throw new InvalidOperationException("the detach dropped the group's open outline");

                // Dissolving to one member removes the group tile and rebuilds
                // the row into standalone tiles.
                widgets.Remove(second);
                island.SetWidgets(widgets, GroupHostPolicy.BuildIslandGroupTiles(
                    new[] { group }, widgets, id => id == group.Id));
                island.UpdateLayout();

                var ungrouped = TilePanelOf(island).Children.Cast<Border>().ToList();
                if (ungrouped.Count != 2)
                    throw new InvalidOperationException("removing the group did not unfold the members");
                if (ungrouped.Any(tile => (tile.Tag as string ?? string.Empty)
                        .StartsWith("group:", StringComparison.Ordinal)))
                    throw new InvalidOperationException("the dissolved group tile stayed in the row");
                if (ungrouped.Any(tile => ReferenceEquals(tile, groupTile)))
                    throw new InvalidOperationException("dissolving the group kept the old group Border");
                if (FindGroupBadge(ungrouped[0]) != null || FindGroupBadge(ungrouped[1]) != null)
                    throw new InvalidOperationException("an unfolded member kept a stale group badge");
                if ((ungrouped[0].ToolTip as string ?? string.Empty).Contains(second.Name))
                    throw new InvalidOperationException("an unfolded member kept the group member names");
            }
            finally
            {
                island.Close();
            }
        }

        /// <summary>
        /// The show seam with <c>animate:false</c> clears a running open fade
        /// and lands the shell at opacity 1 before returning, so a host swap
        /// never flashes from transparent.
        /// </summary>
        private static void P0BNoAnimationShowLandsAtFullOpacity()
        {
            ThemeManager.Initialize("dark");
            var widget = new TodoWidget(new TodoData
            {
                Id = "p0b-show-todo",
                Name = "P0B show",
                Color = "#6A9BCC",
                SelectedDate = DateTime.Today
            });
            try
            {
                widget.ShowPanel(-32000, -32000, activate: false, animate: true);
                widget.ShowPanel(-32000, -32000, activate: false, animate: false);

                if (widget.PanelChrome == null)
                {
                    throw new InvalidOperationException("the todo window has no chrome shell");
                }
                if (widget.PanelChrome.Shell.Opacity != 1)
                {
                    throw new InvalidOperationException(
                        "the no-animation show left the shell at opacity " + widget.PanelChrome.Shell.Opacity);
                }
                if (!widget.IsVisible || !widget.IsPanelOpen)
                {
                    throw new InvalidOperationException("the no-animation show did not open the panel");
                }
            }
            finally
            {
                widget.Close();
            }
        }

